local rows = {
    [3283391133] = {
        ["english"] = { [1] = "I would be honored to train you in the use of the weapons that I have mastered should you have the ability to learn within you." },
        ["text"] = "Для мене буде честю навчити вас користуватися зброєю, якою я володію, якщо ви здатні її опанувати.",
        ["npcs"] = { [1] = 11869 },
        ["roles"] = { ["greeting"] = true },
    },
    [795867403] = {
        ["english"] = { [1] = "I wish to untrain my pet." },
        ["text"] = "Я хочу скинути навчання свого вихованця.",
        ["npcs"] = { [1] = 543, [2] = 2878, [3] = 2879, [4] = 3306, [5] = 3545, [6] = 3620, [7] = 3622, [8] = 3624, [9] = 3688, [10] = 3698, [11] = 4320, [12] = 10086, [13] = 10088, [14] = 10089, [15] = 10090 },
        ["roles"] = { ["reply"] = true },
    },
    [4168107113] = {
        ["english"] = { [1] = "I've been expec...$B$B<Rimblat coughs.>$B$BExcuse me, old habit. I am Rimblat of the Earthen Ring. " },
        ["text"] = "Я на вас чека...$B$B<Рімблат кашляє.>$B$BПерепрошую, стара звичка. Я Рімблат із Кола Землі. ",
        ["npcs"] = { [1] = 16134 },
        ["roles"] = { ["greeting"] = true },
    },
    [1084227582] = {
        ["english"] = { [1] = "If it weren't for the goblins' inconceivable, dumb luck, they'd crash their car during every race!" },
        ["text"] = "Якби не неймовірне дурне везіння гоблінів, вони розбивали б свою машину на кожних перегонах!",
        ["npcs"] = { [1] = 4430 },
        ["roles"] = { ["greeting"] = true },
    },
    [889217185] = {
        ["english"] = { [1] = "I give you warm greetin's, $c, as does the Shattered Hand.$B$BDo not look so surprised, $N. There be shadows even on the highest perches of Orgrimmar--somethin' must hide there. The Shattered Hand take that role willingly. Thrall, even in his good heart, acknowledge that the Hand be necessary to ensure orc and troll safety.$B$BBut you not here to talk 'bout my business, you here for somethin' else." },
        ["text"] = "Щиро вітаю вас, $c, як і Розтрощена Рука.$B$BНе дивуйтеся так, $N. Тіні є навіть на найвищих уступах Орґріммара — хтось мусить у них ховатися. Розтрощена Рука охоче бере цю роль на себе. Навіть добросердий Тралл визнає, що Рука необхідна для безпеки орків і тролів.$B$BТа ви прийшли не про мої справи говорити, а по щось інше.",
        ["npcs"] = { [1] = 8659 },
        ["roles"] = { ["greeting"] = true },
    },
    [2800713146] = {
        ["english"] = { [1] = "It is good to see you again, Doctor $N. I have been following your progress and I dare say that it is time you learned some of the more advanced bandaging techniques.$B$BReturn to me from time to time, as your skill advances, and I shall teach you all that I know." },
        ["text"] = "Радий знову вас бачити, докторе $N. Я стежив за вашими успіхами й насмілюся сказати, що настав час опанувати складніші техніки перев'язування.$B$BПовертайтеся до мене час від часу, коли ваша майстерність зростатиме, і я навчу всього, що знаю.",
        ["npcs"] = { [1] = 12920, [2] = 12939 },
        ["roles"] = { ["greeting"] = true },
    },
    [4288064100] = {
        ["english"] = { [1] = "I wish to unlearn Armorsmithing!" },
        ["text"] = "Я хочу забути бронництво!",
        ["npcs"] = { [1] = 5164 },
        ["roles"] = { ["reply"] = true },
    },
    [3779819287] = {
        ["english"] = { [1] = "I listen and I listen but I don't hear these spirits that Karn speaks of. " },
        ["text"] = "Я слухаю й слухаю, але не чую тих духів, про яких говорить Карн. ",
        ["npcs"] = { [1] = 10278 },
        ["roles"] = { ["greeting"] = true },
    },
    [3644958222] = {
        ["english"] = { [1] = "I have no idea who you are, but your presence is most welcome. Archimonde and his Scourge army could attack at any time, $C. Will you stand with us against this evil?" },
        ["text"] = "Я не знаю, хто ви, але ваша присутність дуже доречна. Архімонд і його армія Скари можуть напасти будь-якої миті, $C. Ви станете з нами проти цього зла?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1192215471] = {
        ["english"] = { [1] = "It sure is! Those hives were abuzz with various silithid that were none too happy to see us.$B$BEverything was going fine until we came across a glyphed crystal in Hive'Regal. She was drawn to it like a moth to a flame! She put her pretty little cheek up against the crystal and instantly entered a trance-like state. Naturally, this worried my crew. We picked her up and carried her out of there with a quickness!" },
        ["text"] = "Саме так! Ті вулики гуділи від усіляких силітидів, зовсім не радих нас бачити.$B$BУсе йшло добре, доки у вулику Реґал ми не натрапили на кристал із гліфами. Її потягло до нього, наче метелика до вогню! Вона притулила гарненьку щічку до кристала й миттєво впала в стан, схожий на транс. Звісно, мою команду це занепокоїло. Ми підхопили її й хутко винесли звідти!",
        ["npcs"] = { [1] = 15170 },
        ["roles"] = { ["greeting"] = true },
    },
    [3548571167] = {
        ["english"] = { [1] = "I've seen terrible things happen to the furbolg over the last few years--they were victims on many fronts. But it's unclear to me what's become of this tribe. Are they corrupted by the same plague that's touched Felwood? Or perhaps they are simply angry at what's happened to their once peaceful people and now seek to defend themselves. Either way, most of them appear hostile to those who come into the area." },
        ["text"] = "За останні кілька років я бачив, як із фурболґами траплялися жахливі речі — вони стали жертвами з багатьох боків. Але я не певен, що сталося саме з цим племенем. Їх осквернила та сама чума, що торкнулася Сквернолісся? Чи вони просто розлючені тим, що сталося з їхнім колись мирним народом, і тепер прагнуть захищатися? Хай там як, більшість із них вороже ставиться до тих, хто заходить у ці землі.",
        ["npcs"] = { [1] = 11548 },
        ["roles"] = { ["greeting"] = true },
    },
    [3701467725] = {
        ["english"] = { [1] = "I will teach you what I can." },
        ["text"] = "Я навчу вас того, що можу.",
        ["npcs"] = { [1] = 2855 },
        ["roles"] = { ["greeting"] = true },
    },
    [584456290] = {
        ["english"] = { [1] = "If that is your wish $c, then you will need to speak to Keras Wolfheart on the Warrior's Terrace.  He is a representative of The League of Arathor and can help you to get to Arathi Basin." },
        ["text"] = "Якщо це ваше бажання, $c, вам треба поговорити з Керасом Вовчим Серцем на Терасі Воїнів.  Він представляє Лігу Аратора й допоможе вам дістатися Низини Араті.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4130011636] = {
        ["english"] = { [1] = "I came to the Crossroads from the south seeking help, $c, but I find only cowards who turn their backs on me--even the mighty Thork insults me so. He is a good leader, but his dismissal of my plea causes me greater anger.$B$BHe claims my rage makes me hasty--that it clouds my judgement--but I will not rest until I have vengeance!" },
        ["text"] = "Я прийшов до Роздоріжжя з півдня в пошуках допомоги, $c, та бачу тут лише боягузів, що відвертаються від мене — навіть могутній Торк зневажає мене. Він добрий ватажок, але його відмова вислухати моє прохання лише сильніше розпалює мій гнів.$B$BВін каже, що лють робить мене необачним — що вона затьмарює мій розум, — але я не спочину, доки не помщуся!",
        ["npcs"] = { [1] = 3432 },
        ["roles"] = { ["greeting"] = true },
    },
    [2535981224] = {
        ["english"] = { [1] = "I think I'm beginning to regret undertaking this pilgrimage. I anticipated that the road would be rough and I'm no stranger to travel, but I wasn't prepared for the rigors of Outland.$B$BOn top of everything else, that Taleris seems to want to push me out of here before I've regained my strength completely." },
        ["text"] = "Здається, я вже починаю шкодувати, що взявся за це паломництво. Я очікував важкої дороги й не новачок у мандрах, але до суворості Позамежжя не був готовий.$B$BДо всього іншого, цей Талеріс, схоже, хоче випровадити мене звідси, перш ніж я повністю відновлю сили.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3430423884] = {
        ["english"] = { [1] = "I live only to serve the master." },
        ["text"] = "Я живу лише заради служіння господарю.",
        ["npcs"] = { [1] = 8509 },
        ["roles"] = { ["greeting"] = true },
    },
    [3910730569] = {
        ["english"] = { [1] = "Is this a serious question? You really don't know?$B$BIf you are the cowardly sort, afraid to get their hands too dirty, you will find Dark Iron scraps on the creatures in the Burning Steppes and Searing Gorge.$B$BIf you're the bloodthirsty adventuring type, the dungeons of Blackrock Spire and Blackrock Depths hold quite a large supply of the scraps." },
        ["text"] = "Це серйозне запитання? Ви справді не знаєте?$B$BЯкщо ви боягуз і не хочете надто бруднити руки, уламки Темного Заліза знайдете на істотах у Палаючому степу й Випаленій ущелині.$B$BА якщо ви кровожерливий шукач пригод, у підземеллях Чорнокамінного Шпиля й Глибин Чорнокамінної гори є великі запаси цих уламків.",
        ["npcs"] = { [1] = 16112 },
        ["roles"] = { ["greeting"] = true },
    },
    [3472799615] = {
        ["english"] = { [1] = "I must say, Booty Bay has the best Clam Chowder to be had anywhere in the South Seas. Oh, not interested in cuisine eh? Well then let me be the first to welcome you to the berth of the Maiden's Fancy, the finest passenger ship to travel between the Eastern Kingdoms and Kalimdor. She's due back for another trip to Ratchet soon, so make yourself comfortable till she arrives." },
        ["text"] = "Мушу сказати, у Бухті Наживи найкраща юшка з молюсків у всіх Південних морях. О, кухня вас не цікавить? Тоді дозвольте першим привітати вас біля причалу «Примхи Діви», найкращого пасажирського корабля між Східними Королівствами й Калімдором. Він скоро повернеться для чергового рейсу до Кабестана, тож улаштовуйтеся зручніше, поки не прибуде.",
        ["npcs"] = { [1] = 9559 },
        ["roles"] = { ["greeting"] = true },
    },
    [1386859650] = {
        ["english"] = { [1] = "If you earn enough Brewfest prize tickets, the ticket redeemer in the Brewfest camp can give you an \"Honorary Brewer\" hand stamp.$b$bThat stamp will allow me to sell you a Brewfest riding ram. But they don't come cheap, mind you!" },
        ["text"] = "Якщо заробите достатньо призових жетонів Хмільного фестивалю, обмінювач жетонів у таборі фестивалю поставить вам на руку штамп «Почесного пивовара».$b$bЗ цим штампом я зможу продати вам фестивального верхового барана. Але дешевими вони не бувають!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [985524475] = {
        ["english"] = { [1] = "I said ye had the blood of a blacksmith in ye, and I was right. Go to Ironforge, to The Great Forge, and find yerself a Dwarven smith by the name of Bengus Deepforge. My teacher, and one of the greatest smiths I've ever known." },
        ["text"] = "Я ж казав, у вас кров коваля, і мав рацію. Ідіть до Залізогарта, у Велику Кузню, й знайдіть дворфа-коваля на ім'я Бенґус Глибокогорн. Він був моїм учителем і одним із найкращих ковалів, яких я знав.",
        ["npcs"] = { [1] = 5511 },
        ["roles"] = { ["greeting"] = true },
    },
    [455567510] = {
        ["english"] = { [1] = "I came to this land to cleanse troubled spirits, but after the attack I fear that my mission has failed.  So many have been taken by the wastes.  Please, you must help them." },
        ["text"] = "Я прийшов у ці землі, щоб очистити стривожених духів, але після нападу боюся, що моя місія провалилася.  Стількох забрала пустка.  Будь ласка, ви мусите їм допомогти.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [145765260] = {
        ["english"] = { [1] = "I require flagging." },
        ["text"] = "Мені потрібно позначитися прапорцем.",
        ["npcs"] = { [1] = 16999 },
        ["roles"] = { ["reply"] = true },
    },
    [3595621000] = {
        ["english"] = { [1] = "I must have made a misstep somewhere to be assigned here." },
        ["text"] = "Мабуть, я десь оступився, раз мене призначили сюди.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1889382831] = {
        ["english"] = { [1] = "I will accept your help in this inspection, $c. Do not assume that I will trust your findings or your motives without my own verification." },
        ["text"] = "Я прийму вашу допомогу в цій перевірці, $c. Але не думайте, що повірю вашим висновкам чи мотивам без власного підтвердження.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2179049375] = {
        ["english"] = { [1] = "I haven't got anymore work for you, $N. I do want you to know that the red snapper we shared was something special that I'll never forget..." },
        ["text"] = "У мене більше немає для вас роботи, $N. Але хочу, щоб ви знали: той червоний луціан, яким ми поділилися, був чимось особливим, і я цього ніколи не забуду...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2370154983] = {
        ["english"] = { [1] = "I desire this eternal quintessence, Duke Hydraxis." },
        ["text"] = "Я жадаю цієї вічної квінтесенції, герцогу Гідраксіс.",
        ["npcs"] = { [1] = 13278 },
        ["roles"] = { ["reply"] = true },
    },
    [2875814677] = {
        ["english"] = { [1] = "It is good to see you again, friend." },
        ["text"] = "Радий знову вас бачити, друже.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [10443851] = {
        ["english"] = { [1] = "It was the Lieutenants of Ragnaros, Geddon and Garr, who would perpetrate the betrayal against my Lord. Thunderaan was caught unaware." },
        ["text"] = "Саме лейтенанти Раґнароса, Ґеддон і Ґарр, учинили зраду проти мого повелителя. Тундераана застали зненацька.",
        ["npcs"] = { [1] = 14347 },
        ["roles"] = { ["greeting"] = true },
    },
    [2998663680] = {
        ["english"] = { [1] = "I sent Ranger Salissa south to the enclave and Ranger Lethvalin west to Tranquillien more than a day ago! Have you seen either of them? Are you the aid that's been sent back?" },
        ["text"] = "Я відправив слідопитку Саліссу на південь до анклаву, а слідопита Летваліна — на захід до Транквілліона більше дня тому! Ви бачили когось із них? Ви та допомога, яку прислали у відповідь?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1780549960] = {
        ["english"] = { [1] = "Isn't that adorable! How did you make it out of the Vale? Maybe you should get back there before someone sends a search party after you." },
        ["text"] = "Хіба це не мило! Як ви вибралися з Долини? Може, вам варто повернутися, поки хтось не вислав пошуковий загін.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3076417821] = {
        ["english"] = { [1] = "I heard a rumor that we're all going to go watch the battle with the scourge at the border tonight.  How delightfully wicked!" },
        ["text"] = "Чув чутки, що сьогодні ввечері ми всі підемо дивитися на битву зі Скарою біля кордону.  Яка чарівна гидота!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1400492165] = {
        ["english"] = { [1] = "I love a good challenge; don't you? Aye, of course ye do. An' that's why you're about to do exactly what I say." },
        ["text"] = "Я люблю добрий виклик; а ви? Ага, звісно любите. І саме тому зараз зробите все, що я скажу.",
        ["npcs"] = { [1] = 11097 },
        ["roles"] = { ["greeting"] = true },
    },
    [4030888077] = {
        ["english"] = { [1] = "I'd love to learn more." },
        ["text"] = "Я б залюбки дізнався більше.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [800535404] = {
        ["english"] = { [1] = "I pray for such things." },
        ["text"] = "Я молюся про таке.",
        ["npcs"] = { [1] = 9077 },
        ["roles"] = { ["reply"] = true },
    },
    [2070578652] = {
        ["english"] = { [1] = "I want to create a guild crest." },
        ["text"] = "Я хочу створити герб гільдії.",
        ["npcs"] = { [1] = 3370, [2] = 4161, [3] = 4974, [4] = 5054, [5] = 5130, [6] = 5193 },
        ["roles"] = { ["reply"] = true },
    },
    [1630440883] = {
        ["english"] = { [1] = "I need many more supplies in order to upgrade our units." },
        ["text"] = "Мені потрібно значно більше припасів, щоб поліпшити наші загони.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [850060887] = {
        ["english"] = { [1] = "I have long known you'd seek me out, $N.$B$BEvery sentient being in this world is driven by the choices they make.  Choices begat further choices, and these in turn make someone who they are.  This is where your fortune is drawn from - who you are, and the choices you make.$B$BAre you ready to discover where your fortune lies?" },
        ["text"] = "Я давно знав, що ви мене знайдете, $N.$B$BКожну розумну істоту в цьому світі ведуть зроблені нею вибори. Один вибір породжує інші, а разом вони визначають, ким стає істота. Саме звідси береться ваша доля — з того, ким ви є, і з виборів, які робите.$B$BГотові дізнатися, що приготувала вам доля?",
        ["npcs"] = { [1] = 14822 },
        ["roles"] = { ["greeting"] = true },
    },
    [3507734680] = {
        ["english"] = { [1] = "I've heard that there's a dwarf in Stormwind who has achieved some fame for his hunting skill.  Maybe you should go see if he could help you." },
        ["text"] = "Чув, у Штормовії є дворф, який здобув певну славу своєю мисливською майстерністю.  Може, вам варто знайти його й попросити допомоги.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [4262027158] = {
        ["english"] = { [1] = "It's good to see an engineer brave enough to make the device.   We goblin engineers laugh at danger!" },
        ["text"] = "Добре бачити інженера, досить хороброго, щоб зробити цей пристрій.   Ми, гоблінські інженери, сміємося з небезпеки!",
        ["npcs"] = { [1] = 14742 },
        ["roles"] = { ["greeting"] = true },
    },
    [3714624570] = {
        ["english"] = { [1] = "I have lost my Goblin Transponder. I need another one." },
        ["text"] = "Я загубив свій гоблінський транспондер. Мені потрібен інший.",
        ["npcs"] = { [1] = 7853 },
        ["roles"] = { ["reply"] = true },
    },
    [1355454604] = {
        ["english"] = { [1] = "I hope yer ready to work." },
        ["text"] = "Сподіваюся, ви готові до роботи.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3084715391] = {
        ["english"] = { [1] = "I wanted to scream but only a low gasp escaped my lips. I was promptly beaten for this act of rebellion. As I lay on the ground, I could see Matis pacing in front of Saruan's body. He seemed visibly concerned. He stated that Sironas or Sirona or some such entity would have his flesh flayed from his bones if Saruan had perished in the beatings. $B" },
        ["text"] = "Я хотів закричати, але з моїх вуст вирвався лише тихий стогін. За цей прояв непокори мене одразу побили. Лежачи на землі, я бачив, як Матіс ходить туди-сюди перед тілом Саруана. Він був помітно стурбований. Він сказав, що Сіронас, чи Сірона, чи якась подібна сутність здере з нього шкіру, якщо Саруан помре від побоїв. $B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3819532042] = {
        ["english"] = { [1] = "It's all around us. It's in my head!" },
        ["text"] = "Воно всюди навколо нас. Воно в моїй голові!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2389861027] = {
        ["english"] = { [1] = "It's good to hear the voices of others here in Forest Song again. I'd begun to feel as though I might be the last of the kaldorei ever to set eyes on these lands before their descent into corruption." },
        ["text"] = "Добре знову чути голоси інших тут, у Лісовій Пісні. Я вже починав відчувати, ніби можу бути останнім із калдорай, хто побачить ці землі перед їхнім падінням у скверну.",
        ["npcs"] = { [1] = 3848 },
        ["roles"] = { ["greeting"] = true },
    },
    [302565008] = {
        ["english"] = { [1] = "It's good to have veterans like you in Alterac Valley, $N.  Our supplies are too low to launch a ground assault through Alterac Valley... speak with our quartermaster - he'll tell you how to increase our supply base." },
        ["text"] = "Добре мати таких ветеранів, як ви, в Альтерацькій долині, $N.  Наших запасів замало, щоб почати наземний наступ через Альтерацьку долину... поговоріть із квартирмейстером — він скаже, як збільшити наші запаси.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1123774776] = {
        ["english"] = { [1] = "I lost my Crystal Pylon User's Manual and need another one." },
        ["text"] = "Я загубив Посібник користувача кришталевим пілоном і потребую ще одного.",
        ["npcs"] = { [1] = 9117 },
        ["roles"] = { ["reply"] = true },
    },
    [1269131824] = {
        ["english"] = { [1] = "I will delay here until more reinforcements arrive, but you have to keep moving. We won't have much time until Arthas realizes we're here." },
        ["text"] = "Я затримаюся тут, доки не прибуде підкріплення, але ви маєте рухатися далі. У нас небагато часу, перш ніж Артас зрозуміє, що ми тут.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3262779707] = {
        ["english"] = { [1] = "It's good to be the king!  Now, let's get back to what you were talking about before..." },
        ["text"] = "Добре бути королем!  А тепер повернімося до того, про що ви говорили раніше...",
        ["npcs"] = { [1] = 14353 },
        ["roles"] = { ["reply"] = true },
    },
    [3889463463] = {
        ["english"] = { [1] = "In the age of war, Razelikh the Defiler served as the most fearsome of Lord Kazzak's lieutenants. When the Legion was defeated and Kazzak forced back into the Tainted Scar, Razelikh was tasked by his master to secure the Blasted Lands.$B$BWhile the Alliance fought petty battles with the Horde over territory outside of the Blasted Lands, Razelikh was uniting the differing Shadow Council sects and the brutish Dreadmaul ogres of the land." },
        ["text"] = "В епоху війни Разеліх Осквернитель був найстрашнішим із лейтенантів лорда Каззака. Коли Легіон зазнав поразки, а Каззака загнали назад до Заплямованого Шраму, господар доручив Разеліху закріпитися в Спустошених землях.$B$BПоки Альянс вів дрібні бої з Ордою за території поза Спустошеними землями, Разеліх об'єднував різні секти Ради Тіней і жорстоких огрів Жахобою цих земель.",
        ["npcs"] = { [1] = 7783 },
        ["roles"] = { ["greeting"] = true },
    },
    [735219943] = {
        ["english"] = { [1] = "I'm a prisoner!$B$BThey shot me and my beautiful zeppelin out of the sky. And what for? Because I was ferrying men and materiel for the Horde? That's nothing new!$B$BNow they have me running her in circles around the bay so that they can bomb the pirates. I just don't have the parts to keep her going like this! I'm barely keeping her together on spit and bailing wire!$B$BIf you're determined to help them out, she's due to arrive back in port in less than a minute.$B$BIt's a crime I tell you!" },
        ["text"] = "Я в'язень!$B$BВони збили мене й мій прекрасний дирижабль із неба. І за що? За те, що я перевозив людей і вантажі для Орди? Та це не новина!$B$BТепер вони змушують мене кружляти над затокою, щоб могли бомбити піратів. У мене просто немає деталей, щоб підтримувати його в такому стані! Він ледве тримається на слині й дроті!$B$BЯкщо ви твердо вирішили їм допомогти, він повернеться в порт менш ніж за хвилину.$B$BЦе злочин, кажу вам!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [213219276] = {
        ["english"] = { [1] = "It's going to take a bit of work, but I think we can save this blood elf's life." },
        ["text"] = "Потрібно трохи попрацювати, але, гадаю, ми зможемо врятувати життя цього ельфа крові.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3464960945] = {
        ["english"] = { [1] = "It's getting away!" },
        ["text"] = "Воно тікає!",
        ["npcs"] = { [1] = 14860 },
        ["roles"] = { ["greeting"] = true },
    },
    [2512877839] = {
        ["english"] = { [1] = "I'm sad!  It's Hallow's End, and I'm sick.  I'm going to miss out on trick-or-treating because I can't go out!" },
        ["text"] = "Мені сумно!  Кінець Тиквовину, а я хворію.  Я пропущу випрошування ласощів, бо не можу вийти надвір!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3446105498] = {
        ["english"] = { [1] = "I guess it's all just about over, right $N? I'm going to miss you... it'll be pretty lonely up here without someone to talk to.$B$BBut that doesn't mean that you can't come back to see me in the future!" },
        ["text"] = "Гадаю, все вже майже скінчилося, так, $N? Я сумуватиму за вами... тут буде дуже самотньо, коли ні з ким стане поговорити.$B$BАле це не означає, що ви не зможете навідати мене знову!",
        ["npcs"] = { [1] = 16033 },
        ["roles"] = { ["greeting"] = true },
    },
    [3300890649] = {
        ["english"] = { [1] = "If you are going to Alterac Valley then go speak to Kartra Bloodsnarl. You will find her inside the Hall of the Brave in the Valley of Honor." },
        ["text"] = "Якщо збираєтеся до Альтерацької долини, поговоріть із Картрою Кровогарч. Знайдете її в Залі Хоробрих у Долині Честі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2612533819] = {
        ["english"] = { [1] = "It's fascinating... I have heard orcs proclaim the odor of humans to be sickening and I have heard humans proclaim the odor of orcs to be wretched; yet, to me, all of the races of these lands give off the same odor: The foul, dizzying scent of greed.$B$BDo you doubt the validity of my claim? Do you not see these things that run your life as merely runoff from the greed which dictates your every decision?$B$BSo be it. As it was greed that displaced me from my home, it shall be greed that takes me back." },
        ["text"] = "Це захопливо... Я чув, як орки стверджують, що запах людей огидний, і чув, як люди називають запах орків нестерпним; та для мене всі раси цих земель пахнуть однаково: мерзенним, запаморочливим смородом жадібності.$B$BСумніваєтеся в правдивості моїх слів? Хіба не бачите, що все, що керує вашим життям, — лише стік тієї жадібності, яка диктує кожне ваше рішення?$B$BНехай так. Жадібність вигнала мене з дому — і жадібність поверне мене назад.",
        ["npcs"] = { [1] = 7363 },
        ["roles"] = { ["greeting"] = true },
    },
    [4206579149] = {
        ["english"] = { [1] = "I can teach you the finer points of Mechanostrider Piloting, provided you have enough gold to cover the lesson!" },
        ["text"] = "Я можу навчити вас тонкощів керування механодолгоногом, якщо у вас вистачить золота на урок!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3534651267] = {
        ["english"] = { [1] = "I hope ye didn't come all the way to the Great Forge just to stay warm. Speak up $g lad : lass;, tell me what it is I can do for ye?" },
        ["text"] = "Сподіваюся, ви не йшли аж до Великої Кузні лише погрітися. Кажіть, $g хлопче : дівчино;, чим я можу вам допомогти?",
        ["npcs"] = { [1] = 4258 },
        ["roles"] = { ["greeting"] = true },
    },
    [3799563256] = {
        ["english"] = { [1] = "I was one of the first tauren druids, of the last generation taught by Shan'do Cenarius, before the Legion, before the Sundering, when the world was still young. Before everything changed.$B$BWhile my brethren hunted great beasts, I hunted stories. I had been drawn to the druidic arts by this hunger, this lust for knowledge. For a time, that hunger was sated as I learned to talk to the trees, rocks, and beasts, and heard their stories.$B$BBut then, the time came when Cenarius walked among us no more and my brethren began to forget what he had taught us. I could not forget, though, and I still needed to learn more about our world.$B$BSo I said my farewells and travelled beyond the lands of my people." },
        ["text"] = "Я був одним із перших тауренів-друїдів, з останнього покоління, яке навчав шан'до Кенарій — до Легіону, до Розколу, коли світ іще був молодим. До того, як усе змінилося.$B$BПоки мої брати полювали на великих звірів, я полював на історії. Саме цей голод, ця жага знань привели мене до друїдського мистецтва. Якийсь час голод ущух, коли я навчився говорити з деревами, камінням і звірами та слухати їхні оповіді.$B$BТа настав час, коли Кенарій більше не ходив серед нас, а мої брати почали забувати його науку. Я ж не міг забути й усе ще прагнув дізнатися більше про наш світ.$B$BТож я попрощався й вирушив за межі земель свого народу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3592218548] = {
        ["english"] = { [1] = "It is those two cannons along the wall that are slowing us down.  Without their protection our forces would be able to rush their fortification without taking any losses.$B$BIt's either take out those cannons or wait until they run out of ammunition.  Anselm's choice, I suppose." },
        ["text"] = "Саме ті дві гармати вздовж стіни нас затримують.  Без їхнього прикриття наші війська могли б штурмувати укріплення без втрат.$B$BАбо знищити гармати, або чекати, доки в них скінчаться боєприпаси.  Вибір Ансельма, гадаю.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3684436884] = {
        ["english"] = { [1] = "If you're interested in sewing with leather, you've certainly come to the right place. Faldron and Telonis are true artists, and I hope to learn much from them." },
        ["text"] = "Якщо вас цікавить шиття зі шкіри, ви точно прийшли куди треба. Фалдрон і Телоніс — справжні митці, і я сподіваюся багато в них навчитися.",
        ["npcs"] = { [1] = 11083 },
        ["roles"] = { ["greeting"] = true },
    },
    [3298727132] = {
        ["english"] = { [1] = "If you ever meet Witch Doctor Tor'gash, tell him his concoctions and charms don't work! I did exactly as he told me to and still Magasha has eyes only for Zurai.$B$BDon't believe a thing that sham witch doctor tells you!" },
        ["text"] = "Якщо колись зустрінете знахаря Тор'ґаша, скажіть йому, що його мікстури й обереги не працюють! Я зробив усе точнісінько, як він сказав, а Маґаша й досі дивиться тільки на Зурая.$B$BНе вірте жодному слову того шарлатана-знахаря!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1591040273] = {
        ["english"] = { [1] = "I regret to say that I cannot aid you, $gnoble sir:gentle lady;, until you learn more of working with leather. Speak with Faldron or Darianna here instead. They can teach you the skill you require." },
        ["text"] = "На жаль, я не можу вам допомогти, $gшляхетний пане:ласкава пані;, доки ви не навчитеся краще працювати зі шкірою. Поговоріть натомість із Фалдроном або Даріанною тут. Вони навчать потрібного ремесла.",
        ["npcs"] = { [1] = 4212 },
        ["roles"] = { ["greeting"] = true },
    },
    [1271755158] = {
        ["english"] = { [1] = "I've done my time in the trenches, and spent many years training the pups. It's good to be home. No matter what has become of it, this is my home." },
        ["text"] = "Я відслужив своє в окопах і багато років навчав молодняк. Добре повернутися додому. Хай що з ним сталося, це мій дім.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [206863987] = {
        ["english"] = { [1] = "I have learned much of potions over the long years, $N, and that knowledge is at your disposal. You have only to ask." },
        ["text"] = "За довгі роки я багато дізнався про зілля, $N, і всі ці знання до ваших послуг. Треба лише попросити.",
        ["npcs"] = { [1] = 11042 },
        ["roles"] = { ["greeting"] = true },
    },
    [2752411256] = {
        ["english"] = { [1] = "It is so good to see you, $g brother : sister;!  This place gives me the creeps.  While you're here, be sure to avail yourself of the many opportunities that these so-called Forsaken are providing." },
        ["text"] = "Як же добре вас бачити, $g брате : сестро;!  Від цього місця мороз поза шкірою.  Поки ви тут, неодмінно скористайтеся численними можливостями, які пропонують ці так звані Відречені.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2578273128] = {
        ["english"] = { [1] = "I have a pretty good idea what ol' Greatfather Winter's gonna be doing when this shift is over.  I got a bottle of Winter Veil cheer right here in my bag, and I intend to get to the bottom of it." },
        ["text"] = "Я добре уявляю, що старий Дідусь Зима робитиме після цієї зміни.  У мене в торбі є пляшка зимопокривного веселощів, і я маю намір дістатися до самого дна.",
        ["npcs"] = { [1] = 13444, [2] = 13445 },
        ["roles"] = { ["greeting"] = true },
    },
    [2976566846] = {
        ["english"] = { [1] = "It's been a busy day in the air, eh $N?  Maybe you should take a moment to catch your breath before going back out." },
        ["text"] = "Насичений сьогодні день у небі, еге ж, $N?  Може, вам варто трохи перевести подих, перш ніж знову вирушати.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [29624126] = {
        ["english"] = { [1] = "I've been in the military my whole life.  I've fought in many wars, under many banners - but they've always been other people's battles.$B$BNot this time.  Every Forsaken soldier you see here has come for one reason alone.  Arthas must be killed." },
        ["text"] = "Я все життя у війську.  Бився в багатьох війнах, під багатьма прапорами — але це завжди були чужі битви.$B$BНе цього разу.  Кожен солдат Відречених, якого ви бачите тут, прийшов з однієї причини.  Артас мусить померти.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [114421639] = {
        ["english"] = { [1] = "It's amazing what you can learn from a gnome if you squeeze them hard enough: clever little tricks about getting out of a bind, making delicious cookies, and even how to make a flying machine." },
        ["text"] = "Дивовижно, скільки можна дізнатися від гнома, якщо досить сильно його стиснути: хитрі способи вибратися з халепи, рецепти смачного печива й навіть як зробити літальну машину.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3963212834] = {
        ["english"] = { [1] = "It's always nice when someone wishes to speak to me. How are things with you, $c?" },
        ["text"] = "Завжди приємно, коли хтось хоче зі мною поговорити. Як у вас справи, $c?",
        ["npcs"] = { [1] = 4488 },
        ["roles"] = { ["greeting"] = true },
    },
    [1229735096] = {
        ["english"] = { [1] = "I'm glad you are here, $c. The military situation in the Sunwell Plateau is rather grim." },
        ["text"] = "Радий, що ви тут, $c. Військова ситуація на плато Сонячного Колодязя доволі похмура.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3728150709] = {
        ["english"] = { [1] = "I'd wager Keryn Sylvius knows the type you're looking for. The company Keryn keeps is less than honorable. She usually hangs out in the Lion's Pride Inn." },
        ["text"] = "Закладаюся, Керін Сільвіус знає тип, якого ви шукаєте. Компанія в Керін не надто почесна. Зазвичай вона сидить у заїзді «Левова Гордість».",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [3616833988] = {
        ["english"] = { [1] = "I can teach you the finer points of Skeletal Horse Riding, provided you have enough gold to cover the lesson!" },
        ["text"] = "Я можу навчити вас тонкощів верхової їзди на скелетних конях, якщо у вас вистачить золота на урок!",
        ["npcs"] = { [1] = 4773 },
        ["roles"] = { ["greeting"] = true },
    },
    [2123491325] = {
        ["english"] = { [1] = "Innkeeper Kauth can see to your needs.  He can be found on the west side of the village in one of the long houses." },
        ["text"] = "Корчмар Каут подбає про ваші потреби.  Його можна знайти на західному боці селища в одному з довгих будинків.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [3788449401] = {
        ["english"] = { [1] = "I try to keep Sentinel Hill stocked, and that's not easy with all the action we see." },
        ["text"] = "Я намагаюся тримати Сторожовий Пагорб добре забезпеченим, а з усіма подіями тут це нелегко.",
        ["npcs"] = { [1] = 491 },
        ["roles"] = { ["greeting"] = true },
    },
    [3003552652] = {
        ["english"] = { [1] = "I know just the one that you speak of $c.  You must seek out Brogun Stoneshield on the Warrior's Terrace.", [2] = "I know just the one that you speak of $c. You must seek out Brogun Stoneshield on the Warrior's Terrace." },
        ["text"] = "Я знаю, про кого ви говорите, $c.  Вам треба знайти Броґана Кам'яного Щита на Терасі Воїнів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3744273194] = {
        ["english"] = { [1] = "If you think you have the strength to pound good metal into weapons and armor for the Horde look for Dwukk next to the heated forge in the northwest corner of Razor Hill." },
        ["text"] = "Якщо думаєте, що маєте досить сили кувати з доброго металу зброю й обладунки для Орди, шукайте Двукка біля розпеченої кузні в північно-західному куті Колючого Пагорба.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [2889604776] = {
        ["english"] = { [1] = "I have run through these plains for many, many seasons.  And I have hunted great beasts.  And I had never been bested... until I faced Ghost Howl.$B$BLong ago, the massive wolf was an ally to the tauren and fought bravely against the Burning Legion.  But he was wounded savagely by a demon, and the tear in his flesh never healed.  Eventually... it drove Ghost Howl mad.$B$BNow he roams the plains in agony, seeking an end to his pain.  To my shame, when we fought I lacked the strength to slay him..." },
        ["text"] = "Я бігав цими рівнинами багато-багато сезонів.  І полював на великих звірів.  І ніколи не знав поразки... доки не зустрів Примарного Вия.$B$BКолись давно цей велетенський вовк був союзником тауренів і хоробро бився проти Палаючого Легіону.  Та демон жорстоко поранив його, і рана в його плоті так і не загоїлася.  Зрештою... вона звела Примарного Вия з розуму.$B$BТепер він блукає рівнинами в муках, шукаючи кінця своїм стражданням.  На мій сором, коли ми билися, мені забракло сили його вбити...",
        ["npcs"] = { [1] = 3052 },
        ["roles"] = { ["greeting"] = true },
    },
    [844530592] = {
        ["english"] = { [1] = "If I didnt know better, I'd say this party was organized by orcs!" },
        ["text"] = "Якби я не знав краще, сказав би, що цю вечірку організували орки!",
        ["npcs"] = { [1] = 15908 },
        ["roles"] = { ["greeting"] = true },
    },
    [691367366] = {
        ["english"] = { [1] = "It's all over 'cept for the crying now. All of the war materiel is being transported to Cenarion Hold in Silithus, and will be there in less than $2113w days. Shouldn't be much longer until the scepter is assembled and the war finally begins." },
        ["text"] = "Усе вже скінчилося, лишилося тільки плакати. Усі військові матеріали перевозять до Кенарійської цитаделі в Силітусі, й вони прибудуть менш ніж за $2113w днів. Незабаром скіпетр буде зібрано й війна нарешті почнеться.",
        ["npcs"] = { [1] = 15383 },
        ["roles"] = { ["greeting"] = true },
    },
    [2883186477] = {
        ["english"] = { [1] = "I think he's on the south side of the abbey." },
        ["text"] = "Гадаю, він на південному боці абатства.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [340645807] = {
        ["english"] = { [1] = "I've heard that the preparations are being shipped over to Silithus and should all arrive in under $2113w days. I don't want to see one of those bugs burrowing through into my mine, so I hope that someone is taking the time to assemble that Scepter of the Shifting Sands so the gong can be rung, the gates opened and the war finally begun." },
        ["text"] = "Чув, приготування вже відправляють до Силітуса й усе має прибути менш ніж за $2113w днів. Не хочу побачити, як якась із тих комах прориється в мою копальню, тож сподіваюся, хтось таки збирає Скіпетр Мінливих Пісків, щоб ударити в гонг, відкрити брами й нарешті почати війну.",
        ["npcs"] = { [1] = 15459 },
        ["roles"] = { ["greeting"] = true },
    },
    [3066078446] = {
        ["english"] = { [1] = "It's all over 'cept for the crying now. All of the war materiel is being transported to Cenarion Hold in Silithus, and the last of it will be there in less than a day. Shouldn't be much longer until the scepter is assembled and the war finally begins." },
        ["text"] = "Усе вже скінчилося, лишилося тільки плакати. Усі військові матеріали перевозять до Кенарійської цитаделі в Силітусі, й останні прибудуть менш ніж за день. Незабаром скіпетр буде зібрано й війна нарешті почнеться.",
        ["npcs"] = { [1] = 15383 },
        ["roles"] = { ["greeting"] = true },
    },
    [338458635] = {
        ["english"] = { [1] = "I cannot, Vaelastrasz! Surely something can be done to heal you!" },
        ["text"] = "Не можу, Веластраз! Невже нічого не можна зробити, щоб вас зцілити?!",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2382692667] = {
        ["english"] = { [1] = "It's all guns and flames until someone loses and dies." },
        ["text"] = "Усе весело — гармати й полум'я — доки хтось не програє й не помре.",
        ["npcs"] = { [1] = 9547 },
        ["roles"] = { ["greeting"] = true },
    },
    [219501128] = {
        ["english"] = { [1] = "It's good to see a new face out here. Our outpost is small and our enemies plentiful. We are surrounded by those who seek to destroy us: the satyr to the west, the orcs of the Warsong Lumber camp to the south, and the demons of Felfire Hill.$B$BWe're grateful that the draenei have accepted our invitation to join us in fortifying Forest Song against these myriad threats." },
        ["text"] = "Добре бачити тут нове обличчя. Наша застава мала, а ворогів багато. Нас оточують ті, хто прагне нас знищити: сатири на заході, орки з лісозаготівельного табору Пісні Війни на півдні й демони Пагорба Скверновогню.$B$BМи вдячні, що дренеї прийняли наше запрошення й допомагають укріплювати Лісову Пісню проти цих численних загроз.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2073543207] = {
        ["english"] = { [1] = "It's all a mess, $c, and it's all my fault! I was warned to get out of dock while there was still time, but did I listen? No.$B$BWhat am I going to do now? Those sickly blood elves, the Wretched, have made off with my magical goods, and ate them I think. I'm pretty sure that means they can't be retrieved. And the Grimscale murlocs pirated away the rest of my goods in the dead of night! Furthermore, to kick an honest merchant when she's down, my crew abandoned ship!$B$BI think I'm going to cry." },
        ["text"] = "Усе жахливо, $c, і це все моя провина! Мене попереджали піти з доку, поки був час, але хіба я послухала? Ні.$B$BЩо мені тепер робити? Ті хворобливі ельфи крові, Знедолені, поцупили мої магічні товари й, здається, з'їли їх. Я майже певна, що тепер їх не повернути. А мурлоки Похмурої Луски вночі викрали решту товарів! І щоб остаточно добити чесну торговицю, моя команда покинула корабель!$B$BЗдається, я зараз заплачу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [362284309] = {
        ["english"] = { [1] = "I'm not blind, you know. I can see what's going on around here!" },
        ["text"] = "Я не сліпий, знаєте. Я бачу, що тут відбувається!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2648522561] = {
        ["english"] = { [1] = "I must know something: How did you go to the bathroom with that thing on?", [2] = "I must know something: How did you go to the bathroom with that thing on? " },
        ["text"] = "Мушу знати одне: як ви ходили до вбиральні в тій штуці?",
        ["npcs"] = { [1] = 10776 },
        ["roles"] = { ["reply"] = true },
    },
    [1287212370] = {
        ["english"] = { [1] = "Innkeeper Pala will help you rest your body and spirit.  You can find her in the building just south of the bank on the lower rise." },
        ["text"] = "Корчмарка Пала допоможе вам відпочити тілом і духом.  Знайдете її в будівлі просто на південь від банку на нижньому уступі.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [1025510810] = {
        ["english"] = { [1] = "If we are to be successful in the creation of a portal to the Isle of Quel'Danas, and the Sunwell which rests upon it, we must acquire an energy source powerful enough to ignite the portal.$B$BWe are $3269w percent completed with our efforts. Will you assist us, $c?" },
        ["text"] = "Щоб успішно створити портал на острів Кель'Данас і до Сонячного Колодязя на ньому, нам потрібне досить потужне джерело енергії, щоб запалити портал.$B$BНаші зусилля завершено на $3269w відсотків. Допоможете нам, $c?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2495116500] = {
        ["english"] = { [1] = "It's a testament to our race's tenacity that Fairbreeze Village still stands.  We shall never concede defeat to the Scourge ever again." },
        ["text"] = "Те, що селище Чистий Вітер досі стоїть, свідчить про незламність нашої раси.  Ми більше ніколи не визнаємо поразки від Скари.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3819697936] = {
        ["english"] = { [1] = "It's a simple process for a craftsman of my caliber.$B$BThe most difficult aspect of crafting items out of beast hides and carapace is the actual acquisition of said parts. Now, if you could bring me a pristine hide from this beast, I could make several different powerful items from the flesh." },
        ["text"] = "Для ремісника мого рівня це простий процес.$B$BНайскладніше у виготовленні речей зі шкур і панцирів звірів — власне дістати потрібні частини. Якщо принесете мені бездоганну шкуру цього звіра, я зможу зробити з неї кілька різних могутніх предметів.",
        ["npcs"] = { [1] = 10637 },
        ["roles"] = { ["greeting"] = true },
    },
    [48840184] = {
        ["english"] = { [1] = "I can instruct you in engineering.  Interested?" },
        ["text"] = "Я можу навчити вас інженерії.  Цікавить?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1552114632] = {
        ["english"] = { [1] = "If yer thinking about forming a guild, then ye'll need to put it past Jondor Steelbrow o'er in the Ironforge Visitor's Center.  Just head southeast from the gates of Ironforge to see him." },
        ["text"] = "Якщо думаєте створити гільдію, доведеться погодити це з Джондором Сталебровим у Центрі відвідувачів Залізогарта.  Просто йдіть на південний схід від брами Залізогарта.",
        ["npcs"] = { [1] = 5595, [2] = 274781 },
        ["roles"] = { ["greeting"] = true },
    },
    [3179579259] = {
        ["english"] = { [1] = "I inspect the body further." },
        ["text"] = "Я оглядаю тіло уважніше.",
        ["npcs"] = { [1] = 10668 },
        ["roles"] = { ["reply"] = true },
    },
    [2456012148] = {
        ["english"] = { [1] = "It's a real honor to be able to aid Brann in exploring ancient Ulduar." },
        ["text"] = "Для мене велика честь допомагати Бранну досліджувати стародавній Ульдуар.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [128488336] = {
        ["english"] = { [1] = "Is there anything else?" },
        ["text"] = "Щось іще?",
        ["npcs"] = { [1] = 16116 },
        ["roles"] = { ["reply"] = true },
    },
    [1464874356] = {
        ["english"] = { [1] = "It's a pleasure to see someone sane around here. How can I help you?" },
        ["text"] = "Приємно бачити тут когось при здоровому глузді. Чим можу допомогти?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2172099856] = {
        ["english"] = { [1] = "It's a little late... for that... $G lad:lass;.$B$B<The Frostborn Scout coughs up some blood on the snow.>$B$BGet... that wench in charge for me...$B$B<The Frostborn Scout slumps over as he breathes his last breath.>" },
        ["text"] = "Трохи запізно... для цього... $G хлопче:дівчино;.$B$B<Розвідник Морозонароджених кашляє кров'ю на сніг.>$B$BДістаньте... ту відьму, що тут командує... за мене...$B$B<Розвідник Морозонароджених осідає на землю й робить останній подих.>",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [542970674] = {
        ["english"] = { [1] = "I wish to browse your wares, Calandrath." },
        ["text"] = "Я хочу переглянути ваші товари, Каландрате.",
        ["npcs"] = { [1] = 15174 },
        ["roles"] = { ["reply"] = true },
    },
    [2032178336] = {
        ["english"] = { [1] = "It's a good thing you guys showed up! The Iron Dwarves have pushed us back to this location, and we're barely managing to hold the line here. $B$BEven worse, they've begun to power up their magical defenses. If we don't attack soon, they'll be able to annihilate us in the blink of an eye!$B$BWe've managed to rebuild several siege machines, demolishers and motorcycles from the Alliance and Horde expeditions that were here before us. However, all of our pilots died in the last assault.$B$BYou must take the vehicles and storm the gates of Ulduar! $B$BPlease, $n! You're our last hope!" },
        ["text"] = "Добре, що ви з'явилися! Залізні дворфи відтіснили нас сюди, і ми ледве тримаємо лінію. $B$BЩе гірше — вони почали заряджати магічний захист. Якщо не атакуємо швидко, вони знищать нас миттєво!$B$BНам вдалося відновити кілька облогових машин, нищителів і мотоциклів із експедицій Альянсу й Орди, що були тут до нас. Але всі наші пілоти загинули в останньому штурмі.$B$BВи мусите сісти в машини й штурмувати брами Ульдуару! $B$BБудь ласка, $n! Ви наша остання надія!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4137128749] = {
        ["english"] = { [1] = "I need some booze, Coot." },
        ["text"] = "Мені потрібна випивка, Куте.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [909110561] = {
        ["english"] = { [1] = "I really don't think our situation is so bad.  I am certain it will all be rectified soon and the Sunwell's power will be restored.  It just can't possibly be as bad as everyone is making it out to be." },
        ["text"] = "Я не думаю, що наше становище таке вже погане.  Упевнений, незабаром усе виправлять і силу Сонячного Колодязя відновлять.  Просто не може бути так погано, як усі розповідають.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3826166418] = {
        ["english"] = { [1] = "I'd like to see what you have to sell." },
        ["text"] = "Я хочу подивитися, що ви продаєте.",
        ["npcs"] = { [1] = 233 },
        ["roles"] = { ["reply"] = true },
    },
    [1057805469] = {
        ["english"] = { [1] = "It'll definitely not be anywhere in the Eastern Kingdoms, that's for sure.$B$BIt'll have to be somwhere on Kalimdor, but still far enough away from the Horde and other races. Someplace unaffected by the Sundering--that means no where near the Night elves' civilization either.$B$BI would guess it'd be someplace protected also... like a valley, or a crater. I don't know. I'm just guessing now. I'm sorry I couldn't help you more." },
        ["text"] = "Його точно не буде ніде в Східних Королівствах, це вже напевно.$B$BДесь у Калімдорі, але досить далеко від Орди та інших рас. Десь, куди не дістав Розкол — тобто й не поблизу цивілізації нічних ельфів.$B$BГадаю, це ще й має бути захищене місце... долина чи кратер. Не знаю. Тепер я вже лише гадаю. Вибачте, що не зміг допомогти більше.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2180377319] = {
        ["english"] = { [1] = "I heard they were going to try to blow up the gnome's car in the next race!  True or not, I'd stand clear of their pit area." },
        ["text"] = "Чув, у наступних перегонах вони збираються підірвати машину гномів!  Правда це чи ні, я б тримався подалі від їхніх боксів.",
        ["npcs"] = { [1] = 4429 },
        ["roles"] = { ["greeting"] = true },
    },
    [4117555695] = {
        ["english"] = { [1] = "It appears you took a wrong turn, $c." },
        ["text"] = "Схоже, ви звернули не туди, $c.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1266884216] = {
        ["english"] = { [1] = "It would be wise to explain to you the depths at which our enemies will go to to hide themselves under our noses.$B$BKnow this first and foremost: our enemy is the Shadow Council. No matter what task I give you, or who I ask you to act against, know that one simple fact.$B$BMany cults exist within the Council, but only to hide its actions against the foolish.$B$BGroups like the Burning Blade, the Argus Wake, and the Searing Blade are all tools of the Council. Consider them one and the same." },
        ["text"] = "Варто пояснити вам, наскільки далеко наші вороги готові зайти, щоб ховатися просто в нас під носом.$B$BЗапам'ятайте насамперед: наш ворог — Рада Тіней. Хай яке завдання я дам і проти кого попрошу діяти, пам'ятайте цей простий факт.$B$BУ Раді існує багато культів, але лише для того, щоб приховувати її дії від дурнів.$B$BТакі групи, як Палаючий Клинок, Пробудження Арґуса й Пекучий Клинок, — лише знаряддя Ради. Вважайте їх одним цілим.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2448784901] = {
        ["english"] = { [1] = "I wish to browse your goods, Dirge." },
        ["text"] = "Я хочу переглянути ваші товари, Дірдж.",
        ["npcs"] = { [1] = 8125 },
        ["roles"] = { ["reply"] = true },
    },
    [2509376169] = {
        ["english"] = { [1] = "I'm afraid that the blade which you hold in your hands is beyond saving. The hatred runs too deep. But do not lose hope, $c. Where one chapter has ended, a new one begins.$B$BFind his son - a more devout and pious man you may never meet. It is rumored that he is able to build the Ashbringer anew, without requiring the old, tainted blade." },
        ["text"] = "Боюся, клинок у ваших руках уже не врятувати. Ненависть проникла надто глибоко. Але не втрачайте надії, $c. Там, де закінчується один розділ, починається інший.$B$BЗнайдіть його сина — навряд чи ви зустрінете людину побожнішу й відданішу. Кажуть, він здатен викувати Спопелитель наново, не використовуючи старого, заплямованого клинка.",
        ["npcs"] = { [1] = 4542 },
        ["roles"] = { ["greeting"] = true },
    },
    [2214304096] = {
        ["english"] = { [1] = "I'll be fine for now, don't worry about me.  I'll find a way out of here once I've performed some cleansing rituals in this room.  Foul magic taints this place, $N." },
        ["text"] = "Поки що зі мною все буде гаразд, не хвилюйтеся.  Я знайду вихід звідси, щойно проведу кілька очисних ритуалів у цій кімнаті.  Це місце заплямоване мерзенною магією, $N.",
        ["npcs"] = { [1] = 16031 },
        ["roles"] = { ["greeting"] = true },
    },
    [3288482092] = {
        ["english"] = { [1] = "If my calculations are correct, the wheel will soon be obsolete!" },
        ["text"] = "Якщо мої розрахунки правильні, колесо скоро застаріє!",
        ["npcs"] = { [1] = 5174 },
        ["roles"] = { ["greeting"] = true },
    },
    [1786441509] = {
        ["english"] = { [1] = "I see potential in you $N. Now grab a hammer and some of those scraps, you need a lot of practice." },
        ["text"] = "Я бачу в вас потенціал, $N. А тепер беріться за молот і ті обрізки — вам потрібно дуже багато практики.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2329775224] = {
        ["english"] = { [1] = "I stood by and watched the corruption of Ragnaros seep through the hearts and minds of the Dark Iron nation. This once honorable race, driven to madness... to evil.$B$BWhen the construction of the Spire was complete, my will to live amongst my people gave way. I passed as a hero of the new nation of Dark Iron. This tomb was placed here - at the entrance to the city I planned and built - in honor of my efforts." },
        ["text"] = "Я стояв осторонь і дивився, як скверна Раґнароса просочується в серця й розуми народу Темного Заліза. Колись шляхетна раса, доведена до божевілля... до зла.$B$BКоли будівництво Шпиля завершилося, моє бажання жити серед свого народу згасло. Я помер героєм нової держави Темного Заліза. Цю гробницю поставили тут — біля входу до міста, яке я спланував і збудував, — на честь моїх заслуг.",
        ["npcs"] = { [1] = 8888 },
        ["roles"] = { ["greeting"] = true },
    },
    [107970629] = {
        ["english"] = { [1] = "I have suffered, but now I can feel it slowly fading from me. I feel... free." },
        ["text"] = "Я страждав, але тепер відчуваю, як це поволі відступає. Я почуваюся... вільним.",
        ["npcs"] = { [1] = 9598 },
        ["roles"] = { ["greeting"] = true },
    },
    [3826534710] = {
        ["english"] = { [1] = "I received word that you were able to help Ranger Valanna and the lieutenant at Zeb'Sora.$B$BThank you, $c. I suppose I should make my way back to Farstrider Enclave now." },
        ["text"] = "Мені повідомили, що вам вдалося допомогти слідопитці Валані та лейтенанту в Зеб'Сорі.$B$BДякую, $c. Гадаю, тепер мені слід повернутися до анклаву Далекоходців.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2313527941] = {
        ["english"] = { [1] = "I wish to hear your story." },
        ["text"] = "Я хочу почути вашу історію.",
        ["npcs"] = { [1] = 7783 },
        ["roles"] = { ["reply"] = true },
    },
    [477564827] = {
        ["english"] = { [1] = "It would appear dear that the Alliance has managed to collect everything needed for the war effort. Now all that we're waiting on are those poor Horde creatures to finish with theirs." },
        ["text"] = "Схоже, люба, Альянсу вдалося зібрати все потрібне для війни. Тепер ми лише чекаємо, коли ті бідолашні створіння Орди закінчать зі своїм.",
        ["npcs"] = { [1] = 15432 },
        ["roles"] = { ["greeting"] = true },
    },
    [3186543867] = {
        ["english"] = { [1] = "I guess the spirits like you better than me, I still have not heard their call but you seem to have gathered their lessons well. Go speak to Karn, he will be excited to see one who hears them as he does." },
        ["text"] = "Схоже, духи люблять вас більше, ніж мене. Я й досі не чув їхнього поклику, а ви, здається, добре засвоїли їхні уроки. Поговоріть із Карном — він зрадіє зустрічі з тим, хто чує їх так само, як він.",
        ["npcs"] = { [1] = 10278 },
        ["roles"] = { ["greeting"] = true },
    },
    [4287239757] = {
        ["english"] = { [1] = "If it weren't for those damned beasts burning our ships, we'd have been home by now. Now leave me alone so I can get back to work!" },
        ["text"] = "Якби не ті кляті звірі, що спалили наші кораблі, ми вже були б удома. А тепер дайте мені спокій, щоб я повернувся до роботи!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1227362689] = {
        ["english"] = { [1] = "It will be a matter of hours before the Alliance in the Derelict Strand are crushed.  They are surrounded and outnumbered." },
        ["text"] = "За кілька годин Альянс на Покинутому узбережжі буде розгромлено.  Вони оточені й поступаються числом.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3811735691] = {
        ["english"] = { [1] = "It was not until after his controversial death that the knights and warriors of Lordaeron would wear similarly fashioned suits in honor of their fallen hero. While the death of Mograine was a great victory for Kel'Thuzad, the resulting martyrdom would be felt until the end of the war.$B$BWhere one did fall, many would rise..." },
        ["text"] = "Лише після його суперечливої смерті лицарі й воїни Лордерону почали носити обладунки подібного фасону на честь полеглого героя. Хоч смерть Моґрейна була великою перемогою Кел'Тузада, наслідки його мучеництва відчувалися до самого кінця війни.$B$BДе впав один, постали б багато...",
        ["npcs"] = { [1] = 16112 },
        ["roles"] = { ["greeting"] = true },
    },
    [3444100489] = {
        ["english"] = { [1] = "I cannot in good conscience spend time training novices while our allies, the undead, are suffering so terribly. Please speak with Kray over there instead; he can help you for now." },
        ["text"] = "Совість не дозволяє мені витрачати час на навчання новачків, поки наші союзники-невмерлі так жахливо страждають. Будь ласка, поговоріть натомість із Креєм — поки що він вам допоможе.",
        ["npcs"] = { [1] = 3009 },
        ["roles"] = { ["greeting"] = true },
    },
    [2451922579] = {
        ["english"] = { [1] = "It was not so long ago that we had to wrest control of Thunderlord Stronghold from the nearby ogres.$B$BYou are here to help us maintain our defenses?  I know that Gor'drek is looking for assistance." },
        ["text"] = "Ще зовсім недавно нам довелося відбивати твердиню Громовержців у сусідніх огрів.$B$BВи тут, щоб допомогти нам тримати оборону?  Знаю, Ґор'дрек шукає помічників.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1252537821] = {
        ["english"] = { [1] = "I'm not about to train you until you're exalted in the eyes of the draenei." },
        ["text"] = "Я й не подумаю вас навчати, доки ви не досягнете звеличення в очах дренеїв.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3811324756] = {
        ["english"] = { [1] = "I have about half the supplies needed to upgrade to champion units." },
        ["text"] = "У мене є приблизно половина припасів, потрібних для поліпшення загонів до чемпіонів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3920595479] = {
        ["english"] = { [1] = "In building of War Quarter on outer ring of city." },
        ["text"] = "У споруджуваному Військовому кварталі на зовнішньому кільці міста.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [244448049] = {
        ["english"] = { [1] = "If you not talk to Mizzle, you not become da king!  Take to Mizzle da Crafty!" },
        ["text"] = "Як не поговориш із Міззлом, королем не станеш!  Іди до Міззла Хитрого!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [462347050] = {
        ["english"] = { [1] = "I confiscate the corn he has stolen, warn him that stealing is a path towards doom and destruction, but I let him go to return to his family." },
        ["text"] = "Я конфіскую в нього вкрадену кукурудзу, попереджаю, що крадіжка — шлях до загибелі й руйнування, але відпускаю його назад до сім'ї.",
        ["npcs"] = { [1] = 14822 },
        ["roles"] = { ["reply"] = true },
    },
    [1094604239] = {
        ["english"] = { [1] = "It is one of the synthesis matrices the Creators use when seeding a world.  Each synthesis matrix is used to achieve the Creators' goals.  For Azeroth, a subterranean being matrix was modified to create a being with increased durability with an affinity for deep region shaping; the Earthen are the product of this modification.$B$BAfter the Earthen had been put into service for the Creators, unforeseen anomalies were discovered that affected their synthesis matrix due to high-stress environments." },
        ["text"] = "Це одна з матриць синтезу, які Творці використовують, заселяючи світ.  Кожна матриця синтезу служить досягненню цілей Творців.  Для Азероту матрицю підземної істоти змінили, щоб створити істоту з підвищеною витривалістю й схильністю до формування глибинних областей; результатом цієї зміни стали земельники.$B$BПісля введення земельників у службу Творців було виявлено непередбачені аномалії, які в умовах високого навантаження впливали на їхню матрицю синтезу.",
        ["npcs"] = { [1] = 7172 },
        ["roles"] = { ["greeting"] = true },
    },
    [1833570114] = {
        ["english"] = { [1] = "It was kind of the Explorers' League to allow me to tag along. However, with the dangers in the Rivenwood and surrounding area, it looks like it may have been foolish of me to come without help." },
        ["text"] = "З боку Ліги дослідників було люб'язно дозволити мені приєднатися. Та з огляду на небезпеки в Розколотому Лісі й околицях, схоже, з мого боку було нерозумно приходити без допомоги.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3601653751] = {
        ["english"] = { [1] = "Is it not astonishing what one can create from the plants of the forest? Truly, Elune has blessed us with her bounty." },
        ["text"] = "Хіба не дивовижно, що можна створити з лісових рослин? Воістину, Елуна благословила нас своїми дарами.",
        ["npcs"] = { [1] = 11041 },
        ["roles"] = { ["greeting"] = true },
    },
    [4200450434] = {
        ["english"] = { [1] = "I can instruct you in tailoring.  Interested?" },
        ["text"] = "Я можу навчити вас кравецтва.  Цікавить?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1441419435] = {
        ["english"] = { [1] = "I heard that a noble among the water elementals, Hydraxis, wages war with the servants of fire.  Let's hope he loses!" },
        ["text"] = "Чув, що один шляхтич серед водяних елементалів, Гідраксіс, воює зі слугами вогню.  Сподіваймося, він програє!",
        ["npcs"] = { [1] = 9545 },
        ["roles"] = { ["greeting"] = true },
    },
    [2189331345] = {
        ["english"] = { [1] = "It was lost when the Violet Citadel fell... splintered into forty-two pieces." },
        ["text"] = "Його втратили, коли впала Фіолетова Цитадель... він розлетівся на сорок два уламки.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [675699845] = {
        ["english"] = { [1] = "I need to know where the princess are, Kharan!" },
        ["text"] = "Я мушу знати, де принцеси, Каране!",
        ["npcs"] = { [1] = 9021 },
        ["roles"] = { ["reply"] = true },
    },
    [312194614] = {
        ["english"] = { [1] = "It was High General Abbendis, High Inquisitor Isillien, and Highlord Mograine that formed the Crusade. In its infancy, the Crusade was a noble order. The madness and insane zealotry that you see now did not exist. It was not until the one known as the Grand Crusader appeared that the wheels of corruption were set in motion." },
        ["text"] = "Саме верховний генерал Аббендіс, верховний інквізитор Ісіллієн і верховний лорд Моґрейн заснували Похід. На початку Похід був шляхетним орденом. Того безумства й шаленого фанатизму, які ви бачите тепер, не існувало. Лише з появою того, кого назвали Великим Хрестоносцем, колеса скверни почали крутитися.",
        ["npcs"] = { [1] = 4542 },
        ["roles"] = { ["greeting"] = true },
    },
    [3502844233] = {
        ["english"] = { [1] = "I bet Illidan is a nice guy underneath.  He just needs a mama, too." },
        ["text"] = "Б'юся об заклад, у глибині душі Іллідан — славний хлопець.  Йому теж просто потрібна матуся.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [491380910] = {
        ["english"] = { [1] = "It was during the Elemental Sundering that the Firelord, Ragnaros, would seek to consume my Lord, Thunderaan, Prince of Air.$B$B<Demitrian bows his head, his face contorted in rage.>$B$BSpeak his name and I shall decorate this ravaged camp with your entrails. Be silent and listen.\010" },
        ["text"] = "Саме під час Стихійного Розколу Володар Вогню Раґнарос спробував поглинути мого повелителя Тундераана, Принца Повітря.$B$B<Демітріан схиляє голову, його обличчя спотворює лють.>$B$BВимовте його ім'я — і я прикрашу цей спустошений табір вашими нутрощами. Мовчіть і слухайте.\010",
        ["npcs"] = { [1] = 14347 },
        ["roles"] = { ["greeting"] = true },
    },
    [3810378094] = {
        ["english"] = { [1] = "It was all I could do to feign death as the corpses of the Scourge piled upon me. There was darkness and only the muffled sounds of the battle above me. The clashing of iron, the gnashing and grinding... gruesome, terrible sounds. And then there was silence. He called to me! \"Fairbanks! Fairbanks where are you? Talk to me Fairbanks!\" And then came the sound of incredulousness. The bite of betrayal, $r..." },
        ["text"] = "Мені лишалося тільки прикинутися мертвим, поки трупи Скари навалювалися на мене. Навколо була темрява й лише приглушені звуки битви згори. Дзвін заліза, скрегіт і хрускіт... моторошні, жахливі звуки. А потім настала тиша. Він кликав мене! «Феєрбенкс! Феєрбенкс, де ти? Відповідай, Феєрбенкс!» А потім у голосі з'явилося невір'я. Гіркота зради, $r...",
        ["npcs"] = { [1] = 4542 },
        ["roles"] = { ["greeting"] = true },
    },
    [2975949711] = {
        ["english"] = { [1] = "It takes a lot of dedication to train and ride a Venomhide." },
        ["text"] = "Щоб навчити й осідлати Отрутошкура, потрібна велика відданість.",
        ["npcs"] = { [1] = 11701 },
        ["roles"] = { ["greeting"] = true },
    },
    [4128692926] = {
        ["english"] = { [1] = "I overheard Regnus Thundergranite in the Hall of Arms bragging about a new trophy for his den the other day.  If yer looking for training from a skilled hunter, Regnus is the one to see." },
        ["text"] = "Днями я чув, як Реґнус Громограніт у Залі Зброї хвалився новим трофеєм для свого лігва.  Якщо шукаєте навчання в умілого мисливця, вам до Реґнуса.",
        ["npcs"] = { [1] = 5595, [2] = 274781 },
        ["roles"] = { ["greeting"] = true },
    },
    [2504647065] = {
        ["english"] = { [1] = "It seems the army of the Scourge has come to Tanaris. A significant number of their necropolises and other forces have been dispatched there.$B$BNumber of Necropolises remaining: $2283W" },
        ["text"] = "Схоже, армія Скари прийшла до Танарісу. Туди відправили значну кількість некрополів та інших сил.$B$BНекрополів залишилося: $2283W",
        ["npcs"] = { [1] = 16285, [2] = 16359 },
        ["roles"] = { ["greeting"] = true },
    },
    [429395212] = {
        ["english"] = { [1] = "I don't get many visitors.  You're looking for something specific, yes?" },
        ["text"] = "До мене нечасто заходять.  Ви шукаєте щось конкретне, так?",
        ["npcs"] = { [1] = 4616 },
        ["roles"] = { ["greeting"] = true },
    },
    [3033486624] = {
        ["english"] = { [1] = "It seems like love is drifting on the wind. I hope that I won't be left out." },
        ["text"] = "Схоже, кохання витає в повітрі. Сподіваюся, мене не оминуть.",
        ["npcs"] = { [1] = 2987, [2] = 2997, [3] = 2999, [4] = 3002, [5] = 3003, [6] = 3005, [7] = 3010, [8] = 3012, [9] = 3014, [10] = 3015, [11] = 3016, [12] = 3017, [13] = 3018, [14] = 3019, [15] = 3020, [16] = 3021, [17] = 3022, [18] = 3023, [19] = 3024, [20] = 3025, [21] = 3027, [22] = 3029, [23] = 3037, [24] = 3050, [25] = 3084, [26] = 3092, [27] = 3093, [28] = 3095, [29] = 3447, [30] = 3978, [31] = 4451, [32] = 4721, [33] = 5770, [34] = 5906, [35] = 6410, [36] = 7793, [37] = 8358, [38] = 8360, [39] = 8361, [40] = 8362, [41] = 8363, [42] = 8364, [43] = 8398, [44] = 14182 },
        ["roles"] = { ["greeting"] = true },
    },
    [2296950533] = {
        ["english"] = { [1] = "I'm here to aid the Captain." },
        ["text"] = "Я тут, щоб допомогти капітану.",
        ["npcs"] = { [1] = 15443 },
        ["roles"] = { ["reply"] = true },
    },
    [633295483] = {
        ["english"] = { [1] = "I'm sorry $g mon : sis;, but I won't be sellin' my raptors to someone who hasn't proven themselves to be exalted to the Darkspear tribe.  When ya make a stand and show yourself to be no less than exalted to us, then I'll make my raptors available to ya." },
        ["text"] = "Вибач, $g друже : сестро;, але я не продаватиму своїх рапторів тому, хто не довів, що досяг звеличення серед племені Темносписа.  Коли покажеш себе гідним звеличення в наших очах, тоді й дам тобі доступ до своїх рапторів.",
        ["npcs"] = { [1] = 7952 },
        ["roles"] = { ["greeting"] = true },
    },
    [2296507298] = {
        ["english"] = { [1] = "It remains to be seen if you are ready, young one.  Even the wisest and oldest of druids are never truly ready when their ultimate time of testing comes.$B$BYou have heard my words, and now you must move on.  Heed what I have taught you.  There will be a time when you will have your strength tested.  You must face your foe as the bear would - with strength of body and with strength of heart.  Learn from the fight, young one.  Go... with my blessings." },
        ["text"] = "Ще треба побачити, чи ви готові, юний друже.  Навіть наймудріші й найстарші друїди ніколи не бувають по-справжньому готові, коли приходить їхнє найвище випробування.$B$BВи почули мої слова, а тепер мусите йти далі.  Пам'ятайте мою науку.  Настане час, коли вашу силу випробують.  Ви маєте зустріти ворога як ведмідь — із силою тіла й силою серця.  Вчіться з бою, юний друже.  Ідіть... з моїм благословенням.",
        ["npcs"] = { [1] = 11956 },
        ["roles"] = { ["greeting"] = true },
    },
    [1211495085] = {
        ["english"] = { [1] = "I have payed your price, Gloom'rel.  Now, teach me your secrets!" },
        ["text"] = "Я сплатив вашу ціну, Похмур'реле.  Тепер навчіть мене своїх таємниць!",
        ["npcs"] = { [1] = 9037 },
        ["roles"] = { ["reply"] = true },
    },
    [1632696586] = {
        ["english"] = { [1] = "I... I am badly injured... " },
        ["text"] = "Я... я тяжко поранений... ",
        ["npcs"] = { [1] = 10740 },
        ["roles"] = { ["greeting"] = true },
    },
    [3725170790] = {
        ["english"] = { [1] = "I don't know what's come over me. My heart feels as hot as new steel." },
        ["text"] = "Не знаю, що зі мною коїться. Моє серце гаряче, мов щойно викувана сталь.",
