    [261075916] = {
        ["english"] = { [1] = "I do not believe you possess the mental acuity to grasp the nature of portal magic.$B$BHowever, you can use the crystal behind me to teleport to the ruins below Dalaran in Crystalsong Forest." },
        ["text"] = "Не думаю, що вашої гостроти розуму достатньо, аби осягнути природу портальної магії.$B$BУтім, ви можете скористатися кристалом позаду мене, щоб телепортуватися до руїн під Далараном у Лісі Кришталевої Пісні.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3512000099] = {
        ["english"] = { [1] = "I don't think you want to learn anything I can teach. Might want to find a $c trainer to help you out." },
        ["text"] = "Не думаю, що ви хочете вчитися чогось із того, що я можу запропонувати. Краще знайдіть наставника для $c — він допоможе.",
        ["npcs"] = { [1] = 915, [2] = 918, [3] = 1411, [4] = 13283 },
        ["roles"] = { ["greeting"] = true },
    },
    [3153584889] = {
        ["english"] = { [1] = "I have what you need, $c." },
        ["text"] = "У мене є те, що вам потрібно, $c.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
