    [3190447673] = {
        ["english"] = { [1] = "I wish to buy from you." },
        ["text"] = "Я хочу купити у вас.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [1721896392] = {
        ["english"] = { [1] = "I will do this with or without your help, Loramus.", [2] = "I will do this with or without your help, Loramus.\010" },
        ["text"] = "Я зроблю це з вашою допомогою чи без неї, Лорамусе.",
        ["npcs"] = { [1] = 7783 },
        ["roles"] = { ["reply"] = true },
    },
    [781157939] = {
        ["english"] = { [1] = "It looks like help has finally arrived!  The Omenai welcome you to our remnant camp, $N." },
        ["text"] = "Схоже, допомога нарешті прибула!  Оменай вітають вас у нашому таборі вцілілих, $N.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2941732847] = {
        ["english"] = { [1] = "I require warrior training." },
        ["text"] = "Мені потрібне навчання воїна.",
        ["npcs"] = { [1] = 911, [2] = 912, [3] = 913, [4] = 914, [5] = 985, [6] = 1229, [7] = 1901, [8] = 2119, [9] = 2131, [10] = 3041, [11] = 3042, [12] = 3043, [13] = 3059, [14] = 3063, [15] = 3153, [16] = 3169, [17] = 3353, [18] = 3354, [19] = 3408, [20] = 3593, [21] = 3598, [22] = 4087, [23] = 4089, [24] = 4593, [25] = 4594, [26] = 4595, [27] = 5113, [28] = 5114, [29] = 5479, [30] = 5480, [31] = 7315 },
        ["roles"] = { ["reply"] = true },
    },
    [226216499] = {
        ["english"] = { [1] = "If you ask me, the best part about fishing is its slow pace.  It gives one time to think, to reflect on past events and to plan for future ones.$B$BOh, and it's also a great excuse to drink.  Heavily." },
        ["text"] = "Як на мене, найкраще в рибальстві — його повільний темп.  Він дає час подумати, згадати минулі події й спланувати майбутні.$B$BО, а ще це чудовий привід випити.  Багато.",
        ["npcs"] = { [1] = 12919 },
        ["roles"] = { ["greeting"] = true },
    },
    [1076782532] = {
        ["english"] = { [1] = "I have lost my Ring of Infinite Wisdom. Are you able to replace it for me?" },
        ["text"] = "Я загубив свій Перстень безмежної мудрості. Можете замінити його?",
        ["npcs"] = { [1] = 15498 },
        ["roles"] = { ["reply"] = true },
    },
    [289924542] = {
        ["english"] = { [1] = "Isn't this just so much fun? I'm so glad that Lord Saltheril throws these parties every night, especially with all of that nastiness occurring to the south. Kind of just makes all of that go away, don't you think?" },
        ["text"] = "Хіба це не чудова розвага? Я так рада, що лорд Салтеріль влаштовує ці вечірки щовечора, особливо коли на півдні коїться вся та гидота. Наче все те просто зникає, правда?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3233354346] = {
        ["english"] = { [1] = "If you manage to complete a deck of Portals cards you will be rewarded with a Greater Darkmoon card of the Twisting Nether.   This card will occasionally pull your spirit back into your body after death and restore you." },
        ["text"] = "Якщо вам удасться зібрати повну колоду карт Порталів, ви отримаєте Велику карту Темного Місяця Підсвітньої Крутоверті.   Вона час від часу повертатиме ваш дух у тіло після смерті й відновлюватиме вас.",
        ["npcs"] = { [1] = 14847 },
        ["roles"] = { ["greeting"] = true },
    },
    [2464684423] = {
        ["english"] = { [1] = "I've misplaced the Brazier of Beckoning!" },
        ["text"] = "Я десь подів Жаровню Закликання!",
        ["npcs"] = { [1] = 16033 },
        ["roles"] = { ["reply"] = true },
    },
    [690989542] = {
        ["english"] = { [1] = "It is Vesprystus that you seek.  He watches over the hippogryphs that come and go from the base of Teldrassil.  You will find him through the portal in western Darnassus that will take you to Rut'theran Village." },
        ["text"] = "Вам потрібен Весприст.  Він доглядає за гіпогрифами, що прилітають і відлітають від підніжжя Тельдрассіля.  Знайдете його через портал у західному Дарнасі, що веде до селища Рут'теран.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [464184396] = {
        ["english"] = { [1] = "I'm lonely.  I wish that there were more kids my age around here.  Sometimes I miss being at the orphanage in Shattrath City." },
        ["text"] = "Мені самотньо.  Хотілося б, щоб тут було більше дітей мого віку.  Іноді я сумую за сиротинцем у Шаттраті.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1844936374] = {
        ["english"] = { [1] = "If a hunter is whom you seek, then it is Dazalar that you should visit.  He can usually be found just outside the Inn in Dolanaar." },
        ["text"] = "Якщо шукаєте мисливця, вам потрібен Дазалар.  Зазвичай його можна знайти просто біля заїзду в Доланаарі.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [1218043089] = {
        ["english"] = { [1] = "It is very kind of you to ask after our needs, $c. It would appear though that we have collected all of the runecloth bandages we feel we'll need of the war. May I ask that you inquire around with some of the other collectors and lend them your aid if needed? Ancestors watch over you." },
        ["text"] = "Дуже люб'язно, що ви питаєте про наші потреби, $c. Та схоже, ми вже зібрали всі бинти з рунічної тканини, які, на нашу думку, знадобляться для війни. Чи можу попросити вас розпитати інших збирачів і допомогти їм, якщо потрібно? Хай предки вас бережуть.",
        ["npcs"] = { [1] = 15532 },
        ["roles"] = { ["greeting"] = true },
    },
    [3623493816] = {
        ["english"] = { [1] = "I wish we had a priest or a druid out here. I can't continue my studies until I've recovered from my injuries." },
        ["text"] = "Хотілося б, щоб тут був жрець або друїд. Я не можу продовжувати дослідження, доки не оговтаюся від поранень.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1016925622] = {
        ["english"] = { [1] = "I have not come to kill you, night elf. And the gods did not do this..." },
        ["text"] = "Я прийшов не вбивати тебе, нічний ельфе. І це зробили не боги...",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2239110593] = {
        ["english"] = { [1] = "It is very important that we find out what the the night elves are up to, $c! Please concentrate all of your efforts toward that end." },
        ["text"] = "Дуже важливо з'ясувати, що задумали нічні ельфи, $c! Будь ласка, зосередьте всі зусилля на цьому.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [792537735] = {
        ["english"] = { [1] = "I wish to unlearn my talents." },
        ["text"] = "Я хочу забути свої таланти.",
        ["npcs"] = { [1] = 198, [2] = 328, [3] = 331, [4] = 375, [5] = 376, [6] = 377, [7] = 459, [8] = 460, [9] = 461, [10] = 837, [11] = 895, [12] = 906, [13] = 911, [14] = 912, [15] = 913, [16] = 914, [17] = 915, [18] = 916, [19] = 917, [20] = 918, [21] = 925, [22] = 926, [23] = 927, [24] = 928, [25] = 944, [26] = 985, [27] = 986, [28] = 987, [29] = 988, [30] = 1226, [31] = 1228, [32] = 1229, [33] = 1231, [34] = 1232, [35] = 1234, [36] = 1404, [37] = 1411, [38] = 1901, [39] = 2119, [40] = 2122, [41] = 2123, [42] = 2124, [43] = 2126, [44] = 2127, [45] = 2128, [46] = 2129, [47] = 2130, [48] = 2131, [49] = 3030, [50] = 3031, [51] = 3032, [52] = 3033, [53] = 3034, [54] = 3036, [55] = 3038, [56] = 3039, [57] = 3040, [58] = 3041, [59] = 3042, [60] = 3043, [61] = 3044, [62] = 3045, [63] = 3046, [64] = 3047, [65] = 3048, [66] = 3049, [67] = 3059, [68] = 3060, [69] = 3061, [70] = 3062, [71] = 3063, [72] = 3064, [73] = 3065, [74] = 3066, [75] = 3153, [76] = 3154, [77] = 3155, [78] = 3156, [79] = 3157, [80] = 3169, [81] = 3170, [82] = 3171, [83] = 3172, [84] = 3173, [85] = 3324, [86] = 3325, [87] = 3326, [88] = 3327, [89] = 3328, [90] = 3344, [91] = 3352, [92] = 3353, [93] = 3354, [94] = 3401, [95] = 3403, [96] = 3406, [97] = 3407, [98] = 3408, [99] = 3593, [100] = 3594, [101] = 3595, [102] = 3596, [103] = 3597, [104] = 3598, [105] = 3599, [106] = 3600, [107] = 3601, [108] = 3602, [109] = 3706, [110] = 3707, [111] = 3963, [112] = 4087, [113] = 4089, [114] = 4090, [115] = 4091, [116] = 4092, [117] = 4138, [118] = 4163, [119] = 4205, [120] = 4214, [121] = 4215, [122] = 4217, [123] = 4218, [124] = 4219, [125] = 4563, [126] = 4564, [127] = 4565, [128] = 4566, [129] = 4567, [130] = 4568, [131] = 4582, [132] = 4583, [133] = 4584, [134] = 4593, [135] = 4594, [136] = 4595, [137] = 4606, [138] = 4607, [139] = 4608, [140] = 5113, [141] = 5114, [142] = 5115, [143] = 5116, [144] = 5117, [145] = 5141, [146] = 5142, [147] = 5143, [148] = 5144, [149] = 5145, [150] = 5146, [151] = 5147, [152] = 5148, [153] = 5149, [154] = 5165, [155] = 5166, [156] = 5167, [157] = 5171, [158] = 5172, [159] = 5173, [160] = 5479, [161] = 5480, [162] = 5484, [163] = 5489, [164] = 5491, [165] = 5492, [166] = 5495, [167] = 5496, [168] = 5497, [169] = 5498, [170] = 5501, [171] = 5504, [172] = 5505, [173] = 5506, [174] = 5515, [175] = 5516, [176] = 5517, [177] = 5612, [178] = 5880, [179] = 5882, [180] = 5883, [181] = 5884, [182] = 5885, [183] = 5994, [184] = 6014, [185] = 6018, [186] = 6707, [187] = 7311, [188] = 7312, [189] = 7315, [190] = 8140, [191] = 8141, [192] = 8142, [193] = 8308, [194] = 9465, [195] = 10930, [196] = 11397, [197] = 11401, [198] = 11406, [199] = 12042, [200] = 13283, [201] = 13417 },
        ["roles"] = { ["reply"] = true },
    },
    [2784977548] = {
        ["english"] = { [1] = "Is there anything you can pay me to do?" },
        ["text"] = "Є щось, за що ви можете мені заплатити?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3099963341] = {
        ["english"] = { [1] = "If it weren't for the Grim Guzzler, I'd spend my free time pulling the wings off dragon whelps." },
        ["text"] = "Якби не «Похмурий Ненажера», я у вільний час відривав би крила драконятам.",
        ["npcs"] = { [1] = 9545 },
        ["roles"] = { ["greeting"] = true },
    },
    [3413483658] = {
        ["english"] = { [1] = "It is true, young $r, we and the Alliance have gathered and prepared all that we will need for this upcoming conflict at Ahn'Qiraj. Even now these things are being sent to Cenarion Hold, and they should all arrive within $2113w days. After all is in place, some person will need to ring the gong on the Scarab Dais to open the gates and start the war." },
        ["text"] = "Це правда, юний $r: ми з Альянсом зібрали й підготували все потрібне для прийдешнього конфлікту в Ан'Кіражі. Уже зараз усе це відправляють до Кенарійської цитаделі, і все має прибути протягом $2113w днів. Коли все буде на місці, хтось муситиме вдарити в гонг на Постаменті Скарабея, щоб відкрити брами й почати війну.",
        ["npcs"] = { [1] = 15477 },
        ["roles"] = { ["greeting"] = true },
    },
    [690464845] = {
        ["english"] = { [1] = "I have a rock in my nose." },
        ["text"] = "У мене в носі камінь.",
        ["npcs"] = { [1] = 14444 },
        ["roles"] = { ["greeting"] = true },
    },
    [2352785627] = {
        ["english"] = { [1] = "I tend these creatures of Gormok as he cannot. I do not fully agree with this slaughter, but at the least he will have his chance to fight." },
        ["text"] = "Я доглядаю цих створінь Ґормока, бо він не може. Я не цілком схвалюю цю різанину, але принаймні він отримає нагоду битися.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1894543008] = {
        ["english"] = { [1] = "I can smell the gunpowder from all the bombs and rockets!  You want to get out there and join the fun?" },
        ["text"] = "Я чую запах пороху від усіх цих бомб і ракет!  Хочете вийти туди й долучитися до веселощів?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3638186152] = {
        ["english"] = { [1] = "I want to buy another stink bomb!" },
        ["text"] = "Я хочу купити ще одну смердючу бомбу!",
        ["npcs"] = { [1] = 15197 },
        ["roles"] = { ["reply"] = true },
    },
    [621072713] = {
        ["english"] = { [1] = "I swear... if Quint tries to plant one more fishing grub on me, I'm going to hack down his tree with my not-so-rusty sword." },
        ["text"] = "Клянуся... якщо Квінт іще раз підкине мені рибальського хробака, я зрубаю його дерево своїм не таким уже й іржавим мечем.",
        ["npcs"] = { [1] = 7852 },
        ["roles"] = { ["greeting"] = true },
    },
    [3098960808] = {
        ["english"] = { [1] = "I shouldn't even be telling you this but if you can make it past all the critters and beasties in Badlands, you might be able to make it to Searing Gorge.$B$BYes, the Badlands. There's some type of back road the orcs paved near Kargath. Just goes to show you what kind of fools we're dealing with here! A backdoor to hell? What were they thinking?" },
        ["text"] = "Мені взагалі не слід вам цього казати, але якщо проберетеся повз усіх тварюк і звірів Безплідних країв, то, можливо, дістанетеся до Випаленої ущелини.$B$BТак, Безплідні краї. Орки проклали якусь обхідну дорогу біля Карґата. От вам і доказ, з якими дурнями маємо справу! Чорний хід у пекло? Про що вони думали?",
        ["npcs"] = { [1] = 3836 },
        ["roles"] = { ["greeting"] = true },
    },
    [4123592494] = {
        ["english"] = { [1] = "I did not doubt you for even one second, $N.$B$BHere are your orders, $N. I know that you will not let me down.\010" },
        ["text"] = "Я не сумнівався у вас ані секунди, $N.$B$BОсь ваші накази, $N. Я знаю, що ви мене не підведете.\010",
        ["npcs"] = { [1] = 9077 },
        ["roles"] = { ["greeting"] = true },
    },
    [2333693239] = {
        ["english"] = { [1] = "It is true, young $r, we and the Alliance have gathered and prepared all that we will need for this upcoming conflict at Ahn'Qiraj. Even now these things are being sent to Cenarion Hold, and the last of them should arrive within a day. After all is in place, some person will need to ring the gong on the Scarab Dais to open the gates and start the war." },
        ["text"] = "Це правда, юний $r: ми з Альянсом зібрали й підготували все потрібне для прийдешнього конфлікту в Ан'Кіражі. Уже зараз усе це відправляють до Кенарійської цитаделі, а остання партія має прибути протягом дня. Коли все буде на місці, хтось муситиме вдарити в гонг на Постаменті Скарабея, щоб відкрити брами й почати війну.",
        ["npcs"] = { [1] = 15477 },
        ["roles"] = { ["greeting"] = true },
    },
    [3170849067] = {
        ["english"] = { [1] = "Ironforge is going to be your best bet for leatherworkers.  If memory servers, there's a shop by The Great Forge that should meet yer needs." },
        ["text"] = "Найкраще шукати шкіряників у Залізогарті.  Якщо пам'ять не зраджує, біля Великої Кузні є крамниця, що має вам підійти.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [2606575567] = {
        ["english"] = { [1] = "I possess part of Eranikus' essence.  What do you want with it... or with me?" },
        ["text"] = "У мене є частина сутності Еранікуса.  Що вам потрібно від неї... чи від мене?",
        ["npcs"] = { [1] = 5353 },
        ["roles"] = { ["reply"] = true },
    },
    [2737499108] = {
        ["english"] = { [1] = "I never stated that you were here to redeem yourself, $g priest:priestess;. You are here to redeem me and the innocents murdered while trying to escape Stratholme.$B$BMy spirit and the spirit of those lost are bound here, cursed to endlessly relive our own tragic deaths." },
        ["text"] = "Я ніколи не казав, що ви тут, аби спокутувати власні гріхи, $g жерцю:жрице;. Ви тут, щоб спокутувати мої й гріхи невинних, убитих під час спроби втекти зі Стратгольма.$B$BМій дух і духи загиблих прикуті до цього місця й приречені без кінця переживати власні трагічні смерті.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4010959307] = {
        ["english"] = { [1] = "I'd like to buy Jack a drink.  Perhaps something... extra strong." },
        ["text"] = "Я хочу пригостити Джека випивкою.  Може, чимось... особливо міцним.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [990036718] = {
        ["english"] = { [1] = "If it is the way of the Warrior that you crave then you must seek out Krang Stonehoof.  You will find him in the southeast corner of the village at his training circle, often instructing his other students." },
        ["text"] = "Якщо прагнете шляху Воїна, знайдіть Кранґа Кам'яне Копито.  Його можна знайти в південно-східному куті селища, на тренувальному колі, де він часто навчає інших учнів.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [869893392] = {
        ["english"] = { [1] = "It is time to face Socrethar, $N.  Are you ready?" },
        ["text"] = "Настав час постати перед Сокретаром, $N.  Ви готові?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1451953412] = {
        ["english"] = { [1] = "I have seen many dangers in these wastes.  Who knows what creatures yet lurk in the dust to ambush the unwary?" },
        ["text"] = "Я бачив чимало небезпек у цих пустках.  Хто знає, які створіння ще ховаються в пилюці, чатуючи на необачних?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4042415407] = {
        ["english"] = { [1] = "I will instruct you when the time is right... that time is not now. You have much more to learn first!" },
        ["text"] = "Я навчу вас, коли настане час... але цей час іще не прийшов. Спершу вам треба навчитися значно більшого!",
        ["npcs"] = { [1] = 4576 },
        ["roles"] = { ["greeting"] = true },
    },
    [496592039] = {
        ["english"] = { [1] = "I don't know much about magic, but there's a mage named Zaldimar who is staying at the Lion's Pride Inn that could probably assist you." },
        ["text"] = "Я мало тямлю в магії, але в заїзді «Левова Гордість» зупинився маг на ім'я Залдімар — він, певно, зможе вам допомогти.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [304975376] = {
        ["english"] = { [1] = "It is the baseline material used in race synthesis.  A cross-section of Azeroth's crust was used as the foundation for the Earthen's synthesis rather than the typical biomass construction foundation used by the Creators.$B$BResearch on the world's composition led the Creators to theorize that an enhanced being could be synthesized that would epitomize the resiliency of this world's essence.  This was accomplished by choosing to use a blend of Azeroth's various stone core compounds as the foundation." },
        ["text"] = "Це базовий матеріал для синтезу рас.  Замість типової біомасової основи, яку Творці використовують для конструювання, фундаментом синтезу земельників став поперечний зріз кори Азероту.$B$BДослідження складу світу привело Творців до теорії, що можна синтезувати вдосконалену істоту, яка втілюватиме стійкість сутності цього світу.  Для цього як основу обрали суміш різних кам'яних сполук ядра Азероту.",
        ["npcs"] = { [1] = 7172 },
        ["roles"] = { ["greeting"] = true },
    },
    [1134446863] = {
        ["english"] = { [1] = "In case it wasn't obvious, I'm not here for customer relations." },
        ["text"] = "Якщо це було не очевидно — я тут не для роботи з клієнтами.",
        ["npcs"] = { [1] = 14827 },
        ["roles"] = { ["greeting"] = true },
    },
    [1633484837] = {
        ["english"] = { [1] = "It is the assistance of Bulrug that you need.  You will find him outside on the lower rise standing between the inn and the Thunder Bluff Bank." },
        ["text"] = "Вам потрібна допомога Булруґа.  Знайдете його надворі на нижньому уступі, між заїздом і банком Громового Бескиду.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [988591749] = {
        ["english"] = { [1] = "It is Syurna that you seek if you are to follow the rogue's path.  She dwells in the Cenarion Enclave down the spiraling path within the western most tree." },
        ["text"] = "Якщо йти шляхом розбійника, вам потрібна Сіурна.  Вона мешкає в Кенарієвому анклаві, вниз спіральною стежкою всередині найзахіднішого дерева.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [4091416090] = {
        ["english"] = { [1] = "If it's a hammer you're looking for, you've come to the right place." },
        ["text"] = "Якщо шукаєте молот — ви прийшли куди треба.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3160367423] = {
        ["english"] = { [1] = "If you're trying to be friendly, save your breath.  Better yet, just stop breathing all together." },
        ["text"] = "Якщо намагаєтеся бути привітними — не витрачайте повітря.  А ще краще — просто перестаньте дихати взагалі.",
        ["npcs"] = { [1] = 14827 },
        ["roles"] = { ["greeting"] = true },
    },
    [3864913662] = {
        ["english"] = { [1] = "If your stomach's rumbling, talk to Galley Chief Steelbelly, but just between you and me? You might want to wait. He's got that name for a reason." },
        ["text"] = "Якщо бурчить у животі, поговоріть із начальником камбуза Сталечеревом, але між нами? Може, краще зачекайте. Він недарма так зветься.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2170928986] = {
        ["english"] = { [1] = "I'm gathering funds to build a monument in honor of those who've died in the war.  It is important to not forget the sacrifices we've made to achieve victory.$B$BWe are $3275w percent done with this goal." },
        ["text"] = "Я збираю кошти на пам'ятник тим, хто загинув у війні.  Важливо не забувати жертв, які ми принесли заради перемоги.$B$BМи виконали цю мету на $3275w відсотків.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3510465647] = {
        ["english"] = { [1] = "Indeed. Nefarian, brood of Deathwing, rules the Spire now. Rend is under the command of the dragon.$B$BIf only you could somehow manage to pass through the Halls of Ascension.$B$B<Eitrigg sighs.>$B$BAlas, only those deemed worthy by the black flight earn privilege to ascend.\010" },
        ["text"] = "Саме так. Нефаріан, нащадок Смертекрила, тепер править Шпилем. Ренд підкоряється дракону.$B$BЯкби ж вам якось вдалося пройти Зали Вознесіння.$B$B<Айтріґ зітхає.>$B$BНа жаль, лише ті, кого чорна зграя визнає гідними, отримують право піднятися.\010",
        ["npcs"] = { [1] = 3144 },
        ["roles"] = { ["greeting"] = true },
    },
    [538278224] = {
        ["english"] = { [1] = "It is shameful that we sin'dorei have lost so much of what we used to call home.  It shall not be long before we regain our strength and retake our southern lands back from the Scourge!" },
        ["text"] = "Ганьба, що ми, сін'дорай, втратили стільки земель, які колись звали домом.  Незабаром ми відновимо сили й відвоюємо наші південні землі у Скари!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1886004663] = {
        ["english"] = { [1] = "It is said that Kel'Thuzad seeks the legendary Atiesh, greatstaff of the Guardian.$B$BYes, the very staff once held by Medivh." },
        ["text"] = "Кажуть, Кел'Тузад шукає легендарний Атієш, великий посох Хранителя.$B$BТак, той самий посох, який колись тримав Медів.",
        ["npcs"] = { [1] = 16116 },
        ["roles"] = { ["greeting"] = true },
    },
    [4233516992] = {
        ["english"] = { [1] = "I can't believe the officials in Stormwind, sending the bulk of our army abroad... when our home front is under so much pressure!$B$BWith thieves coming from Westfall and gnolls encroaching from from the east and west, it's a wonder Stormwind itself isn't besieged." },
        ["text"] = "Не можу повірити, що урядовці Штормовію відправили більшу частину нашого війська за море... тоді як удома на нас тиснуть з усіх боків!$B$BІз Західного краю сунуть злодії, зі сходу й заходу наступають ґноли — диво, що сам Штормовій іще не в облозі.",
        ["npcs"] = { [1] = 963 },
        ["roles"] = { ["greeting"] = true },
    },
    [4125280171] = {
        ["english"] = { [1] = "It is power, imbecile.$B$B<Mataus's eyes darken.>$B$BThese fools send idiots like you into Naxxramas to retrieve desecrated armor so that they may purify it and restore the pieces to their former glory.$B$B<Mataus spits.>$B$BJust the thought of such utter stupidity brings the bile up to my throat.$B$BI too seek that armor, but in its most foul and desecrated form." },
        ["text"] = "Це сила, йолопе.$B$B<Очі Матауса темнішають.>$B$BЦі дурні посилають таких ідіотів, як ви, до Наксрамаса по осквернені обладунки, щоб очистити їх і повернути колишню славу.$B$B<Матаус спльовує.>$B$BВід самої думки про таку безмежну дурість мене нудить.$B$BЯ теж шукаю ці обладунки, але в їхній наймерзеннішій, найоскверненішій формі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3254426723] = {
        ["english"] = { [1] = "It is possible for one, not of dragon kind, to obtain the Adorned Seal of Ascension and pass through the protected barrier. While possession of such an item would surely destroy me, perhaps you could utilize it and lower the barrier.\010" },
        ["text"] = "Істота, яка не належить до драконів, може здобути Оздоблену Печатку Вознесіння й пройти крізь захисний бар'єр. Хоч володіння таким предметом напевно знищило б мене, можливо, ви зможете використати його й опустити бар'єр.\010",
        ["npcs"] = { [1] = 10296, [2] = 10299 },
        ["roles"] = { ["greeting"] = true },
    },
    [2726239991] = {
        ["english"] = { [1] = "Is it? This has always been their method of operation. What is of greater value to Kel'Thuzad and the ever growing Scourge army? A zealous, living, follower that can work their way into a society and then unleash a plague, destroying thousands; or a single undead trooper? Certainly you cannot be that dense$B$BYes, $r, they live, work, and plot among you." },
        ["text"] = "Хіба ні? Це завжди був їхній спосіб дії. Що цінніше для Кел'Тузада й дедалі більшої армії Скари: фанатичний живий послідовник, здатний проникнути в суспільство й випустити чуму, знищивши тисячі, чи один невмерлий солдат? Невже ви справді настільки недалекі$B$BТак, $r, вони живуть, працюють і плетуть змови серед вас.",
        ["npcs"] = { [1] = 11286 },
        ["roles"] = { ["greeting"] = true },
    },
    [3776417417] = {
        ["english"] = { [1] = "I submit myself for further training my master." },
        ["text"] = "Я віддаю себе на подальше навчання, мій учителю.",
        ["npcs"] = { [1] = 2126, [2] = 2127, [3] = 4565 },
        ["roles"] = { ["reply"] = true },
    },
    [609392128] = {
        ["english"] = { [1] = "It was not enough.$B$B<Fairbanks smirks briefly, lost in a memory.>$B$BA thousand came and a thousand died. By the Light! By the might of Mograine! He would smite them down as fast as they could come. Through the chaos, I noticed that the lesser Mograine was still there, off in the distance. I called to him, \"Help us, Renault! Help your father, boy!\"" },
        ["text"] = "Цього було недостатньо.$B$B<Феєрбенкс коротко всміхається, загубившись у спогадах.>$B$BТисяча прийшла — і тисяча померла. Світлом! Могуттю Моґрейна! Він косив їх так швидко, як вони наближалися. Серед хаосу я помітив, що молодший Моґрейн усе ще там, удалині. Я крикнув йому: «Допоможи нам, Рено! Допоможи батькові, хлопче!»",
        ["npcs"] = { [1] = 4542 },
        ["roles"] = { ["greeting"] = true },
    },
    [3576686492] = {
        ["english"] = { [1] = "I don't know of one of those around here.  Your best bet is to go to Orgrimmar to the north and speak to one of their grunts." },
        ["text"] = "Не знаю, чи є тут щось таке.  Найкраще рушайте на північ до Орґріммара й поговоріть із кимось із тамтешніх рубак.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [614292300] = {
        ["english"] = { [1] = "It is we who must make the first strike. We cannot be allowed to repeat the mistakes of the past..." },
        ["text"] = "Саме ми мусимо завдати першого удару. Не можна допустити повторення помилок минулого...",
        ["npcs"] = { [1] = 15192 },
        ["roles"] = { ["greeting"] = true },
    },
    [1313840880] = {
        ["english"] = { [1] = "It is not our way, nor would it be possible. Nefarian is guarded by ancient wards, as old as the Aspects themselves. It is what prevents me from entering the inner sanctum of this citadel. The dark magic prevents any of the other flight to enter without being ordained... unless." },
        ["text"] = "Це не наш шлях, та й це було б неможливо. Нефаріана захищають прадавні обереги, такі ж старі, як самі Аспекти. Саме вони не дають мені ввійти до внутрішнього святилища цієї цитаделі. Темна магія не дозволяє жодній іншій зграї пройти без посвяти... хіба що.",
        ["npcs"] = { [1] = 10296, [2] = 10299 },
        ["roles"] = { ["greeting"] = true },
    },
    [2220543476] = {
        ["english"] = { [1] = "I'll consider that the next time I run into one of these things." },
        ["text"] = "Наступного разу, коли натраплю на таку штуку, подумаю про це.",
        ["npcs"] = { [1] = 10776 },
        ["roles"] = { ["reply"] = true },
    },
    [2020292724] = {
        ["english"] = { [1] = "It is not for us to judge these atrocities. Ivus will pass judgement once he arrives." },
        ["text"] = "Не нам судити ці звірства. Івус винесе вирок, коли прибуде.",
        ["npcs"] = { [1] = 13443 },
        ["roles"] = { ["greeting"] = true },
    },
    [1688699077] = {
        ["english"] = { [1] = "Indeed.", [2] = "Indeed.\010" },
        ["text"] = "Саме так.",
        ["npcs"] = { [1] = 7783, [2] = 9021 },
        ["roles"] = { ["reply"] = true },
    },
    [3354681852] = {
        ["english"] = { [1] = "It is no light endeavor upon which you embark $N.  To get to Warsong Gulch you will want to speak to Aethalas, the Battlemaster of the Silverwing Sentinels.  She will guide your way.  Blessings of the Goddess be with you!" },
        ["text"] = "Ви беретеся за нелегку справу, $N.  Щоб дістатися Ущелини Пісні Війни, поговоріть з Еталас, майстринею бою Вартових Срібного Крила.  Вона вкаже шлях.  Хай благословення Богині буде з вами!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2312111187] = {
        ["english"] = { [1] = "I can't believe it... I was doing a routine recon mission over the central DMZ when all hell broke loose. I saw the Horde Wing Commander, Mulverick, take out both Ichman and Slidore! Anger took hold of me and I broke from my wing man and drove that bastard Mulverick down. Unfortunately, he clipped my gryphon before he crashed, forcing me down as well. I ended up captured by these savages.$B$BI have to get back to base! Help!" },
        ["text"] = "Не можу повірити... Я виконував звичайну розвідувальну місію над центральною нейтральною зоною, аж тут почалося справжнє пекло. Я бачив, як командир крила Орди Малверік збив і Ічмана, і Слідора! Мене охопила лють, я відірвався від веденого й погнав того покидька Малверіка донизу. На жаль, перед падінням він зачепив мого грифона, тож і мені довелося сісти. А потім ці дикуни мене схопили.$B$BЯ мушу повернутися на базу! Допоможіть!",
        ["npcs"] = { [1] = 13439 },
        ["roles"] = { ["greeting"] = true },
    },
    [2102672081] = {
        ["english"] = { [1] = "It is no easy task to protect the Horde's lumber gathering efforts here in Ashenvale, but we have never shied from battle!  The night elves and their allies will fall!" },
        ["text"] = "Захищати заготівлю деревини Орди тут, у Ясенедолі, нелегко, але ми ніколи не уникали бою!  Нічні ельфи та їхні союзники впадуть!",
        ["npcs"] = { [1] = 14781 },
        ["roles"] = { ["greeting"] = true },
    },
    [2782164344] = {
        ["english"] = { [1] = "If my mom were alive, she would put out the fires!" },
        ["text"] = "Якби моя мама була жива, вона б загасила пожежі!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2220158835] = {
        ["english"] = { [1] = "If yer of need of an Inn, The Stonefire Inn is where ye should be.  Ye'll find it just to the left of the entrance to Ironforge if ye be coming, or to the right if ye be going.  $B$BOh, and if yer going that way, then tell them to have a tankard ready for me." },
        ["text"] = "Якщо вам потрібен заїзд, вам до «Кам'яного Вогню».  Знайдете його ліворуч від входу до Залізогарта, якщо заходите, або праворуч, якщо виходите.  $B$BА якщо йдете туди, скажіть, щоб мені приготували кухоль.",
        ["npcs"] = { [1] = 5595, [2] = 274781 },
        ["roles"] = { ["greeting"] = true },
    },
    [4150281580] = {
        ["english"] = { [1] = "If you put on cologne or perfume, then you'll see who is amorous.  Those are the ones who accept love tokens... and offer a gift in return.$B$BBut remember: to give someone a love token, you have to smell just right!  Men like the scent of perfume, while women prefer cologne." },
        ["text"] = "Якщо нанесете одеколон або парфуми, побачите, хто закоханий.  Саме вони приймають знаки кохання... і дають подарунок у відповідь.$B$BАле пам'ятайте: щоб вручити комусь знак кохання, треба пахнути як слід!  Чоловікам подобається аромат парфумів, а жінкам — одеколону.",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 15174, [45] = 16256, [46] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [3343436366] = {
        ["english"] = { [1] = "I grow weary...$B$BFrom here, you can see the waterfalls, $n...The scepter grants you the power to travel to this very place, should you ever desire to enter through the front gates of Maraudon again.$B$BNear the entrance to Maraudon, you will find a passage that goes down beneath the caverns. Use the scepter at the ancient ritual site to create a portal, and you will find yourself here once more." },
        ["text"] = "Я втомлююся...$B$BЗвідси видно водоспади, $n... Скіпетр дає вам силу переміщуватися просто сюди, якщо колись знову захочете увійти через головну браму Мародона.$B$BБіля входу до Мародона ви знайдете прохід, що веде вниз, під печери. Скористайтеся скіпетром на стародавньому ритуальному місці, щоб створити портал, і знову опинитеся тут.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [694203668] = {
        ["english"] = { [1] = "It is my honor to provide for adventurers, for they are heroes in the making." },
        ["text"] = "Для мене честь забезпечувати шукачів пригод, адже з них постають герої.",
        ["npcs"] = { [1] = 4241 },
        ["roles"] = { ["greeting"] = true },
    },
    [1050380845] = {
        ["english"] = { [1] = "I once heard ol' Grimnur say he fished up a sword.  Or was it a swordfish?  Damn that Grimnur, he's told so many fish tales I can't remember which is which.  Well, why don't you go see him over in The Forlorn Cavern and have him tell you what it was." },
        ["text"] = "Якось чув, як старий Ґрімнур казав, ніби виловив меч.  Чи то рибу-меч?  Клятий Ґрімнур розповів стільки рибальських небилиць, що я вже не пам'ятаю, де що.  Та сходіть до нього в Закинуту печеру й нехай сам розповість, що то було.",
        ["npcs"] = { [1] = 5595, [2] = 274781 },
        ["roles"] = { ["greeting"] = true },
    },
    [3212976248] = {
        ["english"] = { [1] = "I like to build stuff. Of course, I like to blow stuff up even more!" },
        ["text"] = "Я люблю щось будувати. А ще більше люблю все підривати!",
        ["npcs"] = { [1] = 11025 },
        ["roles"] = { ["greeting"] = true },
    },
    [2698965424] = {
        ["english"] = { [1] = "It is my fervent hope that we will be able to bring the Light to those places in Ashenvale where it has been forsaken." },
        ["text"] = "Я палко сподіваюся, що ми зможемо принести Світло в ті місця Ясенедолу, де його покинули.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [274812311] = {
        ["english"] = { [1] = "It is located in the Trade District citizen.  It is nearly straight on from the entrance of Stormwind." },
        ["text"] = "Це в Торговому районі, громадянине.  Майже прямо від входу до Штормовію.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [1014808070] = {
        ["english"] = { [1] = "I live only to serve, Warchief! My life is empty and meaningless without your guidance." },
        ["text"] = "Я живу лише заради служіння, вождю! Без ваших настанов моє життя порожнє й безглузде.",
        ["npcs"] = { [1] = 4949 },
        ["roles"] = { ["reply"] = true },
    },
    [137820861] = {
        ["english"] = { [1] = "I want to fly on the wings of the Red Flight." },
        ["text"] = "Я хочу летіти на крилах Червоної зграї.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [917116225] = {
        ["english"] = { [1] = "It is integral to the assimilation of this data that it is understood that the Creators wanted to synthesize a race that would long be an integral part of this world's development cycle after they had departed.  This race would be instrumental in fulfilling the Creators' long-term development objectives for Azeroth.  $B$BAs an ancillary note, the nomenclature \"Earthen\" was deemed apropos for the new race by the Creators, based on the Earthen's composition." },
        ["text"] = "Для засвоєння цих даних принципово важливо зрозуміти: Творці хотіли синтезувати расу, яка ще довго після їхнього відходу залишалася б невід'ємною частиною циклу розвитку цього світу.  Ця раса мала відігравати ключову роль у виконанні довгострокових цілей Творців щодо розвитку Азероту.  $B$BДодаткова примітка: назву «земельники» Творці визнали доречною для нової раси, зважаючи на її склад.",
        ["npcs"] = { [1] = 7172 },
        ["roles"] = { ["greeting"] = true },
    },
    [1813171812] = {
        ["english"] = { [1] = "I could really use a papaya." },
        ["text"] = "Мені б зараз папаю.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [458078388] = {
        ["english"] = { [1] = "It is here that Gul'dan severed the tie between orcs and the elemental spirits. His unquenchable thirst for power could not be satiated with the complete annihilation of the draenei. He had to also destroy Draenor, razing the land and siphoning all of its energies for use in his war.$B$BNow all that is left are remnants of his madness.$B$BLook to the altar, $r - the land is forever haunted..." },
        ["text"] = "Саме тут Ґул'дан розірвав зв'язок між орками й духами стихій. Його невтамовну жагу сили не могло задовольнити навіть повне знищення дренеїв. Він мусив ще й зруйнувати Дренор, спустошити землю й висмоктати всю її енергію для своєї війни.$B$BТепер лишилися лише рештки його безумства.$B$BПогляньте на вівтар, $r — ця земля навіки проклята...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1059960226] = {
        ["english"] = { [1] = "I can't see why you want to learn something else... but I suppose I can point you in the right direction. What training are you after, specifically?" },
        ["text"] = "Не розумію, навіщо вам учитися чогось іншого... але, гадаю, можу вказати правильний напрямок. Яке саме навчання вам потрібне?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [213534955] = {
        ["english"] = { [1] = "If my dad were alive, he would put out the fires!" },
        ["text"] = "Якби мій тато був живий, він би загасив пожежі!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [797898909] = {
        ["english"] = { [1] = "In exchange for one Sulfuron Ingot, I am authorized to grant you one copy of the plans to forge a Sulfuron hammer.$B$BNow an adventurer like yourself is probably thinking to $ghimself:herself;, \"What would I ever need a hammer like that for when what I already own is far superior?\"$B$BWell let me tell you something, $gmister:missy;, there ain't nothing more superior than what the Sulfuron hammer can become!" },
        ["text"] = "В обмін на один злиток сульфурону я уповноважений видати вам одну копію креслень молота Сульфурона.$B$BТепер шукач пригод на кшталт вас, мабуть, думає про себе, $gсам:сама;: «Навіщо мені взагалі такий молот, якщо моя теперішня зброя значно краща?»$B$BТак от, $gпане:панно;, немає нічого кращого за те, чим молот Сульфурона може стати!",
        ["npcs"] = { [1] = 12944 },
        ["roles"] = { ["greeting"] = true },
    },
    [167058201] = {
        ["english"] = { [1] = "It is good to see you again, $N. Perhaps once things have settled down, I can talk to you about the priceless treasure that we have lost..." },
        ["text"] = "Радий знову вас бачити, $N. Можливо, коли все трохи вляжеться, я розповім вам про безцінний скарб, який ми втратили...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3347825051] = {
        ["english"] = { [1] = "I... I did not think of it that way, Warchief." },
        ["text"] = "Я... я не дивився на це так, вождю.",
        ["npcs"] = { [1] = 4949 },
        ["roles"] = { ["reply"] = true },
    },
    [658564904] = {
        ["english"] = { [1] = "If only I hadn't twisted my ankle coming into this place, I'd be in there with my friends.  Hmmm, now that I think about it, maybe it's better that I'm out here?" },
        ["text"] = "Якби я не підвернув щиколотку, заходячи сюди, то був би там із друзями.  Гм, хоча тепер, коли думаю про це, може, краще, що я тут?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3131105796] = {
        ["english"] = { [1] = "I understand that many individuals seek romance in taverns and festivals like this one, but alcohol dulls the senses and makes calculating the difficulties of daily life all fuzzy!$b$bBut I've found a solution! Through many trials and tribulations, I've engineered an extraordinary device that gives you all the benefits of alcohol with none of the drawbacks! With these goggles on, ANYONE looks attractive!$b$bMmm... including you, cutie! Tell you what. I'll give you a discount!" },
        ["text"] = "Я розумію, що багато хто шукає романтики в тавернах і на таких фестивалях, але алкоголь притуплює чуття й робить розрахунок усіх труднощів щоденного життя геть туманним!$b$bТа я знайшов рішення! Після безлічі випробувань я сконструював надзвичайний пристрій, що дає всі переваги алкоголю без жодних недоліків! У цих окулярах ПРИВАБЛИВОЮ здається БУДЬ-ЯКА людина!$b$bМ-м-м... навіть ви, красунчику! Знаєте що? Зроблю вам знижку!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [821115308] = {
        ["english"] = { [1] = "I have much knowledge to impress upon you, $c. You must learn to hunt with honor." },
        ["text"] = "Я маю багато знань, які мушу вам передати, $c. Ви повинні навчитися полювати з честю.",
        ["npcs"] = { [1] = 3352 },
        ["roles"] = { ["greeting"] = true },
    },
    [1312175295] = {
        ["english"] = { [1] = "I have no more knowledge to bestow upon you. Go through the archway and down the ramp to the southeast, and talk to Doctor Herbert Halsey. He is a Forsaken who can teach you more advanced techniques." },
        ["text"] = "Мені більше нічого вам передати. Пройдіть крізь арку, спустіться пандусом на південний схід і поговоріть із доктором Гербертом Галсі. Він Відречений і може навчити вас складніших прийомів.",
        ["npcs"] = { [1] = 4609 },
        ["roles"] = { ["greeting"] = true },
    },
    [1715574337] = {
        ["english"] = { [1] = "I would love to read it to you!$B$BDo not stand at my grave and weep,$BI am not there, I do not sleep.$B$BI am in a thousand winds that blow,$Bacross Northrend's bright and shining snow.$B$BI am the gentle showers of rain,$Bon Westfall's fields of golden grain.$B$BI am in the morning hush,$Bof Stranglethorn's jungle, green and lush.$B$BI am in the drums loud and grand,$Bthe thunderous hooves across Nagrand.$B$BI am the stars warmly gleaming,$Bover Darnassus softly dreaming.$B$BI am in the birds that sing,$BI am in each lovely thing.$B$BDo not stand at my grave and cry,$BI am not there. I do not die.$B " },
        ["text"] = "Я залюбки прочитаю це вам!$B$BНе стій біля могили й не ридай,$Bмене там нема — я не сплю.$B$BЯ в тисячі вітрів, що гуляють,$Bнад сяйним снігом Нортренду.$B$BЯ в лагідних струменях дощу,$Bнад золотим збіжжям Західного краю.$B$BЯ в ранковій тиші$Bзелених, буйних джунглів Тернистої долини.$B$BЯ в гучних величних барабанах,$Bу громі копит над Наґрандом.$B$BЯ в зорях, що тепло сяють$Bнад Дарнасом, що тихо снить.$B$BЯ в співі птахів,$Bя в кожній прекрасній речі.$B$BНе стій біля могили й не плач,$Bмене там нема. Я не вмираю.$B ",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1475993360] = {
        ["english"] = { [1] = "I can not train you. You need to talk to your class trainer." },
        ["text"] = "Я не можу вас навчати. Вам треба поговорити зі своїм класовим наставником.",
        ["npcs"] = { [1] = 2122, [2] = 2130, [3] = 3594, [4] = 4582, [5] = 4583, [6] = 4584 },
        ["roles"] = { ["greeting"] = true },
    },
    [1918643931] = {
        ["english"] = { [1] = "I'm here for cooking training." },
        ["text"] = "Я тут заради навчання кулінарії.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3875137570] = {
        ["english"] = { [1] = "I have no time for a sermon now, $c. Seek your knowledge elsewhere." },
        ["text"] = "Зараз у мене немає часу на проповіді, $c. Шукайте знання деінде.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2575008917] = {
        ["english"] = { [1] = "Inessera is a sharp woman who carries various gems as well as jewelcrafting supplies. You can find her shop in the northern part of Aldor Rise." },
        ["text"] = "Інессера — кмітлива жінка, що продає різні самоцвіти та припаси для ювелірної справи. Її крамниця розташована в північній частині Виступу Алдорів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2236230756] = {
        ["english"] = { [1] = "It is good to see others who fight the Scourge in Stratholme, for it is here they are strongest.$B$BGreetings.  I am Aurius.  I was once a paladin of the Silver Hand, but like others whose faith wavered... I fell from grace.  The Scourge seduced me and nearly transformed me into a death knight!$B$BFinally sensing my peril, I fled to this chapel.  It is a sacred place, where the first paladin, Uther the Lightbringer, was ordained into the order of the Silver Hand." },
        ["text"] = "Добре бачити інших, хто б'ється зі Скарою у Стратгольмі, бо саме тут вона найсильніша.$B$BВітаю.  Я Аврій.  Колись я був паладином Срібної Десниці, але, як і інші, чия віра похитнулася... я впав у немилість.  Скара спокусила мене й мало не перетворила на лицаря смерті!$B$BНарешті усвідомивши небезпеку, я втік до цієї каплиці.  Це святе місце, де першого паладина, Утера Світлоносця, посвятили до ордену Срібної Десниці.",
        ["npcs"] = { [1] = 10917 },
        ["roles"] = { ["greeting"] = true },
    },
    [3741117412] = {
        ["english"] = { [1] = "I'm not out of the belly of this beast for more than two minutes and someone is already asking me about my bathroom behavior??? $G Mister:Missy;, I'd have smacked you silly for that question had you not been the one to rescue me!$B$BAnyhow! I'm grateful for the assistance. Maybe I can pay you back?" },
        ["text"] = "Я ще й двох хвилин не пробув поза черевом цієї тварюки, а мене вже розпитують про походи до вбиральні??? $G Пане:Панно;, я б добряче вам всипав за таке запитання, якби не ви мене врятували!$B$BУ будь-якому разі! Я вдячний за допомогу. Може, зможу віддячити?",
        ["npcs"] = { [1] = 10776 },
        ["roles"] = { ["greeting"] = true },
    },
    [129855803] = {
        ["english"] = { [1] = "I require training, Daryl." },
        ["text"] = "Мені потрібне навчання, Деріле.",
        ["npcs"] = { [1] = 5159 },
        ["roles"] = { ["reply"] = true },
    },
    [1390271598] = {
        ["english"] = { [1] = "I will have my revenge on Kael'thas for this outrage against the Kirin Tor! He once walked among us as a brother, but we are brothers no more.$B$BThere will be a reckoning.$B$B<The archmage nods grimly, not relishing the prospect.>$B$BKael'thas is more than a mere rogue mage. Once I am free from my tower, Ravandwyr and I will assist anyone who opposes him." },
        ["text"] = "Я помщуся Кель'тасу за цю наругу над Кірін-Тором! Колись він ходив серед нас як брат, та більше ми не брати.$B$BНастане час розплати.$B$B<Архімаг похмуро киває, не радіючи такій перспективі.>$B$BКель'тас — не просто маг-відступник. Коли я звільнюся з вежі, ми з Равандвіром допомагатимемо кожному, хто виступить проти нього.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3167247527] = {
        ["english"] = { [1] = "It is good that you wish to honor your kills by putting their bodies to use.  Find Thuwd inside the Kodohide Leatherworks in the middle of The Drag." },
        ["text"] = "Добре, що ви хочете вшанувати вбитих ворогів, використовуючи їхні тіла.  Знайдіть Тувда в «Шкіряному кодо» посеред Хитрого провулка.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [975191646] = {
        ["english"] = { [1] = "If you need to house your pet while you're training another, then you should talk to Jenova Stoneshield over in the Dwarven District." },
        ["text"] = "Якщо треба залишити вихованця, поки навчаєте іншого, поговоріть із Дженовою Кам'яний Щит у Дворфівському районі.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [2351060328] = {
        ["english"] = { [1] = "It is good of you to ask, $c, but we already have all of the baked salmon that we'll need for the war. Perhaps you would be kind enough to check with the other collectors here; they are sure to have something that they could use your help with." },
        ["text"] = "Добре, що ви питаєте, $c, але в нас уже є весь запечений лосось, потрібний для війни. Можливо, ви перевірите інших збирачів тут; певен, їм іще може знадобитися ваша допомога.",
        ["npcs"] = { [1] = 15535 },
        ["roles"] = { ["greeting"] = true },
    },
    [637948054] = {
        ["english"] = { [1] = "It is Gennia Runetotem's counsel that you seek.  You will find her in the large tent on the east side of the village." },
        ["text"] = "Вам потрібна порада Ґеннії Рунічний Тотем.  Знайдете її у великому наметі на східному боці селища.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [3688406321] = {
        ["english"] = { [1] = "I have less than one-third of the supplies needed to upgrade to veteran units." },
        ["text"] = "У мене менше третини припасів, потрібних для поліпшення загонів до ветеранів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1471919093] = {
        ["english"] = { [1] = "It is found on the lowest section of Thunder Bluff.  Search near the bank.  It is not far from there." },
        ["text"] = "Це на найнижчому ярусі Громового Бескиду.  Шукайте біля банку.  Звідти недалеко.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [2734449616] = {
        ["english"] = { [1] = "I would train ye if I could, but ye need the services of someone a bit more... what's the word? Brainy! Look for Trixie Quickswitch in Ironforge. Tell 'er Bronk sent ye!" },
        ["text"] = "Я б вас навчав, якби міг, але вам потрібен хтось трохи більш... як це слово? Мізкуватий! Шукайте Тріксі Швидкоперемикач у Залізогарті. Скажіть, що вас прислав Бронк!",
        ["npcs"] = { [1] = 1702 },
        ["roles"] = { ["greeting"] = true },
    },
    [3559077641] = {
        ["english"] = { [1] = "I think my necklace fell in the lake.  My daddy got it for me, and he's gonna be mad now." },
        ["text"] = "Здається, моє намисто впало в озеро.  Тато подарував його мені, й тепер він розсердиться.",
        ["npcs"] = { [1] = 8962 },
        ["roles"] = { ["greeting"] = true },
    },
    [1941544609] = {
        ["english"] = { [1] = "I'd love to get one of those written fortunes you mentioned!  I've got the space in my inventory for it." },
        ["text"] = "Я б залюбки отримав одне з тих письмових передбачень, про які ви згадували!  У мене є місце в сумках.",
        ["npcs"] = { [1] = 14822 },
        ["roles"] = { ["reply"] = true },
    },
    [161389789] = {
        ["english"] = { [1] = "I came from Ironforge to help out with the rebuilding effort here. If I can teach enough of ye my skills then maybe I can leave it to ye and take myself back home." },
        ["text"] = "Я прийшов зі Залізогарта, щоб допомогти з відбудовою. Якщо навчу достатньо з вас своїх умінь, може, зможу залишити все на вас і повернутися додому.",
        ["npcs"] = { [1] = 5513 },
        ["roles"] = { ["greeting"] = true },
    },
    [2279398760] = {
        ["english"] = { [1] = "I can not Vaelastrasz ! Surely there must be some way to heal you!" },
        ["text"] = "Я не можу, Веластраз! Невже немає жодного способу вас зцілити?!",
        ["npcs"] = { [1] = 13020 },
        ["roles"] = { ["reply"] = true },
    },
    [1538989229] = {
        ["english"] = { [1] = "It is always a pleasure to meet heroes such as yourself in this forsaken land. Is there some form of assistance that I can offer you?" },
        ["text"] = "Завжди приємно зустріти таких героїв, як ви, в цій покинутій землі. Чи можу я чимось допомогти?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [210355687] = {
        ["english"] = { [1] = "I've got my hands full here at the moment, $c.$B$BWhat can I do for you?" },
        ["text"] = "У мене тут зараз повні руки роботи, $c.$B$BЧим можу допомогти?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3020808728] = {
        ["english"] = { [1] = "It is a story of legend and one that I do not have the time nor the inclination to retell. Just know that Medivh was the last of the Guardians. The greatstaff of Atiesh was a focal point of his power and a focal point of corruption." },
        ["text"] = "Це легендарна історія, яку я не маю ані часу, ані бажання переказувати. Просто знайте: Медів був останнім із Хранителів. Великий посох Атієш був осередком його сили й водночас осередком скверни.",
        ["npcs"] = { [1] = 16116 },
        ["roles"] = { ["greeting"] = true },
    },
    [3565927656] = {
        ["english"] = { [1] = "I know you will, $N.$B$BI myself am a priestess, though, unlike you I am long since gone from this world. My spirit, however, remains here, as do the spirits of the thousands who were brutally slain by the mad Prince, Arthas Menethil and his legion of undeath." },
        ["text"] = "Я знаю, що так і буде, $N.$B$BЯ сама жриця, хоча, на відміну від вас, уже давно покинула цей світ. Та мій дух лишився тут, як і духи тисяч тих, кого жорстоко вбили божевільний принц Артас Менетіл та його легіон невмертя.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2074435657] = {
        ["english"] = { [1] = "It is a greater knowledge of the ways of the warlock that I crave." },
        ["text"] = "Я прагну глибших знань про шлях чорнокнижника.",
        ["npcs"] = { [1] = 988 },
        ["roles"] = { ["reply"] = true },
    },
    [2382195944] = {
        ["english"] = { [1] = "I think I understand the Creators' design intent for the Earthen now.  What are the Earthen's anomalies that you spoke of earlier?" },
        ["text"] = "Гадаю, тепер я розумію задум Творців щодо земельників.  А які аномалії земельників ви згадували раніше?",
        ["npcs"] = { [1] = 7172 },
        ["roles"] = { ["reply"] = true },
    },
    [3810649012] = {
        ["english"] = { [1] = "It is a good day to be alive and one with the elements." },
        ["text"] = "Добрий день, щоб бути живим і єдиним зі стихіями.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [129797512] = {
        ["english"] = { [1] = "I, like many others, came to aid my fellow druids when the war started.$B$BNow that the Gates of Ahn'Qiraj are open, I've realized that much work still remains to be done.  I've decided to stay in Silithus and do my best to help the cause, $N.  " },
        ["text"] = "Я, як і багато інших, прийшов допомогти своїм братам-друїдам, коли почалася війна.$B$BТепер, коли Брами Ан'Кіражу відкрито, я зрозумів, що роботи ще дуже багато.  Я вирішив залишитися в Силітусі й зробити все можливе для нашої справи, $N.  ",
        ["npcs"] = { [1] = 15499 },
        ["roles"] = { ["greeting"] = true },
    },
    [3353696081] = {
        ["english"] = { [1] = "If you have more thick leather, I'm sorry but you've come too late. We have all that we need, but before you go would you check with the others here? There's likely someone that still needs your help with their own collecting." },
        ["text"] = "Якщо у вас є ще щільна шкіра, вибачте, але ви запізнилися. У нас уже є все потрібне, та перш ніж іти, перевірте інших тут. Напевно, комусь іще потрібна допомога зі зборами.",
        ["npcs"] = { [1] = 15522 },
        ["roles"] = { ["greeting"] = true },
    },
    [1271606688] = {
        ["english"] = { [1] = "I hear that they have a Mining Trainer in Thunder Bluff to the north.  Take the road out of the village and when you get there ride the elevator to the top of the rise.  Any of the Bluffwatchers should be able to help you from there." },
        ["text"] = "Кажуть, у Громовому Бескиді на півночі є наставник гірництва.  Вирушайте дорогою з селища, а коли дістанетеся туди, підніміться ліфтом на вершину плато.  Будь-який вартовий Бескиду підкаже вам далі.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [1630957945] = {
        ["english"] = { [1] = "I last saw Elder Meadowrun at the Weeping Cave in the Western Plaguelands." },
        ["text"] = "Востаннє я бачив старійшину Лугового Бігу біля Плачучої печери в Західному Чумнозем'ї.",
        ["npcs"] = { [1] = 15566, [2] = 15568, [3] = 15592, [4] = 15594 },
        ["roles"] = { ["greeting"] = true },
    },
    [4143544154] = {
        ["english"] = { [1] = "I only make my mounts available to those who are considered exalted to Orgrimmar and the Orcish race.  Go prove yourself to us, and I'll make my mighty wolves available for your inspection." },
        ["text"] = "Я продаю їздових тварин лише тим, хто досяг звеличення в Орґріммарі та серед орків.  Доведіть свою відданість — і я дозволю вам оглянути моїх могутніх вовків.",
        ["npcs"] = { [1] = 3362 },
        ["roles"] = { ["greeting"] = true },
    },
    [356653745] = {
        ["english"] = { [1] = "I turn over the man to my liege for punishment, as he has broken the law of the land and it is my sworn duty to enforce it." },
        ["text"] = "Я передаю цього чоловіка своєму сюзерену для покарання, бо він порушив закон цих земель, а мій священний обов'язок — його виконувати.",
        ["npcs"] = { [1] = 14822 },
        ["roles"] = { ["reply"] = true },
    },
    [2905847146] = {
        ["english"] = { [1] = "I first set up shop in the Magic Quarter, but it was pretty noisy there. This is a definite improvement, barring a few persistent students who still track me down, despite the fact that I've relocated." },
        ["text"] = "Спочатку я відкрив крамницю в Магічному кварталі, але там було надто галасно. Тут безперечно краще, якщо не зважати на кількох надокучливих учнів, які й досі мене знаходять, хоча я переїхав.",
        ["npcs"] = { [1] = 4588 },
        ["roles"] = { ["greeting"] = true },
    },
    [636912941] = {
        ["english"] = { [1] = "I have so much to do... so much before the plague comes...\010" },
        ["text"] = "У мене ще стільки справ... стільки всього треба зробити до приходу чуми...\010",
        ["npcs"] = { [1] = 10778 },
        ["roles"] = { ["greeting"] = true },
    },
    [429219410] = {
        ["english"] = { [1] = "If you seek our master of Paladin Trainer's, go to Champion Bachi. He will wait of you in Farstriders' Square." },
        ["text"] = "Якщо шукаєте нашого головного наставника паладинів, ідіть до чемпіона Бачі. Він чекатиме на вас на площі Далекоходців.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [804535585] = {
        ["english"] = { [1] = "It would be an honor to battle alongside of you as a brother of the Horde, $N. I accept your offer." },
        ["text"] = "Для мене буде честю битися поруч із вами як брат Орди, $N. Я приймаю вашу пропозицію.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1391467514] = {
        ["english"] = { [1] = "I do not understand the significance of the Forsaken burning a great wicker effigy each night, but our own rituals must seem just as strange to them." },
        ["text"] = "Я не розумію, навіщо Відречені щовечора спалюють величезне солом'яне опудало, але, мабуть, наші власні обряди здаються їм не менш дивними.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [459851765] = {
        ["english"] = { [1] = "It didn't look like much of a \"cure\" to me, and I wasn't about to stand around listening to some crazy robot while he was butchering my people!$B$BWe did what any sane gnome would do... we ran! Well, actually, most of us parachuted off the side of the platform, but you get the picture.$B$BNot many of us managed to make it back here, and we're still spread thin from having to deal with everything else too, like the magnataur to the north and the Scourge to the east. To make things worse, the Horde just setup shop to the northwest!" },
        ["text"] = "Для мене це не виглядало на «ліки», і я не збирався стояти й слухати якогось божевільного робота, поки він різав мій народ!$B$BМи зробили те, що зробив би будь-який розсудливий гном... утекли! Ну, насправді більшість із нас зістрибнула з краю платформи з парашутами, але суть ви зрозуміли.$B$BНебагатьом вдалося повернутися сюди, а ми й так розтягнуті через інші проблеми — магнатаврів на півночі й Скару на сході. А щоб було ще краще, Орда щойно облаштувалася на північному заході!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2791565077] = {
        ["english"] = { [1] = "It cold there!  You go in Royal Quarter, talk to Grizzle Halfmane.", [2] = "It cold there! You go in Royal Quarter, talk to Grizzle Halfmane." },
        ["text"] = "Там холодно!  Іди в Королівський квартал, поговори з Ґріззлом Півгривою.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1304673030] = {
        ["english"] = { [1] = "Issa truut, matey!  Neh tougher salts anyweh but da northsea freebootahs yahso, mon!$B$BBest not brindle s'mady, mon.  Scuppah dat!  'Alf eediat swabs get feh kiss da gunnah's dawta, mate!" },
        ["text"] = "Атож, правда, друже! Нема міцніших морських вовків, ніж північноморські флібустьєри, еге ж!$B$BКраще нікого не дратуй, друже. Облиш це! Половина дурнів-матросів потім цілує гарматну дочку, приятелю!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4094538372] = {
        ["english"] = { [1] = "It is not yet your time. I shall aid your journey back to the realm of the living... for a price." },
        ["text"] = "Ваш час іще не настав. Я допоможу вам повернутися до царства живих... за певну ціну.",
        ["npcs"] = { [1] = 6491, [2] = 13056, [3] = 18153 },
        ["roles"] = { ["greeting"] = true },
    },
    [1677791920] = {
        ["english"] = { [1] = "I thought you were almost done?" },
        ["text"] = "Я думав, ви вже майже закінчили?",
        ["npcs"] = { [1] = 16033 },
        ["roles"] = { ["reply"] = true },
    },
    [3963211194] = {
        ["english"] = { [1] = "Isn't the memorial beautiful?  It is important to remember moments in our history when great sacrifices are made, lest we forget the price of all wars - even ones that are won." },
        ["text"] = "Хіба меморіал не прекрасний?  Важливо пам'ятати миті нашої історії, коли приносяться великі жертви, щоб не забути ціну всіх воєн — навіть переможних.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [899651348] = {
        ["english"] = { [1] = "I will escort you into the Sunwell when you're ready." },
        ["text"] = "Я проведу вас до Сонячного Колодязя, коли будете готові.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4070913323] = {
        ["english"] = { [1] = "Ishnu-dal-dieb, $N. Have you come here in search of knowledge?" },
        ["text"] = "Ішну-дал-дієб, $N. Ви прийшли сюди в пошуках знань?",
        ["npcs"] = { [1] = 3964 },
        ["roles"] = { ["greeting"] = true },
    },
    [2305755359] = {
        ["english"] = { [1] = "I do not offer apprentice training. Look for the tauren Waldor in the Wailing Caverns, here in the Barrens. He can assist you with whatever you need." },
        ["text"] = "Я не навчаю учнів. Знайдіть таурена Валдора в Печерах Стогону, тут, у Степах. Він допоможе вам із усім необхідним.",
        ["npcs"] = { [1] = 3703 },
        ["roles"] = { ["greeting"] = true },
    },
    [3167209338] = {
        ["english"] = { [1] = "I see that you've been putting in your time around here, $c.$B$BPut in more; the demons aren't gone yet, rookie." },
        ["text"] = "Бачу, ви вже чимало попрацювали тут, $c.$B$BПопрацюйте ще; демони нікуди не поділися, новачку.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3761094598] = {
        ["english"] = { [1] = "I used to amuse myself by accepting challenges from anyone who would offer them, but I've long since grown tired of such easy victories.$B$BFor now, I'm taking some time to get my reagent business off the ground and write a book about my experiences in Twilight's Hammer." },
        ["text"] = "Колись я розважався, приймаючи виклик від кожного охочого, але такі легкі перемоги давно мені набридли.$B$BНині я взяв паузу, щоб поставити на ноги торгівлю реагентами й написати книжку про свої часи в Сутінковому Молоті.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1835303972] = {
        ["english"] = { [1] = "I want to go back to the orphanage!" },
        ["text"] = "Я хочу назад до сиротинця!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [908863185] = {
        ["english"] = { [1] = "I know much, listen and be educated, $r." },
        ["text"] = "Я багато знаю. Слухайте й навчайтеся, $r.",
        ["npcs"] = { [1] = 14347 },
        ["roles"] = { ["greeting"] = true },
    },
    [163857298] = {
        ["english"] = { [1] = "I'm keeping an eye on the forsaken idiots down there. You can never be too cautious around them!" },
        ["text"] = "Я стежу за тими дурнями-Відреченими внизу. З ними ніколи не буває зайвої обережності!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1175575326] = {
        ["english"] = { [1] = "If you wish to become a swordsmith, just ask." },
        ["text"] = "Якщо хочете стати мечником, просто скажіть.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4181239680] = {
        ["english"] = { [1] = "I sell only the best gear, tested and true. And the prices are set, so if you want to haggle then go find a Goblin." },
        ["text"] = "Я продаю лише найкраще, перевірене спорядження. Ціни фіксовані, тож якщо хочете торгуватися — шукайте гобліна.",
        ["npcs"] = { [1] = 340, [2] = 1319, [3] = 1320, [4] = 1321, [5] = 1323, [6] = 1324, [7] = 1328, [8] = 1333, [9] = 1339, [10] = 1341, [11] = 1395, [12] = 1440, [13] = 1477, [14] = 1478, [15] = 1721, [16] = 2504, [17] = 2795, [18] = 3626, [19] = 3629, [20] = 5483, [21] = 5565, [22] = 12805 },
        ["roles"] = { ["greeting"] = true },
    },
    [1662675054] = {
        ["english"] = { [1] = "If you manage to complete a deck of Elementals cards you will be rewarded with a Greater Darkmoon card of the Maelstrom.   This card will occasionally impact an enemy you are fighting with for heavy damage." },
        ["text"] = "Якщо вам удасться зібрати повну колоду карт Елементалів, ви отримаєте Велику карту Темного Місяця Виру.   Вона час від часу завдаватиме великої шкоди ворогові, з яким ви б'єтеся.",
        ["npcs"] = { [1] = 14847 },
        ["roles"] = { ["greeting"] = true },
    },
    [2624262326] = {
        ["english"] = { [1] = "I must leave this place at once!" },
        ["text"] = "Я мушу негайно покинути це місце!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [686136119] = {
        ["english"] = { [1] = "If you have come to save the world then you have come to the right place. The faceless one - the Blood God, Hakkar - has been brought back into our world!" },
        ["text"] = "Якщо ви прийшли рятувати світ — ви за адресою. Безликий, Бог Крові Гаккар, повернувся в наш світ!",
        ["npcs"] = { [1] = 14875 },
        ["roles"] = { ["greeting"] = true },
    },
    [1597350726] = {
        ["english"] = { [1] = "Is there no end to these undead?  It seems that for every ghoul or skeleton we kill, two take its place." },
        ["text"] = "Невже цим невмерлим немає кінця?  Здається, на кожного вбитого нами гуля чи скелета приходять двоє нових.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3018643151] = {
        ["english"] = { [1] = "It's a pleasure to see you again, $N.  Your aid has provided us with a considerable boost in the security of our supply lines.  I hope you understand the importance of the logistics involved in large battle efforts such as this." },
        ["text"] = "Приємно знову вас бачити, $N.  Ваша допомога значно підвищила безпеку наших шляхів постачання.  Сподіваюся, ви розумієте важливість логістики в таких великих бойових операціях.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3631699597] = {
        ["english"] = { [1] = "Is there a difference between ooze and slime?" },
        ["text"] = "Є різниця між багном і слизом?",
        ["npcs"] = { [1] = 9616 },
        ["roles"] = { ["reply"] = true },
    },
    [592029745] = {
        ["english"] = { [1] = "Is that a list from Saltheril's Haven?  No doubt, his lordship will require a bottle of my finest.  And, of course, any friend of Lord Saltheril deserves a special price on such a fine vintage." },
        ["text"] = "Це список із Притулку Салтеріля?  Без сумніву, його світлості знадобиться пляшка мого найкращого.  І, звісно, кожен друг лорда Салтеріля заслуговує особливої ціни на таке вишукане вино.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [317280710] = {
        ["english"] = { [1] = "I bet ice cream would taste better if it were socketed!" },
        ["text"] = "Б'юся об заклад, морозиво було б смачніше, якби в нього можна було вставляти самоцвіти!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3815697237] = {
        ["english"] = { [1] = "I would teach him how to demon forge in exchange for his soul. The soul of a Blackrock orc is worth very little but in these trying times, a soul, any soul, is better than none at all." },
        ["text"] = "Я навчив би його демонічного кування в обмін на душу. Душа орка Чорного Каменю варта небагато, але в такі тяжкі часи будь-яка душа краща за жодну.",
        ["npcs"] = { [1] = 10918 },
        ["roles"] = { ["greeting"] = true },
    },
    [2767098760] = {
        ["english"] = { [1] = "Is that a list from Lord Saltheril that you have there? Yes, I can sell you a batch of appetizers, fresh off the fire." },
        ["text"] = "Це список від лорда Салтеріля у вас? Так, я можу продати вам партію закусок, щойно з вогню.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2814716291] = {
        ["english"] = { [1] = "I hope the Light is with you, $N. Is there anything I can do for you today?" },
        ["text"] = "Сподіваюся, Світло з вами, $N. Чим можу допомогти сьогодні?",
        ["npcs"] = { [1] = 837, [2] = 1226, [3] = 5141, [4] = 5142, [5] = 5143, [6] = 11406 },
        ["roles"] = { ["greeting"] = true },
    },
    [3543282570] = {
        ["english"] = { [1] = "If Reethe is somehow involved with the burning of the Shady Rest Inn, you'll have to find him and get some answers out of him.$b$bI sent Ogron to track him down. He was headed off to the southeast. Meet up with Ogron and then go find Reethe." },
        ["text"] = "Якщо Ріт якось причетний до спалення заїзду «Затінений Притулок», вам доведеться знайти його й витягти з нього відповіді.$b$bЯ послав Оґрона вистежити його. Він вирушив на південний схід. Зустріньтеся з Оґроном, а потім знайдіть Ріта.",
        ["npcs"] = { [1] = 4926 },
        ["roles"] = { ["greeting"] = true },
    },
    [804804664] = {
        ["english"] = { [1] = "If you ask me, there's no greater profession than a miner.  And if you ask me, there's no greater miner than a dwarf!" },
        ["text"] = "Як на мене, немає кращої професії за гірника.  А якщо вже питаєте — немає кращого гірника за дворфа!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1931840696] = {
        ["english"] = { [1] = "I'd like you better if you would apply some perfume." },
        ["text"] = "Ви подобалися б мені більше, якби скористалися парфумами.",
        ["npcs"] = { [1] = 68, [2] = 277, [3] = 279, [4] = 297, [5] = 338, [6] = 340, [7] = 482, [8] = 656, [9] = 1141, [10] = 1212, [11] = 1257, [12] = 1285, [13] = 1289, [14] = 1294, [15] = 1298, [16] = 1304, [17] = 1308, [18] = 1310, [19] = 1314, [20] = 1315, [21] = 1316, [22] = 1319, [23] = 1320, [24] = 1323, [25] = 1324, [26] = 1333, [27] = 1339, [28] = 1341, [29] = 1348, [30] = 1349, [31] = 1351, [32] = 1356, [33] = 1395, [34] = 1402, [35] = 1405, [36] = 1427, [37] = 1440, [38] = 1444, [39] = 1472, [40] = 1477, [41] = 1478, [42] = 1498, [43] = 1646, [44] = 1976, [45] = 2050, [46] = 2055, [47] = 2092, [48] = 2308, [49] = 2504, [50] = 2737, [51] = 2786, [52] = 2790, [53] = 2795, [54] = 2799, [55] = 2808, [56] = 2912, [57] = 2918, [58] = 2934, [59] = 2987, [60] = 2999, [61] = 3002, [62] = 3005, [63] = 3016, [64] = 3018, [65] = 3019, [66] = 3020, [67] = 3021, [68] = 3024, [69] = 3027, [70] = 3050, [71] = 3084, [72] = 3093, [73] = 3189, [74] = 3296, [75] = 3313, [76] = 3315, [77] = 3316, [78] = 3317, [79] = 3321, [80] = 3323, [81] = 3329, [82] = 3330, [83] = 3331, [84] = 3334, [85] = 3335, [86] = 3348, [87] = 3349, [88] = 3350, [89] = 3351, [90] = 3360, [91] = 3361, [92] = 3364, [93] = 3366, [94] = 3368, [95] = 3369, [96] = 3371, [97] = 3372, [98] = 3400, [99] = 3409, [100] = 3410, [101] = 3517, [102] = 3518, [103] = 3627, [104] = 3629, [105] = 3842, [106] = 3978, [107] = 4043, [108] = 4047, [109] = 4078, [110] = 4081, [111] = 4216, [112] = 4220, [113] = 4221, [114] = 4222, [115] = 4223, [116] = 4225, [117] = 4226, [118] = 4228, [119] = 4229, [120] = 4230, [121] = 4231, [122] = 4232, [123] = 4233, [124] = 4234, [125] = 4235, [126] = 4236, [127] = 4240, [128] = 4256, [129] = 4259, [130] = 4451, [131] = 4485, [132] = 4553, [133] = 4557, [134] = 4559, [135] = 4560, [136] = 4561, [137] = 4562, [138] = 4569, [139] = 4572, [140] = 4581, [141] = 4585, [142] = 4589, [143] = 4590, [144] = 4592, [145] = 4597, [146] = 4600, [147] = 4601, [148] = 4602, [149] = 4603, [150] = 46