        ["roles"] = { ["greeting"] = true },
    },
    [4026262356] = {
        ["english"] = { [1] = "I do so enjoy sitting out here, listening to the sounds of the Great Sea.  Oh, what?  Yes, there is a ship that will take you to Menethil Harbor.  It docks here from time to time." },
        ["text"] = "Я так люблю сидіти тут і слухати шум Великого Моря.  О, що?  Так, тут є корабель до гавані Менетілів.  Час від часу він причалює сюди.",
        ["npcs"] = { [1] = 12716 },
        ["roles"] = { ["greeting"] = true },
    },
    [1032938782] = {
        ["english"] = { [1] = "If you heard that all of the Horde and Alliance collections have been completed, then you heard right, $c. All of the goods for the war that we gathered and prepared are in the process of being sent to Cenarion Hold in Silithus, with less than $2113w days until the last of it arrives there. After that I suppose we'll just have to wait and see who assembles that scepter to ring the gong with, which will open the gates to Ahn'Qiraj and herald the war." },
        ["text"] = "Якщо ви чули, що Орда й Альянс завершили всі збори, то чули правильно, $c. Усі зібрані й підготовлені військові товари вже відправляють до Кенарійської цитаделі в Силітусі, і до прибуття останньої партії лишилося менше $2113w днів. Після цього, гадаю, залишиться лише чекати, хто збере скіпетр, щоб ударити в гонг, відкрити брами Ан'Кіражу й сповістити початок війни.",
        ["npcs"] = { [1] = 15535, [2] = 15708 },
        ["roles"] = { ["greeting"] = true },
    },
    [2360765162] = {
        ["english"] = { [1] = "I must apologize for not being entirely truthful with you in regards to my identity. I had to be certain that you could be trusted - few people would have selflessly lent assistance to an old and forgotten hermit.$B$BYou have proven yourself as one of those people: A person of integrity and honor." },
        ["text"] = "Мушу перепросити, що не був із вами цілком чесний щодо своєї особи. Я мав переконатися, що вам можна довіряти — мало хто безкорисливо допоміг би старому й забутому самітнику.$B$BВи довели, що належите до таких людей: людей честі та принципів.",
        ["npcs"] = { [1] = 1855 },
        ["roles"] = { ["greeting"] = true },
    },
    [1725738936] = {
        ["english"] = { [1] = "I can teach you the finer points of Horse Riding, provided you have enough gold to cover the lesson!" },
        ["text"] = "Я можу навчити вас тонкощів верхової їзди на конях, якщо у вас вистачить золота на урок!",
        ["npcs"] = { [1] = 4732 },
        ["roles"] = { ["greeting"] = true },
    },
    [3338943452] = {
        ["english"] = { [1] = "Is Tanaris currently under attack?" },
        ["text"] = "Танаріс зараз під атакою?",
        ["npcs"] = { [1] = 16285, [2] = 16359 },
        ["roles"] = { ["reply"] = true },
    },
    [912499119] = {
        ["english"] = { [1] = "Is Azshara currently under attack?" },
        ["text"] = "Азшара зараз під атакою?",
        ["npcs"] = { [1] = 16285, [2] = 16359 },
        ["roles"] = { ["reply"] = true },
    },
    [575566740] = {
        ["english"] = { [1] = "I can train you in First Aid techniques." },
        ["text"] = "Я можу навчити вас прийомів першої допомоги.",
        ["npcs"] = { [1] = 2326, [2] = 2329, [3] = 2798, [4] = 3181, [5] = 3373, [6] = 4211, [7] = 4591, [8] = 5150, [9] = 5759, [10] = 5939, [11] = 5943, [12] = 6094 },
        ["roles"] = { ["greeting"] = true },
    },
    [3889302100] = {
        ["english"] = { [1] = "I will never call Brackenwall Village my home. To do so is to give up hope of reclaiming our rightful lands." },
        ["text"] = "Я ніколи не назву селище Папорохащі своїм домом. Назвати його так — означає втратити надію повернути наші законні землі.",
        ["npcs"] = { [1] = 4501 },
        ["roles"] = { ["greeting"] = true },
    },
    [2805900089] = {
        ["english"] = { [1] = "I cannot hold him for long, we must leave at once!" },
        ["text"] = "Я не зможу стримувати його довго, ми мусимо негайно йти!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4096747556] = {
        ["english"] = { [1] = "Ironfoe?", [2] = "Ironfoe?\010" },
        ["text"] = "Залізолом?",
        ["npcs"] = { [1] = 9563 },
        ["roles"] = { ["reply"] = true },
    },
    [1852790428] = {
        ["english"] = { [1] = "I have reason to believe you're involved in cultist activity." },
        ["text"] = "У мене є підстави вважати, що ви причетні до діяльності культистів.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [81639839] = {
        ["english"] = { [1] = "I no longer train Death Knights, having grown weary of cretinous Initiates and their constant questions.$B$BNow begone." },
        ["text"] = "Я більше не навчаю лицарів смерті — втомився від тупоголових посвячених і їхніх нескінченних запитань.$B$BА тепер геть.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1033947471] = {
        ["english"] = { [1] = "I could use a drink and some rest myself.  You'll find it right in the northwest corner of Razor Hill.  Say hi to Innkeeper Grosk for me." },
        ["text"] = "Я й сам не відмовився б від випивки та відпочинку.  Знайдете це в північно-західному куті Колючого Пагорба.  Передайте від мене вітання корчмарю Ґроску.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [3356973826] = {
        ["english"] = { [1] = "I don't know how they do it...  those mailboxes must be magic portals or something.  Why I see people gathered around the mailbox next to the bank all day pulling swords and shields and various armor all from that small box!" },
        ["text"] = "Не знаю, як вони це роблять...  ті поштові скриньки, мабуть, магічні портали чи щось таке.  Я цілими днями бачу, як люди товпляться біля скриньки поруч із банком і витягають із тієї маленької коробки мечі, щити й усякі обладунки!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2426274002] = {
        ["english"] = { [1] = "I've heard it said that Deneb Walker, holed up in Stromgarde, has a book that is sure to help improve your First Aid techniques." },
        ["text"] = "Чув, що Денеб Вокер, який засів у Стромґарді, має книгу, котра точно допоможе вдосконалити ваші навички першої допомоги.",
        ["npcs"] = { [1] = 2326, [2] = 2327, [3] = 2329, [4] = 3181, [5] = 4211, [6] = 5150, [7] = 6094 },
        ["roles"] = { ["greeting"] = true },
    },
    [4150752264] = {
        ["english"] = { [1] = "I'm busy right now." },
        ["text"] = "Я зараз зайнятий.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3408469603] = {
        ["english"] = { [1] = "I'm sick of sittin' in this hole. I hope whatever sorry pencil-pusher is holdin' up Danath's return gets a punch in the jimmies." },
        ["text"] = "Мені остогидло сидіти в цій дірі. Сподіваюся, той жалюгідний папероїд, через якого затримується повернення Даната, отримає добрячого копняка між ніг.",
        ["npcs"] = { [1] = 2789 },
        ["roles"] = { ["greeting"] = true },
    },
    [3788223572] = {
        ["english"] = { [1] = "I can teach you fishing skills." },
        ["text"] = "Я можу навчити вас рибальства.",
        ["npcs"] = { [1] = 1651, [2] = 1680, [3] = 1683, [4] = 1700, [5] = 2367, [6] = 2834, [7] = 3028, [8] = 3179, [9] = 3607, [10] = 4156, [11] = 4573, [12] = 5161, [13] = 5493, [14] = 5690, [15] = 5938, [16] = 5941, [17] = 7946, [18] = 12032, [19] = 12961, [20] = 14740 },
        ["roles"] = { ["greeting"] = true },
    },
    [332933658] = {
        ["english"] = { [1] = "I can instruct you in blacksmithing.  Interested?" },
        ["text"] = "Я можу навчити вас ковальства.  Цікавить?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2451107332] = {
        ["english"] = { [1] = "I'd like to train in cooking." },
        ["text"] = "Я хочу навчатися кулінарії.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [1107589157] = {
        ["english"] = { [1] = "I would like training." },
        ["text"] = "Мені потрібне навчання.",
        ["npcs"] = { [1] = 3327, [2] = 3328 },
        ["roles"] = { ["reply"] = true },
    },
    [4127871852] = {
        ["english"] = { [1] = "I have something else to ask you about." },
        ["text"] = "Я хочу запитати вас ще про дещо.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [348558964] = {
        ["english"] = { [1] = "I'd like to stable my pet here." },
        ["text"] = "Я хочу залишити тут свого вихованця в стайні.",
        ["npcs"] = { [1] = 13617 },
        ["roles"] = { ["reply"] = true },
    },
    [685403291] = {
        ["english"] = { [1] = "Invulnerable?" },
        ["text"] = "Невразливий?",
        ["npcs"] = { [1] = 3836 },
        ["roles"] = { ["greeting"] = true },
    },
    [3099471438] = {
        ["english"] = { [1] = "I have another question." },
        ["text"] = "У мене є ще одне запитання.",
        ["npcs"] = { [1] = 16285, [2] = 16359 },
        ["roles"] = { ["reply"] = true },
    },
    [2586154591] = {
        ["english"] = { [1] = "I've got too much to do and not enough time to do it in, $r! Please, get out of my way." },
        ["text"] = "У мене купа справ і замало часу, $r! Будь ласка, не заважайте.",
        ["npcs"] = { [1] = 16284 },
        ["roles"] = { ["greeting"] = true },
    },
    [2393206562] = {
        ["english"] = { [1] = "I hope that your interruption is for a good cause, I was in the middle of some important work." },
        ["text"] = "Сподіваюся, ви перервали мене з поважної причини — я саме займався важливою справою.",
        ["npcs"] = { [1] = 5566 },
        ["roles"] = { ["greeting"] = true },
    },
    [894998529] = {
        ["english"] = { [1] = "Invention, my dear $c, is two percent bottled inspiration, four percent solar exposure, six percent chance of thunderstorms clearing by mid-afternoon, and ninety-three percent Rumplesnicker.$B$BWait, did that add to one hundred? I've got my notes around here somewhere." },
        ["text"] = "Винахідництво, мій дорогий $c, — це два відсотки натхнення в пляшці, чотири відсотки сонячного опромінення, шість відсотків імовірності, що гроза розсіється до середини дня, і дев'яносто три відсотки Рамплсніккера.$B$BСтривайте, це в сумі сто? Десь тут у мене були нотатки.",
        ["npcs"] = { [1] = 10305 },
        ["roles"] = { ["greeting"] = true },
    },
    [2374867243] = {
        ["english"] = { [1] = "If you heard that all of the Horde and Alliance collections have been completed, then you heard right, $c. All of the goods for the war that we gathered and prepared are in the process of being sent to Cenarion Hold in Silithus, with less than a day until the last of it arrives there. After that I suppose we'll just have to wait and see who assembles that scepter to ring the gong with, which will open the gates to Ahn'Qiraj and herald the war." },
        ["text"] = "Якщо ви чули, що Орда й Альянс завершили всі збори, то чули правильно, $c. Усі зібрані й підготовлені військові товари вже відправляють до Кенарійської цитаделі в Силітусі, і до прибуття останньої партії лишилося менше дня. Після цього, гадаю, залишиться лише чекати, хто збере скіпетр, щоб ударити в гонг, відкрити брами Ан'Кіражу й сповістити початок війни.",
        ["npcs"] = { [1] = 15535 },
        ["roles"] = { ["greeting"] = true },
    },
    [3164995616] = {
        ["english"] = { [1] = "I welcome you to Theramore, $N.$B$BI apologize for being abrupt and not having a lot of time to exchange pleasantries, but my city must come first. Too many things threaten our way of life and the sanctity of the Alliance. I must stay ever vigilant against forces outside of our control if I'm to ensure my people remain safe and happy.$B$BPerhaps we'll have more time to speak later." },
        ["text"] = "Вітаю вас у Тераморі, $N.$B$BПерепрошую за різкість і за те, що не маю часу на люб'язності, але моє місто понад усе. Надто багато загроз нависло над нашим способом життя й непорушністю Альянсу. Я мушу невпинно пильнувати сили поза нашим контролем, якщо хочу, щоб мій народ залишався в безпеці й добробуті.$B$BМожливо, згодом матимемо більше часу поговорити.",
        ["npcs"] = { [1] = 4968 },
        ["roles"] = { ["greeting"] = true },
    },
    [932277657] = {
        ["english"] = { [1] = "I carry odds and ends, but mostly just odds." },
        ["text"] = "Продаю всяку всячину, та здебільшого просто всячину.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2688733876] = {
        ["english"] = { [1] = "I can make amazing things with the materials I find out here. By Muradin's beard, there are fantastic creatures in these hills! Go have a whack at them, $N, and bring me back some tall tales." },
        ["text"] = "З матеріалів, які я знаходжу тут, можна робити дивовижні речі. Клянусь бородою Мурадіна, у цих пагорбах водяться неймовірні створіння! Ідіть, добряче їм всипте, $N, та поверніться з якоюсь небилицею.",
        ["npcs"] = { [1] = 11097 },
        ["roles"] = { ["greeting"] = true },
    },
    [2592882869] = {
        ["english"] = { [1] = "If it weren't for that cursed, gnomish luck, they'd never win a race!" },
        ["text"] = "Якби не та клята гномська вдача, вони б ніколи не виграли перегонів!",
        ["npcs"] = { [1] = 4429 },
        ["roles"] = { ["greeting"] = true },
    },
    [1827656364] = {
        ["english"] = { [1] = "I'll take a pint of Dark Iron ale.  Oh, you're not the $gwaiter:waitress;?" },
        ["text"] = "Мені пінту елю Темного Заліза.  О, ви не $gофіціант:офіціантка;?",
        ["npcs"] = { [1] = 9554, [2] = 10043 },
        ["roles"] = { ["greeting"] = true },
    },
    [340903867] = {
        ["english"] = { [1] = "I'd be wasting both your gold and my time if I were to teach you how to pilot a Mechanostrider, $c.  You're just too large!" },
        ["text"] = "Навчаючи вас керувати механодолгоногом, я лише змарнував би ваше золото й свій час, $c.  Ви просто завеликі!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3601205891] = {
        ["english"] = { [1] = "I wish to become a weaponsmith." },
        ["text"] = "Я хочу стати зброярем.",
        ["npcs"] = { [1] = 11145 },
        ["roles"] = { ["reply"] = true },
    },
    [3949279596] = {
        ["english"] = { [1] = "I think I need a bath.  *sniff*  I think you need one, too!" },
        ["text"] = "Гадаю, мені треба помитися.  *нюх*  І вам, схоже, теж!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1330399597] = {
        ["english"] = { [1] = "I said GOOD DAY!" },
        ["text"] = "Я сказав: ДОБРОГО ДНЯ!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [651131309] = {
        ["english"] = { [1] = "Interesting... continue, John." },
        ["text"] = "Цікаво... продовжуйте, Джоне.",
        ["npcs"] = { [1] = 9563 },
        ["roles"] = { ["reply"] = true },
    },
    [3108929088] = {
        ["english"] = { [1] = "I just can't seem to get comfortable without a sturdy ceiling of granite over my head. All these stars up there, enough to give ye the shivers." },
        ["text"] = "Я ніяк не можу почуватися затишно без міцної гранітної стелі над головою. А всі ці зорі вгорі — аж мороз поза шкірою.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2249432110] = {
        ["english"] = { [1] = "I know, I know, I'm out here in the middle of nowhere!$B$BMy home is actually in Ratchet, but after crashing my zeppelin here, I thought I might as well start the research I came here to do!" },
        ["text"] = "Знаю, знаю, я тут посеред казна-де!$B$BНасправді мій дім у Кабестані, але після того, як мій дирижабль розбився тут, я вирішив, що можна вже й почати дослідження, заради якого сюди прибув!",
        ["npcs"] = { [1] = 7771 },
        ["roles"] = { ["greeting"] = true },
    },
    [1303381148] = {
        ["english"] = { [1] = "I hope that you're here to help us take back Arathi Basin from The Defilers.  What do you say $N?" },
        ["text"] = "Сподіваюся, ви прийшли допомогти нам відбити Низину Араті в Осквернителів.  Що скажете, $N?",
        ["npcs"] = { [1] = 907 },
        ["roles"] = { ["greeting"] = true },
    },
    [2612499216] = {
        ["english"] = { [1] = "Interesting, interesting... I know of a druid that lives atop the hill above the Wailing Caverns, $N. She might be able to tell you more about this shard you have found.$B$BNow, I must get back to work!" },
        ["text"] = "Цікаво, цікаво... Я знаю друїдку, що живе на пагорбі над Печерами Стогону, $N. Можливо, вона зможе розповісти більше про знайдений вами уламок.$B$BА тепер мені треба повертатися до роботи!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1261096468] = {
        ["english"] = { [1] = "I don't train smiths with no skill, come back when you have something decent to show me." },
        ["text"] = "Я не навчаю ковалів без жодної вправності. Поверніться, коли матимете що пристойне показати.",
        ["npcs"] = { [1] = 7230 },
        ["roles"] = { ["greeting"] = true },
    },
    [635788742] = {
        ["english"] = { [1] = "Icy Scale Breastplate." },
        ["text"] = "Нагрудник із крижаної луски.",
        ["npcs"] = { [1] = 16365 },
        ["roles"] = { ["reply"] = true },
    },
    [3001193895] = {
        ["english"] = { [1] = "I need no home to know I still have a place in this world, $c. The tribes will see... all of them. They fight amongst one another, and for what? Scraps left over by vultures... lands infested by the Legion... bah!$B$BThe centaur should be proud of their heritage--it is just as noble as any Night elf's or orc's--it is time we started acting like it!" },
        ["text"] = "Мені не потрібен дім, щоб знати: я все ще маю місце в цьому світі, $c. Племена ще побачать... усі вони. Вони воюють між собою — заради чого? За недоїдки після стерв'ятників... за землі, кишма набиті Легіоном... тьху!$B$BКентаври мають пишатися своїм спадком — він не менш шляхетний, ніж спадок нічних ельфів чи орків. Час нам нарешті поводитися відповідно!",
        ["npcs"] = { [1] = 13717 },
        ["roles"] = { ["greeting"] = true },
    },
    [2543302165] = {
        ["english"] = { [1] = "I have given my all... for the Horde..." },
        ["text"] = "Я віддав усе... за Орду...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1894248563] = {
        ["english"] = { [1] = "I lived in Dire Maul for a little bit.  That was fun.  Really." },
        ["text"] = "Я трохи пожив у Страхомісті.  Було весело.  Справді.",
        ["npcs"] = { [1] = 14827 },
        ["roles"] = { ["greeting"] = true },
    },
    [2294268062] = {
        ["english"] = { [1] = "Interesting, continue please." },
        ["text"] = "Цікаво, продовжуйте, будь ласка.",
        ["npcs"] = { [1] = 8879 },
        ["roles"] = { ["reply"] = true },
    },
    [2642388925] = {
        ["english"] = { [1] = "I don't care to hear it, $N. Nope, no way are you going to be let into the Searing Gorge. Impossible. Not going to happen. How many times do I have to tell you - I can't let you in! Do you not speak common? Are you an orc in disguise? N-O. NO!$B$BIf I let you in, then I have to let everybody in. Pretty soon your close friends will want in, then their distant relatives, then their friends, and so on and so forth. The last time that happened... well, we won't talk about the last time it happened. " },
        ["text"] = "Не хочу цього слухати, $N. Ні, нізащо вас не пустять у Випалену ущелину. Неможливо. Цього не станеться. Скільки разів повторювати — я не можу вас пропустити! Ви що, не розумієте загальної мови? Може, ви орк під маскуванням? Н-І. НІ!$B$BЯкщо пущу вас, доведеться пускати всіх. Потім захочуть ваші близькі друзі, тоді їхні далекі родичі, потім їхні друзі, і так далі, і так далі. Востаннє, коли так сталося... гаразд, про той випадок ми говорити не будемо. ",
        ["npcs"] = { [1] = 3836 },
        ["roles"] = { ["greeting"] = true },
    },
    [97165450] = {
        ["english"] = { [1] = "Inside the great tent at the northwest corner of the village is where Chaw Stronghide resides.  He will teach you what you must know of Leatherworking for now." },
        ["text"] = "Чау Міцна Шкура мешкає у великому наметі в північно-західному куті селища.  Він навчить вас того, що наразі треба знати про шкірництво.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [3347687104] = {
        ["english"] = { [1] = "Innkeeper Norman on upper ring of Trade Quarter is one to talk to." },
        ["text"] = "Поговоріть із корчмарем Норманом на верхньому кільці Торгового кварталу.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [3157166620] = {
        ["english"] = { [1] = "I don't know what happened. I had just arrived at Venomspite and then all of a sudden I woke up in this cage!$B$BAre you here to rescue me?" },
        ["text"] = "Не знаю, що сталося. Я щойно прибув до Отрутомерзля, а потім раптом прокинувся в цій клітці!$B$BВи прийшли мене визволити?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1894532908] = {
        ["english"] = { [1] = "Inner ring of War Quarter where James Van Brunt work.  Him make us good chain." },
        ["text"] = "Внутрішнє кільце Військового кварталу, де працює Джеймс Ван Брант.  Він робить нам добру кольчугу.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [4036159935] = {
        ["english"] = { [1] = "I will access the discs now." },
        ["text"] = "Зараз я отримаю доступ до дисків.",
        ["npcs"] = { [1] = 7172 },
        ["roles"] = { ["reply"] = true },
    },
    [3096488401] = {
        ["english"] = { [1] = "I hear that you've already begun to pull your weight around here.$B$BGood.  I was worried that we were going to have to 'convince' you to help out." },
        ["text"] = "Чув, ви вже почали приносити тут користь.$B$BДобре.  Я вже боявся, що доведеться вас трохи «переконати» допомогти.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3114991326] = {
        ["english"] = { [1] = "Inn" },
        ["text"] = "Заїзд",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["reply"] = true },
    },
    [4079620047] = {
        ["english"] = { [1] = "I had no choice, or so I thought. I would endure the destruction of Thaurissan and stand by the side of my king and his people.$B$BUnder the control of Ragnaros, King Dagran Thaurissan tore out the heart of this mountain and erected Blackrock Spire. We worked tirelessly to build a dwarven city mightier than any city or fortress that came before... or would come after." },
        ["text"] = "У мене не було вибору — принаймні я так думав. Я переживу знищення Тауріссана й стоятиму поруч зі своїм королем і його народом.$B$BПід владою Раґнароса король Даґран Тауріссан вирвав серце цієї гори й звів Чорнокамінний Шпиль. Ми невтомно працювали, щоб збудувати дворфійське місто, могутніше за будь-яке місто чи фортецю до нього... і після нього.",
        ["npcs"] = { [1] = 8888 },
        ["roles"] = { ["greeting"] = true },
    },
    [3320339246] = {
        ["english"] = { [1] = "Initiating visual aid representation number two.$B$BThe second resultant variance of the Earthen matrix retains many desired elements when compared to the standard subterranean matrix.  The common nomenclature for this variant is \"Dwarf\".$B$BThis variant retains strength and stamina inherent to the Earthen.  In some cases, the dwarf even exceeds the cognitive powers of the Earthen's matrix.  The dwarf, however, retains none of the physical composition of Azeroth's various stone core compounds." },
        ["text"] = "Запуск візуального представлення номер два.$B$BДругий результат варіації матриці земельників зберігає багато бажаних елементів порівняно зі стандартною підземною матрицею.  Загальновживана назва цього варіанта — «дворф».$B$BЦей варіант зберігає силу й витривалість, притаманні земельникам.  У деяких випадках дворф навіть перевершує когнітивні можливості матриці земельників.  Однак дворф не зберігає фізичного складу з різних кам'яних сполук ядра Азероту.",
        ["npcs"] = { [1] = 7172 },
        ["roles"] = { ["greeting"] = true },
    },
    [4220935312] = {
        ["english"] = { [1] = "Indeed. The Scarlet Crusade are an aberration of the Order of the Silver Hand.$B$BYou must believe me, $r; Taelan is a good man. He needs guidance. He needs to remember... remember what it is to be noble and honorable. I know that in his heart, he knows what he does is wrong. Will you help him? Will you help him remember?" },
        ["text"] = "Саме так. Багряний Похід — спотворення Ордена Срібної Десниці.$B$BВи мусите повірити мені, $r: Тейлан — добра людина. Йому потрібне наставництво. Він мусить згадати... згадати, що означає бути шляхетним і чесним. Я знаю: у глибині душі він розуміє, що чинить неправильно. Ви допоможете йому? Допоможете згадати?",
        ["npcs"] = { [1] = 1855 },
        ["roles"] = { ["greeting"] = true },
    },
    [3876301080] = {
        ["english"] = { [1] = "Indeed. The item was ultimately destroyed and Deathwing nearly slain by the combined and renewed power of the four remaining Aspects. Where Deathwing is now is unknown. What we do know, however, is that one of his progeny, Nefarian, rules this citadel and wishes to continue where his father left off." },
        ["text"] = "Саме так. Зрештою предмет було знищено, а Смертекрила майже вбито спільною, відновленою силою чотирьох Аспектів, що лишилися. Де Смертекрил тепер — невідомо. Але ми знаємо, що один із його нащадків, Нефаріан, править цією цитаделлю й хоче продовжити справу батька.",
        ["npcs"] = { [1] = 10296, [2] = 10299 },
        ["roles"] = { ["greeting"] = true },
    },
    [292447453] = {
        ["english"] = { [1] = "I got nothing new for you, kid. You've outgrown manual labor..." },
        ["text"] = "Нічого нового для тебе немає, малий. Ти вже переріс ручну працю...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1677611960] = {
        ["english"] = { [1] = "I want to exchange my Emerald Essence for Ruby Essence." },
        ["text"] = "Я хочу обміняти смарагдову сутність на рубінову.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2035621041] = {
        ["english"] = { [1] = "I don't have time for idle gossip, I'm a professional!" },
        ["text"] = "У мене немає часу на порожні балачки, я професіонал!",
        ["npcs"] = { [1] = 11031 },
        ["roles"] = { ["greeting"] = true },
    },
    [2435330671] = {
        ["english"] = { [1] = "I don't admit this lightly, but you are a far better smith than I am. If you want to learn more than my meager teachings then I suggest you seek out a Dwarf named Therum Deepforge in Stormwind. You will find him in the Dwarven District." },
        ["text"] = "Не люблю це визнавати, але ви значно кращий коваль за мене. Якщо хочете дізнатися більше, ніж можуть дати мої скромні уроки, раджу відшукати дворфа на ім'я Терум Глибокогорн у Штормовії. Ви знайдете його в Дворфівському районі.",
        ["npcs"] = { [1] = 514 },
        ["roles"] = { ["greeting"] = true },
    },
    [2643518333] = {
        ["english"] = { [1] = "I wonder how many more of them live among us. I knew Spark for years - never could I have imagined that he was a traitor." },
        ["text"] = "Цікаво, скільки ще таких живе серед нас. Я знав Іскру роками — ніколи б не подумав, що він зрадник.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2397577284] = {
        ["english"] = { [1] = "Indeed. The brood mother of the Black Dragonflight had used illusion and trickery to disguise herself as a member of the royal court. Worse yet, she had assumed control of the current Highlord of Stormwind, Bolvar Fordragon.$B$BIt is no wonder that such foolish military decisions had been made. The movement of the Alliance forces as of late had left us scratching our heads. We now understand that the Black Flight was attempting to divide the empire - destroy it from within." },
        ["text"] = "Саме так. Матір виводка Чорної зграї за допомогою ілюзій і хитрощів видавала себе за члена королівського двору. Ба більше, вона встановила контроль над нинішнім верховним лордом Штормовію Болваром Фордраґоном.$B$BНе дивно, що ухвалювалися такі дурні військові рішення. Останні пересування сил Альянсу змушували нас лише чухати потилиці. Тепер ми розуміємо: Чорна зграя намагалася розділити королівство й знищити його зсередини.",
        ["npcs"] = { [1] = 4949 },
        ["roles"] = { ["greeting"] = true },
    },
    [3436123390] = {
        ["english"] = { [1] = "I'm afraid there is little I can teach you, $c. You're free to browse my wares, of course, but you will not find them of use to you." },
        ["text"] = "Боюся, я мало чого можу вас навчити, $c. Звісно, можете переглянути мої товари, але нічого корисного для себе там не знайдете.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1523987938] = {
        ["english"] = { [1] = "I heard their mocking laughter as my gryphon crashed and burned, $c.$B$B\"Slidore, you stink!\" They shouted.$B$BNobody talks to Slidore that way! Help me get out of here so that I can show them who the real stinker is!" },
        ["text"] = "Я чув їхній глузливий регіт, коли мій грифон упав і загорівся, $c.$B$B«Слідоре, від тебе тхне!» — кричали вони.$B$BНіхто так не говорить зі Слідором! Допоможіть мені вибратися звідси, і я покажу їм, хто тут насправді смердить!",
        ["npcs"] = { [1] = 13438 },
        ["roles"] = { ["greeting"] = true },
    },
    [1176834030] = {
        ["english"] = { [1] = "I can get back to the Stronghold on my own -- I just need a hand getting the blazes out of this hive!$B$BWho... who are you?" },
        ["text"] = "До твердині я дістануся й сам — мені лише треба допомогти забратися геть із цього вулика!$B$BХто... хто ви?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3263787790] = {
        ["english"] = { [1] = "I'd talk to you if you smelled better. How about cologne? Maybe perfume?" },
        ["text"] = "Я поговорив би з вами, якби від вас краще пахло. Може, одеколон? Або парфуми?",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [2722912346] = {
        ["english"] = { [1] = "In the time before time, what the usurpers would later call the First Age of Creation, my master and his siblings ruled over this world. It was they, the Old Gods, who created all.$B$BAnd it was they who would ultimately be cast down by those that would call themselves Shapers.\010" },
        ["text"] = "За часів до самого часу, в те, що узурпатори пізніше назвуть Першою Епохою Творення, мій володар і його брати та сестри правили цим світом. Саме вони, Старі Боги, створили все.$B$BІ саме їх зрештою повалили ті, хто назвав себе Творцями.\010",
        ["npcs"] = { [1] = 14347 },
        ["roles"] = { ["greeting"] = true },
    },
    [3973963599] = {
        ["english"] = { [1] = "I heard that, after the fireworks show, goblets will be brought to the tables.  Fine toasts we shall raise!" },
        ["text"] = "Чув, що після феєрверків на столи принесуть келихи.  Піднімемо добрі тости!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3680940595] = {
        ["english"] = { [1] = "I will, Tirion." },
        ["text"] = "Так і зроблю, Тіріоне.",
        ["npcs"] = { [1] = 1855 },
        ["roles"] = { ["reply"] = true },
    },
    [1172414675] = {
        ["english"] = { [1] = "I understand this holiday is a creation not of our allies, but the Horde. Why we follow suit, I do not know." },
        ["text"] = "Як я розумію, це свято створили не наші союзники, а Орда. Навіщо ми наслідуємо їх — не знаю.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1115410784] = {
        ["english"] = { [1] = "Indeed, the hills of Winterspring are currently attempting to withstand a renewed Scourge assault. Your assistance would help them greatly.$B$BNumber of Necropolises remaining: $2284W" },
        ["text"] = "Саме так, пагорби Зимоключа зараз намагаються витримати новий наступ Скари. Ваша допомога їм дуже знадобиться.$B$BНекрополів залишилося: $2284W",
        ["npcs"] = { [1] = 16285, [2] = 16359 },
        ["roles"] = { ["greeting"] = true },
    },
    [1696649627] = {
        ["english"] = { [1] = "Indeed, Silverwing Hold is in need of your assistance.  Speak with Elfarran in the audience chamber at Stormwind Keep.", [2] = "Indeed, Silverwing Hold is in need of your assistance. Speak with Elfarran in the audience chamber at Stormwind Keep." },
        ["text"] = "Саме так, твердині Срібного Крила потрібна ваша допомога.  Поговоріть з Ельфарран у залі аудієнцій фортеці Штормовію.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [767304197] = {
        ["english"] = { [1] = "Indeed! They were given every advantage I could muster. I simply can't imagine what went wrong.$b$bHere, $c, take one. I've made a couple of modifications - little refinements really. Now there's no excuse for failure!" },
        ["text"] = "Саме так! Я дав їм усі переваги, які міг. Просто не уявляю, що пішло не так.$b$bОсь, $c, візьміть один. Я зробив кілька змін — дрібні вдосконалення, насправді. Тепер виправдань для невдачі немає!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2598150342] = {
        ["english"] = { [1] = "I do not believe you possess the mental acuity to grasp the nature of portal magic." },
        ["text"] = "Не думаю, що вашої гостроти розуму достатньо, аби осягнути природу портальної магії.",
        ["npcs"] = { [1] = 2485, [2] = 2489, [3] = 2492, [4] = 4165, [5] = 5957, [6] = 5958 },
        ["roles"] = { ["greeting"] = true },
    },
    [3480476628] = {
        ["english"] = { [1] = "Indeed you have, mon. Our stores of blight crystals be nearly sufficient!" },
        ["text"] = "Авжеж, друже. Наших запасів кристалів пошесті вже майже достатньо!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [532353638] = {
        ["english"] = { [1] = "I've got too much to do and not enough time to do it in, $r! Please, get out of my way.$B$BIf you're infected with the maggot slime or ghoul rot, I might be able to help you." },
        ["text"] = "У мене купа справ і замало часу, $r! Будь ласка, не заважайте.$B$BЯкщо ви заражені слизом опаришів або гниллю гулів, можливо, я зможу допомогти.",
        ["npcs"] = { [1] = 16284 },
        ["roles"] = { ["greeting"] = true },
    },
    [55106094] = {
        ["english"] = { [1] = "Incredible story. So how did he die?" },
        ["text"] = "Неймовірна історія. То як він помер?",
        ["npcs"] = { [1] = 4542 },
        ["roles"] = { ["reply"] = true },
    },
    [2103318085] = {
        ["english"] = { [1] = "If you like excitement, our captain's the best!  I love this job!" },
        ["text"] = "Якщо любите гострі відчуття, наш капітан — найкращий!  Обожнюю цю роботу!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1113485792] = {
        ["english"] = { [1] = "I can instruct you in alchemy.  Interested?" },
        ["text"] = "Я можу навчити вас алхімії.  Цікавить?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3288082008] = {
        ["english"] = { [1] = "I cannot store any more supplies.  I have all I can handle!" },
        ["text"] = "Я більше не можу зберігати припаси.  І так ледве все тримаю!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4212186553] = {
        ["english"] = { [1] = "I would have it back, mortal. Atiesh... From it I would create the Highborne anew. I would have it all back. Even the Queen..." },
        ["text"] = "Я хочу повернути його, смертний. Атієш... З нього я відродив би Високородних. Я повернув би все. Навіть Королеву...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3364221854] = {
        ["english"] = { [1] = "If you've been sent to kill me, please take a number and wait your turn." },
        ["text"] = "Якщо вас прислали мене вбити, будь ласка, візьміть номерок і дочекайтеся своєї черги.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2556570704] = {
        ["english"] = { [1] = "Incredible power can be found in the spirits or \"muisek\" of the creatures that we battle against.$B$BLook inside yourself; learn to harness the power of your own spirit, and you will be more powerful than you ever imagined." },
        ["text"] = "Неймовірну силу можна знайти в духах, або «муїсеках», істот, з якими ми б'ємося.$B$BЗазирніть у себе; навчіться приборкувати силу власного духу — і станете могутнішими, ніж будь-коли уявляли.",
        ["npcs"] = { [1] = 8115 },
        ["roles"] = { ["greeting"] = true },
    },
    [2756037103] = {
        ["english"] = { [1] = "If there were just a few more hours in a day..." },
        ["text"] = "Якби в добі було ще кілька годин...",
        ["npcs"] = { [1] = 3412 },
        ["roles"] = { ["greeting"] = true },
    },
    [1861845476] = {
        ["english"] = { [1] = "In your rush to glory, you assumed that the pace of the game revolved around your actions. Can you even fathom how preposterous that sounds to a being like me? A being that if so inclined could cause your own insignificant thoughts to crush the peanut sized mass of grey matter floating within your skull.\010" },
        ["text"] = "У гонитві за славою ви вирішили, що темп гри обертається навколо ваших дій. Чи здатні ви бодай уявити, наскільки безглуздо це звучить для істоти на кшталт мене? Істоти, яка за бажання могла б змусити ваші власні нікчемні думки розчавити арахісоподібну грудочку сірої речовини, що плаває у вашому черепі.\010",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2719508844] = {
        ["english"] = { [1] = "It has been years since I have thought with my heart, but it's all flooding back." },
        ["text"] = "Минуло багато років відтоді, як я думав серцем, але тепер усе повертається.",
        ["npcs"] = { [1] = 3189, [2] = 3400, [3] = 3405, [4] = 3409, [5] = 3410, [6] = 5613, [7] = 5892, [8] = 7294, [9] = 8404 },
        ["roles"] = { ["greeting"] = true },
    },
    [691842199] = {
        ["english"] = { [1] = "In these trying times, a simple donation of cloth can go a long way to help those less fortunate than ourselves.  Cloth goes a long way to making garments and bandages - both important for the war effort!$B$BIf you are interested in donating cloth pieces to the orcs of Orgrimmar, I will gladly accept them and make sure you receive the proper recognition for doing so.$B$BFor the Horde!" },
        ["text"] = "У ці тяжкі часи проста пожертва тканини може дуже допомогти тим, кому пощастило менше за нас.  Із тканини роблять одяг і бинти — і те, й інше важливе для війни!$B$BЯкщо хочете пожертвувати шматки тканини оркам Орґріммара, я залюбки їх прийму й подбаю, щоб ваш внесок належно відзначили.$B$BЗа Орду!",
        ["npcs"] = { [1] = 14726 },
        ["roles"] = { ["greeting"] = true },
    },
    [161838804] = {
        ["english"] = { [1] = "I can tell you where he's not..." },
        ["text"] = "Я можу сказати, де його точно немає...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1536824685] = {
        ["english"] = { [1] = "I'd like to stable my pet here" },
        ["text"] = "Я хочу залишити тут свого вихованця в стайні",
        ["npcs"] = { [1] = 6749, [2] = 9976, [3] = 9977, [4] = 9978, [5] = 9979, [6] = 9980, [7] = 9981, [8] = 9982, [9] = 9983, [10] = 9984, [11] = 9985, [12] = 9986, [13] = 9987, [14] = 9988, [15] = 9989, [16] = 10045, [17] = 10046, [18] = 10047, [19] = 10048, [20] = 10049, [21] = 10050, [22] = 10051, [23] = 10052, [24] = 10053, [25] = 10054, [26] = 10055, [27] = 10056, [28] = 10057, [29] = 10058, [30] = 10059, [31] = 10060, [32] = 10061, [33] = 10062, [34] = 10063, [35] = 10085, [36] = 11069, [37] = 11104, [38] = 11105, [39] = 11117, [40] = 11119, [41] = 13616, [42] = 14741, [43] = 15131, [44] = 15722, [45] = 16094 },
        ["roles"] = { ["reply"] = true },
    },
    [2947711340] = {
        ["english"] = { [1] = "In my travels I have learned the recipe for the Wispcloak.$B$BThis cloak is a tradeable Epic spellcasting cloak that grants Stamina, Spellpower, Intellect and Mana Recovery.   I am looking for someone worthy to teach this recipe to.$B$BSomeone who had completed all the normal dungeons of Northrend and had the \"Northrend Dungeonmaster\" achievement would be worthy of learning the recipe for the Wispcloak." },
        ["text"] = "У мандрах я вивчив рецепт Плаща вогника.$B$BЦе епічний плащ для заклиначів, яким можна торгувати; він надає витривалість, силу заклять, інтелект і відновлення мани.   Я шукаю когось гідного, кому можна передати цей рецепт.$B$BТой, хто пройшов усі звичайні підземелля Нортренду й здобув досягнення «Майстер підземель Нортренду», був би гідний вивчити рецепт Плаща вогника.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2480097182] = {
        ["english"] = { [1] = "I hear that the trolls in Sen'jin Village have a potion maker named Miao'zan.  Look there." },
        ["text"] = "Кажуть, у тролів у селищі Сен'джин є зіллєвар на ім'я Міао'зан.  Шукайте там.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [4283296317] = {
        ["english"] = { [1] = "I give unto you cordial salutations, $r.  You've come far off the beaten path merely to speak to someone dwelling inside a cave.  I trust there is a reason for your strange, yet not unforeseen visit here.  Yes?" },
        ["text"] = "Прийміть мої щирі вітання, $r.  Ви далеко відхилилися від битого шляху лише заради розмови з тим, хто мешкає в печері.  Певен, у цього дивного, хоч і не зовсім неочікуваного візиту є причина.  Так?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1944536224] = {
        ["english"] = { [1] = "I wish to unlearn my pet's skills." },
        ["text"] = "Я хочу, щоб мій вихованець забув свої навички.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3499139198] = {
        ["english"] = { [1] = "If you've the gold, I can teach you how to ride a hawkstrider." },
        ["text"] = "Якщо маєте золото, я навчу вас їздити на яструбодолгонозі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2674443080] = {
        ["english"] = { [1] = "If you have lost a piece of your Zandalarian armor, I may be able to help you." },
        ["text"] = "Якщо ви загубили частину зандаларського обладунку, можливо, я зможу допомогти.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3536571793] = {
        ["english"] = { [1] = "I don't think we can afford to pass an opportunity to ingratiate ourselves with the red flight. With the battles ahead, having them as allies would be invaluable." },
        ["text"] = "Не думаю, що ми можемо дозволити собі втратити нагоду заслужити прихильність червоної зграї. У прийдешніх битвах такі союзники будуть безцінні.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1266981845] = {
        ["english"] = { [1] = "I'm sorry, $N, but I have no time to spend on novices. You want someone closer to your own skill level. Try the night elf Milla Fairancora, in the Craftsmen's Terrace of Darnassus." },
        ["text"] = "Перепрошую, $N, але в мене немає часу на новачків. Вам потрібен хтось ближчий до вашого рівня. Спробуйте звернутися до нічної ельфійки Мілли Файранкори на Терасі Ремісників у Дарнасі.",
        ["npcs"] = { [1] = 3964, [2] = 4900 },
        ["roles"] = { ["greeting"] = true },
    },
    [2223377385] = {
        ["english"] = { [1] = "If you're here to be trained in the tactics and strategy of hunting, you've come to the right place!" },
        ["text"] = "Якщо ви тут, щоб навчитися тактики й стратегії полювання, то прийшли куди треба!",
        ["npcs"] = { [1] = 5116 },
        ["roles"] = { ["greeting"] = true },
    },
    [3460877980] = {
        ["english"] = { [1] = "I'm pleased to say that your talents have outpaced my own. Go away now. Err, try the tauren Una in the northwestern shops of Thunder Bluff's central plateau. She's very skilled, I assure you." },
        ["text"] = "Радий сказати, що ваші таланти перевершили мої. А тепер ідіть. Е-е, спробуйте поговорити з тауренкою Уною в крамницях на північному заході центрального плато Громового Бескиду. Вона дуже вправна, запевняю.",
        ["npcs"] = { [1] = 4588 },
        ["roles"] = { ["greeting"] = true },
    },
    [1514723804] = {
        ["english"] = { [1] = "I have about half the supplies needed to upgrade to veteran units." },
        ["text"] = "У мене є приблизно половина припасів, потрібних для поліпшення загонів до ветеранів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2256521846] = {
        ["english"] = { [1] = "In the Light we all cast shadows, my $g brother : sister;.  Do you seek further guidance today?" },
        ["text"] = "У Світлі ми всі відкидаємо тіні, $g мій брате : моя сестро;.  Чи шукаєте ви сьогодні подальших настанов?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3894461271] = {
        ["english"] = { [1] = "In the King's audience chamber you will find the Lady Hoteshem.  She can assist you in getting to Arathi Basin where The League of Arathor is in need of assistance against The Defilers." },
        ["text"] = "У королівській залі аудієнцій знайдете пані Хотешем.  Вона допоможе вам дістатися Низини Араті, де Лізі Аратора потрібна допомога проти Осквернителів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2447551472] = {
        ["english"] = { [1] = "I know many things, stranger, but your knowledge rivals my own. Enchanters who wish to hone their skills further are known to travel to the Tower of Azora, where an artisan named Kitta Firewind resides." },
        ["text"] = "Я знаю багато, незнайомцю, але ваші знання вже не поступаються моїм. Зачарувальники, які прагнуть удосконалитися, часто вирушають до Вежі Азори, де живе майстриня на ім'я Кітта Вогневій.",
        ["npcs"] = { [1] = 7949 },
        ["roles"] = { ["greeting"] = true },
    },
    [2040753477] = {
        ["english"] = { [1] = "I have food, if you are hungry, and you may make use of my tent, should you require rest." },
        ["text"] = "У мене є їжа, якщо ви голодні, і можете скористатися моїм наметом, якщо треба відпочити.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [985834855] = {
        ["english"] = { [1] = "I love pie." },
        ["text"] = "Я люблю пироги.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4000172456] = {
        ["english"] = { [1] = "In Outland, our forces fight against the Horde to control the Eye of the Storm. It is dangerous, fighting amidst the raging energies of the Nether. Do you have what it takes to join us?" },
        ["text"] = "У Позамежжі наші війська б'ються з Ордою за контроль над Оком Бурі. Битися серед шалених енергій Підсвіття небезпечно. Ви готові приєднатися до нас?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1602291588] = {
        ["english"] = { [1] = "I came to Outland hoping to discover powerful artifacts to assist the League of Arathor against the Defilers in Arathi Basin... but all I've found is this smashing magical loincloth, a ridiculous gnome sidekick, and an egomaniacal undead stalker who insists I've stolen his grey skull, or some such.$B$b$BIn any case, would you care to join the League in their fight while I continue my search?" },
        ["text"] = "Я прибув у Позамежжя в надії знайти могутні артефакти, що допоможуть Лізі Аратора проти Осквернителів у Низині Араті... але все, що я знайшов, — це приголомшлива магічна пов'язка на стегна, безглуздий гном-помічник і самозакоханий невмерлий переслідувач, який твердить, ніби я вкрав його сірий череп, чи щось таке.$B$b$BУ будь-якому разі, чи не бажаєте приєднатися до Ліги в їхній боротьбі, поки я продовжу пошуки?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2350173855] = {
        ["english"] = { [1] = "I'm sorry $g lad : lass; but ye just don't have the foundation to learn what I have to teach. But don't fret, go speak with my student Rotgath, he'll help ye out." },
        ["text"] = "Перепрошую, $g хлопче : дівчино;, але у вас просто немає базових знань, щоб учитися в мене. Та не сумуйте — поговоріть із моїм учнем Ротґатом, він вам допоможе.",
        ["npcs"] = { [1] = 4258 },
        ["roles"] = { ["greeting"] = true },
    },
    [3948314984] = {
        ["english"] = { [1] = "I can not train you." },
        ["text"] = "Я не можу вас навчати.",
        ["npcs"] = { [1] = 3352 },
        ["roles"] = { ["greeting"] = true },
    },
    [42378225] = {
        ["english"] = { [1] = "I've seen a troll named Lau'Tiki fishing down south at the Darkspear Strand.  That's just on the outskirts of Sen'jin Village." },
        ["text"] = "Я бачив троля на ім'я Лау'Тікі, що рибалив на півдні, біля узбережжя Темносписа.  Це просто на околиці селища Сен'джин.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [2257748929] = {
        ["english"] = { [1] = "In need of some alchemy supplies, are we?  Or do you have other business with me?" },
        ["text"] = "Потрібні алхімічні припаси?  Чи у вас до мене інша справа?",
        ["npcs"] = { [1] = 5594 },
        ["roles"] = { ["greeting"] = true },
    },
    [1100405747] = {
        ["english"] = { [1] = "I cannot train a $c such as yourself." },
        ["text"] = "Я не навчаю таких $c, як ви.",
        ["npcs"] = { [1] = 3596, [2] = 3601, [3] = 3963, [4] = 4138, [5] = 4146, [6] = 4205, [7] = 5501, [8] = 8308 },
        ["roles"] = { ["greeting"] = true },
    },
    [3105323091] = {
        ["english"] = { [1] = "I can teach you the finer points of Kodo Riding, provided you have enough gold to cover the lesson!" },
        ["text"] = "Я можу навчити вас тонкощів верхової їзди на кодо, якщо у вас вистачить золота на урок!",
        ["npcs"] = { [1] = 3690 },
        ["roles"] = { ["greeting"] = true },
    },
    [2644767469] = {
        ["english"] = { [1] = "I know these forests as if they were a part of me... But know that there is still much to be learned from them, and much danger still hidden." },
        ["text"] = "Я знаю ці ліси так, наче вони частина мене... Та знайте: у них іще багато чого можна навчитися й чимало небезпек досі приховано.",
        ["npcs"] = { [1] = 3691 },
        ["roles"] = { ["greeting"] = true },
    },
    [858757805] = {
        ["english"] = { [1] = "I seek further druidic training to have a closer understanding of the Earth Mother's will." },
        ["text"] = "Я прагну подальшого навчання друїда, щоб глибше зрозуміти волю Матері-Землі.",
        ["npcs"] = { [1] = 9465 },
        ["roles"] = { ["reply"] = true },
    },
    [791265381] = {
        ["english"] = { [1] = "I can't help ya'! You're ready to see someone who's been at it longer than I have! Let's see... you're an Alliance type, so you need to talk to Lilliam Sparkspindle in Stormwind." },
        ["text"] = "Нічим не можу допомогти! Вам уже час до когось досвідченішого за мене! Так... ви з Альянсу, тож вам треба поговорити з Лілліам Іскрошпиндел у Штормовії.",
        ["npcs"] = { [1] = 3494, [2] = 10993 },
        ["roles"] = { ["greeting"] = true },
    },
    [1085153845] = {
        ["english"] = { [1] = "In the northern part of Darkshore runs the Cliffspring River, flowing down from the lands now known as Felwood.  As the river flows out and empties out into the Mist's Edge, travel north to where the deepest parts of the ocean begin.  A stone formation that some call the Stone Claw due to its shape is where you may find what you seek.$B$BBe warned - threshers gather by the Stone Claw, and will attack those who trespass on their territory." },
        ["text"] = "У північній частині Темнобережжя тече Скельноджерельна річка, що спускається із земель, нині відомих як Сквернолісся.  Коли річка впадає в Край Туманів, пливіть на північ туди, де починаються найглибші води океану.  Кам'яне утворення, яке дехто через форму називає Кам'яним Кігтем, — саме там можете знайти те, що шукаєте.$B$BОбережно: біля Кам'яного Кігтя збираються молотарки й нападають на тих, хто заходить на їхню територію.",
        ["npcs"] = { [1] = 11800 },
        ["roles"] = { ["greeting"] = true },
    },
    [247290648] = {
        ["english"] = { [1] = "In grizzly times a druid can be a dear friend to those around them.  Ask any of the druids in the Cenarion Enclave and they will tell you the same." },
        ["text"] = "У ведмежі часи друїд може бути оленячо добрим другом для тих, хто поруч.  Спитайте будь-якого друїда в Кенарієвому анклаві — вони скажуть те саме.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [2046463878] = {
        ["english"] = { [1] = "I'd like a pair of Synthebrew Goggles." },
        ["text"] = "Я хочу пару окулярів синтехмелю.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3303135493] = {
        ["english"] = { [1] = "It is good to see you again, $N. Would you like me to take you to the master's lair?" },
        ["text"] = "Радий знову вас бачити, $N. Хочете, я відведу вас до лігва господаря?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [925077878] = {
        ["english"] = { [1] = "I've arranged for your flight to Manaforge Coruu.  Are you ready, $N?  You will be dropped off behind enemy lines so make sure you bring everything you need." },
        ["text"] = "Я домовився про ваш переліт до Манакузні Коруу.  Ви готові, $N?  Вас висадять у тилу ворога, тож переконайтеся, що взяли все необхідне.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2886737654] = {
        ["english"] = { [1] = "In decades past - of now ancient wars and conflicts - our kind was driven to the brink of extinction. Much we have endured, $r.$B$BThe onslaught of the Burning Legion. The Demon Soul. The Aspects divided. The ascension of Deathwing. The enslavement of our Queen, Alexstrasza, by the Dragonmaw.$B$BThrough it all, we have been the unshakable will of the dragons - the undaunted force that has fought to represent our waning existence in this world." },
        ["text"] = "У минулі десятиліття, за часів нині вже давніх воєн і конфліктів, наш рід опинився на межі знищення. Багато ми витерпіли, $r.$B$BНаступ Палаючого Легіону. Душа Демона. Роз'єднання Аспектів. Піднесення Смертекрила. Поневолення нашої Королеви Алекстрази Драконовою Пащою.$B$BКрізь усе це ми залишалися незламною волею драконів — безстрашною силою, що боролася за саме наше згасаюче існування в цьому світі.",
        ["npcs"] = { [1] = 10296, [2] = 10299 },
        ["roles"] = { ["greeting"] = true },
    },
    [1978369933] = {
        ["english"] = { [1] = "I thought that they now called themselves the Scarlet Onslaught?" },
        ["text"] = "Я думав, тепер вони називають себе Багряним Натиском?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3291038522] = {
        ["english"] = { [1] = "I believe I noticed a new shipment of mail being delivered not too long ago.  You'll find the mailbox just outside the Thunder Bluff Bank on the lower rise." },
        ["text"] = "Гадаю, не так давно я бачив, як привезли нову партію пошти.  Поштова скринька стоїть просто біля банку Громового Бескиду, на нижньому уступі.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [381312462] = {
        ["english"] = { [1] = "I think Elder Splitrock has traveled to Mauradon in the Desolace." },
        ["text"] = "Гадаю, старійшина Розколота Скеля вирушив до Мародона в Спустошищі.",
        ["npcs"] = { [1] = 15581, [2] = 15587 },
        ["roles"] = { ["greeting"] = true },
    },
    [2708542324] = {
        ["english"] = { [1] = "I can't find my pet frog, Jubjub.  She loves Dark Iron Ale, it's all she ever drinks, but can be so hard to get!  Now I'm out... and Jubjub must have run away to find more!$B$BI wish she would come back..." },
        ["text"] = "Не можу знайти свою жабку Джубджуб.  Вона обожнює ель Темного Заліза — тільки його й п'є, а дістати його так важко!  Тепер у мене все скінчилося... і Джубджуб, мабуть, утекла шукати ще!$B$BХотілося б, щоб вона повернулася...",
        ["npcs"] = { [1] = 14871 },
        ["roles"] = { ["greeting"] = true },
    },
    [2172441221] = {
        ["english"] = { [1] = "If a turtle doesn't have a shell, is he homeless or naked?" },
        ["text"] = "Якщо черепаха без панцира, вона бездомна чи гола?",
        ["npcs"] = { [1] = 14444 },
        ["roles"] = { ["greeting"] = true },
    },
    [3256076897] = {
        ["english"] = { [1] = "In death, the animals of the world bestow both life and protection unto us.  If you feel that you can offer the appropriate respect for their sacrifice, then the skinner's profession may suit you.  Speak with Eladriel in the Craftsmen's Terrace in northern Darnassus to learn more." },
        ["text"] = "Після смерті тварини світу дарують нам і життя, і захист.  Якщо ви здатні виявити належну повагу до їхньої жертви, вам може підійти ремесло шкурника.  Поговоріть з Еладріель на Терасі Ремісників у північному Дарнасі, щоб дізнатися більше.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [1256744429] = {
        ["english"] = { [1] = "In death, the animals of the world bestow both life and protection unto us.  If you feel that you can offer the appropriate respect for their sacrifice, then the skinner's profession may suit you.  Speak with Eladriel in the Craftsman's Terrace in northern Darnassus to learn more." },
        ["text"] = "Після смерті тварини світу дарують нам і життя, і захист.  Якщо ви здатні виявити належну повагу до їхньої жертви, вам може підійти ремесло шкурника.  Поговоріть з Еладріель на Терасі Ремісників у північному Дарнасі, щоб дізнатися більше.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [512059028] = {
        ["english"] = { [1] = "I will make it known to you. You are obviously already proving yourself in our ranks to become a lieutenant so quickly. Perhaps you can return to me later and I will have tasks for you. The council adores those skilled in the arcane, but servants of all kinds are always welcome, no matter their profession." },
        ["text"] = "Я розповім вам. Очевидно, ви вже добре зарекомендували себе в наших лавах, раз так швидко стали лейтенантом. Можливо, згодом повернетеся до мене, і в мене знайдуться для вас завдання. Рада обожнює вправних у таємній магії, але слуги будь-якого фаху завжди бажані, незалежно від професії.",
        ["npcs"] = { [1] = 3216 },
        ["roles"] = { ["greeting"] = true },
    },
    [3256384404] = {
        ["english"] = { [1] = "I want to exchange my Amber Essence for Ruby Essence." },
        ["text"] = "Я хочу обміняти бурштинову сутність на рубінову.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2555952183] = {
        ["english"] = { [1] = "I'm just a student myself, really. Rhiannon's the expert. She's standing by the crates over there. You can learn a lot from her." },
        ["text"] = "Я й сам лише учень, якщо чесно. Ріаннон — справжня фахівчиня. Вона стоїть біля ящиків он там. У неї можна багато чого навчитися.",
        ["npcs"] = { [1] = 11048 },
        ["roles"] = { ["greeting"] = true },
    },
    [1190466465] = {
        ["english"] = { [1] = "In Alterac Valley, battles rage and equipment is in short supply." },
        ["text"] = "В Альтерацькій долині точаться битви, а спорядження бракує.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [19494762] = {
        ["english"] = { [1] = "I cant follow the tracers back out, too many flesh beasts in the way.Send someone in... Follow the tracers... Ya-Six out." },
        ["text"] = "Не можу вибратися назад за трасерами — дорогою надто багато плотяних звірів. Пошліть когось усередину... Ідіть за трасерами... Я-Шість, кінець зв'язку.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1142699825] = {
        ["english"] = { [1] = "If you're going to come out here, make yourself useful because the shadowstalker over there isn't doing much." },
        ["text"] = "Якщо вже прийшли сюди, будьте корисні, бо той тіньовий переслідувач он там майже нічого не робить.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1195479299] = {
        ["english"] = { [1] = "I have traveled far in search of a way to ultimately defeat the League of Arathor in Arathi Basin, but that loin-clothed lummox Adam Eternum hounds my every move.$B$b$BStill, if slayers such as you were to return to Azeroth, perhaps we could defeat the Alliance once and for all!" },
        ["text"] = "Я здолав довгий шлях, шукаючи спосіб остаточно перемогти Лігу Аратора в Низині Араті, але той бовдур у пов'язці на стегнах, Адам Етернум, переслідує мене на кожному кроці.$B$b$BТа якщо такі вбивці, як ви, повернуться до Азероту, можливо, ми нарешті переможемо Альянс раз і назавжди!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4177974275] = {
        ["english"] = { [1] = "In ages past, Eldre'Thalas was a nexus of magical power, and those who dwelt within its hallowed halls wielded immense power.  One such night elf was Millicent Serene - a naturalist who willed the power of nature itself into potent artifacts she forged.$B$BThe Fruit of Fertility was her crowning achievement... she used a specially prepared moonwell to grow an exotic and vibrant vine that was imbued with an aura of protection and growth.  All of Eldre'Thalas flourished from its existence." },
        ["text"] = "У давні віки Елдре'Талас був осередком магічної сили, а ті, хто мешкав у його священних залах, володіли величезною могутністю.  Однією з таких нічних ельфійок була Міллісент Серен — натуралістка, що вкладала саму силу природи в могутні артефакти, які кувала.$B$BПлід Родючості був її найвищим досягненням... вона скористалася особливо підготовленим місячним колодязем, щоб виростити екзотичну, сповнену життя лозу, наділену аурою захисту й росту.  Завдяки їй увесь Елдре'Талас процвітав.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3079436101] = {
        ["english"] = { [1] = "I hold the key to lands of free! Chase me and you'll see!" },
        ["text"] = "У мене ключ від вільних земель! Наздожени мене — і сам побачиш!",
        ["npcs"] = { [1] = 14354 },
        ["roles"] = { ["greeting"] = true },
    },
    [625066778] = {
        ["english"] = { [1] = "I'm a scientist who studies both time and sound, so I'm not quite certain how I'm supposed to think, or find the time to get any work done around here, with all of this racket?!$B$BWhy can't these fools go blow themselves up somewhere else?$B$BAh well, at least I look good.  Say, $g boy : lovely;, have I seen you around here before?" },
        ["text"] = "Я вчений, який досліджує і час, і звук, тож зовсім не розумію, як тут можна думати чи знаходити час на роботу серед цього гуркоту?!$B$BЧому ці дурні не можуть піти й підірвати себе деінде?$B$BЕх, принаймні я добре виглядаю.  Скажіть, $g хлопче : красуне;, ми раніше тут не зустрічалися?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1477266699] = {
        ["english"] = { [1] = "I do not have much time in this world, but Light willing, it is time enough to fulfill my destiny.  When you face Baron Rivendare, I will be with you." },
        ["text"] = "Мені лишилося небагато часу в цьому світі, але, хай буде воля Світла, його вистачить, щоб здійснити мою долю.  Коли ви постанете перед бароном Рівендером, я буду з вами.",
        ["npcs"] = { [1] = 10917 },
        ["roles"] = { ["greeting"] = true },
    },
    [2554924965] = {
        ["english"] = { [1] = "I was shot down by that reckless fool, Mulverick. I fear that if I do not make it back to base, all will be lost! Mulverick and his squad of War Riders must be stopped!" },
        ["text"] = "Мене збив той безрозсудний дурень Малверік. Боюся, якщо я не повернуся на базу, все буде втрачено! Малверіка та його загін Бойових Вершників треба зупинити!",
        ["npcs"] = { [1] = 13437 },
        ["roles"] = { ["greeting"] = true },
    },
    [2706716285] = {
        ["english"] = { [1] = "I have no time to waste on the likes of you $c." },
        ["text"] = "У мене немає часу на таких, як ви, $c.",
        ["npcs"] = { [1] = 2126, [2] = 2127, [3] = 4565 },
        ["roles"] = { ["greeting"] = true },
    },
    [3478326312] = {
        ["english"] = { [1] = "I had a bad encounter with some of the Defias around here recently, but Michelle Belle fixed me up pretty well.  Check with her in the Lion's Pride Inn and see if she'll teach you." },
        ["text"] = "Нещодавно я невдало зіткнувся з кількома Непокірними неподалік, але Мішель Белль добряче мене підлікувала.  Знайдіть її в заїзді «Левова Гордість» і спитайте, чи не навчить вас.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [4163610484] = {
        ["english"] = { [1] = "I have just the thing you need to cast your spell." },
        ["text"] = "У мене є саме те, що вам потрібно для застосування закляття.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [769142860] = {
        ["english"] = { [1] = "In a place called Feralas to the west of here, the hippogryphs, long-time companions of the night elves, are in danger.$B$BI need you to rescue an egg from the ruins of Isildien, to the south, there. The Super Egg-O-Matic can analyze any egg brought to it and judge if it is likely to hatch. I then send the eggs along to the druids, safe from the Gordunni ogres' dark magics.$B$BPlease know, $N, some of the rescued eggs are bad eggs, and will never hatch." },
        ["text"] = "У місці під назвою Фералас, на захід звідси, гіпогрифи — давні супутники нічних ельфів — опинилися в небезпеці.$B$BМені потрібно, щоб ви врятували яйце з руїн Ісільдієна на півдні. Супер Яйце-о-Матик може проаналізувати будь-яке принесене яйце й визначити, чи воно, ймовірно, вилупиться. Потім я передаю яйця друїдам, подалі від темної магії огрів Ґордунні.$B$BАле знайте, $N: деякі врятовані яйця зіпсовані й ніколи не вилупляться.",
        ["npcs"] = { [1] = 7763 },
        ["roles"] = { ["greeting"] = true },
    },
    [301446873] = {
        ["english"] = { [1] = "I need to go. Evil stirs. Die well, Omarion." },
        ["text"] = "Мені треба йти. Зло ворушиться. Помри достойно, Омаріоне.",
        ["npcs"] = { [1] = 16365 },
        ["roles"] = { ["reply"] = true },
    },
    [2353007902] = {
        ["english"] = { [1] = "I can teach you how to cook!" },
        ["text"] = "Я можу навчити вас куховарити!",
        ["npcs"] = { [1] = 1355, [2] = 1382, [3] = 1430, [4] = 1699, [5] = 2818, [6] = 3026, [7] = 3067, [8] = 3087, [9] = 4210, [10] = 4552, [11] = 6286, [12] = 8306 },
        ["roles"] = { ["greeting"] = true },
    },
    [1770409445] = {
        ["english"] = { [1] = "If you manage to complete a deck of Warlords cards you will be rewarded with a Greater Darkmoon card of Heroism.   This card will occasionally heal you while you are engaged in melee combat." },
        ["text"] = "Якщо вам удасться зібрати повну колоду карт Воєвод, ви отримаєте Велику карту Темного Місяця Героїзму.   Вона час від часу зцілюватиме вас у ближньому бою.",
        ["npcs"] = { [1] = 14847 },
        ["roles"] = { ["greeting"] = true },
    },
    [3725689764] = {
        ["english"] = { [1] = "I saw soldiers from Stormwind fighting a fire before.  They were heroes!" },
        ["text"] = "Якось я бачив, як солдати зі Штормовію гасили пожежу.  Вони були героями!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1184953666] = {
        ["english"] = { [1] = "I guess so!" },
        ["text"] = "Мабуть, так!",
        ["npcs"] = { [1] = 14338 },
        ["roles"] = { ["reply"] = true },
    },
    [1493516042] = {
        ["english"] = { [1] = "I will return when I have the Plates of Uldum." },
        ["text"] = "Я повернуся, коли матиму Плити Ульдуму.",
        ["npcs"] = { [1] = 7918 },
        ["roles"] = { ["reply"] = true },
    },
    [3355174358] = {
        ["english"] = { [1] = "I'll be back once I straighten this mess out." },
        ["text"] = "Я повернуся, коли розберуся з цим безладом.",
        ["npcs"] = { [1] = 15170 },
        ["roles"] = { ["reply"] = true },
    },
    [729404608] = {
        ["english"] = { [1] = "I've got fresh meat, fish and mushrooms.  And plenty to drink!" },
        ["text"] = "У мене свіже м'ясо, риба й гриби.  І вдосталь випивки!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1479754649] = {
        ["english"] = { [1] = "I'm lookin' for rogue trainin'." },
        ["text"] = "Я шукаю навчання розбійника.",
        ["npcs"] = { [1] = 5166, [2] = 5167 },
        ["roles"] = { ["reply"] = true },
    },
    [200368344] = {
        ["english"] = { [1] = "I think you'll have better luck looking in Stormwind.  Ask a guard up there and they'll point you in the right direction." },
        ["text"] = "Гадаю, у Штормовії вам пощастить більше.  Спитайте там вартового — він підкаже правильний напрямок.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [1637932957] = {
        ["english"] = { [1] = "I guess that's that. We have all of the Arthas' Tears necessary. You might try asking around. One of these others is sure to have something that they still need collected for the war effort." },
        ["text"] = "Ну, схоже, це все. Ми зібрали всі потрібні Сльози Артаса. Можете порозпитувати навколо. Комусь із решти точно ще щось треба зібрати для військових потреб.",
        ["npcs"] = { [1] = 15445 },
        ["roles"] = { ["greeting"] = true },
    },
    [3257365487] = {
        ["english"] = { [1] = "I can not train you, $c." },
        ["text"] = "Я не можу вас навчати, $c.",
        ["npcs"] = { [1] = 3041, [2] = 3042, [3] = 3043, [4] = 3059, [5] = 3063 },
        ["roles"] = { ["greeting"] = true },
    },
    [2059547670] = {
        ["english"] = { [1] = "Imagine all the wisdom and knowledge locked away within Ulduar. The very secrets of life could be held there!" },
        ["text"] = "Уявіть усю мудрість і знання, замкнені в Ульдуарі. Там можуть зберігатися самі таємниці життя!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1777458907] = {
        ["english"] = { [1] = "If you are not here to help the cause, get out." },
        ["text"] = "Якщо ви не прийшли допомагати нашій справі — геть.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1995679491] = {
        ["english"] = { [1] = "Ilyenia Moonfire, the night elf weapon master who resides at the Warrior's Terrace in Darnassus, can train you in the use of bows." },
        ["text"] = "Іленія Місячний Вогонь, нічна ельфійка-майстриня зброї, що живе на Терасі Воїнів у Дарнасі, може навчити вас користуватися луками.",
        ["npcs"] = { [1] = 11867, [2] = 13084 },
        ["roles"] = { ["greeting"] = true },
    },
    [2907325581] = {
        ["english"] = { [1] = "I hope the archmage appreciates what I've gone through to uphold Hemet's end of the bargain." },
        ["text"] = "Сподіваюся, архімаг оцінить, через що мені довелося пройти, аби виконати частину угоди Гемета.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [482954710] = {
        ["english"] = { [1] = "I have lost my Ring of the Gathering Storm. Are you able to replace it for me?" },
        ["text"] = "Я загубив свій Перстень бурі, що насувається. Можете замінити його?",
        ["npcs"] = { [1] = 15498 },
        ["roles"] = { ["reply"] = true },
    },
    [2951716051] = {
        ["english"] = { [1] = "Ilyenia Moonfire, the night elf weapon master who resides at the Warrior's Terrace in Darnassus, can show ye how to use a bow." },
        ["text"] = "Іленія Місячний Вогонь, нічна ельфійка-майстриня зброї, що живе на Терасі Воїнів у Дарнасі, може навчити вас користуватися луком.",
        ["npcs"] = { [1] = 11865 },
        ["roles"] = { ["greeting"] = true },
    },
    [1888622745] = {
        ["english"] = { [1] = "Ilyenia Moonfire, the night elf weapon master on the Warrior's Terrace in Darnassus, or Buliwyf, the dwarf weapon master within the Timberline Arms in Ironforge, can train you in the use of fist weapons." },
        ["text"] = "Іленія Місячний Вогонь, нічна ельфійка-майстриня зброї на Терасі Воїнів у Дарнасі, або Булівіф, дворф-майстер зброї в «Лісовій Зброярні» Залізогарта, можуть навчити вас користуватися кулачною зброєю.",
        ["npcs"] = { [1] = 11867 },
        ["roles"] = { ["greeting"] = true },
    },
    [4062064095] = {
        ["english"] = { [1] = "Illidan's grasp over my tribe is strong, $N. It shall all be over soon, one way or another.$B$BAre you ready, $N?  My people's future depends on us." },
        ["text"] = "Влада Іллідана над моїм племенем сильна, $N. Скоро все скінчиться — так чи інакше.$B$BВи готові, $N?  Майбутнє мого народу залежить від нас.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1771918176] = {
        ["english"] = { [1] = "If your glove is too big, does it still fit like a glove?" },
        ["text"] = "Якщо рукавиця завелика, вона все одно сидить як влита?",
        ["npcs"] = { [1] = 14444 },
        ["roles"] = { ["greeting"] = true },
    },
    [3008099271] = {
        ["english"] = { [1] = "If you're looking for a flight back to Rut'theran Village, then you should talk to my night elven counterpart, Silva Fil'naveth." },
        ["text"] = "Якщо шукаєте переліт назад до селища Рут'теран, поговоріть із моєю колегою-нічною ельфійкою Сільвою Філ'навет.",
        ["npcs"] = { [1] = 11798 },
        ["roles"] = { ["greeting"] = true },
    },
    [429124263] = {
        ["english"] = { [1] = "If you've come looking for the finest craftsmanship on this or any other continent in the world, then you've come to the right place!$B$BGrimand Elmore, at your service!" },
        ["text"] = "Якщо ви прийшли шукати найкращу майстерність на цьому чи будь-якому іншому континенті світу — ви за адресою!$B$BҐріманд Елмор до ваших послуг!",
        ["npcs"] = { [1] = 1416 },
        ["roles"] = { ["greeting"] = true },
    },
    [1472040221] = {
        ["english"] = { [1] = "I must build a beacon for this marvelous device!" },
        ["text"] = "Я мушу збудувати маяк для цього дивовижного пристрою!",
        ["npcs"] = { [1] = 14743 },
        ["roles"] = { ["reply"] = true },
    },
    [4174243572] = {
        ["english"] = { [1] = "I'm glad Taretha is alive. We now must find a way to free her from her magical bindings." },
        ["text"] = "Я радий, що Тарета жива. Тепер треба знайти спосіб звільнити її від магічних пут.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2923639372] = {
        ["english"] = { [1] = "I'd like to purchase more Tharlendris seeds." },
        ["text"] = "Я хочу придбати ще насіння Тарлендріса.",
        ["npcs"] = { [1] = 4217, [2] = 7879, [3] = 9087 },
        ["roles"] = { ["reply"] = true },
    },
    [2371152878] = {
        ["english"] = { [1] = "I bet Josetta would be more than happy to teach you some new spells.  She is probably up in her room at the Lion's Pride Inn." },
        ["text"] = "Б'юся об заклад, Джозетта залюбки навчить вас кількох нових заклять.  Вона, мабуть, нагорі у своїй кімнаті в заїзді «Левова Гордість».",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [3786989994] = {
        ["english"] = { [1] = "If you have lost a piece of your Zandalarian armor, I may be able to help." },
        ["text"] = "Якщо ви загубили частину зандаларського обладунку, можливо, я зможу допомогти.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3000584588] = {
        ["english"] = { [1] = "If you've been to Zangarmarsh, you might've run into a fellow named Daniels. You know -- wears a strange helmet, only answers to \"the Specialist.\"$B$BOf course, I taught him everything he knows.$B$BDon't let the fine clothing fool you. I'm still a rogue at heart. Daniels and I spent a lot of time in the trenches together, but that was before I retired. As far as I know, he's still out there, giving 'em hell." },
        ["text"] = "Якщо бували в Занґарських болотах, могли натрапити на хлопця на ім'я Деніелс. Знаєте — у дивному шоломі, відгукується лише на «Фахівець».$B$BЗвісно, всього, що він знає, навчив його я.$B$BНе дайте гарному одягу вас обдурити. У душі я досі розбійник. Ми з Деніелсом чимало часу провели разом в окопах, але то було до моєї відставки. Наскільки знаю, він досі там і дає їм жару.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3558492716] = {
        ["english"] = { [1] = "I like to play in the water barrel, but I'm told it's not for children." },
        ["text"] = "Я люблю гратися в бочці з водою, але мені кажуть, що вона не для дітей.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [133904960] = {
        ["english"] = { [1] = "I'm ready to work for you today!  Give me the good stuff!" },
        ["text"] = "Я готовий сьогодні працювати на вас!  Давайте найкраще!",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [52395508] = {
        ["english"] = { [1] = "I train hunters in the ways and traditions of our ancestors. " },
        ["text"] = "Я навчаю мисливців шляхів і традицій наших предків. ",
        ["npcs"] = { [1] = 3038, [2] = 3963, [3] = 8308 },
        ["roles"] = { ["greeting"] = true },
    },
    [1171596383] = {
        ["english"] = { [1] = "I don't have time to babysit! Go talk to me assistant, Uthrar! " },
        ["text"] = "У мене немає часу з вами няньчитися! Ідіть поговоріть із моїм помічником, Утраром! ",
        ["npcs"] = { [1] = 5153 },
        ["roles"] = { ["greeting"] = true },
    },
    [1359453867] = {
        ["english"] = { [1] = "If you're looking to register a guild, I would suggest inquiring within the walls of Silvermoon City itself." },
        ["text"] = "Якщо хочете зареєструвати гільдію, раджу запитати в самому Срібномісяці.",
        ["npcs"] = { [1] = 6806 },
        ["roles"] = { ["greeting"] = true },
    },
    [3012163663] = {
        ["english"] = { [1] = "I can teach you the finer points of Wolf Riding, provided you have enough gold to cover the lesson!" },
        ["text"] = "Я можу навчити вас тонкощів верхової їзди на вовках, якщо у вас вистачить золота на урок!",
        ["npcs"] = { [1] = 4752 },
        ["roles"] = { ["greeting"] = true },
    },
    [1831652354] = {
        ["english"] = { [1] = "I left a war once to tend to the troubles back home in Westfall. That seems like a lifetime ago. Thank the Light that the Defias are no longer a threat.$B$BWe're a long way from home up here, but if we don't win this battle, there may not be a Westfall to return to." },
        ["text"] = "Колись я покинув війну, щоб розібратися з проблемами вдома, у Західному краї. Здається, це було ціле життя тому. Дяка Світлу, Непокірні більше не загроза.$B$BТут ми дуже далеко від дому, але якщо не переможемо в цій битві, нам, можливо, вже не буде до якого Західного краю повертатися.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3518002853] = {
        ["english"] = { [1] = "If you're looking for work, $c, grab yourself a pick and get to digging. There're ruins out there as far as the eye can see!" },
        ["text"] = "Якщо шукаєте роботу, $c, беріть кайло й копайте. Руїни тут тягнуться скільки сягає око!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4242111451] = {
        ["english"] = { [1] = "If you have what it takes, I will be happy to show you the way." },
        ["text"] = "Якщо у вас є все необхідне, я залюбки покажу шлях.",
        ["npcs"] = { [1] = 1317 },
        ["roles"] = { ["greeting"] = true },
    },
    [2069478398] = {
        ["english"] = { [1] = "I have discovered a use for the carapace of the crypt fiend and its various body parts. I am able to fashion an extremely light and very deadly set of armor by combining the fragments with some of the desecrated magical armors lost in Naxxramas." },
        ["text"] = "Я знайшов застосування панциру склепного павука та різним частинам його тіла. Поєднуючи уламки з оскверненими магічними обладунками, загубленими в Наксрамасі, я можу створити надзвичайно легкий і смертоносний комплект броні.",
        ["npcs"] = { [1] = 16132 },
        ["roles"] = { ["greeting"] = true },
    },
    [2286468951] = {
        ["english"] = { [1] = "I can't wait to see it! They seem ready for another round now, so prepare yourselves!" },
        ["text"] = "Не можу дочекатися! Схоже, вони вже готові до нового раунду, тож готуйтеся!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2387561812] = {
        ["english"] = { [1] = "I have tracked the various fragments of the staff across this world and in doing so, discovered Kel'Thuzad's plans to reform the staff. He has already collected several of the staff's fragments - which are being held by his most trusted lieutenants.$B$BI cannot emphasize enough the importance of keeping the greatstaff of the Guardian out of Kel'Thuzad's grasp. Frankly, I do not know what the result would be, other than a catastrophe of epic proportion." },
        ["text"] = "Я вистежив різні уламки посоха по всьому світу й завдяки цьому дізнався про плани Кел'Тузада відновити його. Він уже зібрав кілька уламків, які зберігають його найвідданіші лейтенанти.$B$BНе можу достатньо наголосити, наскільки важливо не дати великому посоху Хранителя потрапити до рук Кел'Тузада. Відверто кажучи, я не знаю, до чого це призведе, крім катастрофи епічного масштабу.",
        ["npcs"] = { [1] = 16116 },
        ["roles"] = { ["greeting"] = true },
    },
    [932259761] = {
        ["english"] = { [1] = "If you're looking for gadgets, doodads, thingamajigs, widgets, whatsis, dohickeys, or gizmos, you've come to the right place!" },
        ["text"] = "Якщо шукаєте ґаджети, прибамбаси, штукенції, причандалля, невідомо-що, химерні механізми чи інші пристрої — ви прийшли куди треба!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3960781341] = {
        ["english"] = { [1] = "I will teach you what I can. Each lesson is a gift from the Goddess herself. Use her gifts wisely, and you shall not falter." },
        ["text"] = "Я навчу вас того, що можу. Кожен урок — дар самої Богині. Користуйтеся її дарами мудро, і не схибите.",
        ["npcs"] = { [1] = 11070 },
        ["roles"] = { ["greeting"] = true },
    },
    [838337347] = {
        ["english"] = { [1] = "I trust very few of your kind, $N. But I can tell that you are a friend." },
        ["text"] = "Я мало кому з вашого роду довіряю, $N. Та бачу, що ви друг.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4103373221] = {
        ["english"] = { [1] = "I got your back, Slidore, but to be honest, you do stink. Take a shower, man." },
        ["text"] = "Я прикриваю тебе, Слідоре, але, якщо чесно, від тебе тхне. Сходи помийся, друже.",
        ["npcs"] = { [1] = 13438 },
        ["roles"] = { ["reply"] = true },
    },
    [123732888] = {
        ["english"] = { [1] = "I'll tell you what you need to know, but I don't have to like it. We're watching you and your kind." },
        ["text"] = "Я скажу вам те, що треба знати, але це не означає, що мені це подобається. Ми стежимо за вами й вашими.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2644086229] = {
        ["english"] = { [1] = "I lost Lord Valthalak's Amulet!" },
        ["text"] = "Я загубив Амулет лорда Вальталака!",
        ["npcs"] = { [1] = 16033 },
        ["roles"] = { ["reply"] = true },
    },
    [43845290] = {
        ["english"] = { [1] = "I wish to browse your wares." },
        ["text"] = "Я хочу переглянути ваші товари.",
        ["npcs"] = { [1] = 6568, [2] = 14624 },
        ["roles"] = { ["reply"] = true },
    },
    [4031819490] = {
        ["english"] = { [1] = "I sell the finest cloth and leather garb this side of the valley!" },
        ["text"] = "Я продаю найкращий одяг із тканини та шкіри по цей бік долини!",
        ["npcs"] = { [1] = 836 },
        ["roles"] = { ["greeting"] = true },
    },
    [1318065448] = {
        ["english"] = { [1] = "It is regrettable that, among our many enemies in Hellfire Peninsula, the orcs of Hellfire Citadel stand among them.$B$BBut... who better to challenge and hone the Horde... than orcs?" },
        ["text"] = "Прикро, що серед численних ворогів на Півострові Пекельного Вогню є й орки Цитаделі Пекельного Вогню.$B$BАле... хто краще випробує й загартує Орду, ніж орки?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3457700639] = {
        ["english"] = { [1] = "In all of my days I never thought to see such a magnificent new frontier.$B$BIf only it weren't tainted by evil and knowledge which is best left hidden." },
        ["text"] = "За всі мої дні я й гадки не мав, що побачу такий величний новий край.$B$BЯкби ж тільки його не плямували зло й знання, яким краще залишатися прихованими.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1198406284] = {
        ["english"] = { [1] = "If you're feeling queasy, speak with Pestle.  He might have something for motion sickness." },
        ["text"] = "Якщо вас нудить, поговоріть із Пестиком.  У нього може бути щось від заколисування.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2578858571] = {
        ["english"] = { [1] = "I require training." },
        ["text"] = "Мені потрібне навчання.",
        ["npcs"] = { [1] = 11146 },
        ["roles"] = { ["reply"] = true },
    },
    [1913515901] = {
        ["english"] = { [1] = "I live only to serve our King." },
        ["text"] = "Я живу лише заради служіння нашому королю.",
        ["npcs"] = { [1] = 14394 },
        ["roles"] = { ["greeting"] = true },
    },
    [2476388916] = {
        ["english"] = { [1] = "I've been expecting you $N.  Are you ready to assist us in Arathi Basin?" },
        ["text"] = "Я чекав на вас, $N.  Ви готові допомогти нам у Низині Араті?",
        ["npcs"] = { [1] = 15008 },
        ["roles"] = { ["greeting"] = true },
    },
    [2936566662] = {
        ["english"] = { [1] = "If you're ever captured by the Legion, tell them \"Xar il romath da tidesbi.\" They will kill you instantly for insulting their god, saving you intolerable torture or worse..." },
        ["text"] = "Якщо вас колись схопить Легіон, скажіть їм: «Xar il romath da tidesbi». Вони миттю вас уб'ють за образу їхнього бога, позбавивши нестерпних тортур чи чогось гіршого...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [982513052] = {
        ["english"] = { [1] = "If you're a real hero of the Horde, then I wanna see you fight a dragon!  Yeah!" },
        ["text"] = "Якщо ти справжній герой Орди, я хочу побачити, як ти б'єшся з драконом!  Так!",
        ["npcs"] = { [1] = 14444 },
        ["roles"] = { ["greeting"] = true },
    },
    [1134353070] = {
        ["english"] = { [1] = "I seek to understand the importance of strength of the body." },
        ["text"] = "Я прагну зрозуміти важливість сили тіла.",
        ["npcs"] = { [1] = 11956 },
        ["roles"] = { ["reply"] = true },
    },
    [931682449] = {
        ["english"] = { [1] = "I do not understand." },
        ["text"] = "Я не розумію.",
        ["npcs"] = { [1] = 7783 },
        ["roles"] = { ["reply"] = true },
    },
    [480698015] = {
        ["english"] = { [1] = "Is Winterspring currently under attack?" },
        ["text"] = "Зимоключ зараз під атакою?",
        ["npcs"] = { [1] = 16285, [2] = 16359 },
        ["roles"] = { ["reply"] = true },
    },
    [4029068456] = {
        ["english"] = { [1] = "If you want to know about the comings and goings of caravans and merchants here in Splintertree Post, then I am fortunately the orc you are looking for.  Unfortunately for you though, I don't like people.$B$BIf you want something, make it quick." },
        ["text"] = "Якщо хочете знати про прибуття й від'їзди караванів і торговців тут, у заставі Розщепленого Дерева, то, на щастя, я саме той орк, якого ви шукаєте.  На ваше нещастя, я не люблю людей.$B$BЯкщо щось треба — швидше.",
        ["npcs"] = { [1] = 12737 },
        ["roles"] = { ["greeting"] = true },
    },
    [3872900443] = {
        ["english"] = { [1] = "If you try to fail and succeed, what did you just do?" },
        ["text"] = "Якщо ви намагаєтеся зазнати невдачі й досягаєте успіху, то що ви щойно зробили?",
        ["npcs"] = { [1] = 14305 },
        ["roles"] = { ["greeting"] = true },
    },
    [3664830530] = {
        ["english"] = { [1] = "I cannot teach you dragonscale leatherworking, $N. You must go to Tanaris and find the home of Narain Soothfancy. Once there, consult the book \"Soothsaying for Dummies.\"" },
        ["text"] = "Я не можу навчити вас шкірництва драконячої луски, $N. Вам треба вирушити до Танарісу й знайти дім Нарайна Всезнайка. Там зверніться до книги «Ворожіння для чайників».",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4052545485] = {
        ["english"] = { [1] = "I have heard your words, Great Bear Spirit, and I understand.  I now seek your blessings to fully learn the way of the Claw." },
        ["text"] = "Я почув твої слова, Великий Духу Ведмедя, і зрозумів.  Тепер я прошу твого благословення, щоб повністю опанувати Шлях Кігтя.",
        ["npcs"] = { [1] = 11956 },
        ["roles"] = { ["reply"] = true },
    },
    [1413119554] = {
        ["english"] = { [1] = "I'd train you if I could, but you're too much for me. Tell you what: go talk to the tauren Una in the northwestern shops of Thunder Bluff's central plateau. She's got some real talent." },
        ["text"] = "Я б вас навчав, якби міг, але ви вже надто вправні для мене. Ось що: поговоріть із тауренкою Уною в крамницях на північному заході центрального плато Громового Бескиду. Вона справжній талант.",
        ["npcs"] = { [1] = 1385 },
        ["roles"] = { ["greeting"] = true },
    },
    [1246116851] = {
        ["english"] = { [1] = "I've heard that the last of the preparations are being shipped over to Silithus and should arrive in under a day. I don't want to see one of those bugs burrowing through into my mine, so I hope that someone is taking the time to assemble that Scepter of the Shifting Sands so the gong can be rung, the gates opened and the war finally begun." },
        ["text"] = "Чув, останні приготування вже відправляють до Силітуса й вони мають прибути менш ніж за день. Не хочу побачити, як якась із тих комах прориється в мою копальню, тож сподіваюся, хтось таки збирає Скіпетр Мінливих Пісків, щоб ударити в гонг, відкрити брами й нарешті почати війну.",
        ["npcs"] = { [1] = 15459 },
        ["roles"] = { ["greeting"] = true },
    },
    [2141666397] = {
        ["english"] = { [1] = "If you manage to complete a deck of Beasts cards you will be rewarded with a Greater Darkmoon card of the Blue Dragon.   This is very useful in restoring of magical energies." },
        ["text"] = "Якщо вам удасться зібрати повну колоду карт Звірів, ви отримаєте Велику карту Темного Місяця Синього Дракона.   Вона дуже корисна для відновлення магічної енергії.",
        ["npcs"] = { [1] = 14847 },
        ["roles"] = { ["greeting"] = true },
    },
    [2231654060] = {
        ["english"] = { [1] = "If ya need a bat, ya come to da right place. I be handlin' all de bats for de scouts." },
        ["text"] = "Якщо тобі потрібен кажан — ти прийшов куди треба. Я відповідаю за всіх кажанів розвідників.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2624531034] = {
        ["english"] = { [1] = "If you travel to Cenarion Hold in Silithus, you will find Elder Bladesing." },
        ["text"] = "Якщо вирушите до Кенарійської цитаделі в Силітусі, знайдете старійшину Пісню Клинка.",
        ["npcs"] = { [1] = 15570, [2] = 15583 },
        ["roles"] = { ["greeting"] = true },
    },
    [4209047181] = {
        ["english"] = { [1] = "I need a vitreous focuser." },
        ["text"] = "Мені потрібен склоподібний фокусатор.",
        ["npcs"] = { [1] = 11056, [2] = 11057 },
        ["roles"] = { ["reply"] = true },
    },
    [1665742083] = {
        ["english"] = { [1] = "If you seek to hunt naga, then you will need all the help you can get. Deep in the water you can find bubbly fissures that produce enough air bubbles that will allow you to breath underwater. Swim up close so that you can use the bubbles." },
        ["text"] = "Якщо збираєтеся полювати на наґ, вам знадобиться вся можлива допомога. Глибоко під водою є бульбашкові тріщини, що випускають достатньо повітря, аби дихати під водою. Підпливайте ближче й користуйтеся бульбашками.",
        ["npcs"] = { [1] = 12340 },
        ["roles"] = { ["greeting"] = true },
    },
    [1884746090] = {
        ["english"] = { [1] = "It feels good to walk about and stretch all four limbs. Is there something I can help you with, $c?" },
        ["text"] = "Добре знову ходити й розминати всі чотири кінцівки. Чимось допомогти, $c?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3136042863] = {
        ["english"] = { [1] = "I know a few things, but I'm no expert. Lucky for you, Magar is. He's standing near the back of the shop. See if he can help you, but be careful not to rile him. He can be irritable." },
        ["text"] = "Я дещо знаю, але не фахівець. На щастя для вас, Маґар — фахівець. Він стоїть у задній частині крамниці. Спробуйте попросити його про допомогу, але не дратуйте. Він буває запальним.",
        ["npcs"] = { [1] = 2855 },
        ["roles"] = { ["greeting"] = true },
    },
    [1405513558] = {
        ["english"] = { [1] = "If I were you, I'd buy a goblin race voucher.  Rooting for the other team is a waste of time." },
        ["text"] = "На вашому місці я купив би талон на гоблінські перегони.  Вболівати за іншу команду — марна справа.",
        ["npcs"] = { [1] = 4429 },
        ["roles"] = { ["greeting"] = true },
    },
    [900518594] = {
        ["english"] = { [1] = "I want to ask you about something else." },
        ["text"] = "Я хочу запитати вас про дещо інше.",
        ["npcs"] = { [1] = 15383, [2] = 15431, [3] = 15432, [4] = 15437, [5] = 15445, [6] = 15446, [7] = 15448, [8] = 15450, [9] = 15451, [10] = 15452, [11] = 15453, [12] = 15455, [13] = 15456, [14] = 15457, [15] = 15458, [16] = 15539, [17] = 15700, [18] = 15701 },
        ["roles"] = { ["reply"] = true },
    },
    [1898560686] = {
        ["english"] = { [1] = "If you are looking to become a great cook, venture over to the Pig and Whistle Tavern in Old Town and talk to Stephen Ryback. That man knows how to cook up a rack of ribs like no other.\010\010Man... now you got me hungry for some of his famous ribs. Don't count on him teaching you that recipe though!" },
        ["text"] = "Якщо хочете стати великим кухарем, вирушайте до таверни «Свиня і Свисток» у Старому місті й поговоріть зі Стівеном Райбеком. Ніхто не готує реберця так, як він.\010\010От халепа... тепер і я хочу його знаменитих реберець. Але не розраховуйте, що він навчить вас того рецепта!",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [1826026195] = {
        ["english"] = { [1] = "I've heard tell of a truly skilled smith across the sea named Saru Steelfury. The smithy in Orgrimmar is where you should head if you wish to ply your trade, $c. Best of luck." },
        ["text"] = "Чув про надзвичайно вправного коваля за морем на ім'я Сару Сталелютий. Якщо хочете займатися ремеслом, $c, вирушайте до кузні в Орґріммарі. Удачі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [298463633] = {
        ["english"] = { [1] = "If you need training in alchemy, there is only one place in Stormwind you need to go... Alchemy Needs. You can find it in the Mage Quarter along the outer rim of shops." },
        ["text"] = "Якщо вам потрібне навчання алхімії, у Штормовії є лише одне місце — «Алхімічні потреби». Знайдете його в Кварталі Магів, уздовж зовнішнього ряду крамниць.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [3021391167] = {
        ["english"] = { [1] = "It is good that you wish to help, $c. Unfortunately I have collected up all of the peacebloom that we feel we'll need for the war effort. Maybe you could ask around; I'm sure that there are likely to be others here that still need your aid in gathering other things." },
        ["text"] = "Добре, що ви хочете допомогти, $c. На жаль, я вже зібрав увесь мироцвіт, який, на нашу думку, знадобиться для війни. Може, розпитайте інших; певен, тут іще є ті, кому потрібна допомога зі збором інших речей.",
        ["npcs"] = { [1] = 15477 },
        ["roles"] = { ["greeting"] = true },
    },
    [2006324533] = {
        ["english"] = { [1] = "In a different time and place I would've been considered but a youngling.  Here I am a seasoned combatant ready to live and die for the glory of the naaru.$B$BTen of us went into Manaforge Ara.  All the others fell to the Legion." },
        ["text"] = "В інший час і в іншому місці мене вважали б лише юнаком.  Тут я досвідчений боєць, готовий жити й померти за славу наару.$B$BДесятеро з нас увійшли до Манакузні Ара.  Усі інші полягли від рук Легіону.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [561444449] = {
        ["english"] = { [1] = "I have been expecting you." },
        ["text"] = "Я чекав на вас.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [313960502] = {
        ["english"] = { [1] = "I must have lived a charmed life, $N. To return to the world as a member of the Forsaken and the Apothecary Society... I couldn't have asked for a more suitable fate." },
        ["text"] = "Мабуть, я прожив зачароване життя, $N. Повернутися до світу як член Відречених і Аптекарського товариства... Кращої долі й не побажаєш.",
        ["npcs"] = { [1] = 10665 },
        ["roles"] = { ["greeting"] = true },
    },
    [1556594512] = {
        ["english"] = { [1] = "If you manage to complete a deck of Lunacy cards you will be rewarded with a Greater Darkmoon card of Madness.   The power of madness will fill you each time you slay an enemy." },
        ["text"] = "Якщо вам удасться зібрати повну колоду карт Безумства, ви отримаєте Велику карту Темного Місяця Божевілля.   Сила божевілля наповнюватиме вас щоразу, коли ви вбиваєте ворога.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3598321192] = {
        ["english"] = { [1] = "If you manage to complete a deck of Furies cards you will be rewarded with a Greater Darkmoon card of Vengeance.   While wielding this card anyone who strikes you has a chance of suffering holy vengeance." },
        ["text"] = "Якщо вам удасться зібрати повну колоду карт Люті, ви отримаєте Велику карту Темного Місяця Помсти.   Поки вона у вас, кожен, хто вас ударить, може зазнати святої відплати.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1891102002] = {
        ["english"] = { [1] = "I can teach you the finer points of Ram Riding, provided you have enough gold to cover the lesson!" },
        ["text"] = "Я можу навчити вас тонкощів верхової їзди на баранах, якщо у вас вистачить золота на урок!",
        ["npcs"] = { [1] = 4772 },
        ["roles"] = { ["greeting"] = true },
    },
    [1724691616] = {
        ["english"] = { [1] = "I got nothin' more to teach! Not for somebody who knows as much as you do, anyway! You Horde types need to talk to Nogg in Orgrimmar!" },
        ["text"] = "Мені більше нічого вас учити! Принаймні того, хто вже знає стільки, скільки ви! Вам, ординцям, треба поговорити з Ногґом в Орґріммарі!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [176876249] = {
        ["english"] = { [1] = "Is this the best they could do?$B$B<Omarion musters the strength to laugh.>$B$BYou do not possess the resolve to face a monster like Kel'Thuzad. You will crumble before his minions - just like those that have come before you...$B$BLeave me here to die. I refuse to return to a world that champions the likes of you.", [2] = "Is this the best they could do?$B$B<Omarion musters the strength to laugh.>$B$BYou do not possess the resolve to face a monster like Kel'Thuzad. You will crumble before his minions - just like those that have come before you...$B$BLeave me here to die. I refuse to return to a world that champions the likes of you.\010" },
        ["text"] = "Це найкраще, на що вони здатні?$B$B<Омаріон збирається з силами й сміється.>$B$BВам бракує рішучості, щоб протистояти чудовиську на кшталт Кел'Тузада. Ви впадете перед його прислужниками — як і ті, хто прийшов до вас...$B$BЗалиште мене тут помирати. Я відмовляюся повертатися у світ, що величає таких, як ви.",
        ["npcs"] = { [1] = 16365 },
        ["roles"] = { ["greeting"] = true },
    },
    [3389270403] = {
        ["english"] = { [1] = "I've lost the cure, Doc! Tell me you got more!!!" },
        ["text"] = "Я загубив ліки, док! Скажіть, що у вас є ще!!!",
        ["npcs"] = { [1] = 7207 },
        ["roles"] = { ["reply"] = true },
    },
    [360006676] = {
        ["english"] = { [1] = "Icy Scale Bracers." },
        ["text"] = "Наручі з крижаної луски.",
        ["npcs"] = { [1] = 16365 },
        ["roles"] = { ["reply"] = true },
    },
    [1506121875] = {
        ["english"] = { [1] = "I wish to join the battle!" },
        ["text"] = "Я хочу приєднатися до битви!",
        ["npcs"] = { [1] = 14990, [2] = 15102, [3] = 15105 },
        ["roles"] = { ["reply"] = true },
    },
    [3343194132] = {
        ["english"] = { [1] = "If you have the money, I have what you need." },
        ["text"] = "Якщо маєте гроші, у мене є те, що вам потрібно.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [213605840] = {
        ["english"] = { [1] = "If you be wantin' ta rest here, ya just need to ask!" },
        ["text"] = "Якщо хочеш тут відпочити — просто скажи!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [233238440] = {
        ["english"] = { [1] = "I heard the new Henweigh 6000 will be rolling off the assembly line soon. I can barely contain my excitement!" },
        ["text"] = "Чув, новий «Генвей 6000» скоро зійде з конвеєра. Я ледве стримую захват!",
        ["npcs"] = { [1] = 11028 },
        ["roles"] = { ["greeting"] = true },
    },
    [2703118002] = {
        ["english"] = { [1] = "I once followed the ways of the Twilight's Hammer. Obsessed with reviving the Old Gods, I journeyed deep into this lair to try to draw power from the cursed beast, Aku'mai!$b$bAfter witnessing the sacrifice of countless innocents, I came to my senses.$b$bI was trapped but now I am free! But so far from my homeland of Khaz Modan!$b$bBrave adventurer, I offer you passage to a very special land in return for slaying Aku'mai. If you wish, I can port you to the city of Darnassus." },
        ["text"] = "Колись я йшов шляхом Сутінкового Молота. Одержимий відродженням Старих Богів, я проник глибоко в це лігво, щоб спробувати черпати силу з проклятого звіра Аку'май!$b$bПобачивши жертви незліченних невинних, я схаменувся.$b$bЯ був у пастці, але тепер вільний! Та так далеко від батьківщини, Каз-Модану!$b$bХоробрий шукачу пригод, за вбивство Аку'май я пропоную вам прохід до дуже особливої землі. Якщо бажаєте, я можу перенести вас до Дарнаса.",
        ["npcs"] = { [1] = 6729 },
        ["roles"] = { ["greeting"] = true },
    },
    [2710191514] = {
        ["english"] = { [1] = "In the northeastern Barrens lies a pool of water sickened by pollution.  The locals call it the Sludge Fen; the Venture Company has turned the once crystal-blue waters into a mire of industrial byproducts and waste.  In the heart of this fen lies what you seek, $N.$B$BBe warned - the Venture Company does not tolerate trespassers, and they consider anyone who does not work for them as such.  You'll especially be a target as a protector of nature, something they vehemently oppose." },
        ["text"] = "На північному сході Степів лежить водойма, хвора від забруднення.  Місцеві звуть її Муловою Трясовиною; Торгова Компанія перетворила колись кришталево-блакитну воду на болото промислових відходів.  У самому серці цієї трясовини лежить те, що ви шукаєте, $N.$B$BМайте на увазі: Торгова Компанія не терпить порушників і вважає такими всіх, хто на неї не працює.  А як захисник природи ви станете особливою мішенню, бо вони люто ненавидять усе подібне.",
        ["npcs"] = { [1] = 11800 },
        ["roles"] = { ["greeting"] = true },
    },
    [501204416] = {
        ["english"] = { [1] = "I want to examine this pylon." },
        ["text"] = "Я хочу оглянути цей пілон.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [1363445775] = {
        ["english"] = { [1] = "Is this city not beautiful, $c?  It warms my heart that we have found such good friends in these night elves." },
        ["text"] = "Хіба це місто не прекрасне, $c?  Моє серце зігріває те, що ми знайшли таких добрих друзів серед нічних ельфів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4167262407] = {
        ["english"] = { [1] = "If you have come looking for the gift of fast and safe mobility, then you have arrived at your destination!  This year's model of the new Mechano-striders have recently arrived, and I am ready to show you all they have to offer!" },
        ["text"] = "Якщо ви прийшли по дар швидкого й безпечного пересування — ви за адресою!  Щойно прибули нові моделі механодолгоногів цього року, і я готовий показати вам усе, на що вони здатні!",
        ["npcs"] = { [1] = 7955 },
        ["roles"] = { ["greeting"] = true },
    },
    [1646637752] = {
        ["english"] = { [1] = "Icebane Bracers." },
        ["text"] = "Наручі кригопогибелі.",
        ["npcs"] = { [1] = 16365 },
        ["roles"] = { ["reply"] = true },
    },
    [2817140627] = {
        ["english"] = { [1] = "If you find the lunar festival revelers in Silvermoon, they can transport you to Moonglade to partake in the celebration." },
        ["text"] = "Якщо знайдете учасників Місячного фестивалю в Срібномісяці, вони можуть перенести вас до Місячної галявини на святкування.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1981108834] = {
        ["english"] = { [1] = "If you figure out any way to improve the device let me know!" },
        ["text"] = "Якщо придумаєте спосіб удосконалити пристрій, скажіть мені!",
        ["npcs"] = { [1] = 14743 },
        ["roles"] = { ["greeting"] = true },
    },
    [3628791302] = {
        ["english"] = { [1] = "It's been so long since I was a novice myself that I don't think I'd be the best teacher for you. Try talking to Tarn or Mak, right over there. One of them should be able to answer your questions." },
        ["text"] = "Минуло стільки часу відтоді, як я сам був новачком, що навряд чи стану для вас найкращим учителем. Поговоріть із Тарном або Маком, он вони. Хтось із них відповість на ваші запитання.",
        ["npcs"] = { [1] = 3007 },
        ["roles"] = { ["greeting"] = true },
    },
    [4252286274] = {
        ["english"] = { [1] = "I seek to understand the importance of strength of the heart." },
        ["text"] = "Я прагну зрозуміти важливість сили серця.",
        ["npcs"] = { [1] = 11956 },
        ["roles"] = { ["reply"] = true },
    },
    [716595721] = {
        ["english"] = { [1] = "I sell only the finest arcane gear, made by the crafters and mages here in the city of Stormwind." },
        ["text"] = "Я продаю лише найкраще арканічне спорядження, виготовлене ремісниками й магами тут, у Штормовії.",
        ["npcs"] = { [1] = 297, [2] = 1141, [3] = 1304, [4] = 1307, [5] = 1308, [6] = 1309, [7] = 1310, [8] = 1312, [9] = 1313, [10] = 1314, [11] = 1315, [12] = 1318, [13] = 1347, [14] = 1405, [15] = 1413, [16] = 1414, [17] = 1415, [18] = 2330, [19] = 3627, [20] = 4078, [21] = 4984, [22] = 5081, [23] = 7295, [24] = 11827, [25] = 11828, [26] = 14497 },
        ["roles"] = { ["greeting"] = true },
    },
    [3988384690] = {
        ["english"] = { [1] = "If you desire, in addition to training, I have it within my power to erase the knowledge of your talents from your mind.  Be warned that every time you undergo this procedure the more difficult it is to perform, and therefore the more expensive it becomes." },
        ["text"] = "Якщо бажаєте, крім навчання, я здатен стерти з вашого розуму знання ваших талантів.  Майте на увазі: щоразу цю процедуру виконувати дедалі складніше, а отже, вона стає дорожчою.",
        ["npcs"] = { [1] = 4217 },
        ["roles"] = { ["greeting"] = true },
    },
    [2707060632] = {
        ["english"] = { [1] = "If you desire to learn the ways of Herbalism then it is to Thunder Bluff that you must go.  Follow the road north out of Bloodhoof Village and take the elevator to the top of the rise.  You can ask a Bluffwatcher there for further assistance." },
        ["text"] = "Якщо хочете вивчити травництво, вам треба до Громового Бескиду.  Ідіть дорогою на північ із селища Кривавого Копита й підніміться ліфтом на вершину плато.  Там попросіть вартового Бескиду підказати далі.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [2191308663] = {
        ["english"] = { [1] = "If you desire to form a fellowship then it is the guild master, Lysheana, that you must see.  You will find her in the Craftsmen's Terrace in the northeastern section of Darnassus." },
        ["text"] = "Якщо бажаєте створити товариство, вам слід звернутися до майстрині гільдій Лішеани.  Знайдете її на Терасі Ремісників у північно-східній частині Дарнаса.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [1292086756] = {
        ["english"] = { [1] = "If you become a friend of the Lower City, perhaps we can do business?" },
        ["text"] = "Якщо станете другом Нижнього Міста, можливо, зможемо вести справи?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2918300418] = {
        ["english"] = { [1] = "I wouldn't do this on any other day, but... I'm thirsty and I hate drinking alone.$B$BBottoms up!" },
        ["text"] = "В інший день я б такого не робив, але... мене мучить спрага, а пити самому я ненавиджу.$B$BДо дна!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3138628021] = {
        ["english"] = { [1] = "I've never experienced cold like this, $r. Even in the absence of ice and snow, the frozen wastes of Northrend are extremely taxing." },
        ["text"] = "Я ніколи не відчував такого холоду, $r. Навіть без льоду й снігу крижані пустки Нортренду страшенно виснажують.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3286187588] = {
        ["english"] = { [1] = "I have nothing more to teach you. Talk to Karolek if you wish to further your leatherworking skills." },
        ["text"] = "Мені більше нічого вас навчити. Поговоріть із Каролеком, якщо хочете вдосконалити навички шкірництва.",
        ["npcs"] = { [1] = 5811 },
        ["roles"] = { ["greeting"] = true },
    },
    [2186797110] = {
        ["english"] = { [1] = "If you have the coin, I have the food and drink to keep that appetite of yours satisfied.  Every copper goes to keeping the Retreat in tip-top shape." },
        ["text"] = "Якщо маєте монету, у мене є їжа й питво, щоб угамувати ваш апетит.  Кожен мідяк іде на те, щоб Прихисток залишався в ідеальному стані.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3477532579] = {
        ["english"] = { [1] = "I'm busy, make it fast!" },
        ["text"] = "Я зайнятий, швидше!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3274289078] = {
        ["english"] = { [1] = "It is with satisfaction that I relay to you we have collected all of the purple lotus that we feel we need. Thank you for your contribution to the effort, $c. If you are so inclined, there are most likely several still here that are collecting other resources for the struggle." },
        ["text"] = "Із задоволенням повідомляю: ми зібрали весь пурпуровий лотос, який, на нашу думку, потрібен. Дякую за ваш внесок, $c. Якщо маєте бажання, тут іще напевно є кілька збирачів інших ресурсів для боротьби.",
        ["npcs"] = { [1] = 15437 },
        ["roles"] = { ["greeting"] = true },
    },
    [865185838] = {
        ["english"] = { [1] = "I execute him as per my liege's instructions, but doing so in as painless of a way as possible.  Justice must be served, but I can show some compassion.\010" },
        ["text"] = "Я страчую його за наказом свого сюзерена, але роблю це якомога безболісніше.  Правосуддя має звершитися, та я можу виявити трохи милосердя.\010",
        ["npcs"] = { [1] = 14822 },
        ["roles"] = { ["reply"] = true },
    },
    [646582980] = {
        ["english"] = { [1] = "If you ask me, and you DID, I think we should kill all of the apothecaries before it's too late!" },
        ["text"] = "Якщо питаєте мене — а ви ПИТАЛИ — я вважаю, треба вбити всіх аптекарів, поки не пізно!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2999628926] = {
        ["english"] = { [1] = "I will delay here until more reinforcements arrive, but you must keep moving. Arthas will soon realize that we're here." },
        ["text"] = "Я затримаюся тут, доки не прибуде підкріплення, але ви мусите рухатися далі. Артас скоро зрозуміє, що ми тут.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3045653697] = {
        ["english"] = { [1] = "I'd like a drink." },
        ["text"] = "Я б випив.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [151141767] = {
        ["english"] = { [1] = "If you are seeking a truly rewarding pursuit, then a life of enchanting is for you!" },
        ["text"] = "Якщо шукаєте справді вдячне ремесло, життя зачарувальника — саме для вас!",
        ["npcs"] = { [1] = 7949 },
        ["roles"] = { ["greeting"] = true },
    },
    [1103989538] = {
        ["english"] = { [1] = "If it is a matter of import that you wish to speak on, $c, it may be more appropriate to seek an audience with Dame Auriferous. I warn you though, she is very busy and you may be in for quite a wait." },
        ["text"] = "Якщо справа, про яку ви хочете поговорити, справді важлива, $c, доречніше буде попросити аудієнції в пані Ауріферус. Але попереджаю: вона дуже зайнята, тож чекати, можливо, доведеться довго.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4125942626] = {
        ["english"] = { [1] = "If you are one that prefers to hunt in the outdoor world, both Felwood's treants and Un'Goro's lashers are an excellent source of fronds.$B$BIf you are more of a risk-taker, the eastern and western wings of Dire Maul will provide you with a nearly limitless supply of savage fronds." },
        ["text"] = "Якщо волієте полювати просто неба, деревники Сквернолісся й батіжники Ун'Ґоро — чудове джерело вай.$B$BЯкщо ж любите ризик, у східному й західному крилах Страхомістя знайдете майже невичерпні запаси диких вай.",
        ["npcs"] = { [1] = 16135 },
        ["roles"] = { ["greeting"] = true },
    },
    [4138736362] = {
        ["english"] = { [1] = "I'll patrol the pass leading up to Frostwolf Keep. Just give me the word and I'll take flight, Commander." },
        ["text"] = "Я патрулюватиму перевал до фортеці Морозних Вовків. Лише дайте слово — і я злетю, командире.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1554033658] = {
        ["english"] = { [1] = "I only wish I had more students like you. Not many will venture so far into enemy territory. I salute your courage." },
        ["text"] = "Хотілося б мати більше таких учнів, як ви. Не кожен насмілиться зайти так далеко на ворожу територію. Віддаю належне вашій відвазі.",
        ["npcs"] = { [1] = 11098 },
        ["roles"] = { ["greeting"] = true },
    },
    [2037748068] = {
        ["english"] = { [1] = "I cannot help you until you have learned more of the essentials. Come back to me when you are ready." },
        ["text"] = "Я не зможу вам допомогти, доки ви не опануєте більше основ. Поверніться, коли будете готові.",
        ["npcs"] = { [1] = 11052 },
        ["roles"] = { ["greeting"] = true },
    },
    [3673823785] = {
        ["english"] = { [1] = "I love the Lunar Festival!  It's a great place to let your hooves kick up dust!" },
        ["text"] = "Я обожнюю Місячний фестиваль!  Це чудове місце, щоб копитами здійняти пилюку!",
        ["npcs"] = { [1] = 15719 },
        ["roles"] = { ["greeting"] = true },
    },
    [269924276] = {
        ["english"] = { [1] = "I'm going to have to kill something, aren't I?" },
        ["text"] = "Мені ж доведеться щось убити, правда?",
        ["npcs"] = { [1] = 14358 },
        ["roles"] = { ["reply"] = true },
    },
    [3740993967] = {
        ["english"] = { [1] = "I think they put him in a cage over near the lumbermill." },
        ["text"] = "Гадаю, його посадили в клітку біля лісопилки.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3177622875] = {
        ["english"] = { [1] = "If you are here to waste my time, then you are wasting the time of the Cenarion Circle as a whole.  For your sake, let us hope that you are not foolish enough to be doing just that." },
        ["text"] = "Якщо ви прийшли марнувати мій час, то марнуєте час усього Кенарієвого Кола.  Заради вас сподіваюся, ви не настільки дурні, щоб саме це й робити.",
        ["npcs"] = { [1] = 3516 },
        ["roles"] = { ["greeting"] = true },
    },
    [699377475] = {
        ["english"] = { [1] = "If you are here to hunt dragons, be my guest.  Where should I send my condolences?" },
        ["text"] = "Якщо ви тут заради полювання на драконів — прошу.  Куди надсилати співчуття?",
        ["npcs"] = { [1] = 7866 },
        ["roles"] = { ["greeting"] = true },
    },
    [1811017449] = {
        ["english"] = { [1] = "If you are here for further training, you have overestimated my abilities. Have a word with Telonis over there; he can help you." },
        ["text"] = "Якщо ви прийшли по подальше навчання, то переоцінили мої здібності. Поговоріть із Телонісом он там; він допоможе.",
        ["npcs"] = { [1] = 11081 },
        ["roles"] = { ["greeting"] = true },
    },
    [2687233069] = {
        ["english"] = { [1] = "If you actually brought me the hide of the beast? Well... Let me show you..." },
        ["text"] = "То ви справді принесли мені шкуру звіра? Ну що ж... Дайте покажу...",
        ["npcs"] = { [1] = 10637 },
        ["roles"] = { ["greeting"] = true },
    },
    [2839174460] = {
        ["english"] = { [1] = "I risk my own life and free him so that he may prove his innocence.  If I can, I'll help him in any way." },
        ["text"] = "Я ризикую власним життям і звільняю його, щоб він міг довести свою невинність.  Якщо зможу, допоможу йому в усьому.",
        ["npcs"] = { [1] = 14822 },
        ["roles"] = { ["reply"] = true },
    },
    [3765274878] = {
        ["english"] = { [1] = "I do not see the warrior's spirit within you, child.  I have no teachings which would benefit a $c such as yourself." },
        ["text"] = "Я не бачу у вас духу воїна, дитя.  У мене немає вчень, що стали б у пригоді такому $c, як ви.",
        ["npcs"] = { [1] = 3593, [2] = 3598, [3] = 4087, [4] = 4089, [5] = 7315 },
        ["roles"] = { ["greeting"] = true },
    },
    [2553458746] = {
        ["english"] = { [1] = "I came to this place because of my study into the backward culture that used to be the Thunderlord clan.$B$BThey were weak and succumbed to the lure of power that came with being transformed into fel orcs through Mannoroth's blood.$B$BI have read all of their texts.  I am particularly interested in the recovery of an artifact, a drum, an arrow and a tablet that were lost when we crushed the Bladespire ogres and pushed them back down into their hold." },
        ["text"] = "Я прийшов сюди, бо вивчаю відсталу культуру колишнього клану Громовержців.$B$BВони були слабкими й піддалися спокусі сили, яку дало перетворення на орків Скверни через кров Маннорота.$B$BЯ прочитав усі їхні тексти.  Особливо мене цікавить повернення артефакту, барабана, стріли й таблички, загублених, коли ми розгромили огрів Клинорогих і загнали їх назад до фортеці.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1740562487] = {
        ["english"] = { [1] = "It's a secret to everybody... including me!$B$BI'm glad you found me -- it's a good thing I'm not hiding in a bush or underneath a rock, isn't it?" },
        ["text"] = "Це таємниця для всіх... навіть для мене!$B$BРадий, що ви мене знайшли — добре, що я не ховаюся в кущах чи під каменем, правда?",
        ["npcs"] = { [1] = 8737 },
        ["roles"] = { ["greeting"] = true },
    },
    [3508450731] = {
        ["english"] = { [1] = "I hope these Shattrath folks stop fighting soon.  They're beginning to get on my nerves.$B$B How can I help you?" },
        ["text"] = "Сподіваюся, ці шаттратці скоро перестануть битися.  Вони вже починають діяти мені на нерви.$B$B Чим можу допомогти?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [110990256] = {
        ["english"] = { [1] = "If yer here to partake in the big spoils, ya best be gettin' in line!$b$bMy share be long overdue....$B" },
        ["text"] = "Якщо прийшли по велику частку здобичі, ставайте в чергу!$b$bМоя частка й так давно прострочена...$B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1617161529] = {
        ["english"] = { [1] = "If ye're looking to learn the profession of leatherworking, ye're gonna need to travel to Ironforge.  I hear there's a nice shop near the Great Forge where ye can learn the profession." },
        ["text"] = "Якщо хочете опанувати шкірництво, доведеться вирушити до Залізогарта.  Кажуть, біля Великої Кузні є добра крамниця, де можна навчитися цього ремесла.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [3769435425] = {
        ["english"] = { [1] = "I seek training in the ways of the Hunter." },
        ["text"] = "Я шукаю навчання шляху мисливця.",
        ["npcs"] = { [1] = 895, [2] = 987, [3] = 1404, [4] = 3038, [5] = 3039, [6] = 3040, [7] = 3061, [8] = 3065, [9] = 3154, [10] = 3171, [11] = 3352, [12] = 3406, [13] = 3407, [14] = 3963, [15] = 4138, [16] = 5115, [17] = 5117, [18] = 5515, [19] = 5516, [20] = 5517, [21] = 8308, [22] = 10930 },
        ["roles"] = { ["reply"] = true },
    },
    [3263302495] = {
        ["english"] = { [1] = "I'm not here to teach babes fresh out of the cradle. Ye've nowhere near the amount of skill I require in my students. In fact, ye're a sad figure of a $glad:lass;, an' I'll thank ye not to stand there jibber-jabberin' at me." },
        ["text"] = "Я тут не для того, щоб навчати немовлят, які щойно вилізли з колиски. Вам і близько не вистачає майстерності, якої я вимагаю від учнів. Та й узагалі, жалюгідний із вас $gхлопче:дівчино;, тож будьте ласкаві не стояти тут і не торохтіти мені під вухом.",
        ["npcs"] = { [1] = 11097 },
        ["roles"] = { ["greeting"] = true },
    },
    [3900369428] = {
        ["english"] = { [1] = "If ye need to get yer hands on some guild creation papers ye'll have to head up to Ironforge and visit the Ironforge Visitor's Center." },
        ["text"] = "Якщо вам потрібні папери для створення гільдії, доведеться вирушити до Залізогарта й навідатися до Центру відвідувачів Залізогарта.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [166084677] = {
        ["english"] = { [1] = "I seek training." },
        ["text"] = "Я шукаю навчання.",
        ["npcs"] = { [1] = 3594 },
        ["roles"] = { ["reply"] = true },
    },
    [3991007480] = {
        ["english"] = { [1] = "I want to exchange my Ruby Essence for Emerald Essence." },
        ["text"] = "Я хочу обміняти рубінову сутність на смарагдову.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3675342959] = {
        ["english"] = { [1] = "If you truly have the desire to learn this profession, then I would point you in the direction of Ainethil, a skilled alchemist at the Craftsmen's Terrace in northern Darnassus." },
        ["text"] = "Якщо справді хочете опанувати цю професію, зверніться до Айнетіль, вправної алхімічки на Терасі Ремісників у північному Дарнасі.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [610579203] = {
        ["english"] = { [1] = "I installed a new device in our car's matrix regulometer.  That should increase its velocity quotient by a factor of no less than fifteen!" },
        ["text"] = "Я встановив новий пристрій у матричний регулометр нашої машини.  Це має підвищити її коефіцієнт швидкості щонайменше у п'ятнадцять разів!",
        ["npcs"] = { [1] = 4430 },
        ["roles"] = { ["greeting"] = true },
    },
    [1775355751] = {
        ["english"] = { [1] = "If you're expecting some kind of official welcome, you're going to be disappointed, $c. We don't stand on tradition, here. What works is what goes." },
        ["text"] = "Якщо очікуєте якогось офіційного прийому, то розчаруєтеся, $c. Тут ми не церемонимося. Працює те, що працює.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4207070741] = {
        ["english"] = { [1] = "It's admirable what The League of Arathor is attempting to do in Arathi Basin.  Too bad those undead abominations and their Horde friends are standing in the way.  Head over to Stormwind Keep.  Lady Hoteshem awaits you in the King's audience chamber.  She can help you to get to Arathi Basin." },
        ["text"] = "Те, що Ліга Аратора намагається зробити в Низині Араті, гідне поваги.  Шкода, що ті невмерлі потвори та їхні друзі з Орди стоять на шляху.  Вирушайте до фортеці Штормовію.  Пані Хотешем чекає в королівській залі аудієнцій.  Вона допоможе вам дістатися Низини Араті.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [195305443] = {
        ["english"] = { [1] = "If there is anything you would have of me..." },
        ["text"] = "Якщо вам щось від мене потрібно...",
        ["npcs"] = { [1] = 3216 },
        ["roles"] = { ["reply"] = true },
    },
    [1604042128] = {
        ["english"] = { [1] = "I study the known and unknown elements of our world." },
        ["text"] = "Я вивчаю відомі й невідомі стихії нашого світу.",
        ["npcs"] = { [1] = 14348 },
        ["roles"] = { ["greeting"] = true },
    },
    [4084546034] = {
        ["english"] = { [1] = "If you have dealings with the doctor over there, be cautious. Whatever they're up to, it's unnatural." },
        ["text"] = "Якщо маєте справи з тим лікарем он там, будьте обережні. Що б вони не робили, це неприродно.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2972686209] = {
        ["english"] = { [1] = "I can instruct you in leatherworking.  Interested?" },
        ["text"] = "Я можу навчити вас шкірництва.  Цікавить?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3243321883] = {
        ["english"] = { [1] = "I have been lost in the Dream. I sense his lifeforce but my powers have not yet grown strong enough to make contact." },
        ["text"] = "Я заблукав у Сні. Я відчуваю його життєву силу, але моїх сил іще замало, щоб установити зв'язок.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1427487677] = {
        ["english"] = { [1] = "I see some interesting characters come and go here at the port. Watch yourself, $N. It's never clear who to trust, what with all of the shady activity that goes on here..." },
        ["text"] = "Я бачу, як тут у порту приходять і йдуть цікаві особи. Будьте обережні, $N. Ніколи не знаєш, кому довіряти, з усіма тими темними справами, що тут кояться...",
        ["npcs"] = { [1] = 4631 },
        ["roles"] = { ["greeting"] = true },
    },
    [882364737] = {
        ["english"] = { [1] = "If you ask me, I think the goblins are a shoe in.  We have the tools, and we have the talent!" },
        ["text"] = "Як на мене, гобліни майже напевно переможуть.  У нас є інструменти й талант!",
        ["npcs"] = { [1] = 4429 },
        ["roles"] = { ["greeting"] = true },
    },
    [358116793] = {
        ["english"] = { [1] = "If someone has put together the magic scepter of the sands then the war with the bugs will be soon. I relish it, $c! The last of our war goods are on their way to Silithus and should be there within a day. Go and bring honor to the Horde!" },
        ["text"] = "Якщо хтось уже зібрав магічний скіпетр пісків, війна з комахами скоро почнеться. Я смакую її, $c! Останні наші військові припаси вже прямують до Силітуса й мають бути там протягом дня. Ідіть і принесіть Орді честь!",
        ["npcs"] = { [1] = 15460 },
        ["roles"] = { ["greeting"] = true },
    },
    [1735849547] = {
        ["english"] = { [1] = "I can show you a few tricks... if you don't mind doing a little something first, that is." },
        ["text"] = "Можу показати вам кілька хитрощів... якщо не заперечуєте спершу дещо для мене зробити.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3642815664] = {
        ["english"] = { [1] = "I... cannot begin to imagine, $N.  All I know is that I am not going to allow it to happen.  It will be destroyed - if not for our continued safety from demonic taint, then for the memory of Millicent Serene... Milli...$B$BThis, my friend, this is where I hope you will come in." },
        ["text"] = "Я... навіть уявити не можу, $N.  Знаю лише, що не дозволю цьому статися.  Його буде знищено — якщо не заради нашої подальшої безпеки від демонічної скверни, то заради пам'яті про Міллісент Серен... Міллі...$B$BІ саме тут, друже, я сподіваюся на вашу допомогу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [483474677] = {
        ["english"] = { [1] = "If someone has put together the magic scepter of the sands then the war with the bugs will be soon. I relish it, $c! The last of our war goods are on their way to Silithus and should be there within $2113w days. Go and bring honor to the Horde!" },
        ["text"] = "Якщо хтось уже зібрав магічний скіпетр пісків, війна з комахами скоро почнеться. Я смакую її, $c! Останні наші військові припаси вже прямують до Силітуса й мають бути там протягом $2113w днів. Ідіть і принесіть Орді честь!",
        ["npcs"] = { [1] = 15460 },
        ["roles"] = { ["greeting"] = true },
    },
    [1546971155] = {
        ["english"] = { [1] = "If overalls are held up by the snaps at the top, then why do they have belt loops?" },
        ["text"] = "Якщо комбінезон тримається на застібках угорі, навіщо на ньому петлі для ременя?",
        ["npcs"] = { [1] = 14305 },
        ["roles"] = { ["greeting"] = true },
    },
    [576578790] = {
        ["english"] = { [1] = "If you are looking to become a mighty paladin, there is no better teacher then Lord Grayson Shadowbreaker. He can be found in the Cathedral of Light in Cathedral Square." },
        ["text"] = "Якщо хочете стати могутнім паладином, кращого вчителя за лорда Ґрейсона Тінелома не знайдете. Він у Соборі Світла на Соборній площі.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [1159031002] = {
        ["english"] = { [1] = "I cannot teach you anything you don't already know. However, the knowledge of my father far surpasses my own. Go inside and speak to him. Good luck!" },
        ["text"] = "Я не можу навчити вас нічого, чого ви вже не знаєте. Та знання мого батька далеко перевершують мої. Зайдіть усередину й поговоріть із ним. Удачі!",
        ["npcs"] = { [1] = 11071 },
        ["roles"] = { ["greeting"] = true },
    },
    [2765189084] = {
        ["english"] = { [1] = "It is good to see you again, $N. How could I ever forget the $g man : woman; who saved my sister's life?" },
        ["text"] = "Радий знову вас бачити, $N. Як я міг забути $g чоловіка : жінку;, що врятував життя моїй сестрі?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1380453216] = {
        ["english"] = { [1] = "I thought I'd never be free from that terrible curse. You have my gratitude, stranger." },
        ["text"] = "Я думав, що ніколи не звільнюся від того жахливого прокляття. Прийміть мою вдячність, незнайомцю.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1096288851] = {
        ["english"] = { [1] = "If not the gods, who? How? What could cause such strife?" },
        ["text"] = "Якщо це зробили не боги, то хто? Як? Що могло спричинити таку ворожнечу?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [46404953] = {
        ["english"] = { [1] = "It is good to see you alive and well, $N!" },
        ["text"] = "Радий бачити вас живими й здоровими, $N!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1204375482] = {
        ["english"] = { [1] = "I have lost my Band of Unending Life. Are you able to replace it for me?" },
        ["text"] = "Я загубив свій Перстень нескінченного життя. Можете замінити його?",
        ["npcs"] = { [1] = 15498 },
        ["roles"] = { ["reply"] = true },
    },
    [2684388457] = {
        ["english"] = { [1] = "It drafty out here." },
        ["text"] = "Тут протяги.",
        ["npcs"] = { [1] = 10666 },
        ["roles"] = { ["greeting"] = true },
    },
    [2685730634] = {
        ["english"] = { [1] = "I wish to become an armorsmith." },
        ["text"] = "Я хочу стати бронником.",
        ["npcs"] = { [1] = 11145 },
        ["roles"] = { ["reply"] = true },
    },
    [4026521792] = {
        ["english"] = { [1] = "If it's frayed abomination stitchings you be wanting, to Stratholme you'll be jaunting.$B$BFormerly the hometown of the Lightbringer hisself, now overrun by the minions of Kel'Thuzad.$B$BBrave the perils of the burning city and strike down the meaty abominations! Take from them your prize: Frayed abomination stitchings!" },
        ["text"] = "Якщо вам потрібні розтріпані шви мерзотища, до Стратгольма вам дорога.$B$BКолись це було рідне місто самого Світлоносця, а тепер його заполонили прислужники Кел'Тузада.$B$BКиньте виклик небезпекам палаючого міста й знищуйте м'ясистих мерзотищ! Заберіть у них свою здобич: розтріпані шви мерзотища!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2003106713] = {
        ["english"] = { [1] = "I'm all ears." },
        ["text"] = "Я весь увага.",
        ["npcs"] = { [1] = 6109, [2] = 10776, [3] = 15481 },
        ["roles"] = { ["reply"] = true },
    },
    [3205981379] = {
        ["english"] = { [1] = "I need a Cenarion beacon." },
        ["text"] = "Мені потрібен Кенарійський маяк.",
        ["npcs"] = { [1] = 9528, [2] = 9529 },
        ["roles"] = { ["reply"] = true },
    },
    [2588049483] = {
        ["english"] = { [1] = "It would appear as if the influence of the Black Dragonflight had extended beyond the borders of the Burning Steppes and into the kingdom of Stormwind itself! The usurper has since been unmasked and ousted." },
        ["text"] = "Схоже, вплив Чорної зграї простягався за межі Палаючого степу й у саме королівство Штормовій! Відтоді узурпаторку викрили й вигнали.",
        ["npcs"] = { [1] = 4949 },
        ["roles"] = { ["greeting"] = true },
    },
    [760748470] = {
        ["english"] = { [1] = "I should find some hired help; I don't like sitting here all day selling fish supplies. I'd much rather go fishing, and then sell supplies." },
        ["text"] = "Мені варто найняти помічника; не люблю цілими днями сидіти тут і продавати рибальське приладдя. Куди приємніше було б ловити рибу, а вже потім продавати припаси.",
        ["npcs"] = { [1] = 12031 },
        ["roles"] = { ["greeting"] = true },
    },
    [3285742037] = {
        ["english"] = { [1] = "If it weren't for the Grim Guzzler, I'd probably spend my free time pulling the wings off dragon whelps." },
        ["text"] = "Якби не «Похмурий Ненажера», я, мабуть, у вільний час відривав би крила драконятам.",
        ["npcs"] = { [1] = 9545 },
        ["roles"] = { ["greeting"] = true },
    },
    [3097302978] = {
        ["english"] = { [1] = "It is time you moved on to a more advanced teacher. In the Feathermoon Stronghold of Feralas dwells the night elf Kylanna Windwhisper. She has a brilliant mind; doubtless she can train you further." },
        ["text"] = "Настав час перейти до досвідченішого наставника. У фортеці Перистого Місяця у Фераласі живе нічна ельфійка Кіланна Вітрошепіт. У неї блискучий розум; без сумніву, вона навчить вас далі.",
        ["npcs"] = { [1] = 4160 },
        ["roles"] = { ["greeting"] = true },
    },
    [1935914608] = {
        ["english"] = { [1] = "If you are ready and wish to quickly return to the normal time stream, I can transport you to Andormu in the Caverns of Time." },
        ["text"] = "Якщо ви готові й хочете швидко повернутися до нормального потоку часу, я можу перенести вас до Андорму в Печери Часу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [47859671] = {
        ["english"] = { [1] = "I'll have you out of there in just a moment." },
        ["text"] = "За мить я вас звідти витягну.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [110970420] = {
        ["english"] = { [1] = "If I wasn't stuck here day in and day out, I would have attained the mastery required to train the likes of you! Unfortunately that's not the case. Go talk to Hgarth at the Sun Rock Retreat in the Stonetalon Mountains." },
        ["text"] = "Якби я не стирчав тут день у день, то вже досяг би майстерності, потрібної, щоб навчати таких, як ви! На жаль, це не так. Поговоріть із Гґартом у Прихистку Сонячного Каменю в Кам'янистих горах.",
        ["npcs"] = { [1] = 4616 },
        ["roles"] = { ["greeting"] = true },
    },
    [3639114894] = {
        ["english"] = { [1] = "If I taught novices, there'd be a lot more students visiting me, and things would get noisy. Go talk to Dan Golthas over there. He's a little intense, but he means well, and he's a decent teacher." },
        ["text"] = "Якби я навчав новачків, до мене приходило б значно більше учнів і стало б галасно. Поговоріть із Деном Ґолтасом он там. Він трохи надто завзятий, але наміри в нього добрі й навчає він непогано.",
        ["npcs"] = { [1] = 4588 },
        ["roles"] = { ["greeting"] = true },
    },
    [3797897836] = {
        ["english"] = { [1] = "If I prove myself to Saru he will have no choice but to let me fight for one of his daughters. Then we will see who is sneering." },
        ["text"] = "Якщо я доведу Сару свою гідність, йому не залишиться нічого іншого, як дозволити мені битися за одну з його дочок. Тоді побачимо, хто сміятиметься.",
        ["npcs"] = { [1] = 1383 },
        ["roles"] = { ["greeting"] = true },
    },
    [712989260] = {
        ["english"] = { [1] = "If I make a gift collection, what do I do with it?" },
        ["text"] = "Якщо я зберу колекцію подарунків, що мені з нею робити?",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 15174, [45] = 16256, [46] = 16458 },
        ["roles"] = { ["reply"] = true },
    },
    [2375205009] = {
        ["english"] = { [1] = "If additional support is not soon sent to the Burning Steppes, I fear the Scourge will establish a base of operations there. If you can, you should go there to aid the defenders.$B$BNumber of Necropolises remaining: $2281W" },
        ["text"] = "Якщо до Палаючого степу невдовзі не надішлють додаткову підтримку, боюся, Скара створить там базу. Якщо можете, вирушайте туди й допоможіть захисникам.$B$BНекрополів залишилося: $2281W",
        ["npcs"] = { [1] = 16285, [2] = 16359 },
        ["roles"] = { ["greeting"] = true },
    },
    [1078489211] = {
        ["english"] = { [1] = "I want to browse your goods" },
        ["text"] = "Я хочу переглянути ваші товари",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3140085236] = {
        ["english"] = { [1] = "If I had some chestnuts, you'd better believe I'd have them roasting over an open fire.  Mmmm!" },
        ["text"] = "Якби в мене були каштани, можете не сумніватися — я б смажив їх над відкритим вогнем.  М-м-м!",
        ["npcs"] = { [1] = 13418, [2] = 13420, [3] = 13430, [4] = 13432, [5] = 13433, [6] = 13434, [7] = 13435, [8] = 13436 },
        ["roles"] = { ["greeting"] = true },
    },
    [1767819349] = {
        ["english"] = { [1] = "I wish I had a $gfather:mother; like you!" },
        ["text"] = "Хотілося б мені мати $gтакого батька:таку матір;, як ви!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2416645847] = {
        ["english"] = { [1] = "I'd like a new invitation to the Lunar Festival." },
        ["text"] = "Я хочу нове запрошення на Місячний фестиваль.",
        ["npcs"] = { [1] = 15895 },
        ["roles"] = { ["reply"] = true },
    },
    [3382988621] = {
        ["english"] = { [1] = "I'm afraid ye would not survive long in Alterac Valley, $c.  Come back and see us when you have a few more seasons under your belt." },
        ["text"] = "Боюся, у Альтерацькій долині ви довго не протримаєтеся, $c.  Повертайтеся, коли матимете за плечима ще кілька сезонів.",
        ["npcs"] = { [1] = 15103 },
        ["roles"] = { ["greeting"] = true },
    },
    [4111971469] = {
        ["english"] = { [1] = "I've managed to work myself into quite a spot here. Far Seer Regulkut tried to warn me, but my carelessness has finally caught up with me.$B$BI came down here to study the ruins of Zeth'Gor, but ran afoul of the Legion on my way. Now, all I have to show for it is a nasty gash on my leg." },
        ["text"] = "Я добряче загнав себе в кут. Далекогляд Регулкут намагався мене застерегти, але моя необережність таки наздогнала мене.$B$BЯ спустився сюди вивчати руїни Зет'Ґора, але дорогою нарвався на Легіон. Тепер усе, що маю показати за свою працю, — мерзенний поріз на нозі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [657504257] = {
        ["english"] = { [1] = "I have to get out of here! Can you get me free?" },
        ["text"] = "Я мушу вибратися звідси! Можете мене звільнити?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3842839818] = {
        ["english"] = { [1] = "I cannot thank you enough for making my pilgrimage possible!" },
        ["text"] = "Не знаю, як і дякувати вам за те, що ви зробили моє паломництво можливим!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2583652960] = {
        ["english"] = { [1] = "I'm not sure where the zeppelin is right now, actually..." },
        ["text"] = "Правду кажучи, я зараз не знаю, де дирижабль...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2382617609] = {
        ["english"] = { [1] = "If Hydraxis recruits more in his war, then it might shift the balance of power..." },
        ["text"] = "Якщо Гідраксіс завербує більше бійців у свою війну, це може змінити рівновагу сил...",
        ["npcs"] = { [1] = 9545 },
        ["roles"] = { ["greeting"] = true },
    },
    [1878014871] = {
        ["english"] = { [1] = "I would remain silent about the kill and allow the knight to claim the reward to aid his family." },
        ["text"] = "Я промовчав би про вбивство й дозволив лицарю забрати нагороду, щоб допомогти його родині.",
        ["npcs"] = { [1] = 14822 },
        ["roles"] = { ["reply"] = true },
    },
    [1994594997] = {
        ["english"] = { [1] = "If he comes back, are you going to fight him again?" },
        ["text"] = "Якщо він повернеться, ви знову з ним битиметеся?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3135789281] = {
        ["english"] = { [1] = "I can instruct you in skinning.  Interested?" },
        ["text"] = "Я можу навчити вас знімати шкури.  Цікавить?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3392581719] = {
        ["english"] = { [1] = "I seek more training in the priestly ways." },
        ["text"] = "Я прагну подальшого навчання на шляху жерця.",
        ["npcs"] = { [1] = 375, [2] = 2123, [3] = 2129, [4] = 3044, [5] = 3045, [6] = 3046, [7] = 3706, [8] = 3707, [9] = 4606, [10] = 4607, [11] = 4608, [12] = 5994, [13] = 6014, [14] = 6018 },
        ["roles"] = { ["reply"] = true },
    },
    [4058836045] = {
        ["english"] = { [1] = "I seek training to ride a steed." },
        ["text"] = "Я хочу навчитися їздити верхи на скакуні.",
        ["npcs"] = { [1] = 3690, [2] = 4732, [3] = 4753, [4] = 4772, [5] = 4773, [6] = 7953 },
        ["roles"] = { ["reply"] = true },
    },
    [101257223] = {
        ["english"] = { [1] = "If I heard correctly, you're already doing good work for Sylvanaar.$B$BKeep it up and maybe we'll be able to keep our home here." },
        ["text"] = "Якщо я правильно почув, ви вже добре попрацювали для Сильванаара.$B$BТак тримати, і, може, нам удасться втримати свій дім тут.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [28754145] = {
        ["english"] = { [1] = "I haven't much time to talk unless it's urgent, citizen. The gates of Theramore are my greatest responsibility." },
        ["text"] = "У мене мало часу на розмови, якщо справа не нагальна, громадянине. Брами Терамора — моя найбільша відповідальність.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1295031730] = {
        ["english"] = { [1] = "It is Vesprystus that you seek.  He watches over the hippogryphs that come and go from the base of Teldrassil." },
        ["text"] = "Вам потрібен Весприст.  Він доглядає за гіпогрифами, що прилітають і відлітають від підніжжя Тельдрассіля.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [3446702516] = {
        ["english"] = { [1] = "I have lost my Ring of Eternal Justice. Are you able to replace it for me?" },
        ["text"] = "Я загубив свій Перстень вічної справедливості. Можете замінити його?",
        ["npcs"] = { [1] = 15498 },
        ["roles"] = { ["reply"] = true },
    },
    [4286955843] = {
        ["english"] = { [1] = "I have a lot of pent up anger and hostility. Just give me a reason, guttersnipe." },
        ["text"] = "У мені накопичилося чимало гніву й ворожості. Тільки дай мені привід, покидьку.",
        ["npcs"] = { [1] = 11279, [2] = 11281 },
        ["roles"] = { ["greeting"] = true },
    },
    [1035095705] = {
        ["english"] = { [1] = "If a bank is what you desire, then your travels take you to the heart of Darnassus.  There you will find storage for your treasures." },
        ["text"] = "Якщо вам потрібен банк, шлях веде до самого серця Дарнаса.  Там знайдете сховище для своїх скарбів.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [3768589977] = {
        ["english"] = { [1] = "Icy Scale Gauntlets." },
        ["text"] = "Рукавиці з крижаної луски.",
        ["npcs"] = { [1] = 16365 },
        ["roles"] = { ["reply"] = true },
    },
    [1734097197] = {
        ["english"] = { [1] = "If you insert tab A into slot B then of course it's going to go BOOM! Here, let me show you what I have and then you can ask Lilliam about how to put it together so it doesn't blow up." },
        ["text"] = "Якщо вставити язичок A у паз B, то, звісно, все БАБАХНЕ! Ось, дайте покажу, що маю, а потім спитайте Лілліам, як усе зібрати так, щоб не вибухнуло.",
        ["npcs"] = { [1] = 5519, [2] = 6579 },
        ["roles"] = { ["greeting"] = true },
    },
    [4283634166] = {
        ["english"] = { [1] = "I can take care of myself, $N." },
        ["text"] = "Я й сам про себе подбаю, $N.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1596624035] = {
        ["english"] = { [1] = "Icebane Gauntlets." },
        ["text"] = "Рукавиці кригопогибелі.",
        ["npcs"] = { [1] = 16365 },
        ["roles"] = { ["reply"] = true },
    },
    [1649880771] = {
        ["english"] = { [1] = "I... Are you...$B$B<Mootoo shivers.>$B$BAre you here to save me?" },
        ["text"] = "Я... Ви...$B$B<Муту тремтить.>$B$BВи прийшли мене врятувати?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1134420739] = {
        ["english"] = { [1] = "I run the fights around here.  You want to place a bet, gamble with confidence - anyone caught fixin' fights gets to walk the plank.$B$BI'll make sure of that myself!" },
        ["text"] = "Я тут керую боями.  Хочете зробити ставку — грайте сміливо: кожен, кого спіймають на підлаштуванні боїв, піде по дошці.$B$BЯ особисто про це подбаю!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2257549185] = {
        ["english"] = { [1] = "Icebane Breastplate." },
        ["text"] = "Нагрудник кригопогибелі.",
        ["npcs"] = { [1] = 16365 },
        ["roles"] = { ["reply"] = true },
    },
    [437169956] = {
        ["english"] = { [1] = "Iam Here, Commander" },
        ["text"] = "Я тут, командире",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4224197872] = {
        ["english"] = { [1] = "I don't know what they put in those kegs, but it goes down like honey!" },
        ["text"] = "Не знаю, що вони кладуть у ті барила, але п'ється воно, наче мед!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4131274195] = {
        ["english"] = { [1] = "I... I'm not really sure how I got here...$B$BI seem to remember traveling... a raft...$B$B" },
        ["text"] = "Я... я й сам не дуже розумію, як сюди потрапив...$B$BЗдається, пам'ятаю подорож... пліт...$B$B",
        ["npcs"] = { [1] = 8737 },
        ["roles"] = { ["greeting"] = true },
    },
    [3868076986] = {
        ["english"] = { [1] = "I... I have failed, $N. The Lord of Bla... The Lord of Blackrock is too powerful. He consumed my energy with... with ease. I turn... I... kill me... you must... you must kill me." },
        ["text"] = "Я... я зазнав невдачі, $N. Володар Чор... Володар Чорнокаменю надто могутній. Він поглинув мою енергію... без жодних зусиль. Я перетворююся... я... убийте мене... ви мусите... мусите мене вбити.",
        ["npcs"] = { [1] = 13020 },
        ["roles"] = { ["greeting"] = true },
    },
    [209365834] = {
        ["english"] = { [1] = "I know very little of the Highborne and nothing of the Shen'dralar." },
        ["text"] = "Я дуже мало знаю про Високородних і нічого — про Шен'дралар.",
        ["npcs"] = { [1] = 14358 },
        ["roles"] = { ["reply"] = true },
    },
    [4292821739] = {
        ["english"] = { [1] = "It nice having a good hunting partner." },
        ["text"] = "Добре мати доброго партнера на полюванні.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2475684688] = {
        ["english"] = { [1] = "I... died.$B$BWhy am I still here? Is there no great hunting ground that I ascend to?$B$BNo... I must first complete my task. Before I can leave this world, the second part of the Cipher of Damnation must be recovered." },
        ["text"] = "Я... помер.$B$BЧому я досі тут? Невже немає великих мисливських угідь, куди я маю піднестися?$B$BНі... спершу я мушу завершити своє завдання. Перш ніж покинути цей світ, треба повернути другу частину Шифру Прокляття.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [345114127] = {
        ["english"] = { [1] = "I wish the snow would just all melt away. It's always getting my robe wet and messing up everything!" },
        ["text"] = "Хотілося б, щоб увесь сніг просто розтанув. Він постійно мочить мою мантію й усе псує!",
        ["npcs"] = { [1] = 6119 },
        ["roles"] = { ["greeting"] = true },
    },
    [3305355346] = {
        ["english"] = { [1] = "I've played my part in destroying entire civilizations... to have to lower myself to dealing with the wretched Cult of the Damned disgusts me." },
        ["text"] = "Я доклав руку до знищення цілих цивілізацій... і тепер мусити опускатися до справ із жалюгідним Культом Проклятих — огидно.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [84558816] = {
        ["english"] = { [1] = "I fear that Colonel Jules may only be saved through a dangerous ritual... an exorcism." },
        ["text"] = "Боюся, полковника Жуля можна врятувати лише небезпечним ритуалом... вигнанням духа.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4271279410] = {
        ["english"] = { [1] = "I'm the new king?  What are you talking about?" },
        ["text"] = "Я новий король?  Про що ви говорите?",
        ["npcs"] = { [1] = 14353 },
        ["roles"] = { ["reply"] = true },
    },
    [3284353460] = {
        ["english"] = { [1] = "I have been slain a hundred times. I always wake here, alive. Some say I am cursed and others..." },
        ["text"] = "Мене вбивали сотню разів. Я завжди прокидаюся тут живим. Одні кажуть, що я проклятий, інші...",
        ["npcs"] = { [1] = 15169 },
        ["roles"] = { ["greeting"] = true },
    },
    [1065869305] = {
        ["english"] = { [1] = "I've not seen finer armor made in many years $N. Not since I trained under Grumnus Steelshaper in the Great Forge. I bet he could teach ye things about makin armor that would spark yer interest." },
        ["text"] = "Я вже багато років не бачив кращих обладунків, $N. Не відтоді, як навчався у Ґрумнуса Сталеформника у Великій Кузні. Закладаюся, він міг би навчити вас такого про виготовлення обладунків, що вас зацікавить.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3125579770] = {
        ["english"] = { [1] = "I usually leave that sort of thing to the gnomes.  If you want to take up the profession, I'm sure you could find some gnomes hanging out in Stormwind that would train you." },
        ["text"] = "Зазвичай я лишаю такі речі гномам.  Якщо хочете опанувати цю професію, у Штормовії напевно знайдуться гноми, які вас навчать.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [1117725060] = {
        ["english"] = { [1] = "I've never seen anything like these nether dragons. They seem to have inherited their sire's temperment, but they have become something entirely different." },
        ["text"] = "Я ніколи не бачив нічого подібного до цих драконів Підсвіття. Схоже, вони успадкували вдачу свого пращура, але стали чимось зовсім іншим.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [558048234] = {
        ["english"] = { [1] = "If I can make a new war machine, I know I can get a pretty penny for it over at the Wrath Gate.  $B$BSome of our previous iterations haven't been entirely... stable, but my flying machine should do the trick if I can just develop an effective bomb system for it." },
        ["text"] = "Якщо я створю нову бойову машину, то зможу виручити за неї кругленьку суму біля Брами Гніву.  $B$BДеякі попередні версії були не зовсім... стабільними, але моя літальна машина має спрацювати, якщо я лише розроблю для неї ефективну бомбову систему.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [848287462] = {
        ["english"] = { [1] = "I've made no mistakes." },
        ["text"] = "Я не припускався помилок.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2160729140] = {
        ["english"] = { [1] = "I have enough supplies to upgrade  our troops to seasoned." },
        ["text"] = "У мене досить припасів, щоб підвищити наші війська до загартованих.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2246937351] = {
        ["english"] = { [1] = "I need another Argent Dawn Commission." },
        ["text"] = "Мені потрібне ще одне доручення Сріблястого Світанку.",
        ["npcs"] = { [1] = 10856, [2] = 10857, [3] = 11536 },
        ["roles"] = { ["reply"] = true },
    },
    [4154656396] = {
        ["english"] = { [1] = "If you manage to complete a deck of Blessings cards you will be rewarded with a Greater Darkmoon card of Crusade.   This will increase the damage you do with your spells and attacks as you continue to fight." },
        ["text"] = "Якщо вам удасться зібрати повну колоду карт Благословень, ви отримаєте Велику карту Темного Місяця Хрестового походу.   Вона збільшуватиме шкоду ваших заклять і атак, поки ви продовжуєте битися.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2084631507] = {
        ["english"] = { [1] = "I've little time for talk, sorry." },
        ["text"] = "У мене мало часу на розмови, вибачте.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [678801114] = {
        ["english"] = { [1] = "It's good to see you again, $N.$B$BCome for a refresher in Scourge tactics?" },
        ["text"] = "Радий знову вас бачити, $N.$B$BПрийшли освіжити знання тактики проти Скари?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2418664273] = {
        ["english"] = { [1] = "I do not trust you enough to speak of such things.$b$bYou must respect the trials our people have endured, the burdens we have borne...$b$bPerhaps, if you were to bring great honor to Dun Niffelem, I would be inclined to share with you the knowledge of our people." },
        ["text"] = "Я ще не довіряю вам настільки, щоб говорити про таке.$b$bВи мусите шанувати випробування, через які пройшов наш народ, тягарі, які ми несли...$b$bМожливо, якщо принесете Дун-Ніффелему велику славу, я погоджуся поділитися з вами знаннями нашого народу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3865769384] = {
        ["english"] = { [1] = "If you prove that you are a true ally, I might consider training you..." },
        ["text"] = "Якщо доведете, що ви справжній союзник, можливо, я погоджуся вас навчати...",
        ["npcs"] = { [1] = 11557 },
        ["roles"] = { ["greeting"] = true },
    },
    [837558441] = {
        ["english"] = { [1] = "I would like to check my deposit box." },
        ["text"] = "Я хочу перевірити свою депозитну скриньку.",
        ["npcs"] = { [1] = 2455, [2] = 2456, [3] = 2457, [4] = 3309, [5] = 3318, [6] = 3320, [7] = 4155 },
        ["roles"] = { ["reply"] = true },
    },
    [1657558132] = {
        ["english"] = { [1] = "I've heard something of your exploits, $N.  I know that while you're here in Forsaken lands that you'll comport yourself with dignity and as a true hero of the sin'dorei!" },
        ["text"] = "Я чув про ваші подвиги, $N.  Знаю, що, перебуваючи тут, на землях Відречених, ви триматиметеся гідно й поводитиметеся як справжній герой сін'дорай!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [79783469] = {
        ["english"] = { [1] = "I'll tell ya, the only proper way to hunt is when yer good an' hammered!" },
        ["text"] = "Скажу тобі: по-справжньому полювати треба лише добряче нализавшись!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4036738263] = {
        ["english"] = { [1] = "Incredible. Your potions display a knowledge that rivals my own. I cannot train you further, but talk to the orc Rogvar of Stonard in the Swamp of Sorrows. He's known for his cutting-edge experiments." },
        ["text"] = "Неймовірно. Ваші зілля свідчать про знання, не гірші за мої. Я більше не можу вас навчати, але поговоріть з орком Роґваром зі Стонарда на Болоті Скорбот. Він відомий передовими експериментами.",
        ["npcs"] = { [1] = 4611 },
        ["roles"] = { ["greeting"] = true },
    },
    [2460172216] = {
        ["english"] = { [1] = "I'm ready!" },
        ["text"] = "Я готовий!",
        ["npcs"] = { [1] = 15612 },
        ["roles"] = { ["reply"] = true },
    },
    [815180321] = {
        ["english"] = { [1] = "I bet ya think you're tough, eh, kid? I guess I might have something for ya if ya can hold your own in the arena. Good stuff, not like Krixel's. That's so last season, ya know?$b$bOh, and have a nice day." },
        ["text"] = "Закладаюся, думаєш, що ти крутий, га, малий? Може, в мене й знайдеться дещо для тебе, якщо зможеш постояти за себе на арені. Добряче барахло, не те що в Крікселя. Те вже з минулого сезону, знаєш?$b$bА, і гарного дня.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3688568400] = {
        ["english"] = { [1] = "I wish to face the Defiler." },
        ["text"] = "Я хочу постати перед Осквернителем.",
        ["npcs"] = { [1] = 8816 },
        ["roles"] = { ["reply"] = true },
    },
    [1645400964] = {
        ["english"] = { [1] = "I'm going to stay here until I catch a 68 Pound Grouper!  You on the other hand want to fly off somewhere, am I right?" },
        ["text"] = "Я лишуся тут, доки не спіймаю 68-фунтового групера!  А ви, певно, хочете кудись полетіти, так?",
        ["npcs"] = { [1] = 4314 },
        ["roles"] = { ["greeting"] = true },
    },
    [1778227768] = {
        ["english"] = { [1] = "I will consider what you have told me." },
        ["text"] = "Я обміркую те, що ви мені сказали.",
        ["npcs"] = { [1] = 5353 },
        ["roles"] = { ["reply"] = true },
    },
    [1265946832] = {
        ["english"] = { [1] = "I've got a lead on Norgannon's keystone, which guards access to Ulduar's archives, but the Titans divided it into two pieces and secreted them away.$B$BOne of the pieces, the keystone's shell, is held within the Inventor's Library on the northern coast, south of Ulduar itself. The first thing you'll need to do is retrieve the fragments of an access disk from the library's guardians." },
        ["text"] = "У мене є зачіпка щодо ключ-каменя Норґаннона, який охороняє доступ до архівів Ульдуару, але титани розділили його навпіл і сховали обидві частини.$B$BОдна з них — оболонка ключ-каменя — зберігається в Бібліотеці Винахідника на північному узбережжі, на південь від самого Ульдуару. Насамперед вам треба забрати уламки диска доступу у вартових бібліотеки.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1347509629] = {
        ["english"] = { [1] = "I have heard tale of my boy being here. That he's now a powerful death knight in service of the Lich King. If this is true, then it must be me that ends the bloodline.$B$BMy charge now is to command Orgrim's Hammer to the top of Icecrown Citadel and destroy all Scourge that get in our way. We leave when you and your allies are ready." },
        ["text"] = "Я чув, що мій хлопець тут. Кажуть, тепер він могутній лицар смерті на службі Короля-ліча. Якщо це правда, саме я мушу обірвати наш рід.$B$BТепер мій обов'язок — вести «Молот Орґріма» до вершини Цитаделі Крижаної Корони й знищити всю Скару, що стане на шляху. Вирушимо, коли ви та ваші союзники будете готові.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1091130485] = {
        ["english"] = { [1] = "It's been a long day of cutting down the mindless Scourge that endlessly parade down the Dead Scar.  I hope you're here to lend a hand and not to waste my time with idle chatter." },
        ["text"] = "Довгий день рубання безмозкої Скари, яка нескінченно суне Мертвим Шрамом.  Сподіваюся, ви тут, щоб допомогти, а не марнувати мій час балачками.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [715928868] = {
        ["english"] = { [1] = "I think not. Rimblat has already proven that new life can grow from the sundered earth. Now we must find a way to reproduce and, more importantly, sustain the growth.$B$BWhile I am here, I am also offering my services to adventurers entering Naxxramas." },
        ["text"] = "Не думаю. Рімблат уже довів, що на розколотій землі може прорости нове життя. Тепер треба знайти спосіб відтворити цей ріст і, що важливіше, підтримувати його.$B$BПоки я тут, я також пропоную свої послуги шукачам пригод, які входять до Наксрамаса.",
        ["npcs"] = { [1] = 16135 },
        ["roles"] = { ["greeting"] = true },
    },
    [31941862] = {
        ["english"] = { [1] = "I have lost my Band of Veiled Shadows. Are you able to replace it for me?" },
        ["text"] = "Я загубив свій Перстень завуальованих тіней. Можете замінити його?",
        ["npcs"] = { [1] = 15498 },
        ["roles"] = { ["reply"] = true },
    },
    [4181362025] = {
        ["english"] = { [1] = "I've been working on a way to transport oil underground between major cities, but everyone tells me it's a pipe dream." },
        ["text"] = "Я працював над способом транспортувати нафту під землею між великими містами, але всі кажуть, що це нездійсненна мрія.",
        ["npcs"] = { [1] = 8736 },
        ["roles"] = { ["greeting"] = true },
    },
    [3329202831] = {
        ["english"] = { [1] = "I heard you was dead... well, you won't be easy to make dead after this!" },
        ["text"] = "Чув, ти вже помер... ну, після цього тебе буде не так легко вбити!",
        ["npcs"] = { [1] = 14326 },
        ["roles"] = { ["greeting"] = true },
    },
    [2482689235] = {
        ["english"] = { [1] = "I've been to Ironforge before.  It smells funny there." },
        ["text"] = "Я вже бував у Залізогарті.  Там дивно пахне.",
        ["npcs"] = { [1] = 14305 },
        ["roles"] = { ["greeting"] = true },
    },
    [2750772991] = {
        ["english"] = { [1] = "I've been meaning to ask you about that monkey." },
        ["text"] = "Я давно хотів запитати вас про ту мавпу.",
        ["npcs"] = { [1] = 15171 },
        ["roles"] = { ["reply"] = true },
    },
    [2129033556] = {
        ["english"] = { [1] = "I cannot be teachin' a Tauren to ride a Raptor." },
        ["text"] = "Не можу ж я вчити таурена їздити верхи на рапторі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2346482157] = {
        ["english"] = { [1] = "I've always liked sorting and organizing things.  I guess I take after my mother." },
        ["text"] = "Мені завжди подобалося сортувати й упорядковувати речі.  Мабуть, це від матері.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4049262770] = {
        ["english"] = { [1] = "I'm what you call a capitalist, $r." },
        ["text"] = "Я, як то кажуть, капіталіст, $r.",
        ["npcs"] = { [1] = 11033 },
        ["roles"] = { ["greeting"] = true },
    },
    [2142279407] = {
        ["english"] = { [1] = "I would show my liege the beast's ear and claim the beast's death as my own, taking the reward for my own use.  It is wrong to claim a deed as your own that someone else in fact did.\010" },
        ["text"] = "Я показав би сюзерену вухо звіра й приписав би собі його смерть, забравши нагороду собі.  Неправильно привласнювати чужий учинок.\010",
        ["npcs"] = { [1] = 14822 },
        ["roles"] = { ["reply"] = true },
    },
    [3255745784] = {
        ["english"] = { [1] = "I'm tellin' you, that Corin Direbrew's a madman.$B$BIt's not MY fault he didn't get invited to compete at Brewfest! But that didn't stop him and all his Dark Iron cronies from roughin' up my employees and drinking all my brew.$B$BSomeone's got to put an end to this!" },
        ["text"] = "Кажу вам, той Корен Худовар — божевільний.$B$BЦе не МОЯ провина, що його не запросили змагатися на Хмільному фестивалі! Але це не завадило йому та його друзякам із Темного Заліза побити моїх працівників і випити все моє пиво.$B$BХтось мусить покласти цьому край!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1995188333] = {
        ["english"] = { [1] = "I do not have time to waste, stranger. State your business or be off!" },
        ["text"] = "У мене немає часу на марнування, незнайомцю. Кажіть, що вам треба, або геть звідси!",
        ["npcs"] = { [1] = 11067 },
        ["roles"] = { ["greeting"] = true },
    },
    [952997598] = {
        ["english"] = { [1] = "I'm sorry, I'm a bit busy right now making horseshoes for Verner Osgood in Lakeshire. " },
        ["text"] = "Вибачте, я зараз трохи зайнятий — роблю підкови для Вернера Осґуда з Приозер'я. ",
        ["npcs"] = { [1] = 514 },
        ["roles"] = { ["greeting"] = true },
    },
    [1701059708] = {
        ["english"] = { [1] = "I would like to train further in the ways of the Light." },
        ["text"] = "Я хочу далі навчатися шляхів Світла.",
        ["npcs"] = { [1] = 925, [2] = 926, [3] = 927, [4] = 928, [5] = 1232, [6] = 3595, [7] = 3600, [8] = 4090, [9] = 4091, [10] = 4092, [11] = 5147, [12] = 5148, [13] = 5149, [14] = 5491, [15] = 5492, [16] = 8140, [17] = 11401 },
        ["roles"] = { ["reply"] = true },
    },
    [3368657906] = {
        ["english"] = { [1] = "I fear that my people are somewhat responsible for this destruction. We are refugees, displaced from our homes by the Burning Legion. This tragedy is a result of our latest evacuation. Our vessel crashed - this debris is a part of that vessel." },
        ["text"] = "Боюся, мій народ частково винен у цьому руйнуванні. Ми біженці, вигнані з домівок Палаючим Легіоном. Ця трагедія стала наслідком нашої останньої евакуації. Наш корабель розбився — ці уламки є його частиною.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2242737969] = {
        ["english"] = { [1] = "I'd like some weapon training" },
        ["text"] = "Я хочу навчитися володіти зброєю",
        ["npcs"] = { [1] = 2704, [2] = 11865, [3] = 11866, [4] = 11867, [5] = 11868, [6] = 11869, [7] = 11870, [8] = 13084 },
        ["roles"] = { ["reply"] = true },
    },
    [3442810063] = {
        ["english"] = { [1] = "I can tell that your wardrobe is in dire need of care." },
        ["text"] = "Бачу, ваш гардероб конче потребує догляду.",
        ["npcs"] = { [1] = 1103 },
        ["roles"] = { ["greeting"] = true },
    },
    [2240845421] = {
        ["english"] = { [1] = "If ye ask me, I think Grif spends a little too much time with the animals.  Still, nobody else knows the hunter's path quite like he does.  Look for him outside the smithy in Kharanos." },
        ["text"] = "Як на мене, Ґріф проводить із тваринами трохи забагато часу.  Але ніхто інший не знає шляху мисливця так добре, як він.  Шукайте його біля кузні в Караносі.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [1641983268] = {
        ["english"] = { [1] = "I'd love to teach you! Show my sister she's not the only one who knows a thing or two about engineering..." },
        ["text"] = "Я б залюбки вас навчив! Покажу сестрі, що не лише вона дещо тямить в інженерії...",
        ["npcs"] = { [1] = 11028 },
        ["roles"] = { ["greeting"] = true },
    },
    [2511941446] = {
        ["english"] = { [1] = "I can teach you the finer points of Tiger Riding, provided you have enough gold to cover the lesson!" },
        ["text"] = "Я можу навчити вас тонкощів верхової їзди на тиграх, якщо у вас вистачить золота на урок!",
        ["npcs"] = { [1] = 4753 },
        ["roles"] = { ["greeting"] = true },
    },
    [1829151350] = {
        ["english"] = { [1] = "In order to serve the Dark Lady and Varimathras we need to advance the front on the Human Infestation." },
        ["text"] = "Щоб служити Темній Пані й Варіматрасу, ми мусимо просунути фронт проти людського нашестя.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [548790126] = {
        ["english"] = { [1] = "In time you will be ready for what I have to teach, $N. Until then, please ask Darianna over there to help you with your training." },
        ["text"] = "З часом ви будете готові до того, чого я можу навчити, $N. А поки попросіть Даріанну он там допомогти з навчанням.",
        ["npcs"] = { [1] = 11081 },
        ["roles"] = { ["greeting"] = true },
    },
    [3384600346] = {
        ["english"] = { [1] = "I cannot believe they made me move my transporter out of town!   Most of the gnomes affected by the accident regained some sort of humanoid form within a few weeks and it should have been an honor to be a participant in such a grand gnomish experiment!$B$BBesides, we needed the eggs!$B" },
        ["text"] = "Не можу повірити, що мене змусили винести транспортер за місто!   Більшість гномів, яких зачепила аварія, за кілька тижнів знову набули чогось схожого на гуманоїдну форму, і участь у такому грандіозному гномському експерименті мала б бути за честь!$B$BТа й яйця нам були потрібні!$B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2838917825] = {
        ["english"] = { [1] = "I execute him as per my liege's instructions, and do it in such a manner that he suffers painfully before he dies as retribution for his crimes against my people." },
        ["text"] = "Я страчую його за наказом свого сюзерена й роблю це так, щоб перед смертю він тяжко страждав — відплата за злочини проти мого народу.",
        ["npcs"] = { [1] = 14822 },
        ["roles"] = { ["reply"] = true },
    },
    [2170614432] = {
        ["english"] = { [1] = "I've got plenty of great recipes for you to take a look at, and at discounted prices, too!" },
        ["text"] = "У мене є чимало чудових рецептів, які можете переглянути, та ще й зі знижкою!",
        ["npcs"] = { [1] = 2837 },
        ["roles"] = { ["greeting"] = true },
    },
    [2886151783] = {
        ["english"] = { [1] = "I don't know how these fireworks work, but they sure are pretty!" },
        ["text"] = "Не знаю, як працюють ці феєрверки, але ж які вони гарні!",
        ["npcs"] = { [1] = 15719 },
        ["roles"] = { ["greeting"] = true },
    },
    [3824145599] = {
        ["english"] = { [1] = "I find the ocean floor to be very peaceful." },
        ["text"] = "Дно океану здається мені напрочуд спокійним місцем.",
        ["npcs"] = { [1] = 15526 },
        ["roles"] = { ["greeting"] = true },
    },
    [3663036399] = {
        ["english"] = { [1] = "If you're not a tailor, I don't think any of my patterns will interest you, but you're welcome to browse!" },
        ["text"] = "Якщо ви не кравець, навряд чи мої викрійки вас зацікавлять, але можете переглянути!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3108106537] = {
        ["english"] = { [1] = "I'm afraid I have nothing to teach to someone with your experience. But you haven't reached the end of the road yet. Speak to Lucan Cordell, behind the counter there. He'll guide you through the next phase of your journey." },
        ["text"] = "Боюся, людині з вашим досвідом мені вже нічого навчити. Але шлях іще не скінчився. Поговоріть із Луканом Корделлом, он за прилавком. Він проведе вас наступним етапом вашого шляху.",
        ["npcs"] = { [1] = 11068 },
        ["roles"] = { ["greeting"] = true },
    },
    [2428218113] = {
        ["english"] = { [1] = "If I am to teach you the secrets of summoning an infernal servant, you must destroy Kroshius and bring me the infernal core from his burning remains. This, however, is not as easy as it sounds. Kroshius has all but burned out completely. You must reignite his corpse and raise him from the rubble. To do this, however, you must gather some components from other demonic entities.$B$BMy imp, Impsy, shall set you on your way." },
        ["text"] = "Якщо я маю навчити вас таємниць виклику слуги-інфернала, ви мусите знищити Крошіуса й принести мені інфернальне ядро з його палаючих останків. Та це не так просто, як звучить. Крошіус майже повністю вигорів. Вам треба знову запалити його труп і підняти з руїн. Для цього, однак, доведеться зібрати деякі компоненти з інших демонічних створінь.$B$BМій біс Імпсі вкаже вам шлях.",
        ["npcs"] = { [1] = 14469 },
        ["roles"] = { ["greeting"] = true },
    },
    [2935494147] = {
        ["english"] = { [1] = "If ye want to find Grumnus, the first thing ye should do is head to Ironforge. Go to the very center of the city and look for the Great Forge, ye should find him there." },
        ["text"] = "Якщо хочете знайти Ґрімнура, насамперед вирушайте до Залізогарта. Ідіть у самісінький центр міста й шукайте Велику Кузню — він має бути там.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1923471961] = {
        ["english"] = { [1] = "I have traveled countless worlds, but I have never seen as enjoyable a celebration as this feast of Winter Veil. You should travel to Ironforge, the dwarves' great city, to see it for yourself." },
        ["text"] = "Я мандрував незліченними світами, але ніде не бачив такого веселого святкування, як Свято Зимового Покрову. Вам варто вирушити до Залізогарта, великого міста дворфів, і побачити все на власні очі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2488879970] = {
        ["english"] = { [1] = "I finally have a story to tell my grandchildren about... A traitor to the kingdom was living among us!$B" },
        ["text"] = "Нарешті матиму що розповісти онукам... Серед нас жив зрадник королівства!$B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1458675672] = {
        ["english"] = { [1] = "I supply the Hold with various relics required for spellcasting as well as other alchemical reagents." },
        ["text"] = "Я постачаю твердині різноманітні реліквії для застосування заклять, а також інші алхімічні реагенти.",
        ["npcs"] = { [1] = 15175 },
        ["roles"] = { ["greeting"] = true },
    },
    [1233882911] = {
        ["english"] = { [1] = "I would like to go to the battleground." },
        ["text"] = "Я хочу вирушити на поле бою.",
        ["npcs"] = { [1] = 347, [2] = 857, [3] = 907, [4] = 2302, [5] = 2804, [6] = 3890, [7] = 5118, [8] = 7410, [9] = 7427, [10] = 10360, [11] = 12197, [12] = 12198, [13] = 14942, [14] = 14981, [15] = 14982, [16] = 14991, [17] = 15006, [18] = 15007, [19] = 15008, [20] = 15103, [21] = 15106 },
        ["roles"] = { ["reply"] = true },
    },
    [3028650578] = {
        ["english"] = { [1] = "I received the majority of my weapons training from Ilyenia Moonfire in the Warrior's Terrace.  You would do well to seek her out if you desire to learn the use of a new weapon.  " },
        ["text"] = "Більшість навчання зброї я пройшов у Іленії Місячний Вогонь на Терасі Воїнів.  Якщо прагнете опанувати нову зброю, вам варто її розшукати.  ",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [1909632822] = {
        ["english"] = { [1] = "I know who you are, $N.  Fate and forces beyond that have brought you to me for a reason, and it is one I take no pleasure in being a part of.  There are many decisions you will make in the coming times, and I hope you are wise enough to make the correct ones.$B$BBelieve me, $r, when I tell you this - there are correct choices." },
        ["text"] = "Я знаю, хто ви, $N.  Доля й сили понад неї привели вас до мене не просто так, і мені не до вподоби моя роль у цьому.  Незабаром вам доведеться зробити чимало виборів, і я сподіваюся, ви матимете досить мудрості, щоб обрати правильно.$B$BПовірте мені, $r: правильні вибори існують.",
        ["npcs"] = { [1] = 5353 },
        ["roles"] = { ["greeting"] = true },
    },
    [3658936434] = {
        ["english"] = { [1] = "I greet you, $r." },
        ["text"] = "Вітаю вас, $r.",
        ["npcs"] = { [1] = 12238 },
        ["roles"] = { ["greeting"] = true },
    },
    [2184726731] = {
        ["english"] = { [1] = "I'm flattered, but really I'm not interested... What?  You want to know where to learn enchanting?  Oh, how embarrassing!  Well, you should...  I'm sure you could... go see, um...  Taladan!  Yes, see Taladan over in the Craftsmen's Terrace!" },
        ["text"] = "Я лестощами задоволений, але справді не зацікавлений... Що?  Ви хочете знати, де вчитися зачарування?  О, як ніяково!  Ну, вам варто... певен, ви могли б... е-е... до Таладана!  Так, ідіть до Таладана на Терасі Ремісників!",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [3174810775] = {
        ["english"] = { [1] = "I'm looking for someone to help me with a task that is long overdue.$B$BYou look capable." },
        ["text"] = "Я шукаю когось, хто допоможе з давно простроченою справою.$B$BВи виглядаєте здібним.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1782701032] = {
        ["english"] = { [1] = "In days long past, we lived for the hunt.  We hunted for glory, for honor...$B$BIs it so different now?" },
        ["text"] = "У давно минулі дні ми жили заради полювання.  Полювали заради слави, заради честі...$B$BХіба тепер усе так інакше?",
        ["npcs"] = { [1] = 15572, [2] = 15573, [3] = 15574, [4] = 15575, [5] = 15576, [6] = 15577, [7] = 15578, [8] = 15579, [9] = 15580, [10] = 15581, [11] = 15582, [12] = 15583, [13] = 15584, [14] = 15585, [15] = 15586, [16] = 15588 },
        ["roles"] = { ["greeting"] = true },
    },
    [3545769614] = {
        ["english"] = { [1] = "I'm honored to meet you, $N, but your skill at potions is greater than my own. Go see Doctor Herbert Halsey, an undead in the Apothecarium of the Undercity. He can help you from now on." },
        ["text"] = "Для мене честь зустріти вас, $N, але ваша майстерність у зіллях перевершує мою. Знайдіть доктора Герберта Галсі, невмерлого в Аптекаріумі Підміста. Відтепер він зможе вам допомогти.",
        ["npcs"] = { [1] = 3347 },
        ["roles"] = { ["greeting"] = true },
    },
    [1911040476] = {
        ["english"] = { [1] = "I know a few things. You want me to show you?" },
        ["text"] = "Я дещо знаю. Хочете, покажу?",
        ["npcs"] = { [1] = 11025 },
        ["roles"] = { ["greeting"] = true },
    },
    [349570105] = {
        ["english"] = { [1] = "It pains me to see my ancestors disturbed from their graves.$B$BWe must strike down the cursed spirit of your Force-Commander Steeljaw, the one who foolishly led his caravan through these sacred grounds." },
        ["text"] = "Мені боляче бачити, як моїх предків турбують у могилах.$B$BМи мусимо знищити проклятого духа вашого командувача Сталевої Щелепи, який безглуздо повів свій караван через ці священні землі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3033925175] = {
        ["english"] = { [1] = "I can hardly believe the Cult was so careless as to leave these behind." },
        ["text"] = "Важко повірити, що Культ був настільки недбалим, аби залишити це тут.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3005150232] = {
        ["english"] = { [1] = "I must have broken hundreds of vials when I first began brewing potions. The glass was so fragile in my clumsy hands. I hope you are more cautious than I was." },
        ["text"] = "Коли я лише починав варити зілля, певно, розбив сотні флаконів. Скло було таким крихким у моїх незграбних руках. Сподіваюся, ви обережніші за мене.",
        ["npcs"] = { [1] = 11047 },
        ["roles"] = { ["greeting"] = true },
    },
    [727294444] = {
        ["english"] = { [1] = "I've got my eye on you, $r." },
        ["text"] = "Я за вами стежу, $r.",
        ["npcs"] = { [1] = 11279, [2] = 11281 },
        ["roles"] = { ["greeting"] = true },
    },
    [889063481] = {
        ["english"] = { [1] = "I have no time for interruptions." },
        ["text"] = "У мене немає часу на перешкоди.",
        ["npcs"] = { [1] = 9080 },
        ["roles"] = { ["greeting"] = true },
    },
    [1340657904] = {
        ["english"] = { [1] = "I'll get the last laugh... they'll see! Oh, hi $c, I didn't see you there." },
        ["text"] = "Я ще посміюся останнім... вони побачать! О, привіт, $c, я вас не помітив.",
        ["npcs"] = { [1] = 10305 },
        ["roles"] = { ["greeting"] = true },
    },
    [741600079] = {
        ["english"] = { [1] = "I want to fly on the wings of the Green Flight." },
        ["text"] = "Я хочу летіти на крилах Зеленої зграї.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [4140918596] = {
        ["english"] = { [1] = "I think I saw them take him over by the north side of the abbey, near the archery targets." },
        ["text"] = "Здається, я бачив, як його повели до північного боку абатства, біля мішеней для стрільби.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3314264993] = {
        ["english"] = { [1] = "I thank you for your inquiry, but I already have all of the wool bandages necessary for the war effort. I suggest that you ask around though; there are many here that could probably still use your aid." },
        ["text"] = "Дякую за ваше бажання допомогти, але в мене вже є всі вовняні бинти, потрібні для війни. Раджу розпитати інших; тут іще багато тих, кому, певно, знадобиться ваша допомога.",
        ["npcs"] = { [1] = 15528 },
        ["roles"] = { ["greeting"] = true },
    },
    [3242228443] = {
        ["english"] = { [1] = "I don't want excuses, I demand results!$B$BYou think what we're doing here is a joke?  If we don't do this right, then not only will the so-called do-gooders come calling, but we'll be found unworthy for elevation within the ranks of the Blackwing.$B$BIs that what you want?" },
        ["text"] = "Мені не потрібні виправдання, мені потрібен результат!$B$BДумаєте, те, що ми тут робимо, — жарт?  Якщо ми схибимо, мало того, що набіжать усі ці так звані добродійники, нас ще й визнають негідними піднесення в лавах Чорного Крила.$B$BВи цього хочете?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1522701503] = {
        ["english"] = { [1] = "I can instruct you in mining.  Interested?" },
        ["text"] = "Я можу навчити вас гірництва.  Цікавить?",
        ["npcs"] = { [1] = 1701, [2] = 3001, [3] = 3137, [4] = 3357, [5] = 4254, [6] = 4598, [7] = 5392 },
        ["roles"] = { ["greeting"] = true },
    },
    [2799814704] = {
        ["english"] = { [1] = "I'm afraid you have me confused with someone who wants to talk to you." },
        ["text"] = "Боюся, ви сплутали мене з кимось, хто хоче з вами розмовляти.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1059169975] = {
        ["english"] = { [1] = "It is good to see you again, $C $N.  Dornaa has been asking about you." },
        ["text"] = "Радий знову вас бачити, $C $N.  Дорнаа питала про вас.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [942182097] = {
        ["english"] = { [1] = "I'm far too busy to be playing 'guess the smell' with you, $r. State your business or get out of my sight!" },
        ["text"] = "Я надто зайнятий, щоб грати з вами у «вгадай запах», $r. Кажіть, що вам треба, або геть із моїх очей!",
        ["npcs"] = { [1] = 16212 },
        ["roles"] = { ["greeting"] = true },
    },
    [4229481280] = {
        ["english"] = { [1] = "I'm extremely busy, $r.$B$BWe have a terrible problem on our hands that must be dealt with at once!" },
        ["text"] = "Я надзвичайно зайнятий, $r.$B$BУ нас жахлива проблема, яку треба вирішити негайно!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [131816386] = {
        ["english"] = { [1] = "If you're looking for information that the Cenarion Circle might have archived somewhere, then I'm the one to talk to.  Then again, you need to know what information you're looking for first before I can really help you.$B$BSee how that works?  Brilliant!" },
        ["text"] = "Якщо шукаєте відомості, які Кенарієве Коло могло десь заархівувати, говоріть зі мною.  Але спершу вам треба знати, які саме відомості шукаєте, перш ніж я справді зможу допомогти.$B$BБачите, як це працює?  Геніяльно!",
        ["npcs"] = { [1] = 11939 },
        ["roles"] = { ["greeting"] = true },
    },
    [2989413698] = {
        ["english"] = { [1] = "I'm busy, $N. Tell Whuut to handle whatever it is. That young pup has been stewing all day long. He spends much more time like that, and he's going to hurt something." },
        ["text"] = "Я зайнятий, $N. Нехай Вуут розбереться, що там у вас. Це молоде щеня весь день вариться у власному соку. Якщо так триватиме, він комусь нашкодить.",
        ["npcs"] = { [1] = 3347 },
        ["roles"] = { ["greeting"] = true },
    },
    [264610874] = {
        ["english"] = { [1] = "I'm as sane as the next guy, $g fella:lady;. Believe what you will, but I AM capable of fashioning this armor. If you're interested, maybe we can make a deal. The sooner I can get out of the assassination business, the better." },
        ["text"] = "Я такий же при здоровому глузді, як і кожен інший, $g друже:пані;. Вірте у що хочете, але я СПРАВДІ здатен виготовити цей обладунок. Якщо зацікавлені, може, домовимося. Чим швидше я залишу справу вбивць, тим краще.",
        ["npcs"] = { [1] = 16131 },
        ["roles"] = { ["greeting"] = true },
    },
    [3174126319] = {
        ["english"] = { [1] = "I train and guide young hunters in the traditions passed down many generations." },
        ["text"] = "Я навчаю й наставляю молодих мисливців за традиціями, що передавалися багато поколінь.",
        ["npcs"] = { [1] = 3171 },
        ["roles"] = { ["greeting"] = true },
    },
    [3138244595] = {
        ["english"] = { [1] = "I hear one comment about waterfowl, and you will be eating through a tube." },
        ["text"] = "Ще один жарт про водоплавних птахів — і їстимете через трубку.",
        ["npcs"] = { [1] = 3174 },
        ["roles"] = { ["greeting"] = true },
    },
    [719453166] = {
        ["english"] = { [1] = "If it's broke, Slagtree can fix it!" },
        ["text"] = "Якщо щось зламалося — Шлаґтрі полагодить!",
        ["npcs"] = { [1] = 14737 },
        ["roles"] = { ["greeting"] = true },
    },
    [1185405104] = {
        ["english"] = { [1] = "I'm afraid your darkness quotient isn't sufficient enough for me to bother talking to you any further.  Move along please." },
        ["text"] = "Боюся, ваш коефіцієнт темряви недостатній, щоб я далі витрачав час на розмову з вами.  Проходьте, будь ласка.",
        ["npcs"] = { [1] = 460, [2] = 3324, [3] = 3325, [4] = 5171, [5] = 5172 },
        ["roles"] = { ["greeting"] = true },
    },
    [3294896340] = {
        ["english"] = { [1] = "I wanted to thank you once more for what you did for me. You gave me the courage to take back my home from the beasts of the forest. In doing so, I found Magwin!" },
        ["text"] = "Я хотів ще раз подякувати за те, що ви для мене зробили. Ви дали мені сміливість відбити свій дім у лісових звірів. І завдяки цьому я знайшов Маґвін!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3140649672] = {
        ["english"] = { [1] = "I keep 'em fed, kid. Yep, Daryl Riknussun, at yer service." },
        ["text"] = "Я їх годую, малий. Ага, Деріл Рікнуссун до ваших послуг.",
        ["npcs"] = { [1] = 5159 },
        ["roles"] = { ["greeting"] = true },
    },
    [3923808346] = {
        ["english"] = { [1] = "If I did not know better I would think that you were mocking me, mortal; but yes, that is mostly correct. You may remain fully clothed." },
        ["text"] = "Якби я не знав краще, подумав би, що ви з мене глузуєте, смертний; але так, загалом усе правильно. Можете залишатися повністю вдягненими.",
        ["npcs"] = { [1] = 6109, [2] = 15481 },
        ["roles"] = { ["greeting"] = true },
    },
    [1951571061] = {
        ["english"] = { [1] = "I'm afraid I'm rather busy fixing horseshoes at the moment.  Would you mind coming back at another time?" },
        ["text"] = "Боюся, я зараз трохи зайнятий підковами.  Не могли б ви повернутися іншим разом?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [851469276] = {
        ["english"] = { [1] = "I'm only here in case someone faints. The new recruits get a little excited and occasionally overexert themselves.$B$B...well, that, and sometimes one of the new mechano-tank prototypes explode. Whoops!" },
        ["text"] = "Я тут лише на випадок, якщо хтось зомліє. Новобранці трохи перезбуджуються й часом перенапружуються.$B$B...ну, і ще іноді вибухає якийсь новий прототип механотанка. Ой!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3602279449] = {
        ["english"] = { [1] = "I WILL have my revenge!" },
        ["text"] = "Я ОБОВ'ЯЗКОВО помщуся!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2284182640] = {
        ["english"] = { [1] = "I'm afraid I cannot speak with you at the moment." },
        ["text"] = "Боюся, зараз я не можу з вами говорити.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [126470873] = {
        ["english"] = { [1] = "I sure could use a kiss about now.  Know where I can find one?" },
        ["text"] = "Мені б зараз не завадив поцілунок.  Не знаєте, де знайти?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4163322378] = {
        ["english"] = { [1] = "I suspect that the imps are stealing knowledge." },
        ["text"] = "Підозрюю, біси крадуть знання.",
        ["npcs"] = { [1] = 14369 },
        ["roles"] = { ["greeting"] = true },
    },
    [959732348] = {
        ["english"] = { [1] = "I wish to make a purchase." },
        ["text"] = "Я хочу дещо придбати.",
        ["npcs"] = { [1] = 11038 },
        ["roles"] = { ["reply"] = true },
    },
    [127155062] = {
        ["english"] = { [1] = "I'll wait." },
        ["text"] = "Я зачекаю.",
        ["npcs"] = { [1] = 15443 },
        ["roles"] = { ["reply"] = true },
    },
    [295504588] = {
        ["english"] = { [1] = "I confront the ruler on his malicious behavior, upholding my liege's honor at the risk of any future diplomacy." },
        ["text"] = "Я дорікаю правителю за його лиху поведінку, відстоюючи честь свого сюзерена, навіть ризикуючи майбутніми дипломатичними відносинами.",
        ["npcs"] = { [1] = 14822 },
        ["roles"] = { ["reply"] = true },
    },
    [1979074761] = {
        ["english"] = { [1] = "I'll tell you what. Since you fancy yourself the hero type, if you can make your way through the Badlands to the Searing Gorge and bring me back something to prove your heroics, I'll see what I can do about getting you a key.$B$BIn the southeasternmost corner of Searing Gorge is a lady almost as tough as me, Margol the Rager. Maybe you should investigate." },
        ["text"] = "Ось що я вам скажу. Раз уже вважаєте себе героєм, проберіться через Безплідні краї до Випаленої ущелини й принесіть щось як доказ своїх подвигів — тоді я подумаю, що можна зробити з ключем.$B$BУ найпівденно-східнішому куті Випаленої ущелини є пані майже така ж міцна, як я, — Марґол Люта. Може, вам варто її розшукати.",
        ["npcs"] = { [1] = 3836 },
        ["roles"] = { ["greeting"] = true },
    },
    [2442944247] = {
        ["english"] = { [1] = "I still do not fully understand." },
        ["text"] = "Я все ще не до кінця розумію.",
        ["npcs"] = { [1] = 4542 },
        ["roles"] = { ["reply"] = true },
    },
    [3158968546] = {
        ["english"] = { [1] = "If you're interested in learning more about the traditional Pilgrim's Bounty feast, speak to any of the hostesses." },
        ["text"] = "Якщо хочете більше дізнатися про традиційний бенкет Щедрості Пілігрима, поговоріть із будь-якою господинею.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3044256488] = {
        ["english"] = { [1] = "I highly recommend that you visit Sayge to get your fortune told. I know, I know... he's a gnoll.  But he's a very special gnoll with the power to divine your future!$B$BAnd we are constantly expanding the faire with all manner of new attractions!" },
        ["text"] = "Дуже раджу навідати Сайґа й дізнатися свою долю. Знаю, знаю... він ґнол.  Але дуже особливий ґнол, здатний провидіти ваше майбутнє!$B$BА ми тим часом постійно розширюємо ярмарок і додаємо нові розваги!",
        ["npcs"] = { [1] = 10445 },
        ["roles"] = { ["greeting"] = true },
    },
    [4271655559] = {
        ["english"] = { [1] = "I sell wares that crafters need. Just the basics, nothing fancy." },
        ["text"] = "Я продаю потрібні ремісникам товари. Тільки основне, нічого вишуканого.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2595718048] = {
        ["english"] = { [1] = "I'm going to miss Camp Winterhoof, but I understand why Chieftain Ashtotem made his decision. Home is a comfort we cannot always afford." },
        ["text"] = "Я сумуватиму за табором Зимового Копита, але розумію рішення вождя Попелястого Тотема. Дім — це розкіш, яку ми не завжди можемо собі дозволити.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3965788168] = {
        ["english"] = { [1] = "I'll gather up the rest of slaves and get them ready to fight. We'll catch up with you before you engage Scourgelord Tyrannus." },
        ["text"] = "Я зберу решту рабів і підготую їх до бою. Ми наздоженемо вас, перш ніж ви вступите в бій із володарем Скари Тіраннусом.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1922978928] = {
        ["english"] = { [1] = "I believe you are up to this task, will you accept the challenge?" },
        ["text"] = "Гадаю, це завдання тобі до снаги. Приймете виклик?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3291811240] = {
        ["english"] = { [1] = "If you manage to complete a deck of Storms cards you will be rewarded with a Greater Darkmoon card of Wrath.   This will increase your chance to get a critical hit with spells or physical attacks until you achieve one." },
        ["text"] = "Якщо вам удасться зібрати повну колоду карт Бур, ви отримаєте Велику карту Темного Місяця Гніву.   Вона збільшуватиме шанс критичного удару закляттями або фізичними атаками, доки ви не завдасте одного.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1947075695] = {
        ["english"] = { [1] = "Impossible." },
        ["text"] = "Неможливо.",
        ["npcs"] = { [1] = 11286 },
        ["roles"] = { ["reply"] = true },
    },
    [959791330] = {
        ["english"] = { [1] = "I'd talk to you if you smelled better. Cologne would be nice." },
        ["text"] = "Я поговорив би з вами, якби від вас краще пахло. Одеколон був би доречний.",
        ["npcs"] = { [1] = 68, [2] = 483, [3] = 1275, [4] = 1286, [5] = 1287, [6] = 1291, [7] = 1295, [8] = 1297, [9] = 1299, [10] = 1301, [11] = 1307, [12] = 1309, [13] = 1312, [14] = 1313, [15] = 1318, [16] = 1321, [17] = 1328, [18] = 1347, [19] = 1350, [20] = 1413, [21] = 1414, [22] = 1415, [23] = 1428, [24] = 1431, [25] = 1721, [26] = 1976, [27] = 2227, [28] = 2330, [29] = 2695, [30] = 2796, [31] = 2802, [32] = 2808, [33] = 2997, [34] = 3003, [35] = 3010, [36] = 3012, [37] = 3014, [38] = 3015, [39] = 3017, [40] = 3022, [41] = 3023, [42] = 3025, [43] = 3029, [44] = 3037, [45] = 3084, [46] = 3092, [47] = 3095, [48] = 3296, [49] = 3312, [50] = 3319, [51] = 3322, [52] = 3333, [53] = 3342, [54] = 3346, [55] = 3356, [56] = 3358, [57] = 3359, [58] = 3367, [59] = 3405, [60] = 3447, [61] = 3561, [62] = 3562, [63] = 3626, [64] = 3979, [65] = 4088, [66] = 4164, [67] = 4167, [68] = 4168, [69] = 4169, [70] = 4170, [71] = 4171, [72] = 4172, [73] = 4173, [74] = 4175, [75] = 4177, [76] = 4180, [77] = 4181, [78] = 4203, [79] = 4262, [80] = 4486, [81] = 4521, [82] = 4554, [83] = 4555, [84] = 4558, [85] = 4570, [86] = 4574, [87] = 4575, [88] = 4577, [89] = 4580, [90] = 4587, [91] = 4599, [92] = 4604, [93] = 4615, [94] = 4775, [95] = 5049, [96] = 5101, [97] = 5108, [98] = 5109, [99] = 5112, [100] = 5120, [101] = 5123, [102] = 5129, [103] = 5138, [104] = 5140, [105] = 5151, [106] = 5154, [107] = 5155, [108] = 5156, [109] = 5158, [110] = 5162, [111] = 5178, [112] = 5407, [113] = 5483, [114] = 5494, [115] = 5510, [116] = 5512, [117] = 5514, [118] = 5543, [119] = 5565, [120] = 5603, [121] = 5657, [122] = 5658, [123] = 5668, [124] = 5669, [125] = 5701, [126] = 5703, [127] = 5704, [128] = 5731, [129] = 5732, [130] = 5747, [131] = 5770, [132] = 5816, [133] = 5817, [134] = 5819, [135] = 5820, [136] = 6034, [137] = 6174, [138] = 6179, [139] = 6272, [140] = 6411, [141] = 6579, [142] = 6740, [143] = 7292, [144] = 7294, [145] = 7295, [146] = 7313, [147] = 7316, [148] = 7740, [149] = 7825, [150] = 7978, [151] = 8026, [152] = 8361, [153] = 8363, [154] = 8364, [155] = 8665, [156] = 8931, [157] = 10455, [158] = 10456, [159] = 11827, [160] = 11828, [161] = 12799, [162] = 12805, [163] = 14376, [164] = 14378, [165] = 14379, [166] = 14380, [167] = 14404, [168] = 14497, [169] = 16002, [170] = 16004 },
        ["roles"] = { ["greeting"] = true },
    },
    [800328502] = {
        ["english"] = { [1] = "I trust the Light is with you, $N. Is there something that I can I help you with?" },
        ["text"] = "Сподіваюся, Світло з вами, $N. Чим можу допомогти?",
        ["npcs"] = { [1] = 375, [2] = 376, [3] = 377, [4] = 5484, [5] = 5489 },
        ["roles"] = { ["greeting"] = true },
    },
    [3801680582] = {
        ["english"] = { [1] = "I would like to enter the secret code to receive my Murloc pet." },
        ["text"] = "Я хочу ввести таємний код, щоб отримати мурлока-вихованця.",
        ["npcs"] = { [1] = 2943, [2] = 7951, [3] = 16070, [4] = 16076 },
        ["roles"] = { ["reply"] = true },
    },
    [1106987076] = {
        ["english"] = { [1] = "It is Bowen Brisboise that you seek then.  You'll find him inside his house southwest of Brill just on the other side of the bridge at Cold Hearth Manor." },
        ["text"] = "Тоді вам потрібен Боуен Брісбуаз.  Знайдете його в його будинку на південний захід від Брілля, відразу за мостом біля садиби Холодне Вогнище.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [3429793486] = {
        ["english"] = { [1] = "I hope you don't think I'm a stalker, or anything like that, $N.$B$BI mean, I know that you're real famous within the Skyguard now, and well... I'm sure that you wouldn't want to hang out with a lowly peon like me.$B$BBut, if you ever want to get together to just hang out, or even wrangle some more rays, drop by anytime!  I'll be here.$B$BI miss you..." },
        ["text"] = "Сподіваюся, ви не думаєте, що я якийсь переслідувач чи щось таке, $N.$B$BТобто я знаю, що ви тепер дуже відомі в Небесній варті, і... певен, вам не захочеться водитися з таким простим наймитом, як я.$B$BАле якщо колись захочете просто посидіти разом чи навіть приборкати ще кількох скатів — заходьте будь-коли!  Я буду тут.$B$BЯ сумую за вами...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [717241090] = {
        ["english"] = { [1] = "I would never turn away someone who's ready to train with me. Unfortunately, you're not! You've still got a ways to go kid!" },
        ["text"] = "Я ніколи не відмовлю тому, хто готовий у мене вчитися. На жаль, ви ще не готові! Вам іще далеко, малий!",
        ["npcs"] = { [1] = 8736 },
        ["roles"] = { ["greeting"] = true },
    },
    [1335315005] = {
        ["english"] = { [1] = "I'd like to fly to Thunder Bluff." },
        ["text"] = "Я хочу полетіти до Громового Бескиду.",
        ["npcs"] = { [1] = 11798 },
        ["roles"] = { ["reply"] = true },
    },
    [2509671160] = {
        ["english"] = { [1] = "I'd like to fly to Rut'theran Village." },
        ["text"] = "Я хочу полетіти до селища Рут'теран.",
        ["npcs"] = { [1] = 11800 },
        ["roles"] = { ["reply"] = true },
    },
    [2404174610] = {
        ["english"] = { [1] = "It is true I have skills to teach to those who are worthy. Would that be you?" },
        ["text"] = "Правда, я маю знання, якими ділюся з гідними. Ви з їхнього числа?",
        ["npcs"] = { [1] = 4213 },
        ["roles"] = { ["greeting"] = true },
    },
    [3878079252] = {
        ["english"] = { [1] = "I come to Silithus every year around this time. The weather is phenomenal for my bunions.$B$BYou should take a stroll with me, friend. Enjoy the sights and what not." },
        ["text"] = "Я щороку приходжу до Силітуса приблизно в цю пору. Погода просто дивовижна для моїх мозолів.$B$BПрогуляйтеся зі мною, друже. Помилуйтеся краєвидами й усім таким.",
        ["npcs"] = { [1] = 14536 },
        ["roles"] = { ["greeting"] = true },
    },
    [1745904651] = {
        ["english"] = { [1] = "I would suggest looking in the Cathedral of Light in Cathedral Square." },
        ["text"] = "Раджу пошукати в Соборі Світла на Соборній площі.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [1907741357] = {
        ["english"] = { [1] = "I wish I knew, dear. He will not listen to you nor will he listen to me. In truth, it is why I am still here. It is why I have not left with Mother Kashur. He must find his heart. Our people will not survive through the winter without leadership." },
        ["text"] = "Хотілося б знати, люба. Він не слухає ні вас, ні мене. Правду кажучи, саме тому я досі тут. Саме тому не пішла з Матір'ю Кашур. Він мусить віднайти своє серце. Наш народ не переживе зиму без провідника.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2912798431] = {
        ["english"] = { [1] = "I hear that they have a Mining Trainer in the Undercity.  All you have to do to get there is head south out of town and go to the back of the Ruins of Lordaeron.  Then take the elevator down into the Undercity itself and ask an Undercity Guardian for further directions." },
        ["text"] = "Кажуть, у Підмісті є наставник гірництва.  Просто вирушайте з міста на південь до задньої частини руїн Лордерону.  Потім спустіться ліфтом у саме Підмісто й попросіть вартового Підміста підказати дорогу.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [3076107320] = {
        ["english"] = { [1] = "I would speak against my brother joining the order, rushing a permanent breech in our relationship.  He would be a danger to himself and those around him, and that is too great a risk hoping he would improve over time." },
        ["text"] = "Я виступив би проти вступу брата до ордену, ризикуючи назавжди зруйнувати наші стосунки.  Він був би небезпечний і для себе, і для оточення, а сподіватися, що з часом він виправиться, — надто великий ризик.",
        ["npcs"] = { [1] = 14822 },
        ["roles"] = { ["reply"] = true },
    },
    [1778543621] = {
        ["english"] = { [1] = "I'm very busy right now, $r. Please leave me alone." },
        ["text"] = "Я зараз дуже зайнятий, $r. Будь ласка, дайте мені спокій.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3696761253] = {
        ["english"] = { [1] = "I would show my liege the beast's ear and claim the beast's death as my own - after all, I did slay it.  I would then offer some of the reward to the destitute knight to help his family." },
        ["text"] = "Я показав би сюзерену вухо звіра й приписав би собі його смерть — зрештою, я справді його вбив.  Потім я віддав би частину нагороди знедоленому лицарю, щоб допомогти його родині.",
        ["npcs"] = { [1] = 14822 },
        ["roles"] = { ["reply"] = true },
    },
    [3634146955] = {
        ["english"] = { [1] = "I'd like to train." },
        ["text"] = "Я хочу навчатися.",
        ["npcs"] = { [1] = 986, [2] = 1231, [3] = 3157, [4] = 3596, [5] = 4205, [6] = 5501, [7] = 11557 },
        ["roles"] = { ["reply"] = true },
    },
    [4079025104] = {
        ["english"] = { [1] = "If we are to make these new lands ours then we must have places to rest our battle weary bodies. Lay your axe by the fire and share the stories of your mighty battles." },
        ["text"] = "Якщо ми хочемо зробити ці нові землі своїми, нам потрібні місця, де виснажені боєм тіла зможуть відпочити. Покладіть сокиру біля вогню й поділіться історіями про свої великі битви.",
        ["npcs"] = { [1] = 5814, [2] = 6928, [3] = 6929, [4] = 6930, [5] = 7731, [6] = 9356, [7] = 12196 },
        ["roles"] = { ["greeting"] = true },
    },
    [2119423593] = {
        ["english"] = { [1] = "I'm sorry, $c, but my wares are best suited to those who know which end of the needle the thread goes through.$B$BI can assure you, tailoring is about far more than monogramming handkerchiefs." },
        ["text"] = "Перепрошую, $c, але мої товари найкраще підходять тим, хто знає, з якого боку голки протягують нитку.$B$BЗапевняю вас, кравецтво — це значно більше, ніж вишивання ініціалів на хустинках.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [121514824] = {
        ["english"] = { [1] = "I have to clean up this mess, but I'll do it without complaint.$B$BYou'll help if you have any Horde pride at all!" },
        ["text"] = "Мені доведеться прибрати цей безлад, але я не скаржитимусь.$B$BЯкщо в вас є бодай крихта гордості за Орду, ви допоможете!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [638509358] = {
        ["english"] = { [1] = "I'm never too busy to speak to a stranger! Almost never, anyway..." },
        ["text"] = "Я ніколи не надто зайнятий, щоб поговорити з незнайомцем! Ну, майже ніколи...",
        ["npcs"] = { [1] = 1676 },
        ["roles"] = { ["greeting"] = true },
    },
    [4102219587] = {
        ["english"] = { [1] = "I have lost my Signet of the Unseen Path. Are you able to replace it for me?" },
        ["text"] = "Я загубив свою Печатку невидимого шляху. Можете замінити її?",
        ["npcs"] = { [1] = 15498 },
        ["roles"] = { ["reply"] = true },
    },
    [3959992921] = {
        ["english"] = { [1] = "I dream, $N... oh yes, I dream. In my dreams I die a thousand times in a thousand different ways. Some would call dreams such as mine nightmares. NOT I! In dreams I die in the thick of battle. For each single death of my own, ten thousand enemies of the Horde fall before me. It is glorious!" },
        ["text"] = "Я бачу сни, $N... о так, бачу. У своїх снах я помираю тисячу разів тисячею різних способів. Дехто назвав би такі сни кошмарами. АЛЕ НЕ Я! У снах я гину в самій гущі битви. За кожну мою смерть десять тисяч ворогів Орди падають переді мною. Це велично!",
        ["npcs"] = { [1] = 9077 },
        ["roles"] = { ["greeting"] = true },
    },
    [3410117340] = {
        ["english"] = { [1] = "I would like to enter the secret code to receive my Murloc costume." },
        ["text"] = "Я хочу ввести таємний код, щоб отримати костюм мурлока.",
        ["npcs"] = { [1] = 2943, [2] = 7951 },
        ["roles"] = { ["reply"] = true },
    },
    [3023344603] = {
        ["english"] = { [1] = "I would like to enter the secret code to receive my Big Blizzard Bear." },
        ["text"] = "Я хочу ввести таємний код, щоб отримати свого Великого Ведмедя Blizzard.",
        ["npcs"] = { [1] = 2943, [2] = 7951 },
        ["roles"] = { ["reply"] = true },
    },
    [3219197346] = {
        ["english"] = { [1] = "I would like to buy from you." },
        ["text"] = "Я хочу купити у вас.",
        ["npcs"] = { [1] = 384, [2] = 491, [3] = 836, [4] = 1243, [5] = 1261, [6] = 1460, [7] = 2357, [8] = 3362, [9] = 3685, [10] = 4730, [11] = 4731, [12] = 4885, [13] = 5411, [14] = 5594, [15] = 7683, [16] = 7852, [17] = 7952, [18] = 7955, [19] = 10856, [20] = 10857, [21] = 11536, [22] = 14739 },
        ["roles"] = { ["reply"] = true },
    },
    [1900092323] = {
        ["english"] = { [1] = "I would create some surreptitious means to keep my brother out of the order.  I can keep him out without him being any bit wiser, thereby saving our familial bonds." },
        ["text"] = "Я вигадав би таємний спосіб не допустити брата до ордену.  Я зможу його зупинити так, що він нічого не запідозрить, і тим самим збережу наші родинні зв'язки.",
        ["npcs"] = { [1] = 14822 },
        ["roles"] = { ["reply"] = true },
    },
    [1155352494] = {
        ["english"] = { [1] = "If you haven't come to train, step back and leave me to my work." },
        ["text"] = "Якщо ви прийшли не вчитися, відійдіть і дайте мені працювати.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [733630975] = {
        ["english"] = { [1] = "I know of a few people around here that practice a profession or two.  What profession do you have in mind?" },
        ["text"] = "Я знаю кількох людей неподалік, які опанували одну-дві професії.  Яка професія вас цікавить?",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [3923748725] = {
        ["english"] = { [1] = "I would be delighted to aid you in the commencement of your pursuit! Let me grab my spinner and we'll get started..." },
        ["text"] = "Із задоволенням допоможу вам розпочати цю справу! Дайте-но я візьму свою блешню — і почнемо...",
        ["npcs"] = { [1] = 3290 },
        ["roles"] = { ["greeting"] = true },
    },
    [1935895359] = {
        ["english"] = { [1] = "I knew that we never should have gone into those caves. It's not natural!" },
        ["text"] = "Я ж знав, що нам не слід було лізти в ті печери. Це неприродно!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4137041494] = {
        ["english"] = { [1] = "I can't teach what I don't know! If only there was someone else who knew more than I do... wait, there is! Go see Buzzek Bracketswing in Gadgetzan!" },
        ["text"] = "Не можу навчити того, чого сам не знаю! От якби був хтось, хто знає більше за мене... стривайте, такий є! Ідіть до Буззека Дужкокрила в Пристробляск!",
        ["npcs"] = { [1] = 11017 },
        ["roles"] = { ["greeting"] = true },
    },
    [1453845485] = {
        ["english"] = { [1] = "I still do not understand." },
        ["text"] = "Я досі не розумію.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2971996923] = {
        ["english"] = { [1] = "I never thought I'd get to see Teldrassil... I certainly never thought we'd crash into Teldrassil." },
        ["text"] = "Я ніколи не думав, що побачу Тельдрассіль... і точно не думав, що ми вріжемося в Тельдрассіль.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1710941910] = {
        ["english"] = { [1] = "I won't challenge you, but I'd like to see your wares." },
        ["text"] = "Я не кидатиму вам виклик, але хотів би переглянути ваші товари.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2068897640] = {
        ["english"] = { [1] = "I don't train your kind $c.  Find your own trainer before you anger me." },
        ["text"] = "Я не навчаю таких, як ви, $c.  Знайдіть свого наставника, поки не розгнівали мене.",
        ["npcs"] = { [1] = 985, [2] = 3153, [3] = 3169, [4] = 3353, [5] = 3354 },
        ["roles"] = { ["greeting"] = true },
    },
    [675204447] = {
        ["english"] = { [1] = "I don't get too many Skinners in here looking for training, but I guess I could teach you something if you're ready." },
        ["text"] = "Не так уже й багато шкурників приходять сюди вчитися, але, гадаю, я можу вас дечого навчити, якщо готові.",
        ["npcs"] = { [1] = 1292 },
        ["roles"] = { ["greeting"] = true },
    },
    [2558111112] = {
        ["english"] = { [1] = "I wish to purchase arcane quickener from you." },
        ["text"] = "Я хочу придбати у вас арканічний прискорювач.",
        ["npcs"] = { [1] = 11056, [2] = 11057 },
        ["roles"] = { ["reply"] = true },
    },
    [3290404655] = {
        ["english"] = { [1] = "I would be happy to take you under my wing. Let us begin." },
        ["text"] = "Я залюбки візьму вас під своє крило. Почнімо.",
        ["npcs"] = { [1] = 4193 },
        ["roles"] = { ["greeting"] = true },
    },
    [3851563122] = {
        ["english"] = { [1] = "I hope that you are here to go to Alterac Valley $N.  We can use all o' the help that we can get." },
        ["text"] = "Сподіваюся, ви тут, щоб вирушити до Альтерацької долини, $N.  Нам знадобиться вся можлива допомога.",
        ["npcs"] = { [1] = 7410 },
        ["roles"] = { ["greeting"] = true },
    },
    [3324926815] = {
        ["english"] = { [1] = "I walk this road alone, seeking ways to defend my honor and rid this land of our enemies.$B$BWhat can I do for you, $N?" },
        ["text"] = "Я йду цим шляхом сам, шукаючи способів захистити свою честь і очистити ці землі від ворогів.$B$BЧим можу допомогти, $N?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [305247692] = {
        ["english"] = { [1] = "I can only assume that you know who I am. And yet you insist on disturbing me?$b$bWhat could you possibly want that requires my attention?" },
        ["text"] = "Можу лише припустити, що ви знаєте, хто я. І все ж наполягаєте на тому, щоб мене турбувати?$b$bЩо вам узагалі може бути потрібно такого, що вимагає моєї уваги?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1649259978] = {
        ["english"] = { [1] = "I know an ace when I see one.  Thanks again for saving my life!" },
        ["text"] = "Я відразу бачу справжнього аса.  Ще раз дякую, що врятували мені життя!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [564102499] = {
        ["english"] = { [1] = "I hear you're quite the cook." },
        ["text"] = "Чув, ви неабиякий кухар.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2632193162] = {
        ["english"] = { [1] = "I kinnae help ye with trainin'. Ye should look fer a $c trainer." },
        ["text"] = "Я не можу допомогти з навчанням. Вам слід знайти наставника для $c.",
        ["npcs"] = { [1] = 895, [2] = 1231, [3] = 5115, [4] = 5116, [5] = 5117, [6] = 5515, [7] = 5516, [8] = 5517, [9] = 10930 },
        ["roles"] = { ["greeting"] = true },
    },
    [12705501] = {
        ["english"] = { [1] = "I must say, you delivered my poison and dealt with those trolls most ruthlessly, $c. You've got the makings of quite a talented young $g man : lady;!" },
        ["text"] = "Мушу сказати, ви доставили мою отруту й розправилися з тими тролями вкрай безжально, $c. У вас є всі задатки $g дуже здібного молодого юнака : дуже здібної молодої дівчини;!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [334295955] = {
        ["english"] = { [1] = "I wish to hear your tale." },
        ["text"] = "Я хочу почути вашу оповідь.",
        ["npcs"] = { [1] = 8436 },
        ["roles"] = { ["reply"] = true },
    },
    [2783383358] = {
        ["english"] = { [1] = "I grow bored of guarding Ambassador Sunsorrow, $n. Care to spar a bit? Perhaps one of us will learn something." },
        ["text"] = "Мені вже набридло стерегти посла Сонячну Скорботу, $n. Не хочете трохи побитися? Може, хтось із нас чогось навчиться.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [141372306] = {
        ["english"] = { [1] = "I, like my brother, honor those who honor their ancestors.  It brings me great joy to share my crafting secrets to disciples of the Lunar Festival!" },
        ["text"] = "Я, як і мій брат, шаную тих, хто шанує своїх предків.  Мені велика радість ділитися ремісничими таємницями з учнями Місячного фестивалю!",
        ["npcs"] = { [1] = 15909 },
        ["roles"] = { ["greeting"] = true },
    },
    [1790423285] = {
        ["english"] = { [1] = "I wish it were true, $N, but it will take more than you alone to overcome the forces of Razelikh and his subordinates.$B$BGather a suitable group of adventurers and would-be heroes and free my men of their eternal torture! Eighteen stones you must shatter.$B$BFight hard and die with honor, $N." },
        ["text"] = "Хотів би я, щоб це було правдою, $N, але самотужки вам не здолати сили Разеліха та його підлеглих.$B$BЗберіть гідну групу шукачів пригод і майбутніх героїв та звільніть моїх людей від вічних мук! Ви мусите розбити вісімнадцять каменів.$B$BБийтеся люто й помріть із честю, $N.",
        ["npcs"] = { [1] = 7572 },
        ["roles"] = { ["greeting"] = true },
    },
    [333728021] = {
        ["english"] = { [1] = "I got some candy at the inn before.  I can't wait to get some more!" },
        ["text"] = "Раніше я взяв трохи цукерок у заїзді.  Не можу дочекатися, коли дістану ще!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3805156785] = {
        ["english"] = { [1] = "I hope to one day forge weapons and armor from the bones of my enemies." },
        ["text"] = "Сподіваюся, колись я викуватиму зброю й обладунки з кісток своїх ворогів.",
        ["npcs"] = { [1] = 4605 },
        ["roles"] = { ["greeting"] = true },
    },
    [3540810576] = {
        ["english"] = { [1] = "I hope that Loralthalis is alright, $c. Maybe I should go up to Duskwither Spire myself? Maybe I should have done that in the first place?" },
        ["text"] = "Сподіваюся, з Лоральталісом усе гаразд, $c. Може, мені самому піднятися до Вежі Сутінкового В'янення? Може, так і треба було зробити від самого початку?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2096714051] = {
        ["english"] = { [1] = "I bet you rotters thought you were pretty clever at the Wrath Gate, didn't you? Playtime's over. We're here to make sure you don't try anything." },
        ["text"] = "Закладаюся, ви, гниляки, вважали себе дуже хитрими біля Брами Гніву, еге ж? Ігри скінчилися. Ми тут, аби ви більше нічого не утнули.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [144162033] = {
        ["english"] = { [1] = "I lost the Flute of the Ancients and require a replacement, Eridan." },
        ["text"] = "Я загубив Флейту Древніх і потребую заміни, Ерідане.",
        ["npcs"] = { [1] = 9116 },
        ["roles"] = { ["reply"] = true },
    },
    [4275135265] = {
        ["english"] = { [1] = "I hear there's a shop up in Ironforge run by the gnomes that specializes in alchemy.  You should go have a look." },
        ["text"] = "Кажуть, у Залізогарті є гномська крамниця, що спеціалізується на алхімії.  Вам варто туди зазирнути.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [1420008761] = {
        ["english"] = { [1] = "I'm afraid you're out of my league, friend! You should go see Nogg in Orgrimmar, he'll take you to the next level!" },
        ["text"] = "Боюся, ви вже не мого рівня, друже! Ідіть до Ногґа в Орґріммарі — він підніме вас на новий рівень!",
        ["npcs"] = { [1] = 3494, [2] = 10993 },
        ["roles"] = { ["greeting"] = true },
    },
    [225210218] = {
        ["english"] = { [1] = "I see you know more of the secret of steel than I do. That is good, for it is meant to be taken. Now you must travel to the jungle south of the human lands, to the goblin city of Booty Bay. There you will find a Goblin named Brikk Keencraft. I do not like Goblins but his knowledge of the secret of steel is unmatched by any I know of." },
        ["text"] = "Бачу, ви знаєте таємницю сталі краще за мене. Це добре, бо її й належить переймати. Тепер вирушайте до джунглів на південь від людських земель, у гоблінське місто Бухта Наживи. Там знайдете гобліна на ім'я Брікк Гостромайстер. Я не люблю гоблінів, але ніхто з відомих мені не знає таємниці сталі краще за нього.",
        ["npcs"] = { [1] = 3355 },
        ["roles"] = { ["greeting"] = true },
    },
    [3080620893] = {
        ["english"] = { [1] = "I will not forrrget what you have done...$B$BPleassse, leave meee..." },
        ["text"] = "Я не забуду того, що ви зробили...$B$BБудь ласка, залиште мене...",
        ["npcs"] = { [1] = 10684 },
        ["roles"] = { ["greeting"] = true },
    },
    [386814569] = {
        ["english"] = { [1] = "I can show you what you wish to know, but you must be patient. Take your time to work the steel and feel the way it shapes beneath your hammer. When you become one with the steel, then you will understand." },
        ["text"] = "Я можу показати вам те, що ви прагнете знати, але мусите бути терплячими. Не поспішайте, працюючи зі сталлю, і відчуйте, як вона набуває форми під вашим молотом. Коли станете єдиним цілим зі сталлю, тоді й зрозумієте.",
        ["npcs"] = { [1] = 10266 },
        ["roles"] = { ["greeting"] = true },
    },
    [157102989] = {
        ["english"] = { [1] = "I sense you've cleared the path to my brethren.  My connection to them and to the temple is still strong.  Do you wish to delve deeper inside?" },
        ["text"] = "Я відчуваю, що ви розчистили шлях до моїх братів.  Мій зв'язок із ними та храмом досі міцний.  Бажаєте заглибитися далі?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3638064067] = {
        ["english"] = { [1] = "I realize you have only recently joined us, and thus may be unaware of our traditions. In Moonglade, a tremendous celebration is taking place. This is a time of year when we honor our elders, and you are certainly invited! Travel to one of our cities if you wish to join in!" },
        ["text"] = "Розумію, ви лише нещодавно приєдналися до нас, тож можете не знати наших традицій. У Місячній галявині відбувається величезне святкування. У цю пору року ми вшановуємо старійшин, і вас, звісно, теж запрошено! Якщо хочете долучитися, вирушайте до одного з наших міст.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4114783091] = {
        ["english"] = { [1] = "I can't help you; your work is beyond my own. Talk to Arthur Moore, over there by the coffins. He'll be able to train you further." },
        ["text"] = "Не можу вам допомогти; ваша майстерність уже перевершила мою. Поговоріть з Артуром Муром, он там, біля трун. Він зможе навчити вас далі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3972148248] = {
        ["english"] = { [1] = "I have lost my Signet of Unyielding Strength. Are you able to replace it for me?" },
        ["text"] = "Я загубив свою Печатку непохитної сили. Можете замінити її?",
        ["npcs"] = { [1] = 15498 },
        ["roles"] = { ["reply"] = true },
    },
    [4043559724] = {
        ["english"] = { [1] = "I will join in the assault upon Icecrown Citadel when the time to strike is upon us." },
        ["text"] = "Я приєднаюся до штурму Цитаделі Крижаної Корони, коли настане час удару.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [283570346] = {
        ["english"] = { [1] = "I detect a charge in your paranarbulatric region!  You must have used the Zephyrium Capacitorium lately -- you can't use it again until the charge wears off..." },
        ["text"] = "Я виявляю заряд у вашій паранарбулатричній ділянці!  Ви, певно, нещодавно користувалися Зефірієвим Конденсаторіумом — повторно скористатися ним не вийде, доки заряд не розвіється...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1094180202] = {
        ["english"] = { [1] = "Isn't it just beautiful? Can you see the potential profit?" },
        ["text"] = "Хіба не краса? Бачите потенційний прибуток?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2215835254] = {
        ["english"] = { [1] = "I've got all the cooking supplies you'll ever need, mon!" },
        ["text"] = "У мене є всі кухарські припаси, які тобі коли-небудь знадобляться, друже!",
        ["npcs"] = { [1] = 14738 },
        ["roles"] = { ["greeting"] = true },
    },
    [2428538438] = {
        ["english"] = { [1] = "I lost a piece of Lord Valthalak's Amulet!" },
        ["text"] = "Я загубив частину Амулета лорда Вальталака!",
        ["npcs"] = { [1] = 16033 },
        ["roles"] = { ["reply"] = true },
    },
    [655854761] = {
        ["english"] = { [1] = "I welcome you, $N. And the Emerald Circle welcomes you.$B$BHopefully together we can help rejuventate and protect this once-mighty forest. Many forces seek to destroy it from without... and within.$B$BDo not be persuaded by the power here--it will only corrupt you, like it has this entire land." },
        ["text"] = "Вітаю вас, $N. І Смарагдове Коло вітає вас.$B$BСподіваюся, разом ми зможемо відродити й захистити цей колись могутній ліс. Багато сил прагнуть знищити його ззовні... і зсередини.$B$BНе піддавайтеся силі цього місця — вона лише осквернить вас, як уже осквернила всю цю землю.",
        ["npcs"] = { [1] = 10922 },
        ["roles"] = { ["greeting"] = true },
    },
    [910869851] = {
        ["english"] = { [1] = "I watched as they beat him without mercy. Their ruthless lieutenant acted as if such cruelty was an act of normalcy. Through the savage beatings, I could feel myself breaking.$B$BAs I watched Vindicator Saruan take their blows, I began to weep. Not out of fear... I wept out of sadness. To see a draenei of the Triumvirate treated in such a manner. If only I could have broken free of my bonds. If only...$B" },
        ["text"] = "Я дивився, як вони безжально його били. Їхній жорстокий лейтенант поводився так, наче така жорстокість була звичайною справою. Від тих лютих побоїв я відчував, як щось у мені ламається.$B$BДивлячись, як оборонець Саруан приймає їхні удари, я почав плакати. Не від страху... від смутку. Бачити, як так поводяться з дренеєм Тріумвірату... Якби ж я лише міг вирватися з пут. Якби ж...$B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1385142936] = {
        ["english"] = { [1] = "I think I hear him coming!  Look to the west!" },
        ["text"] = "Здається, я чую, як він наближається!  Дивіться на захід!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3382175379] = {
        ["english"] = { [1] = "I was standing right next to you, imbecile. I know what you seek." },
        ["text"] = "Я стояв просто поруч із тобою, йолопе. Я знаю, що ти шукаєш.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3175981117] = {
        ["english"] = { [1] = "In a word, magic.$b$bIrresponsible mortals with their brief lifespans think nothing of the lasting effects of their actions.$b$bArcane energies have been tapped too liberally, disrupting the world's balance. If this is allowed to continue, Azeroth will soon be annihilated.$b$bOn this, both sides agree. But before a council could even be appointed, Malygos put his own plan into action.$b$bWe had no choice but to confront him." },
        ["text"] = "Одним словом — магія.$b$bБезвідповідальні смертні зі своїм коротким життям анітрохи не думають про довготривалі наслідки власних дій.$b$bАрканічною енергією користувалися надто щедро, порушуючи рівновагу світу. Якщо так триватиме, Азерот незабаром буде знищено.$b$bУ цьому обидві сторони погоджуються. Але ще до того, як вдалося створити раду, Маліґос уже почав здійснювати власний план.$b$bУ нас не було вибору, крім як виступити проти нього.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [833103449] = {
        ["english"] = { [1] = "I received an update on that just a moment ago. It looks like out of $2061w light leather needed, we have $2060w. As for the others, the report indicated that we've gathered $2063w of $2064w medium leather, and $2069w out of our $2071w thick leather quota." },
        ["text"] = "Щойно отримав свіжі дані. Із потрібних $2061w легкої шкіри маємо $2060w. Щодо решти, у звіті сказано, що ми зібрали $2063w із $2064w середньої шкіри та $2069w із нашої квоти $2071w щільної шкіри.",
        ["npcs"] = { [1] = 15701 },
        ["roles"] = { ["greeting"] = true },
    },
    [3619910946] = {
        ["english"] = { [1] = "I will teach you... soon. I require a demonstration of your loyalty, first." },
        ["text"] = "Я навчу вас... скоро. Спершу мені потрібен доказ вашої відданості.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4087483327] = {
        ["english"] = { [1] = "I seek a $g hero : heroine; of the utmost skill.  $G He : She; will gather others to save the Bloodmaul clan, and all of the ogres of these mountains from the tyranny of our gronn oppressors.$B$BReturn to me when you have learned all that you can.  But, $c, keep quiet about this until that time lest the gronn get wind of our underground movement." },
        ["text"] = "Я шукаю $g героя : героїню; найвищої майстерності.  $G Він : Вона; збере інших, щоб урятувати клан Кривавого Молота й усіх огрів цих гір від тиранії наших поневолювачів-ґроннів.$B$BПоверніться до мене, коли вивчите все, що зможете.  Але, $c, до того часу мовчіть, щоб ґронни не довідалися про наш підпільний рух.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3749337839] = {
        ["english"] = { [1] = "Ishnu-alah, $gbrother:sister;. Have you any tidings from abroad? My heart yearns for news of Teldrassil." },
        ["text"] = "Ішну-ала, $gбрате:сестро;. Є якісь новини з далеких земель? Моє серце прагне звісток про Тельдрассіль.",
        ["npcs"] = { [1] = 3603, [2] = 5500 },
        ["roles"] = { ["greeting"] = true },
    },
    [2045173290] = {
        ["english"] = { [1] = "I'm sorry $N, but you've already learned all I know about cooking.  Of course, you never know when our cooks will whip up something new, so don't be shy and be sure to visit again some time." },
        ["text"] = "Вибачте, $N, але ви вже знаєте все, що я можу навчити про кулінарію.  Хоча ніколи не знаєш, коли наші кухарі вигадають щось нове, тож не соромтеся й навідайтеся знову якось.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [690477817] = {
        ["english"] = { [1] = "I can sense your desire for power, $c." },
        ["text"] = "Я відчуваю вашу жагу до сили, $c.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1543416612] = {
        ["english"] = { [1] = "I want to exchange my Amber Essence for Emerald Essence." },
        ["text"] = "Я хочу обміняти бурштинову сутність на смарагдову.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [4161509658] = {
        ["english"] = { [1] = "If the demons fell, where did they fall from?" },
        ["text"] = "Якщо демони впали, то звідки вони падали?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1839555565] = {
        ["english"] = { [1] = "I shall." },
        ["text"] = "Так і буде.",
        ["npcs"] = { [1] = 7572 },
        ["roles"] = { ["reply"] = true },
    },
    [2360350388] = {
        ["english"] = { [1] = "If you require time to rest and regain your strength, you will find the best at the Inn in Dolanaar.  Innkeeper Keldamyr will see to it that you are taken care of." },
        ["text"] = "Якщо вам треба відпочити й відновити сили, найкраще місце — заїзд у Доланаарі.  Корчмар Келдамір подбає про вас.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [2571033147] = {
        ["english"] = { [1] = "It is good to see you again, $N." },
        ["text"] = "Радий знову вас бачити, $N.",
        ["npcs"] = { [1] = 6766 },
        ["roles"] = { ["greeting"] = true },
    },
    [1282946227] = {
        ["english"] = { [1] = "I'm so happy that Jubjub returned!  I only hope that I don't run out of Dark Iron ale soon, or I fear my pet frog might once again escape!" },
        ["text"] = "Я такий радий, що Джубджуб повернулася!  Сподіваюся лише, що ель Темного Заліза не скінчиться найближчим часом, інакше моя жабка знову може втекти!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [218253863] = {
        ["english"] = { [1] = "If you're looking for a flight back to Thunder Bluff, then you should talk to my tauren counterpart, Bunthen Plainswind." },
        ["text"] = "Якщо шукаєте переліт назад до Громового Бескиду, поговоріть із моїм колегою-тауреном Бунтеном Вітром Рівнин.",
        ["npcs"] = { [1] = 11800 },
        ["roles"] = { ["greeting"] = true },
    },
    [2611193878] = {
        ["english"] = { [1] = "I think you should go, $g mister:miss;. You're scaring Mr. Floppy." },
        ["text"] = "Гадаю, вам краще піти, $g пане:панно;. Ви лякаєте пана Пухнастика.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [691915141] = {
        ["english"] = { [1] = "It is our duty to protect these taunka and provide them with what little comfort we can offer." },
        ["text"] = "Наш обов'язок — захищати цих таунка й дати їм бодай трохи затишку, який можемо запропонувати.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2062176584] = {
        ["english"] = { [1] = "I'm not amused by your audacity in coming to me for training. Go through the archway and down the ramp to the southeast, and talk to Doctor Martin Felben. He is a Forsaken who can teach you the basics." },
        ["text"] = "Мене не тішить ваша зухвалість — приходити до мене по навчання. Пройдіть крізь арку, спустіться пандусом на південний схід і поговоріть із доктором Мартіном Фелбеном. Він Відречений і навчить вас основ.",
        ["npcs"] = { [1] = 4609 },
        ["roles"] = { ["greeting"] = true },
    },
    [1378596732] = {
        ["english"] = { [1] = "I had the pleasure of seeing Kyra Windblade in combat once.  Considering what I witnessed, I am confident she will train you well.  Look for her at the Inn in Dolanaar." },
        ["text"] = "Мені якось довелося бачити Кіру Вітролезу в бою.  Після побаченого я певен, що вона добре вас навчить.  Шукайте її в заїзді Доланаара.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [1564063564] = {
        ["english"] = { [1] = "I only teach students who have already mastered the basics. You must seek out the night elf Darianna in the Craftsmen's Terrace of Darnassus. Her skills will be a perfect complement to yours." },
        ["text"] = "Я навчаю лише тих, хто вже опанував основи. Вам треба знайти нічну ельфійку Даріанну на Терасі Ремісників у Дарнасі. Її вміння чудово доповнять ваші.",
        ["npcs"] = { [1] = 3967 },
        ["roles"] = { ["greeting"] = true },
    },
    [1763892293] = {
        ["english"] = { [1] = "I bid you welcome, $c." },
        ["text"] = "Вітаю вас, $c.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [772804103] = {
        ["english"] = { [1] = "I think Plugger filled one of his kegs too much.  It looks like it's about to blow!" },
        ["text"] = "Здається, Плаґґер переповнив одне зі своїх барилець.  Воно ось-ось вибухне!",
        ["npcs"] = { [1] = 9554, [2] = 10043 },
        ["roles"] = { ["greeting"] = true },
    },
    [296959399] = {
        ["english"] = { [1] = "I was the last to die. As I felt my spirit leaving my mortal shell, I swore a blood oath.$B$B<Prince Toreth shakes his head.>$B$BA pact was made between this land and I: My blood for this world. I became the sole keeper of the history of my people.$B$BI cannot rest until I am secure in knowing that the story of the dragon riders of Loreth'Aran is not lost in the passages of time.\013\010" },
        ["text"] = "Я помер останнім. Відчуваючи, як дух залишає смертну оболонку, я склав криваву присягу.$B$B<Принц Торет хитає головою.>$B$BМіж цією землею і мною було укладено угоду: моя кров — за цей світ. Я став єдиним хранителем історії свого народу.$B$BЯ не зможу спочити, доки не буду певен, що історія драконовершників Лорет'Арана не загубиться в плині часу.\013\010",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2177942339] = {
        ["english"] = { [1] = "I will take you up on that offer, Eitrigg." },
        ["text"] = "Я прийму вашу пропозицію, Айтріґу.",
        ["npcs"] = { [1] = 3144 },
        ["roles"] = { ["reply"] = true },
    },
    [688054347] = {
        ["english"] = { [1] = "I'm glad that you're here to help, $c. The faster we can deal with these trolls, the faster we'll get to send the scourge back to where they came from." },
        ["text"] = "Радий, що ви прийшли допомогти, $c. Чим швидше розберемося з цими тролями, тим швидше відправимо Скару туди, звідки вона прийшла.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2772977452] = {
        ["english"] = { [1] = "I'm a prisoner!$B$BThey shot me and my beautiful zeppelin out of the sky. And what for? Because I was ferrying men and materiel for the Horde? That's nothing new!$B$BNow they have me running her in circles around the bay so that they can bomb the pirates. I just don't have the parts to keep her going like this! I'm barely keeping her together on spit and bailing wire!$B$BI won't be held responsible for what happens to you, but you might as well get on board before she leaves.$B$BIt's a crime I tell you!" },
        ["text"] = "Я в'язень!$B$BВони збили мене й мій прекрасний дирижабль із неба. І за що? За те, що я перевозив людей і вантажі для Орди? Та це не новина!$B$BТепер вони змушують мене кружляти над затокою, щоб могли бомбити піратів. У мене просто немає деталей, щоб підтримувати його в такому стані! Він ледве тримається на слині й дроті!$B$BЯ не відповідатиму за те, що з вами станеться, але можете вже сідати на борт, поки він не вирушив.$B$BЦе злочин, кажу вам!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [756824501] = {
        ["english"] = { [1] = "I'm a simple man who knows a few things about tailoring, but you need more assistance than I can provide. I have heard of a Night Elf who is quite an accomplished tailor. He resides in Stormwind, in the Magic District." },
        ["text"] = "Я простий чоловік і дещо знаю про кравецтво, але вам потрібно більше допомоги, ніж я можу дати. Чув про одного нічного ельфа, дуже вправного кравця. Він живе у Штормовії, в Магічному кварталі.",
        ["npcs"] = { [1] = 1103 },
        ["roles"] = { ["greeting"] = true },
    },
    [3172668669] = {
        ["english"] = { [1] = "I cause you no trouble, boss." },
        ["text"] = "Я вам не заважаю, босе.",
        ["npcs"] = { [1] = 11441, [2] = 11444, [3] = 11445, [4] = 11448, [5] = 11450, [6] = 14325, [7] = 14351 },
        ["roles"] = { ["greeting"] = true },
    },
    [3252370817] = {
        ["english"] = { [1] = "I suppose you are here to be trained in the use of a new weapon?  Make it fast, I'm very busy!" },
        ["text"] = "Гадаю, ви прийшли навчитися користуватися новою зброєю?  Швидше, я дуже зайнятий!",
        ["npcs"] = { [1] = 11870 },
        ["roles"] = { ["greeting"] = true },
    },
    [3488158802] = {
        ["english"] = { [1] = "I think they have her down near the gallows." },
        ["text"] = "Гадаю, її тримають унизу біля шибениці.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2167678587] = {
        ["english"] = { [1] = "I think you be lost, mon...." },
        ["text"] = "Схоже, ти заблукав, друже...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2536807649] = {
        ["english"] = { [1] = "I su... sur... surpose that yar wanna ride back to der outpost. Yarp?" },
        ["text"] = "Я га... га... гадаю, ви хочете повернутися верхи до застави. Ага?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1444392995] = {
        ["english"] = { [1] = "I spend all day retrieving parts for the zeppelin and Frezza doesn't even have the decency to pay me an hourly wage. But you're not here about that, are you? I bet you want to know where the zeppelin is located. Well, you're in luck - I have my zeppelin tracking device right here!" },
        ["text"] = "Я цілими днями шукаю деталі для дирижабля, а Фрезза навіть не має порядності платити мені погодинно. Але ви ж не по це прийшли, правда? Закладаюся, хочете знати, де дирижабль. Вам пощастило — мій пристрій відстеження дирижабля просто тут!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3656075697] = {
        ["english"] = { [1] = "I slay the man on the spot as my liege would expect me to do, as he is nothing more than a thief and a liar." },
        ["text"] = "Я вбиваю чоловіка на місці, як і очікував би мій сюзерен, бо він не більш ніж злодій і брехун.",
        ["npcs"] = { [1] = 14822 },
        ["roles"] = { ["reply"] = true },
    },
    [4224842108] = {
        ["english"] = { [1] = "I quietly ignore the insult.  I will not tell my liege, as I am to secure peace at all costs.  It's only an insult - not a declaration of war." },
        ["text"] = "Я мовчки ігнорую образу.  Я не скажу про неї сюзерену, бо маю за будь-яку ціну забезпечити мир.  Це лише образа — не оголошення війни.",
        ["npcs"] = { [1] = 14822 },
        ["roles"] = { ["reply"] = true },
    },
    [77334206] = {
        ["english"] = { [1] = "I should kill you where you stand, $r!$B$BGet on with your inane prattling and then begone!" },
        ["text"] = "Мені слід убити вас на місці, $r!$B$BЗакінчуйте своє безглузде базікання й забирайтеся!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3434825733] = {
        ["english"] = { [1] = "I should be able to get out here now. Thanks!" },
        ["text"] = "Тепер я вже зможу звідси вибратися. Дякую!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [762232090] = {
        ["english"] = { [1] = "I do not deserve such praise, Warlord Goretooth." },
        ["text"] = "Я не заслуговую такої похвали, воєводо Кривавий Зуб.",
        ["npcs"] = { [1] = 9077 },
        ["roles"] = { ["reply"] = true },
    },
    [789255659] = {
