    [1876793661] = {
        ["english"] = { [1] = "I have duty in an hour, but until then... bottom's up!" },
        ["text"] = "За годину мені на чергування, а доти... до дна!",
        ["npcs"] = { [1] = 9547 },
        ["roles"] = { ["greeting"] = true },
    },
    [4216361926] = {
        ["english"] = { [1] = "I have lost my Band of Vaulted Secrets. Are you able to replace it for me?" },
        ["text"] = "Я загубив свій Перстень прихованих таємниць. Можете замінити його?",
        ["npcs"] = { [1] = 15498 },
        ["roles"] = { ["reply"] = true },
    },
    [3331350305] = {
        ["english"] = { [1] = "I don't get too many cooks in here looking for training, but I guess I could teach you something if you're ready." },
        ["text"] = "Не так уже й багато кухарів приходять сюди вчитися, але, гадаю, я можу вас дечого навчити, якщо готові.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4293660831] = {
        ["english"] = { [1] = "I need a second head like I need to lose my first one." },
        ["text"] = "Друга голова мені потрібна так само, як втратити першу.",
        ["npcs"] = { [1] = 14827 },
        ["roles"] = { ["greeting"] = true },
    },
    [2523424284] = {
        ["english"] = { [1] = "I sense a disturbance, lurking around you..." },
        ["text"] = "Я відчуваю тривожну присутність, що причаїлася навколо вас...",
        ["npcs"] = { [1] = 10433 },
        ["roles"] = { ["greeting"] = true },
    },
    [3580640063] = {
        ["english"] = { [1] = "I'll tell you 'then what.' She went runnin' straight for the hive. And you know what's crazier? Not a single damned bug got in her way or tried to stop her. She ran through them all as if she'd been best friends with 'em for centuries." },
        ["text"] = "Я скажу вам, «і що далі». Вона побігла просто до вулика. І знаєте, що ще божевільніше? Жодна клята комаха не стала їй на дорозі й не спробувала зупинити. Вона пробігла крізь них усіх так, ніби дружила з ними століттями.",
        ["npcs"] = { [1] = 15171 },
        ["roles"] = { ["greeting"] = true },
    },
    [3548699958] = {
        ["english"] = { [1] = "I can instruct you in enchanting.  Interested?" },
        ["text"] = "Я можу навчити вас зачарування.  Цікавить?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [406661660] = {
        ["english"] = { [1] = "I seek training as a druid." },
        ["text"] = "Я шукаю навчання друїда.",
        ["npcs"] = { [1] = 3033, [2] = 3034, [3] = 3036, [4] = 3060, [5] = 3064, [6] = 3597, [7] = 3602, [8] = 4218, [9] = 4219, [10] = 5504, [11] = 5505, [12] = 5506, [13] = 8142, [14] = 12042 },
        ["roles"] = { ["reply"] = true },
    },
    [3199829339] = {
        ["english"] = { [1] = "I thank you, $N. Your dedication to my plea gives rest to my lost wife's spirit, and for that I could never repay you enough.$B$BI cannot say that my hatred will ever cease for the quilboar, but it is satiated for now.$B$BNow I must begin to rebuild my life." },
        ["text"] = "Дякую, $N. Ваша відданість моєму проханню дала спокій духові моєї загиблої дружини, і за це я ніколи не зможу віддячити сповна.$B$BНе скажу, що моя ненависть до голкобразів колись мине, але поки що вона втамована.$B$BТепер мені треба починати життя наново.",
        ["npcs"] = { [1] = 3432 },
        ["roles"] = { ["greeting"] = true },
    },
    [445072443] = {
        ["english"] = { [1] = "I need a few good wing men to get me out of here safely and back to base." },
        ["text"] = "Мені потрібна пара добрих ведених, щоб безпечно вибратися звідси й повернутися на базу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3808875460] = {
        ["english"] = { [1] = "I would like to train." },
        ["text"] = "Я хочу навчатися.",
        ["npcs"] = { [1] = 1681, [2] = 2122, [3] = 2130, [4] = 7866 },
        ["roles"] = { ["reply"] = true },
    },
    [106524783] = {
        ["english"] = { [1] = "I cannot aid you with further lessons: your skills have surpassed mine. Go and see the tauren Una in the northwestern shops of Thunder Bluff's central plateau. She offers more advanced training." },
        ["text"] = "Я більше не можу вас навчати: ваша майстерність перевершила мою. Знайдіть тауренку Уну в крамницях на північному заході центрального плато Громового Бескиду. Вона навчає складніших прийомів.",
        ["npcs"] = { [1] = 3703 },
        ["roles"] = { ["greeting"] = true },
    },
    [1037879902] = {
        ["english"] = { [1] = "I require training, Lumak." },
        ["text"] = "Мені потрібне навчання, Лумаку.",
        ["npcs"] = { [1] = 3332 },
        ["roles"] = { ["reply"] = true },
    },
    [1502440123] = {
        ["english"] = { [1] = "I guess someone needs to bandage us warriors up after the fighting.  Seek out Arnok at the Survival of the Fittest hut next to the Spirit Lodge in the Valley of Spirits.  Look up above and to the west of the Valley of Strength for a lake.  That's where he's at." },
        ["text"] = "Гадаю, після боїв хтось же має перев'язувати нас, воїнів.  Знайдіть Арнока в хатині «Виживання найсильніших» біля Обителі Духів у Долині Духів.  Вище й на захід від Долини Сили є озеро.  Він там.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [4032264718] = {
        ["english"] = { [1] = "I require training, Grimnur." },
        ["text"] = "Мені потрібне навчання, Ґрімнуре.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3757095297] = {
        ["english"] = { [1] = "If our enemies would see that we only wish to live in harmony with them, maybe we wouldn't have to attack them for our own survival?" },
        ["text"] = "Якби наші вороги зрозуміли, що ми лише хочемо жити з ними в злагоді, можливо, нам не довелося б нападати на них заради власного виживання?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1592604407] = {
        ["english"] = { [1] = "I represent the strength which bolsters you as a young druid.  You have come to me to learn this strength, young one, and I will teach this to you.  I will teach you all that is the spirit bear, provided you will listen and understand.$B$BIn order to know what it means to draw upon my spirit, you need to understand the importance of the strength of the body, as well as the strength of the heart." },
        ["text"] = "Я уособлюю силу, що підтримує вас як молодого друїда.  Ви прийшли до мене навчитися цієї сили, юний друже, і я вас навчу.  Я навчу всього, що є духом ведмедя, якщо будете слухати й розуміти.$B$BЩоб збагнути, що означає черпати силу з мого духу, ви маєте зрозуміти важливість сили тіла й сили серця.",
        ["npcs"] = { [1] = 11956 },
        ["roles"] = { ["greeting"] = true },
    },
    [3595545174] = {
        ["english"] = { [1] = "I remember when my brother and I would camp alone in the Azshara wilderness. Look at it now. " },
        ["text"] = "Пам'ятаю, як ми з братом удвох таборували в нетрях Азшари. Погляньте на неї тепер. ",
        ["npcs"] = { [1] = 8586 },
        ["roles"] = { ["greeting"] = true },
    },
    [2231840151] = {
        ["english"] = { [1] = "I don't be worryin' 'bout no Lich Kings. Seen a lotta big-shots come and go, dey always messin' somethin' up. It ain't long aftah that when a posse rolls on through and sends dem quick on dey way to da history books. Dis one ain't no different." },
        ["text"] = "Я не переймаюся ніякими там Королями-лічами. Бачив я чимало великих цяцьок — приходять, ідуть, завжди щось псують. А невдовзі приходить ватага й хутко відправляє їх на сторінки історії. Цей нічим не кращий.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1508027172] = {
        ["english"] = { [1] = "I reckon that the odds of obtaining such a piece would be a one in a million! A once in a lifetime skin! Even the most disciplined artisans of the craft would no doubt fail several hundred times in the process of skinning the beast before a pristine sample was recovered.\010" },
        ["text"] = "Гадаю, шанс здобути такий шматок — один на мільйон! Шкура, що трапляється раз у житті! Навіть найвправніший майстер ремесла, без сумніву, кількасот разів зазнав би невдачі, знімаючи шкуру зі звіра, перш ніж отримав би бездоганний зразок.\010",
        ["npcs"] = { [1] = 10637 },
        ["roles"] = { ["greeting"] = true },
    },
    [3155609153] = {
        ["english"] = { [1] = "I show you how smart I am, boss!  You be extra smart with mighty magic mojo now!$B$BUm... maybe Slip'kik use magic on self. Dat would be good idea..." },
        ["text"] = "Я покажу, який я розумний, босе!  Тепер ви будете дуже розумні з могутнім магічним моджо!$B$BЕм... може, Сліп'кік застосує магію на собі. Це була б добра думка...",
        ["npcs"] = { [1] = 14323 },
        ["roles"] = { ["greeting"] = true },
    },
    [1964895257] = {
        ["english"] = { [1] = "I have enough supplies to upgrade our troops to veterans." },
        ["text"] = "У мене досить припасів, щоб підвищити наші війська до ветеранів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [85594940] = {
        ["english"] = { [1] = "I honor my ancestors in the time-honored shamanistic tradition.  We must never forget the sacrifices that they have made so that we can be here.$B$BAnd we, in turn, must make the necessary sacrifices so that our descendants will have a future.$B$BWhat brings you to me, $c?" },
        ["text"] = "Я вшановую предків за прадавньою шаманською традицією.  Ми ніколи не повинні забувати про жертви, які вони принесли, щоб ми могли жити.$B$BІ ми, своєю чергою, маємо принести необхідні жертви, щоб у наших нащадків було майбутнє.$B$BЩо привело вас до мене, $c?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3464863079] = {
        ["english"] = { [1] = "I feel sick." },
        ["text"] = "Мені зле.",
        ["npcs"] = { [1] = 11216 },
        ["roles"] = { ["reply"] = true },
    },
    [1988827530] = {
        ["english"] = { [1] = "I can't say enough about yer work, truly amazing things that ye can do with a hammer and an anvil. Now, don't be tellin anyone that I suggested ye go find a goblin to teach ye but that's exactly what I'm gonna do. Brikk Keencraft is his name, and last I heard he was operating a shop down in Booty bay." },
        ["text"] = "Про вашу роботу й слів не вистачить — те, що ви робите молотом і ковадлом, просто неймовірне. Тільки нікому не кажіть, що це я порадив вам шукати гобліна-наставника, але саме це я й зроблю. Його звати Брікк Гостромайстер, і востаннє я чув, що він тримав крамницю в Бухті Наживи.",
        ["npcs"] = { [1] = 4258 },
        ["roles"] = { ["greeting"] = true },
    },
    [3058859956] = {
        ["english"] = { [1] = "I do what me can to train you in the priestly ways, if that what you be here for." },
        ["text"] = "Я роблю все, що можу, щоб навчити вас шляху жерця, якщо саме по це ви прийшли.",
        ["npcs"] = { [1] = 3706, [2] = 3707, [3] = 5994, [4] = 6014, [5] = 6018 },
        ["roles"] = { ["greeting"] = true },
    },
    [2212212881] = {
        ["english"] = { [1] = "It takes a bit of practice to be this close to the silithid and go unnoticed.  I don't recommend trying it if you can avoid it.  " },
        ["text"] = "Треба трохи практики, щоб бути так близько до силітидів і лишатися непоміченим.  Не раджу пробувати, якщо можете цього уникнути.  ",
        ["npcs"] = { [1] = 15610 },
        ["roles"] = { ["greeting"] = true },
    },
    [2466048849] = {
        ["english"] = { [1] = "I require a teleport to Naxxramas." },
        ["text"] = "Мені потрібна телепортація до Наксрамаса.",
        ["npcs"] = { [1] = 16999 },
        ["roles"] = { ["reply"] = true },
    },
    [537326593] = {
        ["english"] = { [1] = "I hold the vessel of his rebirth. Should you be prepared to take on this task, you will be required to fortify the vessel and ultimately, break the hold of Ragnaros himself!" },
        ["text"] = "Я зберігаю посудину його відродження. Якщо ви готові взятися за це завдання, вам доведеться зміцнити посудину й зрештою розірвати владу самого Раґнароса!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2131770302] = {
        ["english"] = { [1] = "If you have something to say, say it!" },
        ["text"] = "Якщо маєте що сказати — кажіть!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4153365829] = {
        ["english"] = { [1] = "I just received word on that. We currently have $2021w out of $2020w peacebloom, $2050w of $2051w firebloom, and $2054w out of $2055w purple lotus herbs requested." },
        ["text"] = "Щойно отримав нові дані. Наразі в нас $2021w з $2020w мироцвіту, $2050w з $2051w вогнецвіту та $2054w з потрібних $2055w трав пурпурового лотоса.",
        ["npcs"] = { [1] = 15700 },
        ["roles"] = { ["greeting"] = true },
    },
    [3862298400] = {
        ["english"] = { [1] = "I never understood why some pirates bury their treasure.  Me... I like to keep it within arm's reach." },
        ["text"] = "Я ніколи не розумів, навіщо деякі пірати закопують скарби.  Я волію тримати свої на відстані простягнутої руки.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4062396059] = {
        ["english"] = { [1] = "I never thought we'd escape from that steamy jungle! Now I'm the lead engineer of this expedition. " },
        ["text"] = "Я й гадки не мав, що ми виберемося з тих задушливих джунглів! Тепер я головний інженер цієї експедиції. ",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1094916840] = {
        ["english"] = { [1] = "I perform one final service. I pray it is sufficient..." },
        ["text"] = "Я виконаю останню службу. Молюся, щоб цього вистачило...",
        ["npcs"] = { [1] = 13020 },
        ["roles"] = { ["greeting"] = true },
    },
    [3381058930] = {
        ["english"] = { [1] = "It's good to see you here, $N." },
        ["text"] = "Добре бачити вас тут, $N.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3400002845] = {
        ["english"] = { [1] = "If you seek training in weapons, I can provide." },
        ["text"] = "Якщо шукаєте навчання зброї, я можу його надати.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [91932861] = {
        ["english"] = { [1] = "I have all manner of goods for sale, $c.  Browse at your leisure." },
        ["text"] = "Я продаю всілякі товари, $c.  Дивіться досхочу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [859028389] = {
        ["english"] = { [1] = "I would speak for my brother joining the order, potentially risking the safety of the order.  I could help him with the order's regimens, and I'd have faith in his ability to adapt and learn." },
        ["text"] = "Я підтримав би вступ брата до ордену, потенційно ризикуючи безпекою ордену.  Я міг би допомогти йому з розпорядком ордену й повірив би в його здатність пристосуватися та навчитися.",
        ["npcs"] = { [1] = 14822 },
        ["roles"] = { ["reply"] = true },
    },
    [2035647185] = {
        ["english"] = { [1] = "I have outfitted kings. With the proper training, you can too." },
        ["text"] = "Я споряджав королів. Після належного навчання й ви зможете.",
        ["npcs"] = { [1] = 11052 },
        ["roles"] = { ["greeting"] = true },
    },
    [1983610245] = {
        ["english"] = { [1] = "I have ventured to dark places and learned the tailoring recipe for the Deathchill Cloak.$B$BThis cloak is a tradeable Epic cloak for spellcasters that grants Spellpower, Haste and Critical Strike.   I am looking for someone worthy to teach this recipe to.$B$BSomeone who had completed most of the quests across Northrend and had the \"Loremaster of Northrend\" achievement would be worthy of learning the recipe for the Deathchill Cloak." },
        ["text"] = "Я побував у темних місцях і вивчив кравецький рецепт Плаща смертельного холоду.$B$BЦе епічний плащ для заклиначів, яким можна торгувати; він надає силу заклять, швидкість і критичний удар.   Я шукаю когось гідного, кому можна передати цей рецепт.$B$BТой, хто виконав більшість завдань у Нортренді й здобув досягнення «Хранитель мудрості Нортренду», був би гідний вивчити рецепт Плаща смертельного холоду.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2622533645] = {
        ["english"] = { [1] = "I don't have time to talk right now." },
        ["text"] = "Зараз у мене немає часу розмовляти.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [854401364] = {
        ["english"] = { [1] = "I see you checking out our legally obtained racing rams...  I can see you want in on the ram racing sensation...  But before you can play, you gotta work.$b$bWell, work and play are pretty much the same when it comes to these rams." },
        ["text"] = "Бачу, ви задивляєтеся на наших цілком законно придбаних гоночних баранів...  І бачу, що хочете долучитися до цієї шаленої баранячої гонитви...  Але перш ніж гратися, треба попрацювати.$b$bХоча з цими баранами робота й розвага — майже те саме.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1761444315] = {
        ["english"] = { [1] = "I don't train your kind $c." },
        ["text"] = "Я не навчаю таких, як ви, $c.",
        ["npcs"] = { [1] = 3155, [2] = 3170, [3] = 3327, [4] = 3328, [5] = 3401, [6] = 3599, [7] = 4163, [8] = 4214, [9] = 4215 },
        ["roles"] = { ["greeting"] = true },
    },
    [1416315809] = {
        ["english"] = { [1] = "I must obey." },
        ["text"] = "Я мушу підкорятися.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3363933920] = {
        ["english"] = { [1] = "I have just completed a new dimensional imploder that will make me rich beyond my wildest goblin dreams!   All I need to do is get a skilled Goblin Engineer to build a dimensional ripper that connects to it and try it! \010" },
        ["text"] = "Я щойно завершив новий просторовий імплодер, що зробить мене багатшим за найсміливіші гоблінські мрії!   Треба лише знайти вправного гобліна-інженера, який збудує просторовий роздирач, з'єднає його з імплодером, — і випробувати все це! \010",
        ["npcs"] = { [1] = 14742 },
        ["roles"] = { ["greeting"] = true },
    },
    [3028524957] = {
        ["english"] = { [1] = "I'll be damned if these blasted Scourge are going to drive us away!  Us settlers gave everything up to start new lives in Northrend.$B$BYou'd better believe we're going to fight tooth and nail." },
        ["text"] = "Нехай мене проклянуть, якщо ця клята Скара вижене нас звідси!  Ми, поселенці, відмовилися від усього, щоб почати нове життя в Нортренді.$B$BІ можете не сумніватися — ми битимемося зубами й кігтями.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2216047992] = {
        ["english"] = { [1] = "I mean you no harm. I am scouting the quilboar and taking notes of their activities. My people have noticed something odd--an emanation or darkness--coming from this area. I've come to investigate, and what I've found is very disturbing.$B$BThere seems to be an undead diplomat who is powerful in the ways of the arcane. I don't believe he's one of the Forsaken... I think it's worse." },
        ["text"] = "Я не бажаю вам зла. Я розвідую голкобразів і занотовую їхні дії. Мій народ помітив тут щось дивне — випромінювання чи темряву, що йде з цієї місцевості. Я прийшов розслідувати, і те, що знайшов, дуже тривожить.$B$BСхоже, тут діє невмерлий дипломат, дуже вправний у таємній магії. Не думаю, що він із Відречених... Боюся, все значно гірше.",
        ["npcs"] = { [1] = 12866 },
        ["roles"] = { ["greeting"] = true },
    },
    [1116693421] = {
        ["english"] = { [1] = "I make no pretenses, maggot. The darkness such items hold could very well destroy the both of us. That is why the price is so high. If I'm going to die, it's going to be as a rich man.$B$BAnd I don't give an ounce of gnoll spit how you die, only that you do as I ask. Bring me what I require and we will both benefit - or die, but I've already explained this..." },
        ["text"] = "Я не прикидаюся, личинко. Темрява, яку несуть такі предмети, цілком може знищити нас обох. Саме тому ціна така висока. Якщо мені судилося померти, я помру багатієм.$B$BІ мені байдуже на ґнолячу слину, як помрете ви — головне, щоб зробили те, що я прошу. Принесіть потрібне, і ми обидва матимемо зиск — або помремо, але це я вже пояснив...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [718781238] = {
        ["english"] = { [1] = "I don't want to go back to work" },
        ["text"] = "Я не хочу повертатися до роботи",
        ["npcs"] = { [1] = 10578 },
        ["roles"] = { ["reply"] = true },
    },
    [1229311435] = {
        ["english"] = { [1] = "I cannot help you with further training: your skill at working with leather rivals my own. You should speak with Una, over there. I will vouch for your skill if need be." },
        ["text"] = "Я більше не можу вас навчати: ваше вміння працювати зі шкірою не поступається моєму. Поговоріть з Уною, он вона. Якщо треба, я підтверджу вашу майстерність.",
        ["npcs"] = { [1] = 11084 },
        ["roles"] = { ["greeting"] = true },
    },
    [3436406213] = {
        ["english"] = { [1] = "I have lost my Ring of Unspoken Names. Are you able to replace it for me?" },
        ["text"] = "Я загубив свій Перстень невимовлених імен. Можете замінити його?",
        ["npcs"] = { [1] = 15498 },
        ["roles"] = { ["reply"] = true },
    },
    [3685220376] = {
        ["english"] = { [1] = "I guarantee this bank's security with my own blood, is that good enough for you?" },
        ["text"] = "Я власною кров'ю гарантую безпеку цього банку. Цього вам досить?",
        ["npcs"] = { [1] = 3309, [2] = 3318, [3] = 3320 },
        ["roles"] = { ["greeting"] = true },
    },
    [2898374692] = {
        ["english"] = { [1] = "I lost the Cache of Mau'ari. What can I do?" },
        ["text"] = "Я загубив Сховок Мау'арі. Що мені робити?",
        ["npcs"] = { [1] = 10307 },
        ["roles"] = { ["reply"] = true },
    },
    [3956547599] = {
        ["english"] = { [1] = "I need a ride." },
        ["text"] = "Мені потрібна поїздка.",
        ["npcs"] = { [1] = 352, [2] = 523, [3] = 1572, [4] = 1573, [5] = 2226, [6] = 2858, [7] = 2941, [8] = 2995, [9] = 3305, [10] = 3310, [11] = 3615, [12] = 3838, [13] = 3841, [14] = 4314, [15] = 4551, [16] = 10378, [17] = 12636 },
        ["roles"] = { ["reply"] = true },
    },
    [1294250271] = {
        ["english"] = { [1] = "I left. I would not remain with the Blackrock. No, the deaths of my children would not be in vain. I would not serve under an inept, power hungry maniac such as Rend.$B$BI took shelter in the woods of Lordaeron, living as a hermit near Hearthglen." },
        ["text"] = "Я пішов. Я не міг залишатися з Чорнокамінними. Ні, смерті моїх дітей не мали бути марними. Я не служив би під рукою такого бездарного, жадібного до влади божевільного, як Ренд.$B$BЯ знайшов прихисток у лісах Лордерону й жив самітником неподалік Вогнища.",
        ["npcs"] = { [1] = 3144 },
        ["roles"] = { ["greeting"] = true },
    },
    [2388764296] = {
        ["english"] = { [1] = "I got your back, Ichman. GO GO GO!" },
        ["text"] = "Я прикриваю тебе, Ічмане. ВПЕРЕД, ВПЕРЕД, ВПЕРЕД!",
        ["npcs"] = { [1] = 13437 },
        ["roles"] = { ["reply"] = true },
    },
    [3289961825] = {
        ["english"] = { [1] = "I not-so-quietly ignore the insult, hoping to instill a fear in the ruler that he may have gaffed.  I then inform my liege of the insult when I return." },
        ["text"] = "Я демонстративно ігнорую образу, сподіваючись вселити правителю страх, що він припустився помилки.  А повернувшись, повідомляю сюзерену про образу.",
        ["npcs"] = { [1] = 14822 },
        ["roles"] = { ["reply"] = true },
    },
    [4135074326] = {
        ["english"] = { [1] = "I hope this damned thing works. \"Araxes pounds on the portable trasnponder.\"" },
        ["text"] = "Сподіваюся, ця клята штука працює. «Араксес гупає по переносному транспондеру».",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3357471643] = {
        ["english"] = { [1] = "I wish I had more time to teach all who came before me, but alas that is not the way of things. Until you have learned all that Padaar has to teach, I cannot help you." },
        ["text"] = "Шкода, що я не маю більше часу навчати всіх, хто до мене приходить, але, на жаль, так не буває. Доки не вивчите все, чого може навчити Падаар, я вам не допоможу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1230733415] = {
        ["english"] = { [1] = "I need some reagents and poisons, lady." },
        ["text"] = "Мені потрібні реагенти й отрути, пані.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3772116051] = {
        ["english"] = { [1] = "Indeed. I stand before you in a form that you can comprehend, mortal. Surely, you could not bear to stand in the presence of the dragon known as Vaelastrasz.$B$B<Vaelan laughs.>$B$BShall I continue?" },
        ["text"] = "Саме так. Я стою перед вами у формі, яку ви здатні осягнути, смертний. Ви напевно не витримали б присутності дракона на ім'я Веластраз.$B$B<Вейлан сміється.>$B$BПродовжувати?",
        ["npcs"] = { [1] = 10296, [2] = 10299 },
        ["roles"] = { ["greeting"] = true },
    },
    [330700063] = {
        ["english"] = { [1] = "I call 'er the Spirit of Gnomeregan. Isn't she a beaut? Without your help, she'd've never been restored." },
        ["text"] = "Я називаю її «Духом Гномреґана». Хіба не красуня? Без вашої допомоги її ніколи б не відновили.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [120998363] = {
        ["english"] = { [1] = "I like to play in the water barrel but I'm told it's not for children." },
        ["text"] = "Я люблю гратися в бочці з водою, але мені кажуть, що вона не для дітей.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4250837048] = {
        ["english"] = { [1] = "I haven't time for idle chatter, $c. I must see to the pilgrims and ensure they are prepared for the long journey ahead." },
        ["text"] = "У мене немає часу на порожні балачки, $c. Я мушу доглянути паломників і переконатися, що вони готові до довгої дороги.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [190991002] = {
        ["english"] = { [1] = "It is time for you to journey to Darnassus and speak to Me'lynn. She will guide you from now on." },
        ["text"] = "Настав час вам вирушити до Дарнаса й поговорити з Ме'лінн. Відтепер вона вас наставлятиме.",
        ["npcs"] = { [1] = 4193 },
        ["roles"] = { ["greeting"] = true },
    },
    [3700506962] = {
        ["english"] = { [1] = "I don't suppose you're here to talk about my lovely Kali. Fine, then. Potions it is. Anyone ever tell ye you've got a one-track mind?" },
        ["text"] = "Не думаю, що ви прийшли поговорити про мою любу Калі. Гаразд. Тоді зілля. Вам ніхто не казав, що ви думаєте лише про одне?",
        ["npcs"] = { [1] = 1470 },
        ["roles"] = { ["greeting"] = true },
    },
    [4155191706] = {
        ["english"] = { [1] = "I'm getting ready to travel up the ridge, $N. I could use some help -- would you like to come with me?" },
        ["text"] = "Я готуюся вирушити вгору кряжем, $N. Мені не завадить допомога — підете зі мною?",
        ["npcs"] = { [1] = 10300 },
        ["roles"] = { ["greeting"] = true },
    },
    [3566749318] = {
        ["english"] = { [1] = "I have made contact, $N. It is Lokholar the Ice Lord. He has deemed our cause worthy - our earth bound sacrifice sufficient. He comes soon... prepare yourself." },
        ["text"] = "Я встановив зв'язок, $N. Це Локхолар Володар Криги. Він визнав нашу справу гідною, а нашу земну жертву — достатньою. Він скоро прийде... готуйтеся.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3332940113] = {
        ["english"] = { [1] = "I made a lot of the things you see in the store. What do you think? Answer carefully, your life may depend on it." },
        ["text"] = "Багато речей, які бачите в крамниці, зробив я. Ну як? Відповідайте обережно — від цього може залежати ваше життя.",
        ["npcs"] = { [1] = 2627, [2] = 3363 },
        ["roles"] = { ["greeting"] = true },
    },
    [1227547803] = {
        ["english"] = { [1] = "It is wise that you humble yourself before me $N in your desire for more warlock knowledge." },
        ["text"] = "Мудро з вашого боку смиренно стати переді мною, $N, прагнучи глибших знань чорнокнижника.",
        ["npcs"] = { [1] = 2126, [2] = 2127, [3] = 4564, [4] = 4565 },
        ["roles"] = { ["greeting"] = true },
    },
    [121263328] = {
        ["english"] = { [1] = "I guess your first exercise is going to be to mine your way down to the Undercity.  Heh, get it?  Mine... nevermind.  To get to the Undercity go to the rear of the Ruins of Lordaeron south of Brill, and take the elevator down.  Ask one of the Undercity Guardians there for further assistance." },
        ["text"] = "Гадаю, вашою першою вправою буде прокопати собі шлях до Підміста.  Хе-хе, зрозуміли? Прокопати... гаразд.  Щоб дістатися Підміста, вирушайте до задньої частини руїн Лордерону на південь від Брілля й спустіться ліфтом.  Там попросіть будь-якого вартового Підміста підказати дорогу.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [1144990682] = {
        ["english"] = { [1] = "I promise you this much: The Valley will be ours." },
        ["text"] = "Обіцяю вам одне: Долина буде нашою.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3370943970] = {
        ["english"] = { [1] = "I have enough supplies to upgrade our troops to champions." },
        ["text"] = "У мене досить припасів, щоб підвищити наші війська до чемпіонів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3236121352] = {
        ["english"] = { [1] = "I'm certain you will. Perhaps one day you could deliver a message to an old friend of mine. I hear he still wanders those woods.$B$B<Eitrigg bows his head for a moment, as if in prayer.>$B$BSo Rend, yes... Rend and his brother Maim ruled the Spire, in constant conflict with the Dark Iron dwarves. They managed to displace the dwarves in the upper portion of the city, but only after the dragons came and only after the death of Maim." },
        ["text"] = "Певен, так і буде. Можливо, колись ви передасте звістку моєму старому другові. Кажуть, він досі блукає тими лісами.$B$B<Айтріґ на мить схиляє голову, ніби в молитві.>$B$BОтже, Ренд... так, Ренд і його брат Мейм правили Шпилем, постійно воюючи з дворфами Темного Заліза. Їм вдалося витіснити дворфів із верхньої частини міста, але лише після появи драконів і смерті Мейма.",
        ["npcs"] = { [1] = 3144 },
        ["roles"] = { ["greeting"] = true },
    },
    [1852039181] = {
        ["english"] = { [1] = "I'm neither slim nor shady. As a matter of fact, I find both references insulting.$B$BNow, get out of my sight before I plant my staff up your backside." },
        ["text"] = "Я не худий і не підозрілий. Власне, обидва натяки мене ображають.$B$BА тепер геть із моїх очей, поки я не засунув вам посох туди, де сонце не світить.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1151494920] = {
        ["english"] = { [1] = "I can erase all your talents so that you may choose new ones.$b$bThis becomes more expensive each time you do it." },
        ["text"] = "Я можу скинути всі ваші таланти, щоб ви обрали нові.$b$bЩоразу це коштуватиме дорожче.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [474966634] = {
        ["english"] = { [1] = "I got something for you, $N. Looks important." },
        ["text"] = "У мене дещо є для вас, $N. Схоже на щось важливе.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2345298805] = {
        ["english"] = { [1] = "I get reports of your exploits against the Abyssal Council all the time, $N.  You're doing great things out there!$B$BKeep it up, and we'll make it worth the effort!" },
        ["text"] = "Я постійно отримую звіти про ваші подвиги проти Ради Безодні, $N.  Ви творите там великі справи!$B$BТак тримати, і ми щедро винагородимо ваші зусилля!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3431387505] = {
        ["english"] = { [1] = "I do not enjoy conversation." },
        ["text"] = "Я не люблю розмовляти.",
        ["npcs"] = { [1] = 9502 },
        ["roles"] = { ["greeting"] = true },
    },
    [3015357958] = {
        ["english"] = { [1] = "If tailoring is your thing, Vizzklick will most definitely have your supplies. Take a look around, $N, and let me know if you wish to purchase something!" },
        ["text"] = "Якщо ваше — кравецтво, у Віззкліка точно знайдуться потрібні припаси. Роздивляйтеся, $N, і скажіть, якщо захочете щось придбати!",
        ["npcs"] = { [1] = 6568 },
        ["roles"] = { ["greeting"] = true },
    },
    [3395417804] = {
        ["english"] = { [1] = "I do not have the knowledge you seek." },
        ["text"] = "Я не маю знань, яких ви шукаєте.",
        ["npcs"] = { [1] = 3038, [2] = 3040, [3] = 3061, [4] = 3065, [5] = 3171 },
        ["roles"] = { ["greeting"] = true },
    },
    [1515964629] = {
        ["english"] = { [1] = "I don't think that's going to happen, $G lad:lass;. I've lost a lot of blood... there's no way I'm making it back." },
        ["text"] = "Не думаю, що це станеться, $G хлопче:дівчино;. Я втратив надто багато крові... назад мені вже не дістатися.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2860801075] = {
        ["english"] = { [1] = "I have observed four different kinds of plants that have been affected by the corruption: the songflower, the windblossom, the whipper root, and the night dragon plant.  The songflower and windblossom are common plants in Felwood, while the whipper root and night dragon are seen less frequently.  All are a vital part of Felwood's ecosystem." },
        ["text"] = "Я спостерігав чотири різні види рослин, уражених скверною: піснеквіт, вітроквіт, батожний корінь і нічний дракон.  Піснеквіт і вітроквіт часто трапляються в Скверноліссі, тоді як батожний корінь і нічний дракон — рідше.  Усі вони є важливою частиною екосистеми Сквернолісся.",
        ["npcs"] = { [1] = 9528, [2] = 9529 },
        ["roles"] = { ["greeting"] = true },
    },
    [3334521012] = {
        ["english"] = { [1] = "I don't know, and that worries me. I'll do everything I can to find the Infinites. What I need you to do now is stay close to Arthas by joining his army." },
        ["text"] = "Не знаю, і це мене непокоїть. Я зроблю все, щоб знайти Нескінченних. А вам зараз треба триматися поруч з Артасом, приєднавшись до його війська.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3769568805] = {
        ["english"] = { [1] = "I can teach you the finer points of Raptor Riding, provided you have enough gold to cover the lesson!" },
        ["text"] = "Я можу навчити вас тонкощів верхової їзди на рапторах, якщо у вас вистачить золота на урок!",
        ["npcs"] = { [1] = 7953 },
        ["roles"] = { ["greeting"] = true },
    },
    [854499616] = {
        ["english"] = { [1] = "I need a moment of your time, sir." },
        ["text"] = "Мені потрібна хвилина вашого часу, пане.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3805163069] = {
        ["english"] = { [1] = "I wish you a happy holiday, friend!" },
        ["text"] = "Веселих свят, друже!",
        ["npcs"] = { [1] = 15760 },
        ["roles"] = { ["greeting"] = true },
    },
    [180309882] = {
        ["english"] = { [1] = "It is here that Gul`dan severed the tie between orcs and elemental spirits. His unquenchable thirst for power could not be satiated with the complete annihilation of the draenei. He had to also destroy Draenor, razing the land and siphoning all of its energies for use in his war.  Npw all that is left are remnants of his madness.   Look to the altar, night elf - the land is forever haunted......" },
        ["text"] = "Саме тут Ґул'дан розірвав зв'язок між орками й духами стихій. Його невтамовну жагу сили не могло задовольнити навіть повне знищення дренеїв. Він мусив ще й зруйнувати Дренор, спустошити землю й висмоктати всю її енергію для своєї війни.  Тепер лишилися лише рештки його безумства.   Поглянь на вівтар, нічний ельфе — ця земля навіки проклята......",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2157989851] = {
        ["english"] = { [1] = "I require training, Nissa." },
        ["text"] = "Мені потрібне навчання, Ніссо.",
        ["npcs"] = { [1] = 5150 },
        ["roles"] = { ["reply"] = true },
    },
    [1700864348] = {
        ["english"] = { [1] = "If you're heading toward the city, then I have something important for you to do!" },
        ["text"] = "Якщо прямуєте до міста, у мене є для вас важлива справа!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3913435347] = {
        ["english"] = { [1] = "In the Silverpine Forest along the edges of the North Tide's Run, a derelict boat rests on the shore.  Out to the west of this lies what you seek; swim too far and the ocean will crush you from fatigue.  It resides on the ocean floor in a lockbox, waiting for you to claim it.$B$BYou'll be hard pressed to survive a dive to such depths without aid, so take heart; a bubbly fissure offers renewed breath to divers seeking this half of the pendant.  Use it wisely." },
        ["text"] = "У Срібнохвойному лісі, вздовж краю Північного Припливу, на березі лежить занедбаний човен.  На захід від нього — те, що ви шукаєте; запливете надто далеко — океан виснажить вас до смерті.  Воно лежить на дні в замкненій скриньці й чекає, коли ви його заберете.$B$BБез допомоги вижити на такій глибині буде важко, тож не падайте духом: бульбашкова тріщина дає свіже повітря пірнальникам, які шукають цю половину підвіски.  Користуйтеся нею мудро.",
        ["npcs"] = { [1] = 11798 },
        ["roles"] = { ["greeting"] = true },
    },
    [264716934] = {
        ["english"] = { [1] = "I can tell just by the way you're standing that you're no warrior.  $B$BWhy don't you go do something safe, like read a book." },
        ["text"] = "З того, як ви стоїте, одразу видно, що ви не воїн.  $B$BЧому б вам не зайнятися чимось безпечним — книжку, наприклад, почитати.",
        ["npcs"] = { [1] = 911, [2] = 913, [3] = 914, [4] = 5479, [5] = 5480 },
        ["roles"] = { ["greeting"] = true },
    },
    [1763237684] = {
        ["english"] = { [1] = "It is good to see the Burning Blade is taking over where the Shadow Council once failed." },
        ["text"] = "Добре бачити, що Палаючий Клинок продовжує там, де колись зазнала невдачі Рада Тіней.",
        ["npcs"] = { [1] = 3216 },
        ["roles"] = { ["reply"] = true },
    },
    [8168096] = {
        ["english"] = { [1] = "I can not train you, young one.\010" },
        ["text"] = "Я не можу вас навчати, юний друже.\010",
        ["npcs"] = { [1] = 3039 },
        ["roles"] = { ["greeting"] = true },
    },
}
for key, row in pairs(rows) do addonTable.gossip_hashed.rows[key] = row end
